		#[cfg(any(target_os = "macos", target_os = "linux", windows))]
		"xdg-open",
		"yes",
	];
	let mut names: Vec<&'static str> = omp_builtins::extras::extras()
		.filter(|(_, kind)| matches!(kind, omp_builtins::extras::ExtraKind::Utility { .. }))
		.map(|(name, _)| name)
