/// Restore a live image at each generation, not two unstarted shells. The
/// registration policy is independent of the restored shell variables.
#[tokio::test(flavor = "multi_thread")]
async fn forked_shells_keep_env_external_only() {
	async fn run(
		shell: &Shell,
		dir: &std::path::Path,
		command: &str,
		env: Option<HashMap<String, String>>,
	) -> (ShellRunResult, String) {
		let (tx, rx) = flume::unbounded();
		let result = shell
			.run(
				ShellRunOptions {
					command: command.into(),
					cwd: Some(dir.to_string_lossy().into_owned()),
					env,
					..Default::default()
				},
				Some(tx),
				CancelToken::default(),
			)
			.await
			.expect("run");
		(result, rx.drain().collect())
	}

	let _guard = shell_test_lock().lock().await;
	let scratch = tempfile::tempdir().expect("scratch directory");
	let dir = scratch.path();
	let parent = Shell::new(Some(ShellOptions {
		session_env: Some(HashMap::from([("PI_DISABLE_UUTILS_BUILTINS".into(), "0".into())])),
		..ShellOptions::default()
	}));
	let (result, _) =
		run(&parent, dir, "unset OMP_ENV_FORK_TRANSIENT; OMP_ENV_FORK_VALUE=parent", None).await;
	assert_eq!(result.exit_code, Some(0));

	let overlay = HashMap::from([("OMP_ENV_FORK_TRANSIENT".into(), "transient".into())]);
	let (result, output) =
		run(&parent, dir, "printf %s \"$OMP_ENV_FORK_TRANSIENT\"", Some(overlay)).await;
	assert_eq!(result.exit_code, Some(0));
	assert_eq!(output, "transient");

	let child = parent.fork();
	let (result, output) = run(
		&child,
		dir,
		"printf '%s|%s' \"$OMP_ENV_FORK_VALUE\" \"${OMP_ENV_FORK_TRANSIENT-unset}\"; \
		 OMP_ENV_FORK_VALUE=child",
		None,
	)
	.await;
	assert_eq!(result.exit_code, Some(0));
	assert_eq!(output, "parent|unset");

	let grandchild = child.fork();
	for (shell, expected) in
		[(&parent, "parent|unset"), (&child, "child|unset"), (&grandchild, "child|unset")]
	{
		let (result, output) = run(
			shell,
			dir,
			"printf '%s|%s' \"$OMP_ENV_FORK_VALUE\" \"${OMP_ENV_FORK_TRANSIENT-unset}\"",
			None,
		)
		.await;
		assert_eq!(result.exit_code, Some(0));
		assert_eq!(output, expected);
		let (result, _) = run(
			shell,
			dir,
			"enable env >/dev/null 2>&1; PATH= command env -i OMP_ENV_ONLY=1",
			None,
		)
		.await;
		assert_eq!(result.exit_code, Some(127), "env must not dispatch in process");
	}
}

