/**
 * A tool's batch concurrency for one call: an unset mode is shared, and a
 * throwing per-call resolver is exclusive — the ordering that cannot race —
 * rather than taking down the whole batch.
 */
export function resolveToolConcurrency(
	tool: AgentTool<any, any, any> | undefined,
	args: Record<string, unknown>,
): "shared" | "exclusive" {
	const mode = tool?.concurrency;
	if (typeof mode !== "function") return mode ?? "shared";
	try {
		return mode(args);
	} catch {
		return "exclusive";
	}
}

async function waitForProcessPause(config: AgentLoopConfig, signal?: AbortSignal): Promise<void> {
	try {
		while (agentPauseGate.paused && !signal?.aborted) {
			config.onPauseChange?.(true);
			await agentPauseGate.waitUntilResumed(signal);
		}
	} finally {
		config.onPauseChange?.(false);
	}
}
/** Stop-details marker for a provider error after assistant content/tool args already streamed. */
export const STREAM_INTERRUPTED_AFTER_CONTENT_STOP_DETAIL = "stream_interrupted_after_content";

/** Sentinel returned by the abort race in `streamAssistantResponse`. */
const ABORTED: unique symbol = Symbol("agent-loop-aborted");

/**
 * Cap on consecutive re-samples triggered by a non-terminal stop
 * (`stopDetails.type === "pause_turn"`) without an intervening tool call. Each
 * continuation is a full model request, so a backend that never stops pausing
 * must not spin the loop forever. Resets whenever a turn carries tool calls.
 */
const MAX_PAUSED_TURN_CONTINUATIONS = 8;

/**
 * Cap on consecutive "tool call failed" nudges for a turn that ended with raw
 * DeepSeek DSML tool-call markup in its text and no structured call. A model
 * that keeps leaking after this many corrections is left to yield. Resets
 * whenever a turn carries tool calls.
 */
const MAX_DSML_LEAK_NUDGES = 2;

/**
 * Cap on consecutive forced escalations for a single soft tool requirement.
 * A forced `toolChoice` guarantees the call, so this is purely defensive: if a
 * model somehow never satisfies the requirement, give up forcing rather than
 * spin the loop. Reset whenever the requirement id changes or clears.
 */
const MAX_SOFT_TOOL_ESCALATIONS = 3;

/**
 * Whether a hard `toolChoice` for a turn conflicts with a pending soft tool
 * requirement — i.e. forbids tools (`"none"`) or forces a *different* specific
 * tool. `"auto"`/`"required"`/`"any"` and a same-tool force still let the model
 * satisfy the requirement, so they do not conflict and the soft gate stays active.
 */
function hardToolChoiceBlocks(choice: ToolChoice | undefined, requiredTool: string): boolean {
	if (choice === undefined) return false;
	if (typeof choice === "string") return choice === "none";
	if (choice.type === "computer") return requiredTool !== "computer";
	const name = choice.type === "tool" ? choice.name : "function" in choice ? choice.function.name : choice.name;
	return name !== requiredTool;
}

/**
 * Cadence (ms) for polling queued steering while an `interruptible` tool is in
 * flight, so a steer cuts the wait short instead of sitting idle until the
 * tool's own window elapses. A cheap synchronous queue check; latency-bounded
 * at one tick.
 */
/**
 * Abort reason for a turn-wide interruption where only some tool calls caused
 * the abort and sibling placeholders need neutral messages.
 */
export interface ToolScopedAbortReason {
	readonly kind: "tool-scoped-abort";
	readonly message: string;
	readonly toolCallMessages: Record<string, string>;
	readonly defaultToolCallMessage: string;
}

/** Creates an abort reason that labels matching tool calls separately from siblings. */
export function createToolScopedAbortReason(
	message: string,
	toolCallMessages: Record<string, string>,
	defaultToolCallMessage: string,
): ToolScopedAbortReason {
	return { kind: "tool-scoped-abort", message, toolCallMessages, defaultToolCallMessage };
}

/**
 * Marks an abort raised by a completed post-tool hook as terminal for the
 * current run. External/user aborts still synthesize an aborted assistant
 * boundary; this reason stops after persisting the completed tool batch.
 */
export const TERMINAL_TOOL_RESULT_ABORT_REASON = Symbol.for("pi-agent-core.terminal-tool-result");

/**
 * Abort reason carried by an interruptible tool's signal when queued steering,
 * a peer IRC, or a background completion cut it short. Lets a wait tell the
 * designed wake path apart from an external/user abort of the run.
 */
export const TOOL_INTERRUPT_ABORT_REASON = Symbol.for("pi-agent-core.tool-interrupt");

const STEERING_INTERRUPT_POLL_MS = 250;

class HarmonyLeakInterruption extends Error {
	constructor(
		readonly detection: HarmonyDetection,
		readonly removed: string,
		readonly recovered?: HarmonyRecoveredToolCall,
	) {
		super(`Detected GPT-5 Harmony protocol leakage (${signalListLabel(detection.signals)})`);
		this.name = "HarmonyLeakInterruption";
	}
}
export function resolveOwnedDialectFromEnv(value: string | undefined): Dialect | undefined {
	switch (value) {
		case "1":
		case "true":
			return "glm";
		case "glm":
		case "hermes":
		case "kimi":
		case "xml":
		case "anthropic":
		case "deepseek":
		case "harmony":
		case "qwen3":
		case "gemini":
		case "gemma":
		case "minimax":
			return value;
		default:
			return undefined;
	}
}

type AssistantContentBlock = AssistantMessage["content"][number];
type AssistantToolCallBlock = Extract<AssistantContentBlock, { type: "toolCall" }>;

function snapshotComputerSafetyChecks(value: unknown): ComputerSafetyCheck[] | undefined {
	if (!Array.isArray(value)) return undefined;
	const checks: ComputerSafetyCheck[] = [];
	for (const raw of value) {
		if (!raw || typeof raw !== "object" || Array.isArray(raw)) return undefined;
		const check = raw as Record<string, unknown>;
		if (typeof check.id !== "string" || check.id.length === 0) return undefined;
		if (check.code !== undefined && check.code !== null && typeof check.code !== "string") return undefined;
		if (check.message !== undefined && check.message !== null && typeof check.message !== "string") return undefined;
		checks.push({
			id: check.id,
			...(check.code !== undefined ? { code: check.code as string | null } : {}),
			...(check.message !== undefined ? { message: check.message as string | null } : {}),
		});
	}
	return checks;
}

function isFiniteCoordinate(value: unknown): value is number {
	return typeof value === "number" && Number.isFinite(value);
}

function hasValidComputerKeys(value: unknown, optional: boolean): boolean {
	return (
		(optional && value === undefined) ||
		value === null ||
		(Array.isArray(value) && value.every(key => typeof key === "string"))
	);
}

function snapshotComputerAction(value: unknown): ComputerAction | undefined {
	if (!value || typeof value !== "object" || Array.isArray(value)) return undefined;
	const action = value as Record<string, unknown>;
	switch (action.type) {
		case "click":
			if (
				!(["left", "right", "wheel", "back", "forward"] as unknown[]).includes(action.button) ||
				!isFiniteCoordinate(action.x) ||
				!isFiniteCoordinate(action.y) ||
				!hasValidComputerKeys(action.keys, true)
			)
				return undefined;
			break;
		case "double_click":
			if (
				!isFiniteCoordinate(action.x) ||
				!isFiniteCoordinate(action.y) ||
				!hasValidComputerKeys(action.keys, false)
			)
				return undefined;
			break;
		case "drag":
			if (
				!Array.isArray(action.path) ||
				!action.path.every(
					point =>
						point &&
						typeof point === "object" &&
						isFiniteCoordinate((point as Record<string, unknown>).x) &&
						isFiniteCoordinate((point as Record<string, unknown>).y),
				) ||
				!hasValidComputerKeys(action.keys, true)
			)
				return undefined;
			break;
		case "keypress":
			if (!Array.isArray(action.keys) || !action.keys.every(key => typeof key === "string")) return undefined;
			break;
		case "move":
			if (!isFiniteCoordinate(action.x) || !isFiniteCoordinate(action.y) || !hasValidComputerKeys(action.keys, true))
				return undefined;
			break;
		case "screenshot":
		case "wait":
			break;
		case "scroll":
			if (
				!isFiniteCoordinate(action.x) ||
				!isFiniteCoordinate(action.y) ||
				!isFiniteCoordinate(action.scroll_x) ||
				!isFiniteCoordinate(action.scroll_y) ||
				!hasValidComputerKeys(action.keys, true)
			)
				return undefined;
			break;
		case "type":
			if (typeof action.text !== "string") return undefined;
			break;
		default:
			return undefined;
	}
	return structuredCloneJSON(action) as ComputerAction;
}

function snapshotToolCallProviderMetadata(value: unknown): ToolCallProviderMetadata | undefined {
	if (value === undefined) return undefined;
	if (!value || typeof value !== "object" || Array.isArray(value)) return undefined;
	const metadata = value as Record<string, unknown>;
	if (
		metadata.type !== "computer" ||
		typeof metadata.providerItemId !== "string" ||
		metadata.providerItemId.length === 0
	)
		return undefined;
	if (!Array.isArray(metadata.actions) || metadata.actions.length === 0) return undefined;
	const actions = metadata.actions.map(snapshotComputerAction);
	if (actions.some(action => action === undefined)) return undefined;
	const pendingSafetyChecks = snapshotComputerSafetyChecks(metadata.pendingSafetyChecks);
	if (!pendingSafetyChecks) return undefined;
	return {
		type: "computer",
		providerItemId: metadata.providerItemId,
		actions: actions as ComputerAction[],
		pendingSafetyChecks,
	};
}

function snapshotToolResultProviderMetadata(value: unknown): {
	metadata?: ToolResultProviderMetadata;
	malformed: boolean;
} {
	if (value === undefined) return { malformed: false };
	if (!value || typeof value !== "object" || Array.isArray(value)) return { malformed: true };
	const metadata = value as Record<string, unknown>;
	if (
		metadata.type !== "computer" ||
		!metadata.screenshot ||
		typeof metadata.screenshot !== "object" ||
		Array.isArray(metadata.screenshot)
	) {
		return { malformed: true };
	}
	const screenshot = metadata.screenshot as Record<string, unknown>;
	const hasImageUrl = Object.hasOwn(screenshot, "image_url");
	const hasFileId = Object.hasOwn(screenshot, "file_id");
	if (screenshot.type !== "computer_screenshot" || hasImageUrl === hasFileId) return { malformed: true };
	if (hasImageUrl && (typeof screenshot.image_url !== "string" || screenshot.image_url.length === 0))
		return { malformed: true };
	if (hasFileId && (typeof screenshot.file_id !== "string" || screenshot.file_id.length === 0))
		return { malformed: true };
	const acknowledgedSafetyChecks = snapshotComputerSafetyChecks(metadata.acknowledgedSafetyChecks);
	if (!acknowledgedSafetyChecks) return { malformed: true };
	return {
		malformed: false,
		metadata: {
			type: "computer",
			screenshot: hasImageUrl
				? { type: "computer_screenshot", image_url: screenshot.image_url as string }
				: { type: "computer_screenshot", file_id: screenshot.file_id as string },
			acknowledgedSafetyChecks,
		},
	};
}

function snapshotAssistantContentBlock(block: AssistantContentBlock): AssistantContentBlock {
	switch (block.type) {
		case "text":
		case "image":
			return { ...block };
		case "thinking":
			return { ...block };
		case "redactedThinking":
			return { ...block };
		case "anthropicServerTool":
			return { ...block, block: cloneJsonTree(block.block) };
		case "fallback":
			return { ...block, from: { ...block.from }, to: { ...block.to } };
		case "toolCall": {
			const snap = {
				...block,
				// Providers mutate streaming arguments in place (owned-stream, GLM)
				// as well as replacing them, so containers are always copied; the
				// strings inside are immutable and shared, keeping the per-delta
				// cost independent of the argument payload size.
				arguments: cloneJsonTree(block.arguments),
				providerMetadata: snapshotToolCallProviderMetadata(block.providerMetadata),
			};
			// Object spread copies enumerable symbols in Bun, but the Cursor
			// exec-resolved marker is load-bearing for skip-on-dispatch — copy
			// it explicitly so a projector/snapshot path cannot drop it.
			copyCursorExecResolved(snap, block);
			return snap;
		}
	}
}

function snapshotAssistantMessage(message: AssistantMessage): AssistantMessage {
	return {
		...message,
		content: message.content.map(snapshotAssistantContentBlock),
		usage: {
			...message.usage,
			cost: { ...message.usage.cost },
		},
		disabledFeatures: message.disabledFeatures ? [...message.disabledFeatures] : undefined,
		toolCallAbortMessages: message.toolCallAbortMessages ? { ...message.toolCallAbortMessages } : undefined,
	};
}

/**
 * Incremental variant of `snapshotAssistantMessage` for per-delta
 * `message_update` events.
 *
 * The stream contract guarantees that every content-block mutation a provider
 * makes is paired with an event carrying that block's `contentIndex` (every
 * provider mutates then pushes), and that `output.content` is append-only
 * within a turn. A fresh snapshot therefore only needs to re-clone:
 *
 * - the block the current event targets (`changedIndex`),
 * - blocks still open (started but not ended) — Cursor's edit block merges
 *   `path`/`stream_content` into a live block without an event, so open blocks
 *   are re-cloned on every delta,
 * - blocks appended since the previous snapshot.
 *
 * Every other (finalized) block is carried over from the previous snapshot by
 * reference: finalized blocks are never mutated after their end event, so
 * sharing them is exact and turns the per-delta cost from O(turn content) into
 * O(open blocks) — the difference between quadratic and linear streaming cost
 * on long turns (issue #10605).
 */
function snapshotAssistantMessageIncremental(
	live: AssistantMessage,
	prev: AssistantMessage,
	changedIndex: number,
	openBlocks: ReadonlySet<number>,
): AssistantMessage {
	const liveContent = live.content;
	const prevContent = prev.content;
	const prevLen = prevContent.length;
	// Reference-copy the previous snapshot's block array (native-speed), then
	// patch in fresh clones only where the live state moved: the block this
	// delta targeted, blocks still streaming, and blocks appended since the
	// previous snapshot. Finalized blocks keep their existing snapshot clone.
	const content = prevContent.slice();
	for (let i = prevLen; i < liveContent.length; i++) {
		content.push(snapshotAssistantContentBlock(liveContent[i]!));
	}
	if (changedIndex >= 0 && changedIndex < prevLen && changedIndex < liveContent.length) {
		content[changedIndex] = snapshotAssistantContentBlock(liveContent[changedIndex]!);
	}
	for (const openIndex of openBlocks) {
		if (openIndex !== changedIndex && openIndex >= 0 && openIndex < prevLen && openIndex < liveContent.length) {
			content[openIndex] = snapshotAssistantContentBlock(liveContent[openIndex]!);
		}
	}
	return {
		...live,
		content,
		usage: {
			...live.usage,
			cost: { ...live.usage.cost },
		},
		disabledFeatures: live.disabledFeatures ? [...live.disabledFeatures] : undefined,
		toolCallAbortMessages: live.toolCallAbortMessages ? { ...live.toolCallAbortMessages } : undefined,
	};
}

/**
 * Deep-clone an assistant streaming event so subscribers get an immutable view.
 * Pass `partialSnapshot` when the caller has already snapshotted `event.partial`
 * (the `message_update` push sites alias it as the event's `message`) so the
 * identical partial is not deep-cloned twice per streaming delta.
 */
function snapshotAssistantMessageEvent(
	event: AssistantMessageEvent,
	partialSnapshot?: AssistantMessage,
): AssistantMessageEvent {
	switch (event.type) {
		case "start":
			return { ...event, partial: partialSnapshot ?? snapshotAssistantMessage(event.partial) };
		case "text_start":
		case "text_delta":
		case "text_end":
		case "image_end":
		case "thinking_start":
		case "thinking_delta":
		case "thinking_end":
		case "toolcall_start":
		case "toolcall_delta":
			return { ...event, partial: partialSnapshot ?? snapshotAssistantMessage(event.partial) };
		case "toolcall_end":
			return {
				...event,
				toolCall: snapshotAssistantContentBlock(event.toolCall) as AssistantToolCallBlock,
				partial: partialSnapshot ?? snapshotAssistantMessage(event.partial),
			};
		case "done":
			return { ...event, message: snapshotAssistantMessage(event.message) };
		case "error":
			return { ...event, error: snapshotAssistantMessage(event.error) };
	}
}

/**
 * Normalize a value coming back from `tool.execute()` (or its streaming partial-update callback)
 * into a structurally valid {@link AgentToolResult}.
 *
 * The tool interface is typed, but third-party tools (MCP, extensions, user-authored AgentTools)
 * can violate the contract at runtime. Persisting a malformed result corrupts the session file
 * (missing `content` array → crash on reload). We coerce at the single boundary where untyped
 * results enter the agent loop, so every downstream consumer can rely on the type.
 */
const EMPTY_ERROR_TOOL_RESULT_TEXT = "Tool failed with no output.";

function hasSubstantiveToolResultContent(content: AgentToolResult["content"]): boolean {
	for (const block of content) {
		if (block.type === "image") return true;
		if (block.type === "text" && block.text.trim().length > 0) return true;
	}
	return false;
}

function coerceToolResult(raw: unknown): { result: AgentToolResult<unknown>; malformed: boolean } {
	const rawObj = raw && typeof raw === "object" ? (raw as Record<string, unknown>) : null;
	const rawContent = rawObj?.content;
	const details = rawObj && "details" in rawObj ? rawObj.details : {};
	const providerMetadataResult = snapshotToolResultProviderMetadata(
		rawObj && "providerMetadata" in rawObj ? rawObj.providerMetadata : undefined,
	);
	const providerMetadata = providerMetadataResult.metadata;
	// Tools may flag a non-throwing failure on the result itself (e.g. an
	// aggregator that catches per-entry errors and synthesizes a combined
	// result). Preserve the flag so agent-loop can surface it on the wire.
	const explicitError = Boolean(rawObj && "isError" in rawObj && rawObj.isError);
	// Tools may flag the result contextually useless (zero matches, elapsed
	// wait) so compaction can elide it once consumed. Errors are never useless.
	const useless = Boolean(rawObj && "useless" in rawObj && rawObj.useless);

	if (!Array.isArray(rawContent)) {
		return {
			result: {
				content: [{ type: "text", text: "Tool returned an invalid result: missing content array." }],
				details,
				isError: true,
			},
			malformed: true,
		};
	}

	const content: AgentToolResult["content"] = [];
	let invalidBlocks = 0;
	for (const block of rawContent) {
		if (!block || typeof block !== "object" || !("type" in block)) {
			invalidBlocks++;
			continue;
		}
		if (block.type === "text" && typeof (block as { text?: unknown }).text === "string") {
			content.push({ type: "text", text: sanitizeText((block as { text: string }).text) });
		} else if (
			block.type === "image" &&
			typeof (block as { data?: unknown }).data === "string" &&
			typeof (block as { mimeType?: unknown }).mimeType === "string"
		) {
			content.push(block as { type: "image"; data: string; mimeType: string });
		} else {
			invalidBlocks++;
		}
	}
	if (invalidBlocks > 0) {
		content.push({
			type: "text",
			text: `Tool returned an invalid result: ${invalidBlocks} content block${invalidBlocks === 1 ? "" : "s"} had an unsupported shape.`,
		});
	}
	if (providerMetadataResult.malformed) {
		content.push({
			type: "text",
			text: "Tool returned an invalid result: computer providerMetadata had an unsupported shape.",
		});
	}
	const isError = explicitError || invalidBlocks > 0 || providerMetadataResult.malformed;
	// Anthropic rejects tool_result blocks with is_error: true and empty content.
	if (isError && !hasSubstantiveToolResultContent(content)) {
		content.length = 0;
		content.push({ type: "text", text: EMPTY_ERROR_TOOL_RESULT_TEXT });
	}
	return {
		result: {
			content,
			details,
			providerMetadata,
			...(isError ? { isError: true } : {}),
			...(useless && !isError ? { useless: true } : {}),
		},
		malformed: invalidBlocks > 0 || providerMetadataResult.malformed,
	};
}

/**
 * Start an agent loop with a new prompt message.
 * The prompt is added to the context and events are emitted for it.
 */
export function agentLoop(
	prompts: AgentMessage[],
	context: AgentContext,
	config: AgentLoopConfig,
	signal?: AbortSignal,
	streamFn?: StreamFn,
): EventStream<AgentEvent, AgentMessage[]> {
	const stream = createAgentStream();

	(async () => {
		try {
			const newMessages: AgentMessage[] = [...prompts];
			const currentContext: AgentContext = {
				...context,
				messages: [...context.messages, ...prompts],
			};
			for (const prompt of prompts) {
				(prompt as CommittableAsideMessage)[ASIDE_MESSAGE_COMMIT]?.();
			}

			stream.push({ type: "agent_start" });

			await runLoop(currentContext, newMessages, config, signal, stream, streamFn, prompts);
		} catch (err) {
			stream.fail(err);
		}
	})();

	return stream;
}

/**
 * Whether `message` is kept out of model context: drawn and saved, never sent (a `!!` bash run, a
 * custom row sent with `excludeFromContext`).
 */
export function isExcludedFromContext(message: AgentMessage): boolean {
	return "excludeFromContext" in message && message.excludeFromContext === true;
}

/** Index of the last message the model sees, or -1; rows kept out of context after it do not change the request tail. */
export function lastContextIndex(messages: readonly AgentMessage[]): number {
	let i = messages.length - 1;
	while (i >= 0 && isExcludedFromContext(messages[i])) i--;
	return i;
}

/** The last message the model sees (see {@link lastContextIndex}). */
export function lastContextMessage(messages: readonly AgentMessage[]): AgentMessage | undefined {
	return messages[lastContextIndex(messages)];
}

/**
 * Trailing assistant message whose runnable tool calls have no results yet.
 *
 * A harness that strips failed/aborted tool results in order to re-execute
 * the calls (e.g. `AgentSession.retry`'s tool replay) leaves the transcript
 * in this shape; {@link agentLoopContinue} resumes it by running those calls
 * before the next model call. Cursor exec-resolved blocks are excluded — the
 * provider already executed those server-side. `length`-truncated turns never
 * qualify: their trailing call arguments may be incomplete.
 */
export function unpairedToolCallTail(messages: readonly AgentMessage[]): AssistantMessage | undefined {
	const tail = messages[messages.length - 1];
	if (tail?.role !== "assistant") return undefined;
	// Mirrors the loop's `runnableStop` rule for fresh turns.
	if (tail.stopReason !== "toolUse" && tail.stopReason !== "stop") return undefined;
	const hasRunnable = tail.content.some(
		c => c.type === "toolCall" && (c as CursorExecResolvedCarrier)[kCursorExecResolved] !== true,
	);
	return hasRunnable ? tail : undefined;
}

/**
 * Continue an agent loop from the current context without adding a new message.
 * Used for retries - context already has user message or tool results.
 *
 * **Important:** The last message in context must convert to a `user` or `toolResult` message
 * via `convertToLlm` — except for an assistant tail with unpaired runnable
 * tool calls (see {@link unpairedToolCallTail}), which resumes by executing
 * those calls first. Any other assistant tail is rejected here; other invalid
 * tails cannot be validated since `convertToLlm` is only called once per turn.
 */
export function agentLoopContinue(
	context: AgentContext,
	config: AgentLoopConfig,
	signal?: AbortSignal,
	streamFn?: StreamFn,
): EventStream<AgentEvent, AgentMessage[]> {
	if (context.messages.length === 0) {
		throw new Error("Cannot continue: no messages in context");
	}

	if (context.messages[context.messages.length - 1].role === "assistant" && !unpairedToolCallTail(context.messages)) {
		throw new Error("Cannot continue from message role: assistant");
	}

	const stream = createAgentStream();

	(async () => {
		try {
			const newMessages: AgentMessage[] = [];
			const currentContext: AgentContext = { ...context, messages: [...context.messages] };

			const resumeTail = unpairedToolCallTail(currentContext.messages);
			stream.push(
				resumeTail
					? {
							type: "agent_start",
							resumedToolCallIds: resumeTail.content.flatMap(block =>
								block.type === "toolCall" ? [block.id] : [],
							),
						}
					: { type: "agent_start" },
			);

			await runLoop(currentContext, newMessages, config, signal, stream, streamFn);
		} catch (err) {
			stream.fail(err);
		}
	})();

	return stream;
}

function createAgentStream(): EventStream<AgentEvent, AgentMessage[]> {
	return new EventStream<AgentEvent, AgentMessage[]>(
		(event: AgentEvent) => event.type === "agent_end",
		(event: AgentEvent) => (event.type === "agent_end" ? event.messages : []),
	);
}

/**
 * Build the `agent_end` event payload. When telemetry is enabled, snapshots
 * the run collector so consumers receive {@link AgentRunSummary} +
 * {@link AgentRunCoverage} alongside the messages without parsing OTEL spans.
 * When telemetry is unset, returns the bare event for backwards compatibility.
 */
function buildAgentEndEvent(
	messages: AgentMessage[],
	telemetry: AgentTelemetry | undefined,
	stepCount: number,
): Extract<AgentEvent, { type: "agent_end" }> {
	if (!telemetry) return { type: "agent_end", messages };
	const snapshot = telemetry.collector.snapshot({ stepCount });
	if (telemetry.collector.markRunEnded()) {
		fireOnRunEnd(telemetry, snapshot.summary, snapshot.coverage);
	}
	return { type: "agent_end", messages, telemetry: snapshot.summary, coverage: snapshot.coverage };
}
/**
 * Push a `turn_end` event and run the awaited per-turn hook when the run is
 * still healthy. The hook is skipped for externally aborted or errored turns so
 * a user interrupt does not hang on a background backlog wait.
 *
 * A {@link TERMINAL_TOOL_RESULT_ABORT_REASON} abort is the exception: it is a
 * graceful yield (e.g. a subagent's final `yield` tool), not a user interrupt.
 * The completed tool batch is persisted and the turn must still reach
 * `onTurnEnd` so per-turn bookkeeping — notably advisor review of the yield
 * delta (#9505) — runs exactly as it does for a plain end-of-turn message. The
 * hook receives no signal in that case so downstream waits (advisor catch-up)
 * behave identically to a normal final turn instead of short-circuiting on the
 * spent abort.
 */
async function emitTurnEnd(
	stream: EventStream<AgentEvent, AgentMessage[]>,
	currentContext: AgentContext,
	message: AgentMessage,
	toolResults: ToolResultMessage[],
	config: AgentLoopConfig,
	signal?: AbortSignal,
	context?: Omit<AgentTurnEndContext, "message" | "toolResults">,
	runHookOnAbortedMessage = false,
): Promise<void> {
	stream.push({ type: "turn_end", message, toolResults });
	const terminalYield = signal?.reason === TERMINAL_TOOL_RESULT_ABORT_REASON;
	const isAbortedOrError =
		message.role === "assistant" && (message.stopReason === "aborted" || message.stopReason === "error");
	if ((signal?.aborted && !terminalYield) || (isAbortedOrError && !runHookOnAbortedMessage)) return;
	await config.onTurnEnd?.(currentContext.messages, terminalYield ? undefined : signal, {
		message,
		toolResults,
		additionalMessages: [],
		willContinue: false,
		...context,
	});
}

function createGateStopMessage(model: Model, reason: string | undefined): AssistantMessage {
	return {
		role: "assistant",
		content: [{ type: "text", text: "" }],
		api: model.api,
		provider: model.provider,
		model: model.id,
		usage: {
			input: 0,
			output: 0,
			cacheRead: 0,
			cacheWrite: 0,
			totalTokens: 0,
			cost: { input: 0, output: 0, cacheRead: 0, cacheWrite: 0, total: 0 },
		},
		stopReason: "aborted",
		errorMessage: reason ?? "Stopped before model call",
		timestamp: Date.now(),
	};
}

/**
 * Detailed-result handle returned by {@link agentLoopDetailed}. Adds the
 * run-level telemetry/coverage rollup to the existing `AgentMessage[]`
 * payload without changing the resolved type of `stream.result()`.
 */
export interface AgentLoopDetailedResult {
	readonly messages: AgentMessage[];
	readonly telemetry: AgentRunSummary | undefined;
	readonly coverage: AgentRunCoverage | undefined;
}

/**
 * Convenience wrapper over {@link agentLoop} that exposes the run-level
 * summary + coverage alongside the messages. The returned `stream` is the
 * same `EventStream` callers already consume; `detailed()` awaits the
 * stream's `agent_end` event and returns the additive fields.
 *
 * Existing `stream.result()` semantics are preserved — it still resolves to
 * `AgentMessage[]`. Use {@link agentLoopDetailed} when you need the rollup;
 * use {@link agentLoop} when you do not.
 */
export function agentLoopDetailed(
	prompts: AgentMessage[],
	context: AgentContext,
	config: AgentLoopConfig,
	signal?: AbortSignal,
	streamFn?: StreamFn,
): {
	readonly stream: EventStream<AgentEvent, AgentMessage[]>;
	readonly detailed: () => Promise<AgentLoopDetailedResult>;
} {
	const capture = createDetailedCapture(config);
	const stream = agentLoop(prompts, context, capture.config, signal, streamFn);
	return { stream, detailed: () => capture.detailed(stream) };
}

/**
 * Like {@link agentLoopDetailed} but built on top of
 * {@link agentLoopContinue}.
 */
export function agentLoopContinueDetailed(
	context: AgentContext,
	config: AgentLoopConfig,
	signal?: AbortSignal,
	streamFn?: StreamFn,
): {
	readonly stream: EventStream<AgentEvent, AgentMessage[]>;
	readonly detailed: () => Promise<AgentLoopDetailedResult>;
} {
	const capture = createDetailedCapture(config);
	const stream = agentLoopContinue(context, capture.config, signal, streamFn);
	return { stream, detailed: () => capture.detailed(stream) };
}

/**
 * Wire an `onRunEnd` telemetry hook onto `config` so the detailed helper can
 * capture the run summary without consuming the event stream. Preserves any
 * existing `onRunEnd` the caller had set.
 */
function createDetailedCapture(config: AgentLoopConfig): {
	readonly config: AgentLoopConfig;
	readonly detailed: (stream: EventStream<AgentEvent, AgentMessage[]>) => Promise<AgentLoopDetailedResult>;
} {
	let captured: { summary: AgentRunSummary; coverage: AgentRunCoverage } | undefined;
	const userHook = config.telemetry?.onRunEnd;
	const wired: AgentLoopConfig = {
		...config,
		telemetry: {
			...config.telemetry,
			onRunEnd: (summary, coverage) => {
				captured = { summary, coverage };
				userHook?.(summary, coverage);
			},
		},
	};
	return {
		config: wired,
		detailed: async stream => {
			const messages = await stream.result();
			return {
				messages,
				telemetry: captured?.summary,
				coverage: captured?.coverage,
			};
		},
	};
}

export function normalizeMessagesForProvider(
	messages: Context["messages"],
	model: AgentLoopConfig["model"],
): Context["messages"] {
	// The anthropic and ollama transports apply `stripThinkingHistory` with their
	// own turn-shape rules; chat completions has no wire-level handling, so the
	// history is stripped here.
	const compat = model.api === "openai-completions" ? model.compat : undefined;
	if (!compat || !("stripThinkingHistory" in compat) || compat.stripThinkingHistory !== true) {
		return messages;
	}

	let hasThinking = false;
	for (const message of messages) {
		if (message.role !== "assistant" || !Array.isArray(message.content)) continue;
		for (const block of message.content) {
			if (block.type === "thinking") {
				hasThinking = true;
				break;
			}
		}
		if (hasThinking) break;
	}
	if (!hasThinking) return messages;

	return messages.map(message => {
		if (message.role !== "assistant" || !Array.isArray(message.content)) {
			return message;
		}
		const filtered = message.content.filter(block => block.type !== "thinking");
		return filtered.length === message.content.length ? message : { ...message, content: filtered };
	});
}

/** Schema description of the injected `i` field when neither `PI_INTENT_DESC` nor the caller sets one. */
const DEFAULT_INTENT_FIELD_DESCRIPTION = "concise intent";
const INTENT_SCHEMA_UNION_KEYS = ["anyOf", "oneOf"] as const;

// Memoize injection per input schema identity: normalizeTools runs on every
// model call and injectIntentIntoSchema mints a fresh root object each time,
// which defeats the stamp-keyed schema memos downstream (toolWireSchema,
// stripSchemaDescriptions, tryEnforceStrictSchema each deep-clone + re-walk
// the whole catalog per request). The injected object is shared across
// requests — the same profile as the intent-off path, where parameters IS the
// shared memoized wire schema (see schema-immutability.test.ts). One stamp
// key per (mode, description) variant, "" keying the bare one: agents in one
// process may describe `i` differently over the same shared tool schemas.
const INTENT_STAMPS = { require: new Map<string, symbol>(), optional: new Map<string, symbol>() } as const;

function memoizedInjectIntentIntoSchema(
	schema: Record<string, unknown>,
	mode: "require" | "optional",
	description: string | undefined,
): unknown {
	const stamps = INTENT_STAMPS[mode];
	const variant = description ?? "";
	let key = stamps.get(variant);
	if (!key) {
		key = Symbol(`intent:${mode}`);
		stamps.set(variant, key);
	}
	return stamp(schema, key, host => injectIntentIntoSchema(host, mode, description));
}

/** `schema` with the `i` field first (and required in `require` mode); `description` unset injects it bare. */
function injectIntentIntoSchema(
	schema: unknown,
	mode: "require" | "optional",
	description: string | undefined,
): unknown {
	if (!schema || typeof schema !== "object" || Array.isArray(schema)) return schema;
	const schemaRecord = schema as Record<string, unknown>;
	const propertiesValue = schemaRecord.properties;
	const hasOwnProperties =
		propertiesValue !== null && typeof propertiesValue === "object" && !Array.isArray(propertiesValue);

	// Pure union root (anyOf/oneOf with no own properties): push `i` into each
	// alternative branch so each closed shape keeps `additionalProperties: false`
	// honest with intent tracing. Adding a sibling root `properties: { i }` /
	// `required: [i]` would force every input to satisfy both root *and* a
	// branch, leaving no satisfiable shape because each branch's
	// `additionalProperties: false` rejects every other field — and OpenAI
	// strict sanitization later promotes that sibling to a closed root
	// `type: "object"` that rejects every non-`i` key outright. allOf is not
	// alternation (its members are sub-constraints), so we don't recurse into it.
	if (!hasOwnProperties) {
		for (const key of INTENT_SCHEMA_UNION_KEYS) {
			const variants = schemaRecord[key];
			if (!Array.isArray(variants)) continue;
			return {
				...schemaRecord,
				[key]: variants.map(variant => injectIntentIntoSchema(variant, mode, description)),
			};
		}
	}

	const properties = hasOwnProperties ? (propertiesValue as Record<string, unknown>) : {};
	const requiredValue = schemaRecord.required;
	const required = Array.isArray(requiredValue)
		? requiredValue.filter((item): item is string => typeof item === "string")
		: [];
	if (INTENT_FIELD in properties) {
		const { [INTENT_FIELD]: intentProp, ...rest } = properties;
		const needsReorder = Object.keys(properties)[0] !== INTENT_FIELD;
		const needsRequired = mode === "require" && !required.includes(INTENT_FIELD);
		if (!needsReorder && !needsRequired) return schema;
		return {
			...schemaRecord,
			...(needsReorder ? { properties: { [INTENT_FIELD]: intentProp, ...rest } } : {}),
			...(needsRequired ? { required: [...required, INTENT_FIELD] } : {}),
		};
	}
	return {
		...schemaRecord,
		properties: {
			[INTENT_FIELD]: description === undefined ? { type: "string" } : { type: "string", description },
			...properties,
		},
		...(mode === "require" ? { required: [...required, INTENT_FIELD] } : {}),
	};
}

export interface NormalizeToolsOptions {
	/** Inject the `i` intent field into tool schemas (subject to `PI_NO_INTENT`). */
	injectIntent: boolean;
	/** Schema description of the injected `i` field; `PI_INTENT_DESC` overrides it. Default `concise intent`. */
	intentDescription?: string;
	/** Strip descriptions from the wire specs when the catalog rides in the system prompt. */
	pruneDescriptions?: boolean;
}

export function normalizeTools(tools: AgentContext["tools"], options: NormalizeToolsOptions): Context["tools"] {
	const pruneDescriptions = options.pruneDescriptions === true;
	const injectIntent = options.injectIntent && Bun.env.PI_NO_INTENT !== "1";
	const intentDescription = Bun.env.PI_INTENT_DESC || options.intentDescription || DEFAULT_INTENT_FIELD_DESCRIPTION;
	return tools?.map(t => {
		const intentMode = resolveIntentMode(t.intent);
		const doInjectIntent =
			injectIntent && intentMode !== "omit" && !schemaDefinesProperty(toolWireSchema(t), INTENT_FIELD);
		// When the full catalog is rendered into the system prompt, ship the tool
		// specs without their descriptions (top-level + nested schema annotations)
		// so they are not duplicated on the wire. Strip the STABLE wire schema (the
		// memoized `stripSchemaDescriptions` result is reused across requests), then
		// re-inject `i` (without its hint, which an unset description omits) so
		// intent tracing keeps the field while no descriptions ride the wire.
		if (pruneDescriptions) {
			const stripped = stripSchemaDescriptions(toolWireSchema(t));
			const parameters = (
				doInjectIntent ? memoizedInjectIntentIntoSchema(stripped, intentMode, undefined) : stripped
			) as TSchema;
			return { ...t, parameters, description: "" };
		}
		const wire = toolWireSchema(t);
		const parameters = (
			doInjectIntent ? memoizedInjectIntentIntoSchema(wire, intentMode, intentDescription) : wire
		) as TSchema;
		const description = t.description ?? "";
		const examplesBlock = renderToolExamples({ ...t, parameters }, doInjectIntent ? INTENT_FIELD : undefined);
		const finalDescription = examplesBlock ? `${description}\n\n${examplesBlock}` : description;
		return { ...t, parameters, description: finalDescription };
	});
}

function resolveIntentMode(intent: AgentTool["intent"]): "require" | "optional" | "omit" {
	if (typeof intent === "function") return "omit";
	if (intent === "optional" || intent === "omit") return intent;
	return "require";
}

function extractIntent(args: Record<string, unknown>): { intent?: string; strippedArgs: Record<string, unknown> } {
	const { [INTENT_FIELD]: intent, ...strippedArgs } = args;
	if (typeof intent !== "string") {
		return { strippedArgs };
	}
	const trimmed = intent
		.trim()
		.replace(/\s*\.+$/, "")
		.trim();
	return { intent: trimmed.length > 0 ? trimmed : undefined, strippedArgs };
}

/**
 * Main loop logic shared by agentLoop and agentLoopContinue.
 */
async function runLoop(
	currentContext: AgentContext,
	newMessages: AgentMessage[],
	config: AgentLoopConfig,
	signal: AbortSignal | undefined,
	stream: EventStream<AgentEvent, AgentMessage[]>,
	streamFn?: StreamFn,
	initialMessages: AgentMessage[] = [],
): Promise<void> {
	const telemetry = resolveTelemetry(config.telemetry, config.sessionId);
	const invokeAgentSpan = startInvokeAgentSpan(telemetry, config.model);
	const stepCounter = { count: 0 };
	let caughtError: unknown;
	try {
		await runInActiveSpan(invokeAgentSpan, () =>
			runLoopBody(
				currentContext,
				newMessages,
				config,
				signal,
				stream,
				telemetry,
				invokeAgentSpan,
				stepCounter,
				initialMessages,
				streamFn,
			),
		);
	} catch (err) {
		caughtError = err;
		throw err;
	} finally {
		finishInvokeAgentSpan(telemetry, invokeAgentSpan, {
			stepCount: stepCounter.count,
			errorObject: caughtError,
		});
	}
}

interface StepCounter {
	count: number;
}

/** Largest setTimeout delay before 32-bit overflow (Node/Bun fire in ~1 ms past this). */
const MAX_TIMER_MS = 2_147_483_647;

function isDeadlineExceeded(deadline: number | undefined): boolean {
	return deadline !== undefined && Date.now() >= deadline;
}

function endAgentStream(
	stream: EventStream<AgentEvent, AgentMessage[]>,
	newMessages: AgentMessage[],
	telemetry: AgentTelemetry | undefined,
	stepCount: number,
): void {
	stream.push(buildAgentEndEvent(newMessages, telemetry, stepCount));
	stream.end(newMessages);
}
function emitInputMessages(stream: EventStream<AgentEvent, AgentMessage[]>, messages: readonly AgentMessage[]): void {
	for (const message of messages) {
		stream.push({ type: "message_start", message });
		stream.push({ type: "message_end", message });
	}
}

/**
 * Append passive tool-call context after its results as a developer message.
 * Returns the injected message for turn-end bookkeeping, or undefined when
 * there is nothing to inject. Shared by the normal tool-call path and the
 * resume-tail replay so replayed calls deliver context identically.
 */
function injectExecutionAdditionalContext(
	currentContext: AgentContext,
	newMessages: AgentMessage[],
	stream: EventStream<AgentEvent, AgentMessage[]>,
	additionalContext: string | undefined,
): AgentMessage | undefined {
	if (additionalContext === undefined) return undefined;
	const contextMessage = createAdditionalContextMessage(additionalContext);
	currentContext.messages.push(contextMessage);
	newMessages.push(contextMessage);
	emitInputMessages(stream, [contextMessage]);
	return contextMessage;
}

/**
 * Resolve aside entries at the moment the loop is about to inject them. Each entry
 * is either a ready {@link AgentMessage} or a sync thunk evaluated here so the
 * producer can make the final inject-or-drop decision (return null) against
 * up-to-the-injection state — e.g. dropping late diagnostics a newer edit
 * superseded. Kept sync so it can never stall the loop.
 */
function resolveAsides(entries: AsideMessage[] | undefined): AgentMessage[] {
	if (!entries || entries.length === 0) return [];
	const out: AgentMessage[] = [];
	try {
		for (const entry of entries) {
			const message = typeof entry === "function" ? entry() : entry;
			if (message) out.push(message);
		}
	} catch (error) {
		discardAsides(out, toError(error));
		throw error;
	}
	return out;
}

function discardAsides(messages: readonly AgentMessage[], error: Error): void {
	for (const message of messages) {
		try {
			(message as CommittableAsideMessage)[ASIDE_MESSAGE_DISCARD]?.(error);
		} catch (discardError) {
			logger.error("Aside discard hook threw", { error: discardError });
		}
	}
}

async function runLoopBody(
	currentContext: AgentContext,
	newMessages: AgentMessage[],
	config: AgentLoopConfig,
	signal: AbortSignal | undefined,
	stream: EventStream<AgentEvent, AgentMessage[]>,
	telemetry: AgentTelemetry | undefined,
	invokeAgentSpan: Span | undefined,
	stepCounter: StepCounter,
	initialMessages: AgentMessage[],
	streamFn?: StreamFn,
): Promise<void> {
	let deadlineTimer: Timer | undefined;
	if (config.deadline !== undefined) {
		const deadline = config.deadline;
		const deadlineAbortController = new AbortController();
		const deadlineReason = new DOMException("Deadline exceeded", "TimeoutError");
		// setTimeout overflows past 2^31-1 ms and fires in ~1 ms, so a valid `--max-time 600h`
		// aborted the first turn at once: wait in bounded slices and recheck the deadline.
		const armDeadline = (): void => {
			const delay = deadline - Date.now();
			if (delay <= 0) deadlineAbortController.abort(deadlineReason);
			else deadlineTimer = setTimeout(armDeadline, Math.min(delay, MAX_TIMER_MS));
		};
		armDeadline();
		signal = signal ? AbortSignal.any([signal, deadlineAbortController.signal]) : deadlineAbortController.signal;
	}

	const softRequirementState = config.softToolRequirementState ?? { escalations: 0 };
	let preserveSoftRequirementState = false;

	let pendingMessages: AgentMessage[] = [];
	// Steering the provider took from the queue during the last response:
	// `liveAccepted` reached the model inside it, `liveDeferred` did not.
	let liveAccepted: AgentMessage[] = [];
	let liveDeferred: AgentMessage[] = [];
	const endAbortedBeforeModel = async (messages: AgentMessage[], turnOpen: boolean): Promise<boolean> => {
		if (!signal?.aborted || !config.isUndeliveredQueuedMessage) return false;
		const undelivered = new Set(messages.filter(message => config.isUndeliveredQueuedMessage?.(message)));
		for (const list of [currentContext.messages, newMessages]) {
			for (let i = list.length - 1; i >= 0; i--) {
				if (undelivered.has(list[i])) list.splice(i, 1);
			}
		}
		if (!turnOpen) stream.push({ type: "turn_start" });
		emitInputMessages(
			stream,
			messages.filter(message => !undelivered.has(message)),
		);
		const aborted = emitAbortedAssistantMessage(null, false, new Set(), currentContext, config, stream, signal);
		newMessages.push(aborted);
		await emitTurnEnd(stream, currentContext, aborted, [], config, signal, { willContinue: false });
		endAgentStream(stream, newMessages, telemetry, stepCounter.count);
		return true;
	};
	try {
		let messagesToEmit = [...initialMessages];
		if (isDeadlineExceeded(config.deadline)) {
			emitInputMessages(stream, messagesToEmit);
			endAgentStream(stream, newMessages, telemetry, stepCounter.count);
			return;
		}
		// Check for steering messages at start (user may have typed while waiting).
		// Skip when the run is already externally aborted — dequeuing would strand
		// the messages in a run that is about to die.
		try {
			pendingMessages = signal?.aborted ? [] : (await config.getSteeringMessages?.(signal)) || [];
		} catch (error) {
			if (signal?.aborted && (await endAbortedBeforeModel(messagesToEmit, false))) return;
			stream.push({ type: "turn_start" });
			emitInputMessages(stream, messagesToEmit);
			throw error;
		}
		let harmonyRetryAttempt = 0;
		let harmonyTruncateResumeCount = 0;
		let pausedTurnContinuations = 0;
		let dsmlLeakNudges = 0;

		// Soft tool requirement lifecycle (reminder then escalation; see SoftToolRequirement).
		// The host-owned state survives only a gate stop between Agent.prompt calls.
		// Resolved once per logical turn at the fetch site below and reused across
		// Harmony-leak re-samples (which re-enter the same turn) so the consuming
		// getToolChoice is never advanced twice; the flag resets at the message boundary.
		let hostToolChoice: ToolChoice | undefined;
		let softRequiredTool: string | undefined;
		let softSatisfies: SoftToolRequirement["satisfies"];
		let directiveResolvedForTurn = false;
		let turnOpen = false;
		// A trailing assistant message with unpaired tool calls: the harness
		// stripped the failed/aborted results so this run re-executes the calls
		// (AgentSession.retry's tool replay). Run them before the first model
		// call; the loop then continues normally on the fresh results. Queued
		// steering stays parked until after the batch — injecting a message
		// between the tool_use blocks and their results would break the
		// provider's pairing invariant.
		const resumeTail = unpairedToolCallTail(currentContext.messages);
		if (resumeTail) {
			stream.push({ type: "turn_start" });
			emitInputMessages(stream, messagesToEmit);
			messagesToEmit = [];
			turnOpen = true;
			const executionResult = await executeToolCalls(
				currentContext,
				resumeTail,
				signal,
				stream,
				config,
				telemetry,
				invokeAgentSpan,
				[],
			);
			for (const result of executionResult.toolResults) {
				currentContext.messages.push(result);
				newMessages.push(result);
			}
			const resumeContextMessage = injectExecutionAdditionalContext(
				currentContext,
				newMessages,
				stream,
				executionResult.additionalContext,
			);
			await emitTurnEnd(stream, currentContext, resumeTail, executionResult.toolResults, config, signal, {
				willContinue: !isDeadlineExceeded(config.deadline),
				...(resumeContextMessage ? { additionalMessages: [resumeContextMessage] } : {}),
			});
			turnOpen = false;
			// A tool hook may mark its completed result as terminal (e.g. subagent
			// yield) — same stop-before-next-model-call rule as the main loop.
			if (signal?.reason === TERMINAL_TOOL_RESULT_ABORT_REASON) {
				endAgentStream(stream, newMessages, telemetry, stepCounter.count);
				return;
			}
		}

		// Outer loop: continues when queued follow-up messages arrive after agent would stop.
		// On that path an aside may be revoked after drain, leaving no new work to run.
		let stoppedForFollowUp = false;
		outer: while (true) {
			let hasMoreToolCalls = true;

			// Inner loop: process tool calls and steering messages
			while (hasMoreToolCalls || pendingMessages.length > 0) {
				if (isDeadlineExceeded(config.deadline)) {
					emitInputMessages(stream, messagesToEmit);
					endAgentStream(stream, newMessages, telemetry, stepCounter.count);
					return;
				}
				// Park at the turn boundary while the process-wide pause gate is
				// engaged (host /pause). An external abort releases the park so a
				// cancelled run still unwinds while everything else stays frozen.
				if (agentPauseGate.paused) await waitForProcessPause(config, signal);
				if (pendingMessages.length > 0) {
					pendingMessages = pendingMessages.flatMap(message => {
						const refresh = (message as CommittableAsideMessage)[ASIDE_MESSAGE_REFRESH];
						if (!refresh) return [message];
						const fresh = refresh();
						return fresh ? [fresh] : [];
					});
				}
				if (stoppedForFollowUp && pendingMessages.length === 0) break outer;
				stoppedForFollowUp = false;

				// Build the provider-bound context before opening the turn. Queue
				// messages are added now but their events remain deferred until
				// provider preparation either succeeds or opens an error turn.
				const turnMessages = messagesToEmit;
				messagesToEmit = [];
				if (pendingMessages.length > 0) {
					for (const message of pendingMessages) {
						currentContext.messages.push(message);
						newMessages.push(message);
						turnMessages.push(message);
						(message as CommittableAsideMessage)[ASIDE_MESSAGE_COMMIT]?.();
					}
					pendingMessages = [];
				}

				let preparedProviderCall: PreparedProviderCall;
				let gateResult: AgentPreModelCallResult;
				const emitTurnInputs = () => {
					emitInputMessages(
						stream,
						signal?.aborted
							? turnMessages.filter(message => !config.isUndeliveredQueuedMessage?.(message))
							: turnMessages,
					);
				};
				try {
					if (config.syncContextBeforeModelCall) {
						await config.syncContextBeforeModelCall(currentContext, signal);
					}
					if (signal?.aborted && (await endAbortedBeforeModel(turnMessages, turnOpen))) return;

					if (!directiveResolvedForTurn) {
						const directive = signal?.aborted ? undefined : config.getToolChoice?.();
						const softReq = isSoftToolRequirement(directive) ? directive : undefined;
						hostToolChoice = directive === undefined || isSoftToolRequirement(directive) ? undefined : directive;
						softRequiredTool = softReq?.toolName;
						softSatisfies = softReq?.satisfies;
						const softRequirementId = softRequirementState.id;
						if (softReq !== undefined) {
							if (softReq.id !== softRequirementId) {
								softRequirementState.id = softReq.id;
								softRequirementState.forcedToolChoice = undefined;
								softRequirementState.escalations = 0;
								for (const reminder of softReq.reminder) {
									currentContext.messages.push(reminder);
									newMessages.push(reminder);
									turnMessages.push(reminder);
								}
							}
						} else {
							softRequirementState.id = undefined;
							softRequirementState.forcedToolChoice = undefined;
							softRequirementState.escalations = 0;
						}
						directiveResolvedForTurn = true;
					}

					preparedProviderCall = await prepareProviderCall(currentContext, config, signal);
					if (signal?.aborted && (await endAbortedBeforeModel(turnMessages, turnOpen))) return;
					preparedProviderCall.liveSteering = openLiveSteering(config, signal, preparedProviderCall);
					gateResult = (await config.beforeModelCall?.(preparedProviderCall.context, signal)) || undefined;
				} catch (error) {
					if (signal?.aborted && (await endAbortedBeforeModel(turnMessages, turnOpen))) return;
					if (!turnOpen) {
						stream.push({ type: "turn_start" });
						emitTurnInputs();
						turnOpen = true;
					}
					throw error;
				}
				if (signal?.aborted && (await endAbortedBeforeModel(turnMessages, turnOpen))) return;
				if (config.beforeModelCall && signal?.aborted) {
					gateResult = { stop: true };
				}
				if (gateResult?.stop) {
					if (gateResult.reason) {
						logger.debug("Agent loop stopped before the model call", { reason: gateResult.reason });
					}
					if (!turnOpen && !signal?.aborted) {
						try {
							config.onToolChoiceRejected?.();
						} catch (error) {
							stream.push({ type: "turn_start" });
							emitInputMessages(stream, turnMessages);
							turnOpen = true;
							throw error;
						}
					}
					emitInputMessages(stream, turnMessages);
					if (turnOpen) {
						const stopMessage = createGateStopMessage(preparedProviderCall.model, gateResult.reason);
						currentContext.messages.push(stopMessage);
						newMessages.push(stopMessage);
						stream.push({ type: "message_start", message: stopMessage });
						stream.push({ type: "message_end", message: stopMessage });
						await emitTurnEnd(
							stream,
							currentContext,
							stopMessage,
							[],
							config,
							signal,
							{ willContinue: false },
							true,
						);
						turnOpen = false;
					}
					preserveSoftRequirementState = !signal?.aborted;
					endAgentStream(stream, newMessages, telemetry, stepCounter.count);
					return;
				}

				if (!turnOpen) {
					stream.push({ type: "turn_start" });
					turnOpen = true;
				}

				// Stream assistant response
				let recovered: HarmonyRecoveredToolCall | undefined;
				let message: AssistantMessage;
				let inputsEmitted = false;
				try {
					if (agentPauseGate.paused) await waitForProcessPause(config, signal);
					message = await streamAssistantResponse(
						currentContext,
						config,
						signal,
						stream,
						telemetry,
						invokeAgentSpan,
						stepCounter,
						streamFn,
						harmonyRetryAttempt,
						hostToolChoice,
						softRequirementState.forcedToolChoice,
						preparedProviderCall,
						() => {
							if (config.isUndeliveredQueuedMessage) signal?.throwIfAborted();
							emitTurnInputs();
							inputsEmitted = true;
						},
						message => {
							const finalToolCalls = message.content.filter(
								(content): content is Extract<AssistantMessage["content"][number], { type: "toolCall" }> =>
									content.type === "toolCall" &&
									(content as CursorExecResolvedCarrier)[kCursorExecResolved] !== true,
							);
							if (
								finalToolCalls.length === 0 ||
								(message.stopReason !== "toolUse" && message.stopReason !== "stop") ||
								isDeadlineExceeded(config.deadline)
							) {
								return false;
							}
							const softGateActive =
								softRequiredTool !== undefined && !hardToolChoiceBlocks(config.toolChoice, softRequiredTool);
							return (
								!softGateActive ||
								finalToolCalls.every(
									toolCall => softSatisfies?.(toolCall) ?? toolCall.name === softRequiredTool,
								)
							);
						},
					);
					harmonyRetryAttempt = 0;
					harmonyTruncateResumeCount = 0;
				} catch (err) {
					if (!inputsEmitted) {
						if (signal?.aborted && (await endAbortedBeforeModel(turnMessages, turnOpen))) return;
						emitTurnInputs();
					}
					if (!(err instanceof HarmonyLeakInterruption)) throw err;
					if (err.recovered) {
						if (harmonyTruncateResumeCount >= 2) {
							await emitHarmonyAudit(config, err, "escalated", harmonyRetryAttempt);
							throw new Error(
								`GPT-5 Harmony leak recurred after truncate-and-resume recovery (${signalListLabel(err.detection.signals)}).`,
							);
						}
						harmonyTruncateResumeCount++;
						recovered = err.recovered;
						message = recovered.message;
						await emitHarmonyAudit(config, err, "truncate_resume", harmonyRetryAttempt);
						// A recovered message completes the turn, so the abort-retry counter
						// resets like the normal success path (the truncate-resume counter
						// keeps accumulating for its cross-turn cap).
						harmonyRetryAttempt = 0;
					} else {
						if (harmonyRetryAttempt >= 2) {
							await emitHarmonyAudit(config, err, "escalated", harmonyRetryAttempt);
							throw new Error(
								`GPT-5 Harmony leak persisted after ${harmonyRetryAttempt} retries (${signalListLabel(err.detection.signals)}).`,
							);
						}
						await emitHarmonyAudit(config, err, "abort_retry", harmonyRetryAttempt);
						harmonyRetryAttempt++;
						continue;
					}
				} finally {
					const channel = preparedProviderCall.liveSteering;
					if (channel) {
						liveAccepted.push(...channel.accepted);
						liveDeferred.push(...channel.deferred);
					}
				}
				if (recovered) {
					// Mint/repair ids before any snapshot: the recovered message skipped
					// the streamed prepare (the leak interruption landed first), and the
					// `message_start`/`message_end` copies below are what persistence and
					// every consumer retain. Repairing only at executeToolCalls would
					// leave those copies under a never-materialized id while the result
					// carries the minted one. The later prepare stays idempotent — the
					// repaired mark rides the snapshot (object spread), and the minted
					// ids are already claimed at run scope.
					ensureUniqueToolCallIds(message, toolCallIdsDispatchedUnder(currentContext));
					message = snapshotAssistantMessage(message);
					currentContext.messages.push(message);
					stream.push({ type: "message_start", message: snapshotAssistantMessage(message) });
					stream.push({ type: "message_end", message: snapshotAssistantMessage(message) });
				}
				newMessages.push(message);

				// The escalation choice (if any) applied to the call above; clear it so
				// only the single escalation turn carries the forced choice.
				softRequirementState.forcedToolChoice = undefined;

				// A fresh logical turn re-resolves the directive next iteration; a Harmony
				// retry `continue`s before this line and keeps the cached value.
				directiveResolvedForTurn = false;

				if (message.stopReason === "error" || message.stopReason === "aborted") {
					// Create placeholder tool results for any tool calls in the aborted message
					// This maintains the tool_use/tool_result pairing that the API requires
					type ToolCallContent = Extract<AssistantMessage["content"][number], { type: "toolCall" }>;
					// Cursor exec-resolved blocks already have their toolResult buffered
					// for out-of-band emission; a placeholder aborted result here would
					// pair a duplicate to the same toolCallId (issue #4348 codex review).
					const toolCalls = message.content.filter(
						(c): c is ToolCallContent =>
							c.type === "toolCall" && (c as CursorExecResolvedCarrier)[kCursorExecResolved] !== true,
					);
					// Provider-built aborted messages (stream error events) carry no
					// per-tool labels; derive them from a tool-scoped abort signal so
					// only the matching call is blamed and siblings stay neutral.
					const scopedAbort = toolScopedAbortReason(signal);
					const toolCallAbortMessages =
						message.toolCallAbortMessages ??
						(scopedAbort ? buildToolCallAbortMessages(message, scopedAbort) : undefined);
					const toolResults: ToolResultMessage[] = [];
					for (const toolCall of toolCalls) {
						const errorMessage = toolCallAbortMessages?.[toolCall.id] ?? message.errorMessage;
						const result = createAbortedToolResult(toolCall, stream, message.stopReason, errorMessage);
						currentContext.messages.push(result);
						newMessages.push(result);
						toolResults.push(result);
						// The placeholder result above keeps the API's tool_use/tool_result
						// pairing intact, but no execute_tool span is started for these
						// calls. Mirror the run-collector entry directly so the run
						// summary's tool counters and `coverage.toolsInvoked` reflect
						// what the user actually saw on the wire.
						recordSkippedTool(telemetry, {
							toolCallId: toolCall.id,
							toolName: toolCall.name,
							status: message.stopReason === "aborted" ? "aborted" : "error",
						});
					}
					await emitTurnEnd(stream, currentContext, message, toolResults, config, signal, { willContinue: false });
					turnOpen = false;

					stream.push(buildAgentEndEvent(newMessages, telemetry, stepCounter.count));
					stream.end(newMessages);
					return;
				}

				// Run tools whenever the turn carries tool_use blocks AND was not truncated.
				// `stop_reason` is provider metadata that never goes back on the wire, so it
				// does not gate continuation validity: replaying a tool_use turn with the
				// tool_results appended is accepted whether the turn ended on `tool_use` or
				// `end_turn` (adaptive/interleaved-thinking Opus routinely emits tool calls
				// under `end_turn`; verified against the live Anthropic API). The only
				// continuation hazard is a thinking block carrying a stale/invalid signature,
				// which `transformMessages` already neutralizes — it strips the signature on
				// non-`toolUse` turns and the encoder downgrades the unsigned block to text,
				// which the API accepts. So treat `stop` (end_turn/pause_turn) the same as
				// `toolUse`. `length` (max_tokens) is the one reason we must NOT run: the
				// trailing tool_use may be truncated with incomplete arguments — those calls
				// are abandoned below. (`error`/`aborted` already returned above.)
				type ToolCallContent = Extract<AssistantMessage["content"][number], { type: "toolCall" }>;
				// A Cursor exec-channel synthesized `toolCall` block carries
				// `kCursorExecResolved` because Cursor already executed the tool
				// server-side (via the bridge) and buffered the result for
				// out-of-band emission — running it here again would duplicate the
				// same side-effecting call (issue #4348 review by @chatgpt-codex-connector).
				const toolCalls = message.content.filter(
					(c): c is ToolCallContent =>
						c.type === "toolCall" && (c as CursorExecResolvedCarrier)[kCursorExecResolved] !== true,
				);
				const runnableStop = message.stopReason === "toolUse" || message.stopReason === "stop";
				hasMoreToolCalls = runnableStop && toolCalls.length > 0;

				const deadlinePassed = isDeadlineExceeded(config.deadline);
				if (hasMoreToolCalls && deadlinePassed) {
					hasMoreToolCalls = false;
				}

				// A turn is compliant ONLY when it calls the required tool and nothing
				// else — mirroring the forced-tool_choice turn, which can emit only that
				// tool. A required+detour batch is treated as non-compliant so detour
				// tools never run side effects while the requirement is still pending.
				const calledOnlyRequiredTool =
					softRequiredTool !== undefined &&
					toolCalls.length > 0 &&
					toolCalls.every(toolCall => softSatisfies?.(toolCall) ?? toolCall.name === softRequiredTool);
				const softGateActive =
					softRequiredTool !== undefined && !hardToolChoiceBlocks(config.toolChoice, softRequiredTool);
				const softNonCompliant = softGateActive && !calledOnlyRequiredTool;

				const toolResults: ToolResultMessage[] = [];
				const additionalMessages: AgentMessage[] = [];
				if (softNonCompliant && softRequiredTool !== undefined) {
					SpeculativeOperationCoordinator.discardForMessage(message, "soft tool requirement deferred execution");
					if (softRequirementState.escalations >= MAX_SOFT_TOOL_ESCALATIONS) {
						throw new Error(
							`Soft tool requirement '${softRequiredTool}' was not satisfied after ${MAX_SOFT_TOOL_ESCALATIONS} forced turns; aborting to avoid an unbounded force loop.`,
						);
					}
					// A soft-required tool is pending but the model called something else
					// (or yielded). Do NOT execute the detour — pair each call with a
					// skipped result and force the required tool next turn. This is the
					// only turn that changes toolChoice; a model that complies with the
					// reminder pays no message-cache invalidation. Re-engage so the loop
					// never yields while the requirement is unmet.
					for (const toolCall of toolCalls) {
						const result = createAbortedToolResult(
							toolCall,
							stream,
							"skipped",
							`Not executed: call the \`${softRequiredTool}\` tool to resolve the pending action before using other tools.`,
						);
						currentContext.messages.push(result);
						newMessages.push(result);
						toolResults.push(result);
						recordSkippedTool(telemetry, {
							toolCallId: toolCall.id,
							toolName: toolCall.name,
							status: "skipped",
						});
					}
					softRequirementState.forcedToolChoice = { type: "tool", name: softRequiredTool };
					softRequirementState.escalations++;
					hasMoreToolCalls = true;
				} else if (hasMoreToolCalls) {
					const executionResult = await executeToolCalls(
						currentContext,
						message,
						signal,
						stream,
						config,
						telemetry,
						invokeAgentSpan,
						[...liveAccepted, ...liveDeferred],
					);
					toolResults.push(...executionResult.toolResults);

					for (const result of toolResults) {
						currentContext.messages.push(result);
						newMessages.push(result);
					}
					const injectedContext = injectExecutionAdditionalContext(
						currentContext,
						newMessages,
						stream,
						executionResult.additionalContext,
					);
					if (injectedContext) additionalMessages.push(injectedContext);
				} else if (toolCalls.length > 0) {
					SpeculativeOperationCoordinator.discardForMessage(
						message,
						deadlinePassed ? "deadline exceeded before dispatch" : "final message was not runnable",
						deadlinePassed ? "aborted" : "discarded",
					);
					// Turn ended on a non-runnable reason (`length` truncation) or deadline was exceeded
					// but left toolCall blocks behind. pair each with a placeholder result.
					const skipReason = deadlinePassed ? "aborted" : message.stopReason === "length" ? "length" : "skipped";
					const skipErrMsg = deadlinePassed ? "Deadline exceeded" : undefined;
					for (const toolCall of toolCalls) {
						const result = createAbortedToolResult(toolCall, stream, skipReason, skipErrMsg);
						currentContext.messages.push(result);
						newMessages.push(result);
						toolResults.push(result);
						recordSkippedTool(telemetry, {
							toolCallId: toolCall.id,
							toolName: toolCall.name,
							status: deadlinePassed ? "aborted" : "skipped",
						});
					}
					if (message.stopReason === "length" && toolResults.length > 0 && !deadlinePassed) {
						hasMoreToolCalls = true;
					}
				}

				// A tool hook may mark its completed result as terminal (e.g. subagent yield).
				// Stop before the next provider call without changing external/user abort semantics.
				if (signal?.reason === TERMINAL_TOOL_RESULT_ABORT_REASON) {
					hasMoreToolCalls = false;
				}

				if (toolCalls.length > 0) {
					pausedTurnContinuations = 0;
					dsmlLeakNudges = 0;
				} else if (
					!hasMoreToolCalls &&
					message.stopReason === "stop" &&
					message.stopDetails?.type === "pause_turn" &&
					pausedTurnContinuations < MAX_PAUSED_TURN_CONTINUATIONS
				) {
					// Non-terminal stop: the provider ended the response but not the turn
					// (e.g. Codex `end_turn: false` on a commentary-only progress update).
					// Re-sample with the assistant message replayed so the model keeps
					// working; the next round folds steering/asides in like any other
					// mid-work turn.
					pausedTurnContinuations++;
					hasMoreToolCalls = true;
				} else if (
					!hasMoreToolCalls &&
					message.stopReason === "stop" &&
					dsmlLeakMessages.has(message) &&
					dsmlLeakNudges < MAX_DSML_LEAK_NUDGES
				) {
					// DeepSeek wrote its tool call as raw DSML text the healer could not
					// recover (often missing the opening envelope). The markup was
					// stripped before commit; without a nudge the loop would yield as if
					// the model were done, so tell it the call failed and re-sample.
					const nudge = injectExecutionAdditionalContext(
						currentContext,
						newMessages,
						stream,
						dsmlToolCallLeakPrompt,
					);
					if (nudge) additionalMessages.push(nudge);
					dsmlLeakNudges++;
					hasMoreToolCalls = true;
				}

				await emitTurnEnd(stream, currentContext, message, toolResults, config, signal, {
					additionalMessages,
					willContinue: hasMoreToolCalls && !isDeadlineExceeded(config.deadline),
				});
				turnOpen = false;

				if (isDeadlineExceeded(config.deadline)) {
					endAgentStream(stream, newMessages, telemetry, stepCounter.count);
					return;
				}
				// On external abort (user interrupt), leave the steering queue intact: the
				// session aborts then continues, delivering the queue into a fresh run.
				// Draining it here would inject the messages right before a model call that
				// instantly aborts — message lands in history, agent never responds. The
				// mid-batch interrupt poll only peeks (hasSteeringMessages), so the queue
				// still owns every message until this dequeue.
				// Aborted: live-taken steering stays unrecorded, so the agent returns
				// it to the queue for the continuation run.
				const live = signal?.aborted ? [] : [...liveAccepted, ...liveDeferred];
				const liveReachedModel = !signal?.aborted && liveAccepted.length > 0;
				if (liveReachedModel) {
					for (const message of liveAccepted) {
						if (message.role === "user") message.liveSteered = true;
					}
				}
				liveAccepted = [];
				liveDeferred = [];
				if (liveReachedModel) {
					// The server continues from exactly this steering; anything else
					// queued now would not line up with its continuation, so it waits
					// for the next boundary (or is steered into that response).
					pendingMessages = live;
				} else {
					const steering = signal?.aborted
						? []
						: [...live, ...((await config.getSteeringMessages?.(signal)) || [])];
					if (hasMoreToolCalls) {
						// Mid-work: fold any non-interrupting asides into the next turn alongside steering.
						const asides = signal?.aborted ? [] : resolveAsides(await config.getAsideMessages?.("work"));
						pendingMessages = asides.length > 0 ? [...steering, ...asides] : steering;
					} else {
						// Stop boundary: only steering (live user input) forces another turn here. Leave
						// asides for the outer drain below so a passive aside can't trigger an extra model
						// turn ahead of a queued follow-up — the outer drain batches asides + follow-ups together.
						pendingMessages = steering;
					}
				}
			}

			if (isDeadlineExceeded(config.deadline)) {
				endAgentStream(stream, newMessages, telemetry, stepCounter.count);
				return;
			}

			// Agent would stop here. Drain non-interrupting asides + follow-up messages.
			await config.onBeforeYield?.();

			if (isDeadlineExceeded(config.deadline)) {
				endAgentStream(stream, newMessages, telemetry, stepCounter.count);
				return;
			}
			// Skip queue drains when externally aborted (same stranding hazard as above).
			// Re-poll steering too: a steer can land between the stop-boundary dequeue
			// above and this yield point (e.g. queued while onBeforeYield ran). Without
			// this poll it would strand in the queue until the next manual prompt.
			const lateSteering = signal?.aborted ? [] : (await config.getSteeringMessages?.(signal)) || [];
			const asideMessages = signal?.aborted ? [] : resolveAsides(await config.getAsideMessages?.("stop"));
			const followUpMessages = signal?.aborted ? [] : (await config.getFollowUpMessages?.(signal)) || [];
			if (lateSteering.length > 0 || asideMessages.length > 0 || followUpMessages.length > 0) {
				// Set as pending so the inner loop processes them before stopping.
				pendingMessages = [...lateSteering, ...asideMessages, ...followUpMessages];
				stoppedForFollowUp = true;
				continue;
			}

			// No more messages, exit
			break;
		}

		endAgentStream(stream, newMessages, telemetry, stepCounter.count);
	} finally {
		discardAsides(pendingMessages, new Error("Aside message was not committed before the agent loop ended"));
		if (!preserveSoftRequirementState) {
			softRequirementState.id = undefined;
			softRequirementState.forcedToolChoice = undefined;
			softRequirementState.escalations = 0;
		}
		if (deadlineTimer) {
			clearTimeout(deadlineTimer);
		}
	}
}

async function emitHarmonyAudit(
	config: AgentLoopConfig,
	interruption: HarmonyLeakInterruption,
	action: "truncate_resume" | "abort_retry" | "escalated",
	retryN: number,
): Promise<void> {
	await config.onHarmonyLeak?.(
		createHarmonyAuditEvent({
			action,
			detection: interruption.detection,
			model: config.getModel?.() ?? config.model,
			retryN,
			removed: interruption.removed,
		}),
	);
}

interface PreparedProviderCall {
	model: Model;
	context: Context;
	promptToolWireTools: Context["tools"];
	ownedDialect: Dialect | undefined;
	/** Steering source offered to the provider for this call. */
	liveSteering?: LiveSteeringChannel;
}

/**
 * Classify the first `count` steering messages for a tool-batch interrupt:
 * any user-authored message wins, then agent-attributed user messages, else
 * system steering (advisor cards, hidden directives). Shared by the agent's
 * queue peek and the loop's live-taken steering.
 */
export function steeringQueueState(messages: readonly AgentMessage[], count = messages.length): SteeringQueueState {
	if (count === 0) return { queued: false };
	let hasAgentSteering = false;
	for (let i = 0; i < count; i++) {
		const message = messages[i];
		const role = "role" in message ? message.role : undefined;
		const attribution = "attribution" in message ? message.attribution : undefined;
		if (attribution === "user") return { queued: true, source: "user" };
		if (role !== "user") continue;
		if (attribution !== "agent") return { queued: true, source: "user" };
		hasAgentSteering = true;
	}
	return { queued: true, source: hasAgentSteering ? "agent" : "system" };
}

/**
 * Offer queued steering to a provider that can deliver it into the response it
 * is streaming. Latency decides whether steering lands before the model commits
 * to its next output, so claims convert only the steering batch — message-level
 * transforms (steering envelope, redaction) — never the whole transcript.
 * Provider-context transforms rewrite images, so image-bearing steering waits
 * for the boundary rather than risk bytes the next request would not replay.
 */
function openLiveSteering(
	config: AgentLoopConfig,
	loopSignal: AbortSignal | undefined,
	prepared: PreparedProviderCall,
): LiveSteeringChannel | undefined {
	const { getSteeringMessages, waitForSteeringMessages } = config;
	if (!getSteeringMessages || !waitForSteeringMessages || prepared.ownedDialect) return undefined;
	const bound = (signal: AbortSignal): AbortSignal => (loopSignal ? AbortSignal.any([signal, loopSignal]) : signal);
	return new LiveSteeringChannel({
		wait: signal => waitForSteeringMessages(bound(signal)),
		take: async signal => {
			const messages = await getSteeringMessages(bound(signal));
			if (messages.length > 0) config.onLiveSteeringTaken?.(messages);
			return messages;
		},
		toProvider: async (messages, signal) => {
			const transformed = config.transformContext
				? await config.transformContext(messages, bound(signal))
				: messages;
			const converted = normalizeMessagesForProvider(await config.convertToLlm(transformed), prepared.model);
			const userMessages: UserMessage[] = [];
			for (const message of converted) {
				if (message.role !== "user") return undefined;
				if (typeof message.content !== "string" && message.content.some(part => part.type === "image")) {
					return undefined;
				}
				userMessages.push(message);
			}
			return userMessages.length > 0 ? userMessages : undefined;
		},
	});
}

async function prepareProviderCall(
	context: AgentContext,
	config: AgentLoopConfig,
	signal: AbortSignal | undefined,
): Promise<PreparedProviderCall> {
	const model = config.getModel?.() ?? config.model;
	let messages = context.messages;
	if (config.transformContext) {
		messages = await config.transformContext(messages, signal);
	}

	const llmMessages = await config.convertToLlm(messages);
	const normalizedMessages = normalizeMessagesForProvider(llmMessages, model);
	const ownedDialect: Dialect | undefined =
		(config.getDialect ? config.getDialect(model) : config.dialect) ?? resolveOwnedDialectFromEnv(Bun.env.PI_DIALECT);
	const pruneToolDescriptions = !!config.pruneToolDescriptions && !ownedDialect;
	let llmContext: Context;
	if (config.appendOnlyContext) {
		config.appendOnlyContext.syncMessages(normalizedMessages);
		llmContext = config.appendOnlyContext.build(context, {
			intentTracing: !!config.intentTracing,
			intentDescription: config.intentDescription,
			pruneToolDescriptions,
		});
	} else {
		llmContext = {
			systemPrompt: context.systemPrompt,
			messages: normalizedMessages,
			tools: normalizeTools(context.tools, {
				injectIntent: !!config.intentTracing,
				intentDescription: config.intentDescription,
				pruneDescriptions: pruneToolDescriptions,
			}),
		};
	}
	// Before the transform too, so a request-size clamp in it measures the withdrawn definitions the provider
	// re-declares; recomputed below against what the transform returns.
	if (config.sentToolDefinitions) llmContext = config.sentToolDefinitions.withInactiveTools(llmContext);
	if (config.transformProviderContext) {
		llmContext = await config.transformProviderContext(llmContext, model);
	}

	let promptToolWireTools: Context["tools"];
	if (ownedDialect && llmContext.tools && llmContext.tools.length > 0) {
		promptToolWireTools = llmContext.tools;
		llmContext = {
			...llmContext,
			systemPrompt: [...(llmContext.systemPrompt ?? []), renderInbandToolPrompt(promptToolWireTools, ownedDialect)],
			messages: encodeInbandToolHistory(llmContext.messages, ownedDialect, promptToolWireTools),
			tools: undefined,
		};
	}
	// After `transformProviderContext`, so the recorded definitions are exactly what the provider receives.
	if (config.sentToolDefinitions) {
		if (llmContext.tools) config.sentToolDefinitions.record(llmContext.tools);
		llmContext = config.sentToolDefinitions.withInactiveTools(llmContext);
	}
	return { model, context: llmContext, promptToolWireTools, ownedDialect };
}

/**
 * Stream an assistant response from the LLM.
 * This is where AgentMessage[] gets transformed to Message[] for the LLM.
 */
async function streamAssistantResponse(
	context: AgentContext,
	config: AgentLoopConfig,
	signal: AbortSignal | undefined,
	stream: EventStream<AgentEvent, AgentMessage[]>,
	telemetry: AgentTelemetry | undefined,
	invokeAgentSpan: Span | undefined,
	stepCounter: StepCounter,
	streamFn?: StreamFn,
	harmonyRetryAttempt = 0,
	hostToolChoice?: ToolChoice,
	forcedToolChoice?: ToolChoice,
	prepared?: PreparedProviderCall,
	onProviderStart?: () => void,
	canDispatchFinalToolCalls?: (message: AssistantMessage) => boolean,
): Promise<AssistantMessage> {
	const providerCall = prepared ?? (await prepareProviderCall(context, config, signal));
	const { model, context: llmContext, promptToolWireTools, ownedDialect } = providerCall;

	const streamFunction = streamFn || streamSimple;

	const dynamicReasoning = config.getReasoning?.();
	const dynamicDisableReasoning = config.getDisableReasoning?.();
	// `getServiceTier` is authoritative when present (replaces the static tier
	// for both the wire request and telemetry), so callers can scope priority
	// per model without touching the shared session `serviceTier`.
	const effectiveServiceTier = config.getServiceTier ? config.getServiceTier(model) : config.serviceTier;
	const harmonyMitigationEnabled = isHarmonyLeakMitigationTarget(model);
	const dsmlLeakRecoveryEnabled = isDsmlLeakRecoveryTarget(model);
	const harmonyAbortController = harmonyMitigationEnabled ? new AbortController() : undefined;
	const requestSignal = harmonyAbortController
		? signal
			? AbortSignal.any([signal, harmonyAbortController.signal])
			: harmonyAbortController.signal
		: signal;
	// Owned tool calling: aborted by the stream wrapper when the model starts
	// fabricating a `<tool_response>`, so the provider stops generating the rest of
	// the hallucinated turn. Merged into the provider signal ONLY (not
	// `requestSignal`), so it cancels the request without tripping the loop's
	// external-abort handling (`abortRacePromise` / `requestSignal.aborted`).
	const promptToolAbortController = ownedDialect ? new AbortController() : undefined;
	const providerAbortSignals: AbortSignal[] = [];
	if (requestSignal) providerAbortSignals.push(requestSignal);
	if (promptToolAbortController) providerAbortSignals.push(promptToolAbortController.signal);
	const finalRequestSignal =
		providerAbortSignals.length === 0
			? undefined
			: providerAbortSignals.length === 1
				? providerAbortSignals[0]!
				: AbortSignal.any(providerAbortSignals);
	const requestApiKey = (config.getApiKey ? await config.getApiKey(model) : undefined) ?? config.apiKey;
	let resolvedCredential: ApiKeyResolution;
	const resolvedApiKey = await resolveApiKeyOnce(requestApiKey, finalRequestSignal, resolved => {
		resolvedCredential = resolved;
	});
	const apiKey = isApiKeyResolver(requestApiKey)
		? seedApiKeyResolver(resolvedCredential ?? resolvedApiKey, requestApiKey)
		: requestApiKey;

	// Re-resolve metadata after credential selection so the per-request value
	// reflects the credential actually used, not the snapshot from AgentLoopConfig construction.
	const resolvedMetadata = config.metadataResolver ? config.metadataResolver(model.provider) : config.metadata;
	const effectiveTemperature =
		harmonyRetryAttempt > 0 && config.temperature !== undefined ? config.temperature + 0.05 : config.temperature;
	// Owned tool calling sends no native tools, so any tool_choice would error.
	const effectiveToolChoice = ownedDialect ? undefined : (hostToolChoice ?? forcedToolChoice ?? config.toolChoice);
	const effectiveReasoning = dynamicReasoning ?? config.reasoning;
	const effectiveDisableReasoning = dynamicDisableReasoning ?? config.disableReasoning;
	// `getCwd` is read once per LLM call so a mid-run session move (`/move`) reaches
	// workspace-scoped provider discovery; falls back to the static `cwd` when unset.
	const effectiveCwd = config.getCwd?.() ?? config.cwd;

	const chatStepNumber = stepCounter.count;
	stepCounter.count += 1;
	const chatSpan = startChatSpan(telemetry, model, {
		parent: invokeAgentSpan,
		stepNumber: chatStepNumber,
		request: {
			maxTokens: config.maxTokens,
			temperature: effectiveTemperature,
			topP: config.topP,
			topK: config.topK,
			presencePenalty: config.presencePenalty,
			serviceTier: effectiveServiceTier,
			reasoningEffort: typeof effectiveReasoning === "string" ? effectiveReasoning : undefined,
			toolChoice: effectiveToolChoice,
			tools: llmContext.tools,
			systemPrompt: llmContext.systemPrompt,
			messages: llmContext.messages,
		},
	});

	// Wrap the user-supplied onResponse so we always observe response headers
	// for telemetry (`ChatUsageEvent.headers`, gateway auto-detection) without
	// stealing them from the configured hook.
	let capturedHeaders: Readonly<Record<string, string>> | undefined;
	const userOnResponse = config.onResponse;
	const captureOnResponse: AgentLoopConfig["onResponse"] = (response, modelInfo) => {
		capturedHeaders = response.headers;
		return userOnResponse?.(response, modelInfo);
	};

	// Cursor executes its tools server-side during the stream and hands each
	// result to `cursorOnToolResult`; the host persists them after the assistant
	// message, so this loop never runs them and never sees them. A follow-up the
	// loop picks up after this turn needs them in its own context, or the next
	// request rebuilds this turn with every call unpaired. The host follows the
	// results with one message carrying their passive context, so that is
	// mirrored too. Entries are reserved synchronously so concurrent transforms
	// keep their arrival order. When the server re-sends a call it already ran
	// (issue #15749), the newer result replaces the earlier one, matching the
	// single result the host persists.
	const cursorToolResults: {
		result: ToolResultMessage;
		additionalContext: string | undefined;
		/** The host transform, which the provider does not always await. */
		pending: Promise<void>;
	}[] = [];
	const userCursorOnToolResult = config.cursorOnToolResult;
	const collectCursorToolResult: AgentLoopConfig["cursorOnToolResult"] = userCursorOnToolResult
		? async result => {
				const superseded = cursorToolResults.findIndex(entry => entry.result.toolCallId === result.toolCallId);
				if (superseded >= 0) cursorToolResults.splice(superseded, 1);
				// Read before the transform, which may return a message without it.
				const additionalContext = (result as ToolResultWithAdditionalContext)[TOOL_RESULT_ADDITIONAL_CONTEXT];
				const { promise: pending, resolve: settle } = Promise.withResolvers<void>();
				const entry = { result, additionalContext, pending };
				cursorToolResults.push(entry);
				try {
					const settled = await userCursorOnToolResult(result);
					if (settled) entry.result = settled;
					return settled;
				} finally {
					settle();
				}
			}
		: undefined;
	// Like the host before it persists, wait for transforms still running so the
	// next request carries the result the transcript stores.
	const appendCursorToolResults = async (): Promise<void> => {
		await Promise.all(cursorToolResults.map(entry => entry.pending));
		for (const { result } of cursorToolResults) context.messages.push(result);
		const additionalContext = joinAdditionalContext(cursorToolResults.map(entry => entry.additionalContext));
		if (additionalContext !== undefined) context.messages.push(createAdditionalContextMessage(additionalContext));
	};

	const finishChat = async (message: AssistantMessage): Promise<void> => {
		await finishChatSpan(telemetry, chatSpan, message, {
			stepNumber: chatStepNumber,
			modelId: model.id,
			serviceTier: effectiveServiceTier,
			responseHeaders: capturedHeaders,
			baseUrl: model.baseUrl,
		});
	};

	try {
		return await runInActiveSpan(chatSpan, async () => {
			onProviderStart?.();
			let response = await streamFunction(model, llmContext, {
				...config,
				apiKey,
				metadata: resolvedMetadata,
				toolChoice: effectiveToolChoice,
				reasoning: effectiveReasoning,
				disableReasoning: effectiveDisableReasoning,
				temperature: effectiveTemperature,
				serviceTier: effectiveServiceTier,
				cwd: effectiveCwd,
				signal: finalRequestSignal,
				onResponse: captureOnResponse,
				cursorOnToolResult: collectCursorToolResult,
				liveSteering: providerCall.liveSteering,
			});
			if (promptToolWireTools && ownedDialect) {
				// Re-materialize in-band tool-call text as native toolCall content blocks
				// so the rest of the loop executes them unchanged. When the model starts
				// fabricating tool results, the abort callback cancels the provider — unless
				// `abortOnFabricatedToolResult` is false, in which case the stream drains and
				// the fabricated continuation is discarded without aborting.
				response = wrapInbandToolStream(
					response,
					promptToolWireTools,
					ownedDialect,
					() => promptToolAbortController?.abort(),
					config.abortOnFabricatedToolResult ?? true,
				);
			}

			let partialMessage: AssistantMessage | null = null;
			let addedPartial = false;
			// Previous `message_update` snapshot for the incremental rebuild below;
			// null until the turn's `start` event seeds it.
			let turnSnapshot: AssistantMessage | null = null;
			// Content indices of blocks that started streaming but have not ended
			// yet — re-cloned on every delta because live blocks may be patched
			// without a paired event (Cursor's silent edit-block merge).
			const openBlocks = new Set<number>();
			const completedToolCallIds = new Set<string>();
			const argStreams = new Map<number, { id: string; stream: AgentToolArgStream }>();
			const cancelArgStreams = (): void => {
				for (const { id, stream: argStream } of argStreams.values()) {
					try {
						argStream.cancel();
					} catch (error) {
						logger.debug("Tool argument stream cancel failed", { toolCallId: id, error });
					}
				}
				argStreams.clear();
			};
			const speculationConfig =
				config.speculativeToolExecution?.enabled === true ? config.speculativeToolExecution : undefined;
			const speculationCoordinator = speculationConfig
				? new SpeculativeOperationCoordinator(speculationConfig, {
						context,
						loopConfig: config,
						signal: requestSignal,
					})
				: undefined;
			const speculationPlansFromStream =
				!config.transformAssistantMessage || config.transformAssistantMessagePreservesToolCalls === true;

			let providerStreamSettled = false;
			let speculationSettled = false;
			const responseIterator = response[Symbol.asyncIterator]();
			const finishAbortedStream = async (): Promise<AssistantMessage> => {
				try {
					const cleanup = responseIterator.return?.();
					if (cleanup) void cleanup.catch(() => {});
				} catch {
					// Provider cancellation failures cannot change the committed aborted message.
				}
				await speculationCoordinator?.discardAll("run aborted", "aborted");
				speculationSettled = true;
				const aborted = emitAbortedAssistantMessage(
					partialMessage,
					addedPartial,
					completedToolCallIds,
					context,
					config,
					stream,
					requestSignal,
				);
				await finishChat(aborted);
				return aborted;
			};

			// Set up a single abort race: register the abort listener once for the whole
			// stream and reuse the same race promise for every iterator.next() instead of
			// allocating Promise.withResolvers and add/removeEventListener per event.
			let abortRacePromise: Promise<typeof ABORTED> | undefined;
			let detachAbortListener: (() => void) | undefined;
			if (requestSignal) {
				if (requestSignal.aborted) {
					return await finishAbortedStream();
				}
				const { promise, resolve } = Promise.withResolvers<typeof ABORTED>();
				const onAbort = () => resolve(ABORTED);
				requestSignal.addEventListener("abort", onAbort, { once: true });
				abortRacePromise = promise;
				detachAbortListener = () => requestSignal.removeEventListener("abort", onAbort);
			}

			try {
				while (true) {
					let next: IteratorResult<AssistantMessageEvent>;
					if (abortRacePromise) {
						const result = await Promise.race([responseIterator.next(), abortRacePromise]);
						if (result === ABORTED) {
							return await finishAbortedStream();
						}
						next = result;
					} else {
						next = await responseIterator.next();
					}
					if (next.done) {
						providerStreamSettled = true;
						break;
					}

					const event = next.value;
					if (event.type === "done" || event.type === "error") {
						let finalMessage = recoverTransientErrorToolTurn(
							retainCompletedToolCalls(await response.result(), completedToolCallIds),
							context.tools ?? [],
						);
						if (harmonyMitigationEnabled) {
							const detection = detectHarmonyLeakInAssistantMessage(finalMessage);
							if (detection) {
								const recovered = recoverHarmonyToolCall(finalMessage, detection);
								const removed = recovered?.removed ?? extractHarmonyRemoved(finalMessage, detection);
								if (addedPartial) {
									emitDiscardedHarmonyPartial(
										partialMessage,
										stream,
										`Discarded after GPT-5 Harmony protocol leakage (${signalListLabel(detection.signals)})`,
									);
									context.messages.pop();
									addedPartial = false;
								}
								throw new HarmonyLeakInterruption(detection, removed, recovered);
							}
						}
						finalMessage = snapshotAssistantMessage(finalMessage);
						// Unhealed DSML markup must not reach history, including reasoning
						// and turns with a valid structured call. Only a failed text-only
						// call needs the recovery nudge.
						if (dsmlLeakRecoveryEnabled) {
							const hasToolCall = finalMessage.content.some(block => block.type === "toolCall");
							const removed = removeDsmlToolMarkupLeak(finalMessage);
							if (removed && finalMessage.stopReason === "stop" && !hasToolCall) {
								dsmlLeakMessages.add(finalMessage);
							}
						}
						// Expand inline macros (and any other registered rewrite) on the
						// finalized message before it reaches the context, the UI, or tool
						// dispatch — so a single mutation is the source of truth for all three.
						if (config.transformAssistantMessage) {
							await config.transformAssistantMessage(finalMessage, requestSignal);
						}
						// A pre-dispatch hook may request approval or change external state, so
						// do not run it until the outer loop has established this tool turn can
						// actually dispatch. The same gate keeps host-deferred speculation from
						// being released for truncated, expired, or soft-tool-rejected turns.
						const finalToolCallsCanDispatch =
							!requestSignal?.aborted &&
							(canDispatchFinalToolCalls?.(finalMessage) ??
								(finalMessage.stopReason !== "error" &&
									finalMessage.stopReason !== "aborted" &&
									finalMessage.stopReason !== "length"));
						const preparedDispatch = finalToolCallsCanDispatch
							? await prepareToolCallDispatch(finalMessage, context, config, requestSignal)
							: undefined;
						if (preparedDispatch?.size) {
							preparedDispatchByMessage.set(finalMessage, preparedDispatch);
						}
						if (speculationCoordinator) {
							if (!finalToolCallsCanDispatch || !preparedDispatch) {
								await speculationCoordinator.discardAll(
									"final message cannot reach tool dispatch",
									requestSignal?.aborted ? "aborted" : "discarded",
								);
							} else {
								await speculationCoordinator.reconcileFinalCalls(
									await speculativeFinalCalls(
										finalMessage,
										preparedDispatch,
										config.transformToolCallArguments,
										speculationCoordinator,
									),
								);
								await speculationCoordinator.finalizeAdmissions();
								speculationCoordinator.attach(finalMessage);
							}
						}
						if (addedPartial) {
							context.messages[context.messages.length - 1] = finalMessage;
						} else {
							context.messages.push(finalMessage);
						}
						await appendCursorToolResults();
						if (!addedPartial) {
							stream.push({ type: "message_start", message: snapshotAssistantMessage(finalMessage) });
						}
						stream.push({ type: "message_end", message: snapshotAssistantMessage(finalMessage) });
						await finishChat(finalMessage);
						speculationSettled = true;
						providerStreamSettled = true;
						return finalMessage;
					}
					if (requestSignal?.aborted) {
						return await finishAbortedStream();
					}

					if (event.type === "toolcall_start") {
						const block = event.partial.content[event.contentIndex];
						if (block?.type === "toolCall") {
							const tool = resolveToolForCall(context.tools, block, config.resolveFallbackTool);
							if (tool?.openArgStream) {
								try {
									const argStream = tool.openArgStream({
										toolCallId: block.id,
										toolName: block.name,
										customWireName: block.customWireName,
										emit: update =>
											stream.push({
												type: "tool_stream_update",
												toolCallId: block.id,
												toolName: block.name,
												update,
											}),
									});
									if (argStream) argStreams.set(event.contentIndex, { id: block.id, stream: argStream });
								} catch (error) {
									logger.debug("Tool argument stream open failed", { toolCallId: block.id, error });
								}
							}
						}
					} else if (event.type === "toolcall_delta") {
						const entry = argStreams.get(event.contentIndex);
						if (entry) {
							try {
								entry.stream.push(event.delta);
							} catch (error) {
								logger.debug("Tool argument stream push failed", { toolCallId: entry.id, error });
							}
						}
					} else if (event.type === "toolcall_end") {
						const entry = argStreams.get(event.contentIndex);
						if (entry) {
							try {
								entry.stream.end(event.toolCall.arguments);
							} catch (error) {
								logger.debug("Tool argument stream end failed", { toolCallId: entry.id, error });
							} finally {
								argStreams.delete(event.contentIndex);
							}
						}
					}

					switch (event.type) {
						case "start":
							partialMessage = event.partial;
							if (addedPartial) {
								context.messages[context.messages.length - 1] = partialMessage;
								completedToolCallIds.clear();
								// `message` and `assistantMessageEvent.partial` intentionally share one
								// immutable snapshot of the streaming partial: every message_update
								// consumer treats both as read-only, so cloning the identical partial
								// twice per delta was pure waste.
								const messageSnapshot = snapshotAssistantMessage(partialMessage);
								turnSnapshot = messageSnapshot;
								openBlocks.clear();
								stream.push({
									type: "message_update",
									assistantMessageEvent: snapshotAssistantMessageEvent(event, messageSnapshot),
									message: messageSnapshot,
								});
							} else {
								context.messages.push(partialMessage);
								addedPartial = true;
								turnSnapshot = snapshotAssistantMessage(partialMessage);
								stream.push({ type: "message_start", message: turnSnapshot });
							}
							break;

						case "text_start":
						case "text_delta":
						case "text_end":
						case "image_end":
						case "thinking_start":
						case "thinking_delta":
						case "thinking_end":
						case "toolcall_start":
						case "toolcall_delta":
						case "toolcall_end":
							if (partialMessage) {
								if (event.type === "toolcall_start" && speculationCoordinator && speculationPlansFromStream) {
									// Stream sessions plan from pre-transform arguments, exactly like
									// direct candidates (see admitFinalized below): with a transformer
									// that may rewrite calls, the authoritative call may differ, so any
									// speculative work started from the original would be phantom I/O.
									speculationCoordinator.register(event.contentIndex);
									const toolCall = event.partial.content[event.contentIndex];
									if (toolCall?.type === "toolCall") {
										const tool = context.tools?.find(candidate => candidate.name === toolCall.name);
										try {
											const session = await tool?.speculation?.stream?.open({
												coordinator: speculationCoordinator,
												parentToolCallId: toolCall.id,
											});
											if (session) {
												if (!speculationCoordinator.registerStreamSession(toolCall.id, session)) {
													await session.discard("stream speculation coordinator rejected session");
												}
											}
										} catch {
											await speculationCoordinator.discardStreamSession(
												toolCall.id,
												"stream speculation policy failed to open",
											);
										}
									}
								}
								if (event.type === "toolcall_delta") {
									const toolCall = event.partial.content[event.contentIndex];
									if (toolCall?.type === "toolCall") {
										try {
											await speculationCoordinator
												?.streamSession(toolCall.id)
												?.update(toolCall, getStreamingPartialJson(toolCall));
										} catch {
											await speculationCoordinator?.discardStreamSession(
												toolCall.id,
												"stream speculation update failed",
											);
										}
									}
								}
								if (event.type === "toolcall_end") {
									completedToolCallIds.add(event.toolCall.id);
									const session = speculationCoordinator?.streamSession(event.toolCall.id);
									try {
										await session?.finalize({
											toolCall: event.toolCall,
											args:
												event.toolCall.arguments && typeof event.toolCall.arguments === "object"
													? (event.toolCall.arguments as Record<string, unknown>)
													: {},
										});
									} catch {
										await speculationCoordinator?.discardStreamSession(
											event.toolCall.id,
											"stream speculation finalize failed",
										);
									}
								}
								partialMessage = event.partial;
								context.messages[context.messages.length - 1] = partialMessage;
								config.onAssistantMessageEvent?.(partialMessage, event);
								// Track which blocks are still streaming: open blocks are
								// re-cloned on every delta, finalized blocks are shared.
								const contentIndex = (event as { contentIndex?: number }).contentIndex;
								if (contentIndex !== undefined) {
									if (event.type.endsWith("_start")) openBlocks.add(contentIndex);
									else if (event.type.endsWith("_end")) openBlocks.delete(contentIndex);
								}
								// READ-ONLY-CONSUMER INVARIANT: `message` and
								// `assistantMessageEvent.partial` intentionally share one snapshot,
								// and the snapshot is rebuilt incrementally — only the delta's
								// block, open blocks, and newly appended blocks are deep-cloned;
								// finalized blocks are carried over from the previous snapshot by
								// reference (see `snapshotAssistantMessageIncremental`), so they are
								// shared across ALL message_update snapshots of the turn.
								// Consumers MUST treat both fields — and every content block inside
								// them — as read-only: mutating a snapshot would corrupt every
								// earlier and later snapshot of the turn, not just this one. In
								// exchange, per-delta work is proportional to the live stream
								// instead of the whole turn (issue #10605).
								const messageSnapshot: AssistantMessage = turnSnapshot
									? snapshotAssistantMessageIncremental(
											partialMessage,
											turnSnapshot,
											contentIndex ?? -1,
											openBlocks,
										)
									: snapshotAssistantMessage(partialMessage);
								turnSnapshot = messageSnapshot;
								stream.push({
									type: "message_update",
									assistantMessageEvent: snapshotAssistantMessageEvent(event, messageSnapshot),
									message: messageSnapshot,
								});
							}
							if (
								event.type === "toolcall_end" &&
								speculationCoordinator &&
								speculationConfig &&
								speculationPlansFromStream
							) {
								speculationCoordinator.admitFinalized(context, event.toolCall, config, requestSignal);
							}
							break;
					}
				}
			} finally {
				detachAbortListener?.();
				cancelArgStreams();
				if (!providerStreamSettled) {
					await speculationCoordinator?.discardAll("provider stream failed", "aborted");
					speculationSettled = true;
				}
			}

			try {
				let trailing = recoverTransientErrorToolTurn(
					retainCompletedToolCalls(await response.result(), completedToolCallIds),
					context.tools ?? [],
				);
				if (harmonyMitigationEnabled) {
					const detection = detectHarmonyLeakInAssistantMessage(trailing);
					if (detection) {
						const recovered = recoverHarmonyToolCall(trailing, detection);
						const removed = recovered?.removed ?? extractHarmonyRemoved(trailing, detection);
						if (addedPartial) {
							emitDiscardedHarmonyPartial(
								partialMessage,
								stream,
								`Discarded after GPT-5 Harmony protocol leakage (${signalListLabel(detection.signals)})`,
							);
							context.messages.pop();
							addedPartial = false;
						}
						throw new HarmonyLeakInterruption(detection, removed, recovered);
					}
				}
				if (config.transformAssistantMessage) {
					await config.transformAssistantMessage(trailing, requestSignal);
				}
				trailing = snapshotAssistantMessage(trailing);
				const finalToolCallsCanDispatch =
					!requestSignal?.aborted &&
					(canDispatchFinalToolCalls?.(trailing) ??
						(trailing.stopReason !== "error" &&
							trailing.stopReason !== "aborted" &&
							trailing.stopReason !== "length"));
				const preparedDispatch = finalToolCallsCanDispatch
					? await prepareToolCallDispatch(trailing, context, config, requestSignal)
					: undefined;
				if (preparedDispatch?.size) {
					preparedDispatchByMessage.set(trailing, preparedDispatch);
				}
				if (speculationCoordinator) {
					if (!finalToolCallsCanDispatch || !preparedDispatch) {
						await speculationCoordinator.discardAll(
							"final message cannot reach tool dispatch",
							requestSignal?.aborted ? "aborted" : "discarded",
						);
					} else {
						await speculationCoordinator.reconcileFinalCalls(
							await speculativeFinalCalls(
								trailing,
								preparedDispatch,
								config.transformToolCallArguments,
								speculationCoordinator,
							),
						);
						await speculationCoordinator.finalizeAdmissions();
						speculationCoordinator.attach(trailing);
					}
				}
				if (addedPartial) {
					context.messages[context.messages.length - 1] = trailing;
				} else {
					context.messages.push(trailing);
					stream.push({ type: "message_start", message: snapshotAssistantMessage(trailing) });
				}
				await appendCursorToolResults();
				stream.push({ type: "message_end", message: snapshotAssistantMessage(trailing) });
				await finishChat(trailing);
				speculationSettled = true;
				providerStreamSettled = true;
				return trailing;
			} catch (error) {
				if (!speculationSettled) {
					await speculationCoordinator?.discardAll("provider stream finalization failed", "aborted");
				}
				throw error;
			}
		});
	} catch (err) {
		failChatSpan(telemetry, chatSpan, {
			errorObject: err,
			responseHeaders: capturedHeaders,
			baseUrl: model.baseUrl,
		});
		throw err;
	}
}

function retainCompletedToolCalls(
	message: AssistantMessage,
	completedToolCallIds: ReadonlySet<string>,
): AssistantMessage {
	if (message.stopReason !== "error" && message.stopReason !== "aborted") return message;
	let droppedIncompleteToolCall = false;
	const content = message.content.filter(block => {
		if (block.type !== "toolCall") return true;
		const keep = completedToolCallIds.has(block.id);
		if (!keep) droppedIncompleteToolCall = true;
		return keep;
	});
	if (!droppedIncompleteToolCall) return message;
	return {
		...message,
		content,
		stopDetails:
			message.stopDetails?.type === STREAM_INTERRUPTED_AFTER_CONTENT_STOP_DETAIL
				? message.stopDetails
				: {
						type: STREAM_INTERRUPTED_AFTER_CONTENT_STOP_DETAIL,
						category: message.stopDetails?.type ?? null,
						explanation: message.stopDetails?.explanation ?? message.errorMessage ?? null,
					},
	};
}

function recoverTransientErrorToolTurn(
	message: AssistantMessage,
	availableTools: ReadonlyArray<Pick<AgentTool, "name" | "customWireName">>,
): AssistantMessage {
	if (message.stopReason !== "error") return message;
	const toolCalls = message.content.filter(block => block.type === "toolCall");
	if (toolCalls.length === 0) return message;
	const stopDetailType = message.stopDetails?.type;
	const stopDetailCategory = message.stopDetails?.category;
	if (
		stopDetailType === "refusal" ||
		stopDetailType === "sensitive" ||
		stopDetailCategory === "refusal" ||
		stopDetailCategory === "sensitive"
	)
		return message;
	const availableToolNames = new Set<string>();
	for (const tool of availableTools) {
		availableToolNames.add(tool.name);
		if (tool.customWireName !== undefined) availableToolNames.add(tool.customWireName);
	}
	if (!toolCalls.every(toolCall => availableToolNames.has(toolCall.name))) return message;
	const errorText = `${message.errorMessage ?? ""}\n${message.stopDetails?.explanation ?? ""}`;
	if (
		!AIError.isStreamReadErrorText(errorText) &&
		!AIError.isStreamEnvelopeErrorText(errorText) &&
		!AIError.isTransientStreamParseError(message.errorMessage) &&
		!AIError.isTransientStreamParseError(message.stopDetails?.explanation)
	)
		return message;
	return {
		...message,
		stopReason: "toolUse",
		stopDetails:
			message.stopDetails?.type === STREAM_INTERRUPTED_AFTER_CONTENT_STOP_DETAIL
				? message.stopDetails
				: {
						type: STREAM_INTERRUPTED_AFTER_CONTENT_STOP_DETAIL,
						category: message.stopDetails?.type ?? null,
						explanation: message.stopDetails?.explanation ?? message.errorMessage ?? null,
					},
		errorMessage: undefined,
		errorId: undefined,
		errorStatus: undefined,
	};
}

function emitDiscardedHarmonyPartial(
	partialMessage: AssistantMessage | null,
	stream: EventStream<AgentEvent, AgentMessage[]>,
	errorMessage: string,
): void {
	if (!partialMessage) return;
	stream.push({
		type: "message_end",
		message: snapshotAssistantMessage({ ...partialMessage, stopReason: "error", errorMessage }),
	});
}

function isStringRecord(value: unknown): value is Record<string, string> {
	if (!value || typeof value !== "object" || Array.isArray(value)) return false;
	return Object.values(value).every(child => typeof child === "string");
}

function toolScopedAbortReason(signal: AbortSignal | undefined): ToolScopedAbortReason | undefined {
	const reason = signal?.reason;
	if (!reason || typeof reason !== "object") return undefined;
	if (Reflect.get(reason, "kind") !== "tool-scoped-abort") return undefined;
	if (typeof Reflect.get(reason, "message") !== "string") return undefined;
	if (typeof Reflect.get(reason, "defaultToolCallMessage") !== "string") return undefined;
	return isStringRecord(Reflect.get(reason, "toolCallMessages")) ? reason : undefined;
}

function buildToolCallAbortMessages(
	message: AssistantMessage,
	reason: ToolScopedAbortReason,
): Record<string, string> | undefined {
	let hasToolCall = false;
	const messages: Record<string, string> = {};
	for (const block of message.content) {
		if (block.type !== "toolCall") continue;
		hasToolCall = true;
		messages[block.id] = reason.toolCallMessages[block.id] ?? reason.defaultToolCallMessage;
	}
	return hasToolCall ? messages : undefined;
}

/** Resolve the human-readable reason an abort carried. A caller that aborts via
 *  `AbortController.abort(reason)` with a string or a non-`AbortError` `Error`
 *  (e.g. the coding agent's user-interrupt label) gets that text surfaced on the
 *  synthesized assistant message's `errorMessage`; a bare `abort()` (whose
 *  `signal.reason` is the default `AbortError` `DOMException`) falls back to the
 *  generic sentinel that downstream renderers treat as "no specific reason". */
export function abortReasonText(signal: AbortSignal | undefined): string {
	return toolScopedAbortReason(signal)?.message ?? AIError.callerAbortReason(signal) ?? "Request was aborted";
}

function emitAbortedAssistantMessage(
	partialMessage: AssistantMessage | null,
	addedPartial: boolean,
	completedToolCallIds: ReadonlySet<string>,
	context: AgentContext,
	config: AgentLoopConfig,
	stream: EventStream<AgentEvent, AgentMessage[]>,
	requestSignal: AbortSignal | undefined,
): AssistantMessage {
	const model = config.getModel?.() ?? config.model;
	const errorMessage = abortReasonText(requestSignal);
	const errorId =
		errorMessage === "Request was aborted"
			? AIError.create(AIError.Flag.Abort)
			: AIError.classify(requestSignal?.reason) || undefined;
	const base: AssistantMessage = partialMessage
		? { ...partialMessage, stopReason: "aborted", errorMessage, errorId }
		: {
				role: "assistant",
				content: [],
				api: model.api,
				provider: model.provider,
				model: model.id,
				usage: {
					input: 0,
					output: 0,
					cacheRead: 0,
					cacheWrite: 0,
					totalTokens: 0,
					cost: { input: 0, output: 0, cacheRead: 0, cacheWrite: 0, total: 0 },
				},
				stopReason: "aborted",
				errorMessage,
				errorId,
				timestamp: Date.now(),
			};
	// Only tool calls that reached `toolcall_end` survive abort/error replay. A
	// labeled user interrupt still surfaces through `errorMessage`, but partial
	// tool arguments are unsafe to keep and can carry incomplete provider IDs.
	const retained = retainCompletedToolCalls(base, completedToolCallIds);
	const scopedAbort = toolScopedAbortReason(requestSignal);
	const toolCallAbortMessages = scopedAbort ? buildToolCallAbortMessages(retained, scopedAbort) : undefined;
	if (toolCallAbortMessages) {
		retained.toolCallAbortMessages = toolCallAbortMessages;
	}
	const abortedMessage = snapshotAssistantMessage(retained);
	if (addedPartial) {
		context.messages[context.messages.length - 1] = abortedMessage;
	} else {
		context.messages.push(abortedMessage);
		stream.push({ type: "message_start", message: snapshotAssistantMessage(abortedMessage) });
	}
	stream.push({ type: "message_end", message: snapshotAssistantMessage(abortedMessage) });
	return abortedMessage;
}

/** Per-call outcome of the pre-dispatch prepare phase (validation + `beforeToolCall`). */
interface PreparedToolCall {
	tool: AgentTool<any> | undefined;
	/** Validated (possibly hook-revised) execution args; raw args when validation failed. */
	args: Record<string, unknown>;
	/**
	 * Passive context returned by `beforeToolCall`. Committed after the batch
	 * settles only when the call's final result is not an error, so a call the
	 * tool's own approval gate denies (or that otherwise fails) injects nothing.
	 */
	additionalContext?: string;
	/** Transformed args shared by final reconciliation and eventual dispatch. */
	executionArgs?: Record<string, unknown>;
	/** Transform failure retained for execution's scheduled error result. */
	transformError?: unknown;
	validationErrorMessage?: string;
	blocked?: boolean;
	blockReason?: string;
	prepareError?: unknown;
}

/** Committed assistant messages whose unhealed DSML tool-call markup was stripped; the loop answers them with a failure nudge. */
const dsmlLeakMessages = new WeakSet<AssistantMessage>();

/**
 * Prepare results computed in the stream-done branch (before `message_start`/
 * `message_end`) so a `beforeToolCall` args revision is baked into the message
 * every consumer snapshots. `executeToolCalls` consumes them; a message that
 * bypassed the streamed path (e.g. Harmony-recovered) is prepared at dispatch
 * time instead.
 */
const preparedDispatchByMessage = new WeakMap<AssistantMessage, Map<string, PreparedToolCall>>();

function resolveToolForCall(
	tools: AgentTool<any>[] | undefined,
	toolCall: AgentToolCall,
	resolveFallbackTool: AgentLoopConfig["resolveFallbackTool"],
): AgentTool<any> | undefined {
	// Tools emitted via OpenAI's custom-tool path (e.g. `apply_patch` on GPT-5)
	// come back under their wire-level name, which may differ from the
	// harness-internal `name`. Match on either, preferring `name` for
	// determinism if both somehow collide.
	return (
		tools?.find(t => t.name === toolCall.name) ??
		tools?.find(t => t.customWireName !== undefined && t.customWireName === toolCall.name) ??
		// Not in the advertised set: let the host route side-transport tools
		// (e.g. xd:// device mounts) called by their top-level name. It receives
		// the snapshot searched above, never the agent's live tools, so a
		// mid-stream roster change cannot widen what this request can reach.
		resolveFallbackTool?.(toolCall.name, tools ?? [])
	);
}

/** Shortest suggestable segment; below this the match is noise (`id`, `to`). */
const MIN_TOOL_NAME_SUGGESTION_SEGMENT = 3;
/** Cap on names listed for an ambiguous miss, so the error stays readable. */
const MAX_TOOL_NAME_SUGGESTIONS = 3;

/**
 * Tool names sharing a trailing `_`-delimited segment with `name`.
 *
 * A model that mis-transcribes a long opaque tool name reliably keeps the
 * trailing verb — that segment is the only part carrying meaning, while any
 * leading id segments are high-entropy and mnemonic-free. Matching on it turns
 * an otherwise dead `not found` into a self-correcting one.
 *
 * Both the last `__` and last `_` boundary are tried, so a name that lost only
 * its separator (`…__resolve_library_id`) and one that lost a whole id segment
 * (`…__read`) both recover. `fallbackNames` adds targets the host can route but
 * never advertises (`xd://` device mounts); without them a corrupted device
 * call is the one miss with nothing to suggest, because the capability exists
 * in the session yet appears in no advertised name. Purely advisory: this only
 * builds an error string and never selects a tool, so dispatch semantics are
 * unchanged.
 */
function suggestToolNames(
	name: string,
	tools: ReadonlyArray<Pick<AgentTool, "name" | "customWireName">> | undefined,
	fallbackNames?: Iterable<string>,
): string[] {
	const candidates: string[] = [];
	for (const tool of tools ?? []) {
		candidates.push(tool.name);
		if (tool.customWireName !== undefined) candidates.push(tool.customWireName);
	}
	// Devices rank after the advertised set: when one verb matches both, the
	// tool the model was actually offered is the better guess.
	if (fallbackNames !== undefined) for (const fallbackName of fallbackNames) candidates.push(fallbackName);
	if (candidates.length === 0) return [];
	const segments: string[] = [];
	for (const boundary of ["__", "_"]) {
		const idx = name.lastIndexOf(boundary);
		if (idx < 0) continue;
		const segment = name.slice(idx + boundary.length);
		if (segment.length >= MIN_TOOL_NAME_SUGGESTION_SEGMENT && !segments.includes(segment)) segments.push(segment);
	}
	if (segments.length === 0) return [];
	// Longest tail first. A distinctive `__` tail (`resolve_library_get`) is a
	// far stronger signal than the generic `_` tail it contains (`get`), and the
	// caller truncates the list — so the strongest match has to sort ahead of
	// however many tools happen to share the weak one.
	segments.sort((a, b) => b.length - a.length);
	const matches: string[] = [];
	for (const segment of segments) {
		for (const candidate of candidates) {
			if (candidate === name || matches.includes(candidate)) continue;
			if (candidate === segment || candidate.endsWith(`_${segment}`)) matches.push(candidate);
		}
	}
	return matches;
}

/**
 * `Tool <name> not found`, plus a suggestion when the session holds a plausible
 * intended target. Exact wording is not a contract; the model reads it.
 */
function formatToolNotFoundMessage(
	name: string,
	tools: ReadonlyArray<Pick<AgentTool, "name" | "customWireName">> | undefined,
	fallbackNames?: Iterable<string>,
): string {
	const suggestions = suggestToolNames(name, tools, fallbackNames);
	if (suggestions.length === 0) return `Tool ${name} not found`;
	if (suggestions.length === 1) return `Tool ${name} not found. Did you mean ${suggestions[0]}?`;
	return `Tool ${name} not found. Closest available: ${suggestions.slice(0, MAX_TOOL_NAME_SUGGESTIONS).join(", ")}`;
}

/**
 * Enforce the invariant every downstream matcher keys on: `toolCall.id` is
 * unique and non-empty across the whole run — not just within one assistant
 * message. Providers can deliver a reused id (wire length truncation, Responses
 * `callId|itemId` composite collapse) or an id that never materialized (`""`) —
 * the same occurrences the replay pipeline repairs or drops
 * (`deduplicateToolCallIds` / `sanitizeMalformedToolCalls`). Id-keyed per-call
 * state — the prepare map below, every UI and persistence matcher — would
 * otherwise merge sibling calls: the later call's prepared entry overwrites the
 * earlier's, both calls execute the sibling's payload, and colliding result ids
 * merge or drop one sibling's output in every consumer. Message-scope
 * uniqueness is not enough for the session-wide consumers
 * (`formatSessionHistoryMarkdown`'s last-entry-wins map, the advisor delta
 * split, `EventController.#toolTimelineComponents`, persistence keys): a second
 * assistant turn whose ids never materialized used to re-mint `call_1`,
 * `call_2`, … and re-derive the same `_dup` suffixes, so those consumers merged
 * the cross-turn collisions. Every id kept or minted here is therefore claimed
 * in the run-scoped registry (`toolCallIdsDispatchedUnder`) and every candidate
 * is generated until unused at run scope. Never-materialized is the sanitizer's
 * trim test (`isMalformedToolCallId`): a whitespace-only id is minted like an
 * empty one, never kept — it would be dropped from provider replay together
 * with its result, the live/replay divergence this repair exists to close.
 * Cursor server-resolved blocks are never re-keyed (the provider correlates
 * their results out-of-band under its own ids) but their ids still join the
 * registry so no minted candidate collides with one. Idempotent: the message is
 * marked repaired and re-entry is a no-op, so the Harmony path can repair
 * before its snapshots while the dispatch-time prepare sees the already-minted
 * ids and leaves them alone.
 */
const kToolCallIdsRepaired = Symbol("agent-loop.toolCallIdsRepaired");

/** Assistant message optionally carrying the {@link kToolCallIdsRepaired} mark. */
type ToolCallIdsRepairedCarrier = AssistantMessage & { [kToolCallIdsRepaired]?: true };

/**
 * Run-scoped registry of every tool-call id {@link ensureUniqueToolCallIds} has
 * kept, minted, or seen on a server-resolved block under one
 * {@link AgentContext}. Keyed by the dispatch context (the same object every
 * `prepareToolCallDispatch` receives) so the uniqueness window spans every
 * assistant turn of the run rather than resetting per message. Each run gets a
 * fresh loop context, so minted ids use the process-unique `mintToolCallId`.
 */
const dispatchedToolCallIdsByContext = new WeakMap<AgentContext, Set<string>>();

function toolCallIdsDispatchedUnder(context: AgentContext): Set<string> {
	let dispatched = dispatchedToolCallIdsByContext.get(context);
	if (!dispatched) {
		dispatched = new Set();
		dispatchedToolCallIdsByContext.set(context, dispatched);
	}
	return dispatched;
}

function ensureUniqueToolCallIds(message: ToolCallIdsRepairedCarrier, dispatchedIds: Set<string>): void {
	if (message[kToolCallIdsRepaired] === true) return;
	const content = message.content;
	const reserved = new Set<string>();
	for (const block of content) {
		if (block.type === "toolCall" && block.id) reserved.add(block.id);
	}
	const seen = new Set<string>();
	for (const block of content) {
		if (block.type !== "toolCall") continue;
		if ((block as CursorExecResolvedCarrier)[kCursorExecResolved] === true) {
			if (block.id?.trim()) dispatchedIds.add(block.id);
			continue;
		}
		if (block.id?.trim() && !seen.has(block.id) && !dispatchedIds.has(block.id)) {
			seen.add(block.id);
			dispatchedIds.add(block.id);
			continue;
		}
		let candidate: string;
		if (block.id?.trim()) {
			let suffix = 1;
			candidate = appendDuplicateSuffix(block.id, `_dup${suffix}`, MAX_TOOL_CALL_ID_LENGTH);
			while (seen.has(candidate) || reserved.has(candidate) || dispatchedIds.has(candidate)) {
				suffix += 1;
				candidate = appendDuplicateSuffix(block.id, `_dup${suffix}`, MAX_TOOL_CALL_ID_LENGTH);
			}
		} else {
			// Process-unique minter: a per-run counter would re-mint `call_1` in
			// every run and collide with earlier runs' calls in session history.
			do {
				candidate = mintToolCallId();
			} while (seen.has(candidate) || reserved.has(candidate) || dispatchedIds.has(candidate));
		}
		block.id = candidate;
		seen.add(candidate);
		dispatchedIds.add(candidate);
	}
	message[kToolCallIdsRepaired] = true;
}

/**
 * Pre-dispatch phase for every pending tool call on `assistantMessage`, run in
 * call order: tool-call id repair, intent extraction, argument validation, and
 * the `beforeToolCall` hook. A hook `args` revision is revalidated against the
 * tool schema and written back to `toolCall.arguments`; run before
 * `message_start`/`message_end` (the streamed path) that makes the revision the
 * single source of truth — history, execution events, persistence, provider
 * replay, concurrency scheduling, and `tool.execute` all agree. Id repair in
 * {@link ensureUniqueToolCallIds} follows the same rule. Failures are recorded
 * per call and surfaced by `executeToolCalls` at the record's scheduled slot.
 */
async function prepareToolCallDispatch(
	assistantMessage: AssistantMessage,
	context: AgentContext,
	config: AgentLoopConfig,
	signal: AbortSignal | undefined,
): Promise<Map<string, PreparedToolCall>> {
	const { resolveFallbackTool, suggestFallbackToolNames, intentTracing, beforeToolCall } = config;
	// Unique, non-empty ids first: everything below and every consumer of this
	// message keys per-call state on `toolCall.id`.
	ensureUniqueToolCallIds(assistantMessage, toolCallIdsDispatchedUnder(context));
	const prepared = new Map<string, PreparedToolCall>();
	for (const toolCall of assistantMessage.content) {
		if (toolCall.type !== "toolCall") continue;
		if ((toolCall as CursorExecResolvedCarrier)[kCursorExecResolved] === true) continue;
		const tool = resolveToolForCall(context.tools, toolCall, resolveFallbackTool);
		// A host fallback accepts aliases (`xd://recall`, a mis-separated MCP
		// name) that providers reject when replayed as a function-call name.
		// Record the call under the resolved tool's canonical name so history,
		// persistence, and replay agree; custom-wire calls keep their wire name.
		if (tool && toolCall.name !== tool.name && toolCall.name !== tool.customWireName) {
			toolCall.name = tool.name;
		}
		const entry: PreparedToolCall = { tool, args: toolCall.arguments as Record<string, unknown> };
		prepared.set(toolCall.id, entry);
		let argsForExecution = toolCall.arguments as Record<string, unknown>;
		if (intentTracing) {
			// A schema-owned `i` is a tool argument, never a harness intent.
			const ownsIntent = tool !== undefined && schemaDefinesProperty(toolWireSchema(tool), INTENT_FIELD);
			const { intent, strippedArgs } = ownsIntent
				? { intent: undefined, strippedArgs: argsForExecution }
				: extractIntent(toolCall.arguments);
			argsForExecution = strippedArgs;
			if (intent) {
				toolCall.intent = intent;
			} else if (typeof tool?.intent === "function") {
				try {
					const derived = tool.intent(strippedArgs as never)?.trim();
					if (derived) {
						toolCall.intent = derived;
					}
				} catch {
					// intent function must never break tool execution
				}
			}
		}
		const validate = (args: Record<string, unknown>): Record<string, unknown> | undefined => {
			try {
				if (!tool) {
					throw new Error(formatToolNotFoundMessage(toolCall.name, context.tools, suggestFallbackToolNames?.()));
				}
				return validateAgentToolArguments(tool, { ...toolCall, arguments: args });
			} catch (validationError) {
				const parseFailed = "__parseError" in args;
				entry.args = parseFailed ? { __parseError: args.__parseError } : args;
				entry.validationErrorMessage =
					validationError instanceof Error ? validationError.message : String(validationError);
				return undefined;
			}
		};
		const effectiveArgs = validate(argsForExecution);
		if (effectiveArgs === undefined) continue;
		entry.args = effectiveArgs;
		if (!beforeToolCall || !tool) continue;
		let beforeResult: BeforeToolCallResult | undefined;
		try {
			beforeResult = await beforeToolCall(
				{ assistantMessage, toolCall, tool, args: effectiveArgs, context },
				signal,
			);
		} catch (e) {
			// Contract: a throwing hook surfaces as a tool-error result without
			// aborting the batch — rethrown inside the execution span in runTool.
			entry.prepareError = e;
			continue;
		}
		if (beforeResult?.block) {
			entry.blocked = true;
			entry.blockReason = beforeResult.reason;
			continue;
		}
		if (isNonBlankContext(beforeResult?.additionalContext)) {
			entry.additionalContext = beforeResult.additionalContext;
		}
		if (beforeResult?.args !== undefined) {
			// Revalidate: a hook revision is untrusted input to the tool schema.
			const revised = validate(beforeResult.args);
			if (revised === undefined) continue;
			// Bake the revision into the message itself. On the streamed path this
			// precedes every consumer snapshot, so there is exactly one version of
			// the call anywhere downstream.
			toolCall.arguments = beforeResult.args;
			entry.args = revised;
		}
	}
	return prepared;
}

/**
 * Final calls that can still reach tool execution after pre-dispatch policy.
 * Omitting a call is deliberate: reconciliation discards its direct candidate
 * and streamed children before final admission can release deferred work.
 */
function transformedExecutionArgs(
	prepared: PreparedToolCall,
	toolCall: AgentToolCall,
	transformToolCallArguments: AgentLoopConfig["transformToolCallArguments"],
): Record<string, unknown> | undefined {
	if (prepared.transformError !== undefined) return undefined;
	if (prepared.executionArgs !== undefined) return prepared.executionArgs;
	try {
		const args = transformToolCallArguments
			? transformToolCallArguments(prepared.args, toolCall.name)
			: prepared.args;
		prepared.executionArgs = args;
		return args;
	} catch (error) {
		prepared.transformError = error;
		return undefined;
	}
}

async function speculativeFinalCalls(
	assistantMessage: AssistantMessage,
	preparedDispatch: ReadonlyMap<string, PreparedToolCall>,
	transformToolCallArguments: AgentLoopConfig["transformToolCallArguments"],
	speculationCoordinator: SpeculativeOperationCoordinator | undefined,
): Promise<Map<string, AgentToolCall>> {
	// Settle admissions first: a slow assessment would otherwise look like a
	// missing candidate and force a second transform application below.
	await speculationCoordinator?.settleAdmissions();
	const calls = new Map<string, AgentToolCall>();
	for (const content of assistantMessage.content) {
		if (content.type !== "toolCall" || (content as CursorExecResolvedCarrier)[kCursorExecResolved] === true) {
			continue;
		}
		const prepared = preparedDispatch.get(content.id);
		if (
			!prepared ||
			prepared.blocked ||
			prepared.prepareError !== undefined ||
			prepared.validationErrorMessage !== undefined
		) {
			continue;
		}
		// Reuse the admission-time transform when the finalized raw call is
		// unchanged, so a stateful transform runs exactly once end-to-end and
		// the reconciled path is the path already accessed. Changed raw args
		// (e.g. a beforeToolCall revision) fall through to a single fresh
		// transform, leaving the stale candidate for reconciliation to discard.
		const reused = speculationCoordinator?.directExecutionArgsFor(
			content.id,
			content.arguments as Record<string, unknown>,
		);
		let executionArgs: Record<string, unknown> | undefined;
		if (reused !== undefined) {
			prepared.executionArgs = reused;
			executionArgs = reused;
		} else {
			executionArgs = transformedExecutionArgs(prepared, content, transformToolCallArguments);
		}
		if (executionArgs === undefined) continue;
		calls.set(content.id, { ...content, arguments: executionArgs });
	}
	return calls;
}

/**
 * Execute tool calls from an assistant message. Returns model-visible context
 * only after every result has settled, preserving assistant call order.
 *
 * `tool_execution_end` fires as each call settles so live UI updates promptly;
 * result `message_start`/`message_end` events (which append to agent state and
 * the persisted session) are held until every earlier call has a result, so
 * history always pairs results in call order regardless of completion order.
 */
async function executeToolCalls(
	currentContext: AgentContext,
	assistantMessage: AssistantMessage,
	signal: AbortSignal | undefined,
	stream: EventStream<AgentEvent, AgentMessage[]>,
	config: AgentLoopConfig,
	telemetry: AgentTelemetry | undefined,
	invokeAgentSpan: Span | undefined,
	// Steering the provider took off the queue during the response that emitted
	// this batch; it injects at this batch's boundary like queued steering.
	liveSteering: readonly AgentMessage[],
): Promise<{ toolResults: ToolResultMessage[]; additionalContext?: string }> {
	const tools = currentContext.tools;
	const {
		hasSteeringMessages,
		hasIrcInterrupts,
		hasBackgroundCompletions,
		hasQueuedAsides,
		interruptMode = "immediate",
		getToolContext,

		transformToolCallArguments,
		resolveFallbackTool,
		suggestFallbackToolNames,
		afterToolCall,
	} = config;
	type ToolCallContent = Extract<AssistantMessage["content"][number], { type: "toolCall" }>;
	// Defensive: the outer loop already filters exec-resolved blocks before
	// deciding to invoke `executeToolCalls`, but skip them here too so the
	// guarantee lives with the code that would re-run the tool.
	const toolCalls = assistantMessage.content.filter(
		(c): c is ToolCallContent =>
			c.type === "toolCall" && (c as CursorExecResolvedCarrier)[kCursorExecResolved] !== true,
	);
	const emittedToolResults: ToolResultMessage[] = [];
	const toolCallInfos = toolCalls.map(call => ({ id: call.id, name: call.name }));
	const batchId = `${assistantMessage.timestamp ?? Date.now()}_${toolCalls[0]?.id ?? "batch"}`;
	// `interruptMode: "wait"` only spares side-effecting work: interruptible
	// waits are always cut short, since a pure wait has nothing to finish and
	// would otherwise sit out its full window with a message already queued.
	const softInterrupts = interruptMode !== "wait";
	const steeringAbortController = new AbortController();
	const ircAbortController = new AbortController();
	// Cooperative channel: aborted when queued steering (or an interrupting
	// peer IRC) is detected mid-batch. Tools receive it via tool context
	// (`ctx.steeringSignal`) and MAY react — e.g. an auto-backgroundable bash
	// backgrounds itself so the message injects promptly — but it never kills
	// anything; ignoring it is always safe.
	const steeringSoftController = new AbortController();
	// Interruptible tools (pure waits: wait, vibe) observe steering +
	// external + IRC aborts. Every other tool sees ONLY the external signal:
	// neither queued steering nor a peer IRC ever hard-kills a partially
	// side-effecting foreground tool (e.g. `bash`) — those get the cooperative
	// `steeringSignal` above, and the message injects at the next boundary.
	const nonInterruptibleSignal: AbortSignal = signal ?? new AbortController().signal;
	const interruptibleSignal: AbortSignal = signal
		? AbortSignal.any([signal, steeringAbortController.signal, ircAbortController.signal])
		: AbortSignal.any([steeringAbortController.signal, ircAbortController.signal]);
	const interruptState: { triggered: boolean; source?: AsideInterruptSource } = { triggered: false };

	// Streamed messages were prepared (validation + `beforeToolCall`) before
	// `message_end`, so hook revisions are already part of the message; anything
	// that bypassed the streamed path is prepared here instead.
	const preparedDispatch =
		preparedDispatchByMessage.get(assistantMessage) ??
		(await prepareToolCallDispatch(assistantMessage, currentContext, config, signal));
	const speculationCoordinator = SpeculativeOperationCoordinator.take(assistantMessage);

	const records = toolCalls.map(toolCall => {
		const prepared = preparedDispatch.get(toolCall.id) ?? {
			tool: resolveToolForCall(tools, toolCall, resolveFallbackTool),
			args: toolCall.arguments as Record<string, unknown>,
		};
		const { tool, args } = prepared;
		const interruptibleMode = tool?.interruptible;
		let interruptible = false;
		if (typeof interruptibleMode === "function") {
			try {
				// Resolved from the prepared (possibly hook-revised) args so an
				// argument-dependent policy governs the call that actually runs.
				interruptible = interruptibleMode(args);
			} catch {
				// Resolver failures default to preserving the tool's outcome.
				interruptible = false;
			}
		} else {
			interruptible = interruptibleMode === true;
		}
		return {
			toolCall,
			tool,
			args,
			interruptible,
			handlesToolInterrupt: interruptible && tool?.handlesToolInterrupt === true,
			signal: interruptible ? interruptibleSignal : nonInterruptibleSignal,
			started: false,
			result: undefined as AgentToolResult<any> | undefined,
			isError: false,
			skipped: false,
			toolResultMessage: undefined as ToolResultMessage | undefined,
			resultEmitted: false,
			validationErrorMessage: prepared.validationErrorMessage,
			blocked: prepared.blocked === true,
			blockReason: prepared.blockReason,
			prepareError: prepared.prepareError,
			preparedContext: prepared.additionalContext,
			reportedContext: [] as string[],
			executionArgs: prepared.executionArgs,
			transformError: prepared.transformError,
		};
	});

	// Derive batch readiness from existing dispatch records, not extra participants.
	const refreshPauseState = (): void => {
		config.onPauseChange?.(
			agentPauseGate.paused &&
				!signal?.aborted &&
				!speculationCoordinator?.isRunning &&
				records.some(record => !record.started && !record.skipped && !record.toolResultMessage) &&
				!records.some(record => record.started && !record.toolResultMessage),
		);
	};
	if (speculationCoordinator) speculationCoordinator.onIdle = refreshPauseState;

	const isToolAborted = (record: (typeof records)[number]): boolean =>
		signal?.aborted === true ||
		(record.signal.aborted && !(record.handlesToolInterrupt && record.signal.reason === TOOL_INTERRUPT_ABORT_REASON));

	const checkAsideInterrupts = async (): Promise<void> => {
		// Asides only fire once: an interrupt already recorded on interruptState
		// must not re-abort, and (unlike steering) never re-consumes a queue.
		// A completion-triggered record is the exception — it leaves the
		// cooperative signal down, so keep polling until a peer IRC escalates
		// (only when soft interrupts are enabled; otherwise nothing is left).
		if (signal?.aborted) return;
		if (interruptState.triggered && (!softInterrupts || steeringSoftController.signal.aborted)) return;
		// Peer IRC, queued asides and background completions (finished jobs,
		// exited supervised processes) hard-abort interruptible waits only;
		// foreground tools keep running (no partial side effects).
		let source: AsideInterruptSource | undefined;
		if (hasIrcInterrupts && (await hasIrcInterrupts())) source = "irc";
		else if (!interruptState.triggered && hasQueuedAsides && (await hasQueuedAsides())) source = "aside";
		else if (!interruptState.triggered && hasBackgroundCompletions && (await hasBackgroundCompletions()))
			source = "background";
		if (!source) return;
		if (!interruptState.triggered) {
			interruptState.triggered = true;
			interruptState.source = source;
			ircAbortController.abort(TOOL_INTERRUPT_ABORT_REASON);
		}
		// Only an urgent aside raises the cooperative signal that makes
		// backgroundable foreground work (auto-background bash/eval) detach
		// itself. A peer waiting on an IRC is blocked on this batch; a finished
		// background job is not — its notice is an aside that injects at the
		// batch boundary either way. Detaching ordinary foreground work for it
		// also cascades: the freshly detached job's own completion re-triggers
		// this check for the next command, so millisecond-long commands chain
		// into separate background deliveries (#12869).
		if (source === "irc" && softInterrupts) steeringSoftController.abort("irc");
	};

	const checkSteering = async (): Promise<void> => {
		// `signal` (external/user abort) is checked separately from the internal
		// abort controllers: once the run is externally aborted it is unwinding
		// and the interrupt would be redundant.
		if (signal?.aborted) return;
		// Mid-batch steering detection must be non-consuming. If a direct
		// integration only provides getSteeringMessages(), the queue drains at the
		// injection boundary below; polling it here would strand or drop messages.
		let steeringQueued = false;
		let steeringSource: SteeringInterruptSource | undefined;
		if (liveSteering.length > 0) {
			steeringQueued = true;
			steeringSource = steeringQueueState(liveSteering).source;
		} else if (hasSteeringMessages) {
			const queuedState = await hasSteeringMessages();
			if (typeof queuedState === "boolean") {
				steeringQueued = queuedState;
				steeringSource = queuedState ? "user" : undefined;
			} else {
				const state: SteeringQueueState = queuedState;
				steeringQueued = state.queued;
				steeringSource = state.source ?? (state.queued ? "unknown" : undefined);
			}
		}
		if (steeringQueued) {
			// Queued steering hard-aborts only interruptible waits and (unless
			// interruptMode is "wait") raises the cooperative soft signal for
			// everything else: the boundary dequeue
			// below injects the message as soon as running tools finish (or
			// background themselves). Not-yet-started interruptible tools are
			// skipped unless they can drain the queued wake. Idempotent — a
			// second steer poll after the abort is a no-op.
			if (!steeringAbortController.signal.aborted) {
				interruptState.triggered = true;
				interruptState.source = steeringSource ?? "unknown";
				steeringAbortController.abort(TOOL_INTERRUPT_ABORT_REASON);
				if (softInterrupts) steeringSoftController.abort(interruptState.source);
			}
			return;
		}
		await checkAsideInterrupts();
	};

	// Index of the first record whose result message has not been emitted yet.
	let nextResultIndex = 0;
	const flushResultMessages = (): void => {
		for (; nextResultIndex < records.length; nextResultIndex++) {
			const message = records[nextResultIndex].toolResultMessage;
			if (!message) return;
			emittedToolResults.push(message);
			stream.push({ type: "message_start", message });
			stream.push({ type: "message_end", message });
		}
	};

	const emitToolResult = (record: (typeof records)[number], result: AgentToolResult<any>, isError: boolean): void => {
		if (record.resultEmitted) return;
		const { toolCall } = record;
		if (!record.started) {
			stream.push({
				type: "tool_execution_start",
				toolCallId: toolCall.id,
				toolName: toolCall.name,
				args: record.args,
				intent: toolCall.intent,
			});
		}
		stream.push({
			type: "tool_execution_end",
			toolCallId: toolCall.id,
			toolName: toolCall.name,
			result,
			isError,
		});

		const toolResultMessage: ToolResultMessage = {
			role: "toolResult",
			toolCallId: toolCall.id,
			toolName: toolCall.name,
			content: result.content,
			details: result.details,
			providerMetadata: result.providerMetadata,
			isError,
			...(result.useless && !isError ? { useless: true } : {}),
			timestamp: Date.now(),
		};
		record.result = result;
		record.isError = isError;
		record.toolResultMessage = toolResultMessage;
		record.resultEmitted = true;
		flushResultMessages();
	};

	const runTool = async (
		record: (typeof records)[number],
		index: number,
		earlierEffectsSettled: Promise<void> | undefined,
	): Promise<void> => {
		// A pending interrupt preempts not-yet-started interruptible tools,
		// except receivers that drain the wake with an already-aborted signal.
		// Non-interruptible work is never skipped, whatever the source: the
		// expensive part — generating the call — is already paid, the tool
		// itself is cheap, and a skip only makes the model re-emit the same
		// call after the steer lands (#10439). The same guarantee is what keeps
		// a batched `todo`/`write` queued behind an aborted wait alive (#7493)
		// and lets a subagent's already-emitted terminal `yield` commit when
		// the parent steers mid-stream (#10645). The steer still injects at the
		// batch boundary; the cooperative soft signal lets long-running tools
		// step aside on their own.
		if (interruptState.triggered && record.interruptible && !record.handlesToolInterrupt) {
			// Skip both span emission and the collector orphan record here. The
			// tail sweep below (after `Promise.allSettled`) is the single path
			// that handles "no result message was produced" — it calls
			// `recordSkippedTool` and `emitToolResult` once per record, so any
			// work we did here would double-count.
			record.skipped = true;
			return;
		}
		// Park before starting this tool while the process-wide pause gate is
		// engaged. Tools already executing are unaffected (pausing never aborts);
		// a batch interrupted mid-pause unwinds via the signal checks below.
		while (agentPauseGate.paused && !record.signal.aborted) {
			refreshPauseState();
			await agentPauseGate.waitUntilResumed(record.signal);
		}
		config.onPauseChange?.(false);

		const { toolCall, tool } = record;
		// Validation (and the beforeToolCall hook) ran in the prepare phase; a
		// failure recorded there surfaces here at the record's scheduled slot so
		// result emission keeps batch order.
		if (record.validationErrorMessage !== undefined) {
			emitToolResult(
				record,
				{
					content: [{ type: "text" as const, text: record.validationErrorMessage }],
					details: { isError: true, error: record.validationErrorMessage },
				},
				true,
			);
			return;
		}
		const effectiveArgs = record.args;
		if (isToolAborted(record)) {
			record.skipped = true;
			recordSkippedTool(telemetry, {
				toolCallId: toolCall.id,
				toolName: toolCall.name,
				status: "aborted",
			});
			emitToolResult(record, createToolSignalAbortedResult(signal?.aborted ? signal : record.signal), true);
			return;
		}
		record.started = true;
		stream.push({
			type: "tool_execution_start",
			toolCallId: toolCall.id,
			toolName: toolCall.name,
			args: effectiveArgs,
			intent: toolCall.intent,
		});

		const toolSpan = startExecuteToolSpan(telemetry, {
			tool,
			toolName: toolCall.name,
			toolCallId: toolCall.id,
			args: effectiveArgs,
			parent: invokeAgentSpan,
		});
		if (toolSpan && toolCall.intent) {
			toolSpan.setAttribute(OmpGenAIAttr.ToolCallIntent, toolCall.intent);
		}

		let result: AgentToolResult<any> = { content: [], details: {} };
		let isError = false;
		let caughtError: unknown;
		let completedToolExecution = false;
		let executionStarted = false;
		const abortBeforeToolExecution = (): boolean => {
			if (!isToolAborted(record)) return false;
			result = createToolSignalAbortedResult(signal?.aborted ? signal : record.signal);
			isError = true;
			return true;
		};

		await runInActiveSpan(toolSpan, async () => {
			try {
				if (!tool) {
					throw new Error(formatToolNotFoundMessage(toolCall.name, tools, suggestFallbackToolNames?.()));
				}
				if (abortBeforeToolExecution()) return;

				if (record.prepareError !== undefined) throw record.prepareError;
				if (record.blocked) {
					throw new ToolCallBlockedError(record.blockReason);
				}
				if (record.transformError !== undefined) throw record.transformError;
				const executionArgs =
					record.executionArgs ??
					(transformToolCallArguments ? transformToolCallArguments(effectiveArgs, toolCall.name) : effectiveArgs);
				record.args = executionArgs;
				// A transform or awaited claim can cancel the external run after
				// a queued wake already fixed the combined signal's reason.
				if (abortBeforeToolExecution()) return;

				const speculativeOutcome = speculationCoordinator
					? await speculationCoordinator.claim(tool, toolCall, executionArgs, earlierEffectsSettled, record.signal)
					: undefined;
				if (speculativeOutcome) {
					// Normalize exactly like the ordinary execute path below: third-party
					// speculation policies/hosts may return malformed results (missing or
					// non-array content) that must never persist verbatim in history.
					const coerced = coerceToolResult(speculativeOutcome.result);
					result = coerced.result;
					if (coerced.malformed || result.isError) isError = true;
					completedToolExecution = true;
					executionStarted = true;
				}

				if (!completedToolExecution) {
					if (abortBeforeToolExecution()) return;
					// The cooperative steering signal and the passive-context sink
					// ride the loop-owned ToolCallContext (surfacing as
					// `ctx.toolCall.*`); the host surfaces the sink on the context it
					// builds, and the loop hands that object to the tool untouched.
					// Wrapper-dispatched nested calls (for example `write xd://…`)
					// inherit the context, so their passive hook context joins this
					// root call at the batch boundary.
					const toolContext = getToolContext?.({
						batchId,
						index,
						total: toolCalls.length,
						toolCalls: toolCallInfos,
						steeringSignal: steeringSoftController.signal,
						providerMetadata: toolCall.providerMetadata,
						...(earlierEffectsSettled ? { earlierEffectsSettled } : {}),
						addAdditionalContext: context => {
							if (isNonBlankContext(context)) record.reportedContext.push(context);
						},
					});
					const streamSession = speculationCoordinator?.takeStreamSession(toolCall.id);
					if (streamSession && toolContext) {
						toolContext[SPECULATIVE_STREAM_SESSION] = streamSession;
					} else if (streamSession && !streamSession.contextIndependent) {
						await streamSession.discard("outer tool context cannot carry stream speculation");
					}
					let rawResult: unknown;
					try {
						// Context construction and stream cleanup can also cancel;
						// nothing may await or call host code after this final check.
						if (abortBeforeToolExecution()) return;
						executionStarted = true;
						rawResult = await tool.execute(
							toolCall.id,
							executionArgs,
							record.signal,
							partialResult => {
								const event: Extract<AgentEvent, { type: "tool_execution_update" }> = {
									type: "tool_execution_update",
									toolCallId: toolCall.id,
									toolName: toolCall.name,
									args: executionArgs,
									partialResult: coerceToolResult(partialResult).result,
								};
								if (stream.done) config.onDetachedToolUpdate?.(event);
								else stream.push(event);
							},
							toolContext,
						);
					} finally {
						await streamSession?.discard("outer tool completed without committing stream speculation");
					}
					completedToolExecution = true;
					const coerced = coerceToolResult(rawResult);
					result = coerced.result;
					if (coerced.malformed || result.isError) isError = true;
				}
			} catch (e) {
				caughtError = e;
				result = {
					content: [{ type: "text", text: e instanceof Error ? e.message : String(e) }],
					details: {},
				};
				isError = true;
			}

			if (afterToolCall && (!record.signal.aborted || completedToolExecution)) {
				try {
					const after = await afterToolCall(
						{
							assistantMessage,
							toolCall,
							args: record.args,
							result,
							isError,
							context: currentContext,
						},
						record.signal,
					);
					if (after) {
						// Re-normalize the post-hook result: `afterToolCall` is untyped user/extension
						// code and may return malformed `content` (non-array / invalid blocks), which
						// would otherwise be persisted verbatim and corrupt the session — the same
						// hazard `coerceToolResult` guards on the execute path.
						const coerced = coerceToolResult({
							content: after.content ?? result.content,
							details: after.details ?? result.details,
							isError: after.isError ?? result.isError,
							providerMetadata: after.providerMetadata ?? result.providerMetadata,
							useless: after.useless ?? result.useless,
						});
						result = coerced.result;
						isError = coerced.malformed || (after.isError ?? isError);
						if (isNonBlankContext(after.additionalContext)) {
							record.reportedContext.push(after.additionalContext);
						}
					}
				} catch (e) {
					caughtError = e;
					result = {
						content: [{ type: "text", text: e instanceof Error ? e.message : String(e) }],
						details: {},
					};
					isError = true;
				}
			}
		});

		const interrupted = interruptState.triggered;
		const perToolAborted = record.signal.aborted;
		const abortedDuringExecution = perToolAborted && isError && !completedToolExecution;
		if (record.interruptible && interrupted && abortedDuringExecution && !signal?.aborted) {
			// Queued steering/asides abort only interruptible tools. An external
			// user abort takes priority even if a queued interrupt fixed the
			// combined signal's reason first; keep the actual cancellation error.
			record.skipped = true;
			emitToolResult(record, createSkippedToolResult(interruptState.source, executionStarted), true);
		} else {
			// A tool that finished before the interrupt landed (`completedToolExecution`)
			// keeps its real result even if its signal aborted around completion:
			// the model must see the work it actually performed (#4752).
			// Non-interruptible tools also retain errors from external user aborts.
			emitToolResult(record, result, isError);
		}

		const firstTextBlock = result.content?.[0];
		const errorMessageForSpan =
			caughtError === undefined && isError && firstTextBlock?.type === "text" ? firstTextBlock.text : undefined;
		const status = abortedDuringExecution
			? "aborted"
			: caughtError instanceof ToolCallBlockedError
				? "blocked"
				: isError
					? "error"
					: "ok";
		finishExecuteToolSpan(telemetry, toolSpan, {
			result,
			isError,
			status,
			errorMessage: errorMessageForSpan,
			errorObject: caughtError,
			toolCallId: toolCall.id,
			toolName: toolCall.name,
		});

		// Best-effort steering probe: its own failure is surfaced by the
		// dedicated watch path (which guards the identical call), so a rejecting
		// host `hasSteeringMessages`/`hasIrcInterrupts` callback must not reject
		// this task. An unguarded rejection here fires after the tool already
		// ran and poisons the `start.then(runTool)` ordering chain, skipping
		// every later chained record with a phantom "pending steering" result.
		await checkSteering().catch(() => undefined);
	};

	let lastExclusive: Promise<void> = Promise.resolve();
	let sharedTasks: Promise<void>[] = [];
	// The shared calls among `sharedTasks` whose approval, asked with the call's
	// arguments, is not "read": they may change files that a later call running
	// beside them reads.
	let sharedEffects: Promise<void>[] = [];
	const tasks: Promise<void>[] = [];

	// While tool calls are in flight, queued steering or interrupting IRC would
	// otherwise wait out the tools' own window. Poll only non-consuming queues:
	// detection hard-aborts interruptible waits (running or not yet started),
	// and steering/IRC additionally soft-signal cooperative tools
	// (auto-background bash), so the boundary dequeue below injects the message
	// promptly. In "wait" mode only a batch holding an interruptible wait needs
	// the watch; checkSteering is idempotent (no-op once triggered).
	const hasAsidePeek =
		hasIrcInterrupts !== undefined || hasBackgroundCompletions !== undefined || hasQueuedAsides !== undefined;
	const watchSteeringWhileRunning =
		(softInterrupts || records.some(record => record.interruptible)) &&
		(hasSteeringMessages !== undefined || hasAsidePeek);
	// Live-taken steering is already pending: interrupt before any call starts
	// so interruptible tools skip or drain the queued wake without blocking.
	if (liveSteering.length > 0) await checkSteering();
	const eventDrivenSteeringWatch =
		watchSteeringWhileRunning && config.waitForSteeringMessages !== undefined && hasSteeringMessages !== undefined;
	const steeringWatchAbortController = new AbortController();
	const steeringWatchSignal = signal
		? AbortSignal.any([signal, steeringWatchAbortController.signal])
		: steeringWatchAbortController.signal;
	// Race every wait against one local abort promise. The callback contract does
	// not require an implementation to observe the signal, and one that resolves
	// only on the next queue event would otherwise never settle once the batch
	// finishes, so awaiting it during teardown would hang a batch with no steer.
	const { promise: watchAborted, resolve: resolveWatchAbort } = Promise.withResolvers<void>();
	if (steeringWatchSignal.aborted) {
		resolveWatchAbort();
	} else {
		steeringWatchSignal.addEventListener("abort", () => resolveWatchAbort(), { once: true });
	}
	const watchAbortedFalse = watchAborted.then(() => false);
	const steeringWatchPromise = eventDrivenSteeringWatch
		? (async (): Promise<void> => {
				while (!steeringWatchSignal.aborted) {
					// Subscribe before checking queue state. This closes the edge
					// race where a steer arrives after a check but before listener
					// registration: the subsequent check observes queued state,
					// while later arrivals resolve this already-installed wait.
					const steeringQueued = config.waitForSteeringMessages?.(steeringWatchSignal).then(
						() => true,
						() => false,
					);
					const steeringChecked = checkSteering().then(
						() => true,
						() => false,
					);
					if (!(await Promise.race([steeringChecked, watchAbortedFalse]))) return;
					// Stop once nothing is left to escalate: the cooperative signal
					// is up, or (without soft interrupts) the waits are cut. A
					// completion-only trigger leaves the soft signal down, so keep
					// watching: a genuine steer arriving afterwards must still
					// reach foreground tools.
					if (
						steeringWatchSignal.aborted ||
						steeringSoftController.signal.aborted ||
						(!softInterrupts && interruptState.triggered)
					)
						return;
					if (!(await Promise.race([steeringQueued, watchAbortedFalse]))) return;
				}
			})()
		: undefined;
	// IRC interrupt records and background completions live in session-owned
	// queues with no wake callback. Keep the timer fallback when either peek is
	// present; system steering uses the event-driven path above and does not poll.
	const steeringWatchTimer =
		watchSteeringWhileRunning && (!eventDrivenSteeringWatch || hasAsidePeek)
			? setInterval(
					() => void (eventDrivenSteeringWatch ? checkAsideInterrupts() : checkSteering()),
					STEERING_INTERRUPT_POLL_MS,
				)
			: undefined;
	for (let index = 0; index < records.length; index++) {
		const record = records[index];
		// Resolved from the prepared (possibly hook-revised) args — raw args
		// only when validation failed, and those records error out before executing.
		const concurrency = resolveToolConcurrency(record.tool, record.args);
		const start = concurrency === "exclusive" ? Promise.all([lastExclusive, ...sharedTasks]) : lastExclusive;
		const earlierEffectsSettled =
			concurrency === "shared" && sharedEffects.length > 0
				? Promise.allSettled(sharedEffects).then(() => undefined)
				: undefined;
		const task = start.then(async () => {
			try {
				await runTool(record, index, earlierEffectsSettled);
			} finally {
				refreshPauseState();
			}
		});
		tasks.push(task);
		if (concurrency === "exclusive") {
			lastExclusive = task;
			sharedTasks = [];
			sharedEffects = [];
		} else {
			sharedTasks.push(task);
			// A dynamic approval is asked with the prepared arguments, as concurrency
			// is above, and no context; one that throws, or that says anything but
			// "read", counts as a call that may write. A resolver that says "write"
			// only with a context or only for transformed arguments is not counted, so
			// a read after it returns what it read first.
			const approval = record.tool?.approval;
			let decision: ToolApprovalDecision | undefined;
			try {
				decision = typeof approval === "function" ? approval(record.args) : approval;
			} catch {
				decision = undefined;
			}
			const tier = typeof decision === "string" ? decision : (decision?.tier ?? "exec");
			if (tier !== "read") sharedEffects.push(task);
		}
	}
	try {
		await Promise.allSettled(tasks);
	} finally {
		if (speculationCoordinator) speculationCoordinator.onIdle = undefined;
		config.onPauseChange?.(false);
		steeringWatchAbortController.abort();
		await steeringWatchPromise?.catch(() => undefined);
		clearInterval(steeringWatchTimer);
	}

	for (const record of records) {
		if (!record.toolResultMessage) {
			record.skipped = true;
			recordSkippedTool(telemetry, {
				toolCallId: record.toolCall.id,
				toolName: record.toolCall.name,
				status: "skipped",
			});
			emitToolResult(record, createSkippedToolResult(interruptState.source, false), true);
		}
	}
	await speculationCoordinator?.discardAll("candidate was not dispatched");

	// Skipped calls never ran. Hook-prepared context also requires a non-error
	// final result; context the tool itself reported during execution stands.
	// Within a call, tool-reported context (including nested `xd://` dispatch)
	// precedes the hook's: wrappers release hook context only after the call
	// succeeds, so this is the one order every dispatch path can produce.
	const additionalContext = joinAdditionalContext(
		records
			.filter(record => !record.skipped)
			.flatMap(record => [
				...record.reportedContext,
				record.toolResultMessage?.isError ? undefined : record.preparedContext,
			]),
	);
	return {
		toolResults: emittedToolResults,
		...(additionalContext !== undefined ? { additionalContext } : {}),
	};
}

/**
 * Discriminator embedded in {@link AgentToolResult.details} and
 * {@link ToolResultMessage.details} for tool calls that were emitted by the
 * assistant but never actually invoked locally.
 *
 * The synthetic result exists only to preserve the tool_use / tool_result
 * pairing the provider API requires; no `tool.execute()` ran. UI, telemetry,
 * and history consumers can key on `__synthetic === true` to render or
 * classify these as "call emitted, not executed" instead of a real local
 * tool failure — the mislabeling this discriminator was introduced to fix
 * (#4321): a provider-side stream error after tool-call emission (e.g. Codex
 * websocket close) was surfaced by the CLI as if the local tool had failed.
 *
 * `source` names the state that prevented execution — either an assistant-side
 * turn termination (`assistant_stop_*`) or a mid-batch interrupt that skipped a
 * still-pending call to service queued steering/peer input (`interrupt_skipped`).
 * `upstreamError` is the provider-reported message when the turn ended with
 * `stopReason === "error"`.
 */
export interface SyntheticToolResultDetails {
	__synthetic: true;
	source:
		| "assistant_stop_aborted"
		| "assistant_stop_error"
		| "assistant_stop_skipped"
		| "assistant_stop_length"
		| "interrupt_skipped";
	executed: false;
	upstreamError?: string;
}

/**
 * Metadata for an interrupt-aborted call that entered `tool.execute()` but
 * threw before returning a usable result. It may have performed partial work.
 */
interface InterruptedToolResultDetails {
	__interrupted: true;
	source: "interrupt_skipped";
	execution: "started";
}

/**
 * Narrow an {@link AgentMessage} to a synthetic {@link ToolResultMessage} —
 * a tool_result emitted for a tool call the assistant never invoked (see
 * {@link SyntheticToolResultDetails}). Consumers use this to look past the
 * placeholder pairing back to the assistant turn that produced it, e.g.
 * `AgentSession.retry()` walking back over the synthetic results a
 * stalled/aborted mid-tool-call turn leaves behind.
 */
export function isSyntheticToolResultMessage(
	message: AgentMessage | undefined,
): message is ToolResultMessage<SyntheticToolResultDetails> {
	return (
		message?.role === "toolResult" &&
		(message.details as SyntheticToolResultDetails | undefined)?.__synthetic === true
	);
}

function syntheticDetailsFor(
	reason: "aborted" | "error" | "skipped" | "length",
	errorMessage: string | undefined,
): SyntheticToolResultDetails {
	const source: SyntheticToolResultDetails["source"] =
		reason === "aborted"
			? "assistant_stop_aborted"
			: reason === "error"
				? "assistant_stop_error"
				: reason === "length"
					? "assistant_stop_length"
					: "assistant_stop_skipped";
	return {
		__synthetic: true,
		source,
		executed: false,
		...(reason === "error" && errorMessage ? { upstreamError: errorMessage } : {}),
	};
}

/**
 * Create the persisted synthetic result for a tool call that was emitted by
 * the assistant but never invoked locally.
 */
export function createSyntheticToolResultMessage(
	toolCall: Extract<AssistantMessage["content"][number], { type: "toolCall" }>,
	reason: "aborted" | "error" | "skipped" | "length",
	errorMessage?: string,
): ToolResultMessage<SyntheticToolResultDetails> {
	const message =
		reason === "aborted"
			? "Tool execution was aborted"
			: reason === "length"
				? "Tool call was not executed because the assistant hit its output token limit (stop_reason: length) before the arguments could complete; the recorded arguments are truncated and unsafe to run. Do NOT retry by re-emitting the same large payload — split the work into several smaller tool calls (e.g. for `write`/`edit`, write the first chunk then append the rest with subsequent `edit` insert ops, or break the file into multiple `write` targets)"
				: reason === "skipped"
					? "Tool call was not executed because the assistant ended its turn"
					: "Tool call was not executed because the provider stream ended with an error before the tool could run";
	const details = syntheticDetailsFor(reason, errorMessage);
	return {
		role: "toolResult",
		toolCallId: toolCall.id,
		toolName: toolCall.name,
		content: [{ type: "text", text: errorMessage ? `${message}: ${errorMessage}` : `${message}.` }],
		details,
		isError: true,
		timestamp: Date.now(),
	};
}

/**
 * Create and emit a tool result for a tool call that was emitted by the
 * assistant but never invoked locally.
 */
function createAbortedToolResult(
	toolCall: Extract<AssistantMessage["content"][number], { type: "toolCall" }>,
	stream: EventStream<AgentEvent, AgentMessage[]>,
	reason: "aborted" | "error" | "skipped" | "length",
	errorMessage?: string,
): ToolResultMessage {
	const toolResultMessage = createSyntheticToolResultMessage(toolCall, reason, errorMessage);
	const result: AgentToolResult<SyntheticToolResultDetails> = {
		content: toolResultMessage.content,
		details: toolResultMessage.details,
	};

	stream.push({
		type: "tool_execution_start",
		toolCallId: toolCall.id,
		toolName: toolCall.name,
		args: toolCall.arguments,
		intent: toolCall.intent,
	});
	stream.push({
		type: "tool_execution_end",
		toolCallId: toolCall.id,
		toolName: toolCall.name,
		result,
		isError: true,
	});
	stream.push({ type: "message_start", message: toolResultMessage });
	stream.push({ type: "message_end", message: toolResultMessage });

	return toolResultMessage;
}

function createToolSignalAbortedResult(signal: AbortSignal): AgentToolResult<unknown> {
	const reason = abortReasonText(signal);
	return {
		content: [{ type: "text", text: `Tool was not executed because the run was aborted: ${reason}.` }],
		details: {},
	};
}

/** Origin of a mid-batch interrupt: queued steering, a peer IRC, a queued aside, or a background completion notice. */
type AsideInterruptSource = SteeringInterruptSource | "irc" | "aside" | "background";

function createSkippedToolResult(
	source: AsideInterruptSource | undefined,
	executionStarted: boolean,
): AgentToolResult<SyntheticToolResultDetails | InterruptedToolResultDetails> {
	let reason = "pending steering message";
	let blocker = "queued message";
	if (source === "user") {
		reason = "queued user message";
		blocker = "queued message";
	} else if (source === "agent") {
		reason = "pending parent steering message";
		blocker = "steering message";
	} else if (source === "system") {
		reason = "pending system advisory";
		blocker = "advisory";
	} else if (source === "irc") {
		reason = "pending peer interrupt";
		blocker = "interrupt";
	} else if (source === "aside") {
		reason = "a queued aside message";
		blocker = "aside";
	} else if (source === "background") {
		reason = "a queued background completion (job or supervised process)";
		blocker = "completion notice";
	}
	return {
		content: [
			{
				type: "text",
				text: `Skipped due to ${reason}. Do not count this skipped result as completed work or verification. After the ${blocker} is handled on the next step, retry the skipped tool if it is still needed.`,
			},
		],
		details: executionStarted
			? { __interrupted: true, source: "interrupt_skipped", execution: "started" }
			: { __synthetic: true, source: "interrupt_skipped", executed: false },
	};
}

import type {
	ApiKey,
	AssistantMessage,
	AssistantMessageEvent,
	AssistantMessageEventStream,
	Context,
	Effort,
	ImageContent,
	Message,
	Model,
	ServiceTier,
	SimpleStreamOptions,
	Static,
	streamSimple,
	TextContent,
	Tool,
	ToolCallProviderMetadata,
	ToolChoice,
	ToolResultMessage,
	ToolResultProviderMetadata,
	TSchema,
} from "@oh-my-pi/pi-ai";
import type { Dialect } from "@oh-my-pi/pi-ai/dialect";
import type { HarmonyAuditEvent } from "@oh-my-pi/pi-ai/utils/harmony-leak";
import type { AppendOnlyContextManager } from "./append-only-context";
import type { AgentRunCoverage, AgentRunSummary } from "./run-collector";
import type { SentToolDefinitions } from "./sent-tool-definitions";
import type { AgentTelemetryConfig } from "./telemetry";

/** Stream function - can return sync or Promise for async config lookup */
export type StreamFn = (
	...args: Parameters<typeof streamSimple>
) => AssistantMessageEventStream | Promise<AssistantMessageEventStream>;

/** Staged queue preparation; commit synchronously only while the batch is still owned. */
export interface QueuedMessagePreparation {
	/** Append context after the originals; undefined stops this attempt, retaining originals unless explicitly removed. */
	commit(): readonly AgentMessage[] | undefined;
}

/** Which agent queue a batch came from: steering amends the running task, follow-ups start the next one. */
export type QueuedMessageQueue = "steering" | "followUp";

/** Prepare an exclusively claimed batch. Undefined delivers unchanged; the signal also aborts when the claim is cancelled. */
export type PrepareQueuedMessages = (
	messages: readonly AgentMessage[],
	signal: AbortSignal,
	queue: QueuedMessageQueue,
) => QueuedMessagePreparation | undefined | Promise<QueuedMessagePreparation | undefined>;

/**
 * Synchronous arbiter over queued messages leaving a queue for delivery, for a
 * queue whose messages someone else may withdraw concurrently (a session homed
 * on another thread whose view pops them).
 */
export interface QueuedMessageGate {
	/**
	 * Called with the batch about to be removed from `queue` for delivery; returns
	 * the candidates that must be dropped from the queue instead. The others are
	 * claimed for delivery.
	 */
	claim(queue: QueuedMessageQueue, candidates: readonly AgentMessage[]): readonly AgentMessage[];
	/** Called with claimed messages that left delivery undelivered (requeued, withdrawn, or cancelled). */
	release(messages: readonly AgentMessage[]): void;
}

/** Called once an aside has been inserted into the agent's live context. */
export const ASIDE_MESSAGE_COMMIT = Symbol("aside-message-commit");
/** Symbol-keyed handoff for one finalized, tool-owned stream speculation session. */
export const SPECULATIVE_STREAM_SESSION = Symbol("speculative-stream-session");
/** Called when an aside was drained but the agent loop ended before inserting it. */
export const ASIDE_MESSAGE_DISCARD = Symbol("aside-message-discard");
/** Revalidate a generation-scoped batch immediately before insertion into live context. */
export const ASIDE_MESSAGE_REFRESH = Symbol("aside-message-refresh");

export type CommittableAsideMessage = AgentMessage & {
	[ASIDE_MESSAGE_COMMIT]?: () => void;
	[ASIDE_MESSAGE_DISCARD]?: (error: Error) => void;
	[ASIDE_MESSAGE_REFRESH]?: () => AgentMessage | null;
};

/**
 * An aside entry: a ready {@link AgentMessage}, or a sync thunk evaluated at
 * injection time that returns the message to inject or `null` to skip it. Thunks
 * let the producer make the final inject-or-drop decision against current state
 * (e.g. dropping late diagnostics a newer edit superseded).
 */
export type AsideMessage = CommittableAsideMessage | (() => CommittableAsideMessage | null);

/** Where the loop polls asides: after a tool batch (`"work"`) or after a turn without tool calls (`"stop"`). */
export type AsideBoundary = "work" | "stop";

export interface AgentTurnEndContext {
	/** Assistant/user message that just completed this turn boundary. */
	message: AgentMessage;
	/** Tool results produced by this turn, already paired with `message` in the live context. */
	toolResults: ToolResultMessage[];
	/**
	 * Passive model-visible messages appended after the tool results at this
	 * boundary. The agent loop always sends an array (possibly empty);
	 * absent is equivalent to empty for hosts that construct the context.
	 */
	additionalMessages?: AgentMessage[];
	/** True when the current tool-loop batch is continuing without yielding to post-turn steering. */
	willContinue: boolean;
}

export interface AgentPreModelCallStop {
	/** Stop the agent loop before sending the next provider request. */
	stop: true;
	/** Optional owner-facing reason, logged by the loop when it stops. */
	reason?: string;
}

export type AgentPreModelCallResult = AgentPreModelCallStop | undefined;

/**
 * A pre-model-call gate. Return {@link AgentPreModelCallStop} to refuse the
 * request, or nothing to proceed; the signal aborts with the run.
 */
export type AgentBeforeModelCall = (
	context: Context,
	signal?: AbortSignal,
) => AgentPreModelCallResult | void | Promise<AgentPreModelCallResult | void>;

/**
 * A soft tool requirement: the host wants `toolName` called before the loop
 * runs other tools or yields, but WITHOUT paying the forced-`toolChoice` cost
 * up front (changing `tool_choice` invalidates the provider message cache).
 * Returned from {@link AgentLoopConfig.getToolChoice} in place of a hard
 * {@link ToolChoice}: the loop injects `reminder` once when a new `id` becomes
 * active, runs with `toolChoice` unchanged, and escalates to a one-turn forced
 * choice only if the model fails to call `toolName`. Auto-clears when the host
 * stops returning it or `toolName` is no longer an active tool.
 */
export interface SoftToolRequirement {
	/** Discriminates a soft requirement from a hard {@link ToolChoice}. */
	soft: true;
	/**
	 * Stable id of the *current* requirement. The loop injects `reminder` when
	 * this id first becomes active and again whenever it changes (e.g. one
	 * stacked preview resolves and the next becomes the head), but never
	 * re-injects for an unchanged id across turns.
	 */
	id: string;
	/** Tool that must be called before the loop runs other tools or yields. */
	toolName: string;
	/**
	 * Per-call compliance check: a turn satisfies the requirement only when every
	 * tool call passes. Defaults to `name === toolName`. Lets a host demand a
	 * specific invocation shape (e.g. `write` targeting a virtual device path)
	 * instead of any call to `toolName`. Escalation still forces `toolName`.
	 */
	satisfies?(toolCall: { name: string; arguments?: Record<string, unknown> }): boolean;
	/** Host-owned reminder messages, injected once per `id` activation. */
	reminder: AgentMessage[];
}

/**
 * A per-turn tool-choice directive: either a hard provider {@link ToolChoice}
 * (applied verbatim) or a {@link SoftToolRequirement} (remind-then-escalate).
 */
export type ToolChoiceDirective = ToolChoice | SoftToolRequirement;

/** Mutable soft-requirement lifecycle retained across stopped agent runs. */
export interface SoftToolRequirementState {
	id?: string;
	forcedToolChoice?: ToolChoice;
	escalations: number;
}

/** True when a {@link ToolChoiceDirective} is a soft requirement, not a hard choice. */
export function isSoftToolRequirement(directive: ToolChoiceDirective | undefined): directive is SoftToolRequirement {
	return typeof directive === "object" && directive !== null && (directive as SoftToolRequirement).soft === true;
}

/**
 * Source category for a queued steering interrupt observed without consuming the queue.
 * Distinguishes real-user, agent-authored, system/advisor, and unknown steering.
 */
export type SteeringInterruptSource = "user" | "agent" | "system" | "unknown";

/** Non-consuming summary of whether queued steering should interrupt a tool batch. */
export interface SteeringQueueState {
	/** True when at least one steering message is queued. */
	queued: boolean;
	/** Best-effort origin used only to word synthetic skipped-tool results. */
	source?: SteeringInterruptSource;
}

/**
 * Configuration for the agent loop.
 */
export interface AgentLoopConfig extends SimpleStreamOptions {
	model: Model;

	/** Reports whether this loop has reached a safe process-pause boundary. */
	onPauseChange?: (paused: boolean) => void;

	/**
	 * When to interrupt tool execution for steering messages.
	 * - "immediate" = cut interruptible waits short and raise the cooperative
	 *   `steeringSignal` for other running tools (default)
	 * - "wait" = let non-interruptible tools finish undisturbed; interruptible
	 *   waits are still cut short, since they have no work to complete
	 */
	interruptMode?: "immediate" | "wait";

	/**
	 * Optional session identifier forwarded to LLM providers.
	 * Used by providers that support session-based caching (e.g., OpenAI Codex).
	 */
	sessionId?: string;

	/** Absolute wall-clock deadline in Unix epoch milliseconds. */
	deadline?: number;

	/**
	 * Optional resolver called per LLM request to produce request metadata.
	 * When set, the agent loop evaluates it **after** `getApiKey` resolves the
	 * session-sticky credential, ensuring the metadata's `account_uuid` reflects
	 * the credential actually used for the request (not the credential that was
	 * current when `AgentLoopConfig` was first constructed). Overrides the static
	 * `metadata` field when present.
	 */
	metadataResolver?: (provider: string) => Record<string, unknown> | undefined;

	/**
	 * Converts AgentMessage[] to LLM-compatible Message[] before each LLM call.
	 *
	 * Each AgentMessage must be converted to a UserMessage, AssistantMessage, or ToolResultMessage
	 * that the LLM can understand. AgentMessages that cannot be converted (e.g., UI-only notifications,
	 * status messages) should be filtered out.
	 *
	 * @example
	 * ```typescript
	 * convertToLlm: (messages) => messages.flatMap(m => {
	 *   if (m.role === "custom") {
	 *     // Convert custom message to user message
	 *     return [{ role: "user", content: m.content, timestamp: m.timestamp }];
	 *   }
	 *   if (m.role === "notification") {
	 *     // Filter out UI-only messages
	 *     return [];
	 *   }
	 *   // Pass through standard LLM messages
	 *   return [m];
	 * })
	 * ```
	 */
	convertToLlm: (messages: AgentMessage[]) => Message[] | Promise<Message[]>;

	/**
	 * Optional transform applied to the context before `convertToLlm`.
	 *
	 * Use this for operations that work at the AgentMessage level:
	 * - Context window management (pruning old messages)
	 * - Injecting context from external sources
	 *
	 * @example
	 * ```typescript
	 * transformContext: async (messages) => {
	 *   if (agent.tokenizer.countMessages(messages) > MAX_TOKENS) {
	 *     return pruneOldMessages(messages);
	 *   }
	 *   return messages;
	 * }
	 * ```
	 */
	transformContext?: (messages: AgentMessage[], signal?: AbortSignal) => Promise<AgentMessage[]>;

	/**
	 * Optional transform applied to the final provider context after conversion,
	 * normalization, and append-only context handling, but before telemetry capture
	 * and provider send.
	 */
	transformProviderContext?: (context: Context, model: Model) => Context | Promise<Context>;

	/** Remembers sent tool definitions to fill {@link Context.inactiveTools}. */
	sentToolDefinitions?: SentToolDefinitions;

	/**
	 * Resolves the API key or resolver for the current model before each LLM call.
	 *
	 * Returning an ApiKeyResolver lets the stream retry policy refresh or rotate
	 * the model-scoped credential after auth/usage-limit errors.
	 */
	getApiKey?: (model: Model) => Promise<ApiKey | undefined> | ApiKey | undefined;

	/**
	 * Returns steering messages to inject into the conversation mid-run.
	 *
	 * Called at injection boundaries only (loop start and after a tool batch
	 * fully settles), so dequeued messages are immediately injected. The
	 * mid-batch interrupt poll uses {@link hasSteeringMessages} instead and
	 * never consumes the queue.
	 */
	getSteeringMessages?: (signal?: AbortSignal) => Promise<AgentMessage[]>;

	/** Whether input is still owned by a queue and must be restored if a model call is aborted before it starts. */
	isUndeliveredQueuedMessage?: (message: AgentMessage) => boolean;

	/**
	 * Peeks whether steering messages are queued, without consuming them.
	 *
	 * Polled while a tool batch runs (in "wait" mode, only when the batch holds an
	 * interruptible tool) to decide whether to abort in-flight and skip
	 * not-yet-started *interruptible* waits, unless they handle queued interrupts;
	 * every other already-emitted call still executes and the message injects
	 * at the batch boundary. The queue keeps
	 * owning its messages until the loop reaches the next injection boundary and
	 * dequeues via {@link getSteeringMessages} — so callers can still cancel or
	 * restore queued messages while in-flight tools settle, and an external
	 * abort in that window leaves the queue intact for a post-abort continue.
	 *
	 * Returning `true` is treated as user-originated steering for compatibility.
	 * Return a {@link SteeringQueueState} when the queue can distinguish system
	 * advisories from real user messages.
	 *
	 * When omitted, steering never interrupts a running tool batch; queued
	 * messages are still delivered at the next injection boundary.
	 */
	hasSteeringMessages?: () => boolean | SteeringQueueState | Promise<boolean | SteeringQueueState>;

	/**
	 * Wakes the in-flight tool interrupt watcher when a steering message is queued.
	 * The callback must not consume the queue; the loop still calls
	 * {@link hasSteeringMessages} before aborting and injects through
	 * {@link getSteeringMessages}.
	 */
	waitForSteeringMessages?: (signal?: AbortSignal) => Promise<void>;

	/**
	 * Called when live steering dequeues messages via {@link getSteeringMessages}
	 * for the response being streamed. The loop records them in the transcript
	 * after that response (or its tool batch); an abort before then leaves them
	 * unrecorded for the host to requeue.
	 */
	onLiveSteeringTaken?: (messages: AgentMessage[]) => void;

	/**
	 * Peeks whether IRC messages should interrupt an interruptible waiting tool.
	 *
	 * Uses the same delivery rules as steering: the poll is non-consuming, only
	 * runs for interruptible tools, and cuts them short even when interruptMode
	 * is "wait".
	 * The host owns message injection at the next boundary.
	 */
	hasIrcInterrupts?: () => boolean | Promise<boolean>;
	/**
	 * Peeks whether a background notice (finished job, exited supervised
	 * process, output a running job was asked to report) is queued for aside
	 * injection at the next boundary.
	 *
	 * Same rules as {@link hasIrcInterrupts}: non-consuming, only cuts
	 * *interruptible* waits short, in either interruptMode. Without
	 * it a completion notice sits behind an hour-long `wait` that the agent
	 * would have abandoned had it seen the notice. Unlike a peer IRC it never
	 * raises {@link ToolCallContext.steeringSignal}: a queued completion must
	 * not push ordinary foreground work (auto-background bash/eval) into the
	 * background.
	 */
	hasBackgroundCompletions?: () => boolean | Promise<boolean>;
	/**
	 * Peeks whether a passive aside (an extension or user message queued with
	 * `deliverAs: "aside"`) is waiting for injection at the next boundary.
	 *
	 * Same rules as {@link hasBackgroundCompletions}: non-consuming, ends only
	 * *interruptible* waits, never raises {@link ToolCallContext.steeringSignal}.
	 * The host still injects the aside once at the boundary; ordinary running
	 * tools finish first.
	 */
	hasQueuedAsides?: () => boolean | Promise<boolean>;
	/**
	 * Receives a tool's `onUpdate` frames that arrive after this run's event
	 * stream ended: a call that returned while its background job keeps
	 * reporting (`details.async`), whose run yielded before the job settled.
	 * Without it those frames are dropped.
	 */
	onDetachedToolUpdate?: (event: Extract<AgentEvent, { type: "tool_execution_update" }>) => void;

	/**
	 * Returns follow-up messages to process after the agent would otherwise stop.
	 *
	 * Called when the agent has no more tool calls and no steering messages.
	 * If messages are returned, they're added to the context and the agent
	 * continues with another turn.
	 */
	getFollowUpMessages?: (signal?: AbortSignal) => Promise<AgentMessage[]>;
	/**
	 * Returns non-interrupting "aside" messages to inject at a step boundary.
	 *
	 * Polled after each tool batch (before the next LLM call) AND at the yield
	 * check. Unlike steering, these never abort foreground tools (only an
	 * interruptible `wait` ends early, via the peek hooks) — they are passive
	 * notifications (e.g. background-job completions, late LSP diagnostics) that
	 * should reach the model between requests without waiting for the agent to
	 * fully stop. Returned messages are appended to the context with normal
	 * message events and keep the loop running so the model can react.
	 *
	 * `boundary` is `"work"` after a tool batch and `"stop"` when the model ended
	 * its turn without tool calls; a provider may hold back messages that should
	 * not extend a finished turn.
	 */
	getAsideMessages?: (boundary: AsideBoundary) => Promise<AsideMessage[]>;
	/**
	 * Hook fired right before the loop would exit.
	 *
	 * Called when the agent has no more tool calls and no steering messages,
	 * immediately before polling follow-up messages.
	 */
	onBeforeYield?: () => Promise<void> | void;

	/**
	 * Provides tool execution context, resolved per tool call.
	 * Use for late-bound UI or session state access. The loop passes the tool
	 * call's {@link ToolCallContext}; hosts that support passive tool context
	 * surface its `addAdditionalContext` sink as
	 * {@link AgentToolContext.addAdditionalContext}. The returned object is
	 * handed to the tool as-is.
	 */
	getToolContext?: (toolCall?: ToolCallContext) => AgentToolContext | undefined;

	/**
	 * Refreshes prompt/tool context from live session state before each model call.
	 * Use this when tool availability or the system prompt can change mid-turn.
	 *
	 * Runs after pending messages are folded in and before provider conversion.
	 * Mutate the agent context here; use `beforeModelCall` to inspect the
	 * provider-bound context.
	 */
	syncContextBeforeModelCall?: (context: AgentContext, signal?: AbortSignal) => void | Promise<void>;

	/**
	 * Asked after the complete provider context has been built, including
	 * message conversion, provider transforms, normalized tools, and owned
	 * dialect prompt injection. Returning {@link AgentPreModelCallStop} ends
	 * the stream without emitting `turn_start`, so no turn is left open and no
	 * request is billed. Return nothing to proceed. The signal aborts when
	 * the run is canceled or its deadline expires.
	 */
	beforeModelCall?: AgentBeforeModelCall;

	/**
	 * Optional transform applied to tool call arguments before execution.
	 * Use for deobfuscating secrets or rewriting arguments.
	 */
	transformToolCallArguments?: (args: Record<string, unknown>, toolName: string) => Record<string, unknown>;
	/**
	 * Opt-in speculative execution for finalized, discard-safe tool calls.
	 *
	 * Candidates remain invisible until ordinary dispatch commits their result.
	 */
	speculativeToolExecution?: SpeculativeToolExecutionConfig;
	/**
	 * Resolve a tool call whose name matched no advertised tool (including
	 * `customWireName` aliases). Lets hosts route calls to tools they expose
	 * through side transports (e.g. `xd://` device mounts) instead of failing
	 * with "Tool not found". Returning `undefined` keeps the failure.
	 *
	 * `advertised` is the very snapshot exact-name dispatch just searched — the
	 * set offered to THIS request. A host must resolve against it rather than
	 * its own live tool state: an MCP `tools/list_changed` mid-stream reassigns
	 * the agent's tools, so live state can hold a roster the model never saw,
	 * and a name-recovering host would dispatch a tool this request never
	 * advertised while exact dispatch still answered from the snapshot.
	 */
	resolveFallbackTool?: (name: string, advertised: readonly AgentTool<any>[]) => AgentTool<any> | undefined;
	/**
	 * Names reachable through {@link resolveFallbackTool} but absent from the
	 * advertised set (e.g. `xd://` device mounts). Consulted only to name a
	 * plausible target when a call misses, so a mis-transcribed device call is
	 * recoverable; never a dispatch source.
	 */
	suggestFallbackToolNames?: () => Iterable<string>;

	/**
	 * Enable intent tracing for tool calls.
	 * When enabled, the harness injects a `string` field into tool schemas sent to the model,
	 * then strips from arguments before executing tools.
	 */
	intentTracing?: boolean;
	/** Schema description of the injected intent field; `PI_INTENT_DESC` overrides it. Default `concise intent`. */
	intentDescription?: string;
	/**
	 * Strip tool descriptions (top-level + nested schema annotations) from the
	 * provider-bound tool specs. Use when the full catalog is rendered into the
	 * system prompt instead, so descriptions are not duplicated on the wire.
	 */
	pruneToolDescriptions?: boolean;
	/**
	 * Owned tool calling dialect.
	 *
	 * Undefined keeps provider-native tool calling. A dialect value sends no
	 * native `tools`, forces `toolChoice` off, appends that dialect's tool catalog
	 * instructions, re-encodes prior tool calls/results as text, and parses the
	 * model's text output back into canonical `toolCall` blocks.
	 */
	dialect?: Dialect;
	/**
	 * Per-call owned-dialect resolver, read once per LLM call with the model
	 * being requested. Authoritative when set: its return value (including
	 * `undefined` = native tool calling) replaces the static {@link dialect}.
	 */
	getDialect?: (model: Model) => Dialect | undefined;
	/**
	 * When owned (in-band) tool calling is active and the model starts
	 * fabricating a tool result inside its own turn, control how the loop reacts:
	 * - `true` (default): abort the provider request immediately so it stops
	 *   generating the hallucinated continuation (cheaper, lower latency).
	 * - `false`: let the request finish and silently discard everything past the
	 *   fabrication boundary (keeps the connection alive but pays for the tokens
	 *   the model spends on the discarded tail).
	 * Only meaningful when {@link dialect} (or `PI_DIALECT`) selects an
	 * owned dialect; native tool calling never fabricates results in text.
	 */
	abortOnFabricatedToolResult?: boolean;
	/**
	 * Append-only context mode — stabilizes system prompt + tool spec bytes
	 * across turns so provider prefix caches hit at maximum rate.
	 *
	 * When set, the loop reads messages from the append-only log (stable
	 * byte prefix) and caches system prompt + tools. Tools exclude per-turn
	 * `i` intent fields.
	 */
	appendOnlyContext?: AppendOnlyContextManager;

	/**
	 * Inspect assistant streaming events before they are published to the outer agent event stream.
	 * Callers may abort synchronously to stop consuming buffered provider events.
	 */
	onAssistantMessageEvent?: (message: AssistantMessage, event: AssistantMessageEvent) => void;

	/**
	 * Called when GPT-5 Harmony protocol leakage is detected and mitigated.
	 */
	onHarmonyLeak?: (event: HarmonyAuditEvent) => void | Promise<void>;

	/**
	 * Dynamic tool-choice directive, resolved once per turn. Returns a hard
	 * {@link ToolChoice} (applied verbatim, overriding the static `toolChoice`),
	 * a {@link SoftToolRequirement} (the loop reminds-then-escalates instead of
	 * forcing `tool_choice` immediately, so a model that complies with the
	 * reminder pays no message-cache invalidation), or `undefined` to fall back
	 * to the static `toolChoice`.
	 */
	getToolChoice?: () => ToolChoiceDirective | undefined;

	/**
	 * Soft-requirement lifecycle retained by the host when a pre-model-call
	 * gate stops a run before its pending reminder or escalation is served.
	 */
	softToolRequirementState?: SoftToolRequirementState;

	/**
	 * Notifies the host that the pre-model-call gate stopped the run after a
	 * hard tool choice was obtained from {@link getToolChoice} but before it
	 * was served, so the host can retain it for the next admitted request.
	 */
	onToolChoiceRejected?: () => void;

	/**
	 * Dynamic reasoning effort override, resolved per LLM call.
	 * When set and returns a value, overrides the static `reasoning` captured
	 * at run-loop start. Use this so mid-run thinking-level changes apply on
	 * the next model call instead of waiting for the next prompt.
	 */
	getReasoning?: () => Effort | undefined;
	/**
	 * Dynamic model override, resolved once per LLM call. When set, each
	 * provider call re-reads the model (like {@link getReasoning}) so mid-run
	 * model switches — context promotion, retry fallback — apply on the next
	 * call instead of the run finishing on the stale model captured at
	 * run-loop start. Falls back to the static {@link model} when unset.
	 */
	getModel?: () => Model;

	/**
	 * Dynamic reasoning-disable override, resolved per LLM call. When set,
	 * its return value overrides the static `disableReasoning` from
	 * `SimpleStreamOptions` for that request. Pair with `getReasoning` so
	 * mid-run transitions into and out of the explicit `off` state propagate
	 * to the next provider call.
	 */
	getDisableReasoning?: () => boolean | undefined;

	/**
	 * Per-call effective service-tier resolver. Unlike {@link getReasoning},
	 * this is *authoritative*: when set, its return value (including
	 * `undefined`) fully replaces the static `serviceTier` for the request and
	 * its telemetry. The resolver receives the model being requested so the
	 * caller can scope the tier per provider/model without mutating the shared
	 * session `serviceTier` (e.g. opting a Fireworks model into the Priority
	 * serving path while leaving the OpenAI/Anthropic tier untouched).
	 */
	getServiceTier?: (model: Model) => ServiceTier | undefined;

	/**
	 * Per-call working-directory resolver, read once per LLM call. When set, its
	 * return value overrides the static {@link SimpleStreamOptions.cwd} for the
	 * request (falling back to that static `cwd` when it returns `undefined`).
	 * Lets the host reflect a session move (`/move`, which updates the working
	 * directory without reconstructing the loop config) into provider options —
	 * e.g. GitLab Duo Agent namespace/project discovery keys off this cwd's git
	 * remote, so a stale value would strand discovery on the original repo.
	 */
	getCwd?: () => string | undefined;

	/**
	 * Called once per tool call after argument validation, in call order, before
	 * the call is scheduled — ahead of concurrency resolution,
	 * `tool_execution_start`, and `tool.execute`. On the streamed path it runs
	 * before the assistant message's `message_start`/`message_end` are emitted.
	 *
	 * Return `{ block: true }` to prevent execution. The loop emits an error tool
	 * result instead (using `reason` as the error text, or a default if omitted).
	 *
	 * Return `{ args }` to replace the arguments the call runs with. The
	 * replacement is revalidated against the tool schema and written back to the
	 * tool-call block, making it the single source of truth: history, execution
	 * events, persistence, provider replay, concurrency scheduling, and
	 * `tool.execute` all see the revised arguments. Mutating `context.args` in
	 * place also survives into execution, but a returned `args` object wins.
	 *
	 * The hook receives the run's request abort signal and is responsible for
	 * honoring it. Throwing surfaces as a tool-error result and does not abort the
	 * rest of the batch.
	 */
	beforeToolCall?: (
		context: BeforeToolCallContext,
		signal?: AbortSignal,
	) => Promise<BeforeToolCallResult | undefined> | BeforeToolCallResult | undefined;
	/**
	 * Called after a turn ends and before the loop polls steering/asides for the
	 * next iteration. `context` carries the just-finished turn; `context.willContinue`
	 * is true when the current tool-loop batch is continuing without yielding to
	 * post-turn steering.
	 */
	onTurnEnd?: (messages: AgentMessage[], signal?: AbortSignal, context?: AgentTurnEndContext) => Promise<void> | void;

	/**
	 * Called once an assistant message is finalized from the model stream, before
	 * it is appended to the context, emitted as `message_end`, or its tool calls
	 * are validated and dispatched. The hook may mutate the message in place —
	 * both its text content and its tool-call arguments — and those edits are seen
	 * by the transcript, the UI, and tool execution alike (single source of truth).
	 *
	 * Used for inline macro expansion: rewriting `@[[runtime.name(args)]]` tokens
	 * to host-computed values before anything downstream consumes the message.
	 * Runs at most once per assistant message; must not throw (a throw would abort
	 * the turn).
	 */
	transformAssistantMessage?: (message: AssistantMessage, signal?: AbortSignal) => Promise<void> | void;

	/**
	 * Declares that {@link transformAssistantMessage} never rewrites or removes a
	 * tool call the model streamed (it may edit text or append new calls). Stream
	 * speculation sessions and direct speculative candidates plan from streamed
	 * calls, so they stay disabled under a transform unless this is set.
	 */
	transformAssistantMessagePreservesToolCalls?: boolean;

	/**
	 * Called after a tool finishes executing, before `tool_execution_end` and the
	 * tool-result message are emitted.
	 *
	 * Return an `AfterToolCallResult` to override individual fields of the executed
	 * tool result. Omitted fields keep their original values; there is no deep merge.
	 *
	 * Throwing surfaces as a tool-error result and does not abort the rest of the batch.
	 */
	afterToolCall?: (
		context: AfterToolCallContext,
		signal?: AbortSignal,
	) => Promise<AfterToolCallResult | undefined> | AfterToolCallResult | undefined;
	/**
	 * Opt-in OpenTelemetry instrumentation. Passing `{}` enables the loop's
	 * GenAI-semantic-convention spans (`invoke_agent`, `chat`, `execute_tool`)
	 * using the global tracer provider. Leaving this field undefined disables
	 * the instrumentation entirely — the loop performs zero tracer lookups.
	 *
	 * See {@link AgentTelemetryConfig} for the full surface (hooks, content
	 * capture, cost estimator, agent identity).
	 */
	telemetry?: AgentTelemetryConfig;
}

/**
 * Batch/sequencing metadata for the tool call currently being processed.
 */
export interface ToolCallContext {
	batchId: string;
	index: number;
	total: number;
	toolCalls: Array<{ id: string; name: string }>;
	/** Provider-native metadata for the current call, when present. */
	providerMetadata?: ToolCallProviderMetadata;
	/**
	 * Settles once every earlier call of this batch that runs alongside this one
	 * and may change files (its approval, asked with its arguments and no context,
	 * is not "read", e.g. `bash`) has
	 * finished; absent when there is none. The model sees the batch's results only
	 * after the whole batch, so a read-only tool can check its target again here
	 * and redo a read those calls changed instead of returning stale content.
	 */
	earlierEffectsSettled?: Promise<void>;
	/**
	 * Cooperative steering signal: aborted when a queued user/steering message
	 * (or an interrupting peer IRC) is detected while this tool batch runs. Its
	 * `reason` names the source: a {@link SteeringInterruptSource} or `"irc"`.
	 * Unlike the hard abort signal it NEVER kills the tool — long-running
	 * tools MAY observe it (via `ctx.toolCall.steeringSignal`) to finish early
	 * or background themselves so the message injects promptly; ignoring it is
	 * always safe (the message injects at the next batch boundary).
	 */
	steeringSignal?: AbortSignal;
	/**
	 * Loop-owned sink for passive context reported while this call executes.
	 * Values join the call's context at the batch boundary and are injected
	 * after the batch's tool results, in assistant tool-call order, before the
	 * next provider request. Blank values are ignored.
	 */
	addAdditionalContext?: (context: string) => void;
}

/** A single tool-call content block emitted by an assistant message. */
export type AgentToolCall = Extract<AssistantMessage["content"][number], { type: "toolCall" }>;

export interface SpeculativeResourceAccess {
	scheme: "file";
	path: string;
	access: "read";
}

/** Declares an operation whose early execution can be discarded without rollback. */
export type ToolSpeculationEffect =
	| { kind: "pure" }
	| { kind: "local_read"; resources: readonly SpeculativeResourceAccess[] };

export type ToolSpeculationAssessment =
	| { eligible: false; reason: string }
	| { eligible: true; effect: ToolSpeculationEffect };

/** Immutable finalized call data provided to a tool-owned policy. */
export interface ToolSpeculationAssessmentContext {
	toolCall: AgentToolCall;
	args: Readonly<Record<string, unknown>>;
}

export interface ToolSpeculationExecutionContext extends ToolSpeculationAssessmentContext {
	effect: ToolSpeculationEffect;
}

export interface ToolSpeculationCommitContext extends ToolSpeculationExecutionContext {
	physicalOutcome: SpeculativePhysicalOutcome;
}

export interface ToolSpeculationDiscardContext extends ToolSpeculationExecutionContext {
	reason: string;
}

export interface SpeculativePhysicalOutcome {
	kind: "result";
	result: AgentToolResult<unknown>;
	isError: boolean;
	/** Opaque evidence binding the result to the local bytes actually consumed. */
	evidence?: unknown;
}

export interface SpeculativeToolReference {
	name: string;
	approval?: ToolApproval;
	formatApprovalDetails?: (args: unknown) => string | string[] | undefined;
}

export interface SpeculativeOperationContext extends ToolSpeculationExecutionContext {
	tool: SpeculativeToolReference;
	candidateId: string;
	source: "direct" | "eval_shadow";
	dependencies: readonly string[];
}

export interface SpeculativeCommitContext extends SpeculativeOperationContext {
	physicalOutcome: SpeculativePhysicalOutcome;
}

export interface SpeculativeDiscardContext extends SpeculativeOperationContext {
	reason: string;
}

export type SpeculativeAuthorization =
	| { allowed: false; reason: string }
	| { allowed: true; deferBeforeToolCall?: boolean };

export type SpeculativeCommitDecision =
	| { kind: "committed"; result: AgentToolResult<unknown> }
	| { kind: "fallback"; reason: string }
	| { kind: "failed"; error: unknown };

export interface SpeculativeExecutionHost {
	authorize(context: SpeculativeOperationContext): SpeculativeAuthorization | Promise<SpeculativeAuthorization>;
	/**
	 * Capture content evidence after admission gates pass but before the
	 * candidate executes. The coordinator invokes this immediately before
	 * starting speculative execution — which for hook-deferred candidates is
	 * after `beforeToolCall` runs — so content inspection never precedes a
	 * hook that may block the call. Return false (or throw) to veto the
	 * candidate without executing it. Hosts without this hook keep the legacy
	 * behavior of capturing during `authorize`.
	 */
	captureEvidence?(context: SpeculativeOperationContext): boolean | Promise<boolean>;
	validate?(context: SpeculativeCommitContext): boolean | Promise<boolean>;
	commit?(
		context: SpeculativeCommitContext,
		commitDefault: () => Promise<AgentToolResult<unknown>>,
	): Promise<SpeculativeCommitDecision>;
	discard?(context: SpeculativeDiscardContext): void | Promise<void>;
	/**
	 * Authorize a stream session to start effectful work (e.g. subagents) from
	 * partially streamed arguments. The session owns that work and must abort it
	 * when the finalized call is invalid, blocked, or changed. Hosts without this
	 * hook deny every launch.
	 */
	authorizeLaunch?(context: SpeculativeLaunchContext): SpeculativeAuthorization | Promise<SpeculativeAuthorization>;
	close?(reason: string): void | Promise<void>;
}

/** Effectful work a tool-owned stream session asks to start before its outer call dispatches. */
export interface SpeculativeLaunchContext {
	tool: SpeculativeToolReference;
	toolCall: AgentToolCall;
	/** Arguments the launch was planned from: the streamed prefix of the outer call. */
	args: Readonly<Record<string, unknown>>;
}

export interface ToolSpeculationStreamContext {
	readonly coordinator: SpeculativeOperationSink;
	readonly parentToolCallId: string;
}

/** One dependency-aware child operation projected by a streamed outer tool. */
export interface SpeculativeChildDefinition {
	candidateId: string;
	parentToolCallId: string;
	dependencies: readonly string[];
	toolCall: AgentToolCall;
	tool: AgentTool;
	source: "eval_shadow";
	virtualDurationMs?: number;
}

/** Opaque ownership handle returned after agent-core validates and authorizes a child. */
export interface SpeculativeChildHandle {
	readonly candidateId: string;
	readonly fingerprint: string;
	readonly effect: ToolSpeculationEffect;
	readonly outcome: Promise<SpeculativePhysicalOutcome>;
	commit(actualArgs: Readonly<Record<string, unknown>>): Promise<AgentToolResult<unknown> | undefined>;
	discard(reason: string): Promise<void>;
}

export interface ToolSpeculationStreamSession {
	/** True when the tool owns claim routing and does not need an AgentToolContext attachment. */
	readonly contextIndependent?: boolean;
	update(toolCall: AgentToolCall, partialJson?: string): void | Promise<void>;
	finalize(context: ToolSpeculationAssessmentContext): void | Promise<void>;
	commit(): void | Promise<void>;
	discard(reason: string): void | Promise<void>;
	/**
	 * Whether the session's streamed plan still authorizes these final
	 * arguments. The coordinator discards the session when the finalized call
	 * kept its ID but a hook or argument transform replaced its arguments:
	 * deferred work planned from the original code must never release.
	 * Sessions without this predicate are always retained.
	 */
	matchesFinalArgs?(args: Readonly<Record<string, unknown>>): boolean;
}

export interface SpeculativeOperationSink {
	readonly maxInFlight: number;
	admit(definition: SpeculativeChildDefinition): Promise<SpeculativeChildHandle | undefined>;
	/** Host-gated permission for effectful stream work; see {@link SpeculativeExecutionHost.authorizeLaunch}. */
	authorizeLaunch?(context: SpeculativeLaunchContext): Promise<SpeculativeAuthorization>;
	discardChildren?(parentToolCallId: string, reason: string): void | Promise<void>;
	close(reason: string): void | Promise<void>;
}

export interface ToolSpeculationPolicy {
	finalized?: {
		assess(context: ToolSpeculationAssessmentContext): ToolSpeculationAssessment | Promise<ToolSpeculationAssessment>;
		execute(context: ToolSpeculationExecutionContext, signal: AbortSignal): Promise<SpeculativePhysicalOutcome>;
		commit?(
			context: ToolSpeculationCommitContext,
			outcome: SpeculativePhysicalOutcome,
		): Promise<AgentToolResult<unknown>>;
		discard?(context: ToolSpeculationDiscardContext): void | Promise<void>;
	};
	stream?: {
		open(
			context: ToolSpeculationStreamContext,
		): ToolSpeculationStreamSession | Promise<ToolSpeculationStreamSession | undefined>;
	};
}

/** Diagnostic information for one speculative operation. */
export interface SpeculativeToolTelemetry {
	source: "direct" | "eval_shadow";
	candidateId: string;
	parentToolCallId?: string;
	toolName: string;
	effectKind?: ToolSpeculationEffect["kind"];
	candidateStartedAt?: number;
	candidateFinishedAt?: number;
	dispatchReachedAt?: number;
	dependencyCount: number;
	queueMs?: number;
	executionDurationMs?: number;
	overlapMs?: number;
	outcome: "committed" | "discarded" | "ineligible" | "fingerprint_mismatch" | "aborted" | "commit_conflict";
	reason?: string;
	resourceCount: number;
}

/** Opt-in configuration for discard-safe speculative tool execution. */
export interface SpeculativeToolExecutionConfig {
	enabled: boolean;
	maxInFlight?: number;
	host?: SpeculativeExecutionHost;
	onTelemetry?: (event: SpeculativeToolTelemetry) => void;
}

/**
 * Result returned from `beforeToolCall`.
 *
 * Set `block: true` to prevent the tool from executing. The loop emits an error tool
 * result instead, using `reason` as the error text (or a default if omitted).
 *
 * Set `args` to replace the tool-call arguments. The replacement is revalidated
 * against the tool schema (a failure surfaces as a validation-error tool result),
 * written back to the tool-call block on the assistant message, and seen by
 * history, scheduling, execution events, and `tool.execute` alike. It is
 * ignored when `block` is true.
 *
 * Set `additionalContext` to attach passive model-visible context to this call.
 * Non-empty values from a tool batch are injected in assistant tool-call order,
 * a value identical to an earlier one in the batch only once,
 * after every result settles and before the next provider request. It is
 * dropped when the call is blocked or skipped, or when its final result is an
 * error (including an approval denial raised by the tool's own gate). Within a
 * call it follows any context the tool reported during execution.
 */
export interface BeforeToolCallResult {
	block?: boolean;
	reason?: string;
	args?: Record<string, unknown>;
	additionalContext?: string;
}

/**
 * Partial override returned from `afterToolCall`.
 *
 * Merge semantics are field-by-field; omitted fields keep the executed values.
 * No deep merge is performed.
 */
export interface AfterToolCallResult {
	/** If provided, replaces the tool result content array in full. */
	content?: (TextContent | ImageContent)[];
	/** If provided, replaces the tool result details payload in full. */
	details?: unknown;
	/** If provided, replaces the provider-native result metadata in full. */
	providerMetadata?: ToolResultProviderMetadata;
	/** If provided, replaces the error flag carried with the tool result. */
	isError?: boolean;
	/** If provided, replaces the contextually-useless flag carried with the tool result. */
	useless?: boolean;
	/**
	 * Trusted post-tool instructions for the next provider request. Delivered
	 * outside the tool result, after all calls in the batch settle. Unlike
	 * `BeforeToolCallResult.additionalContext`, this is retained for error
	 * results because the callback receives the finalized outcome.
	 */
	additionalContext?: string;
}

/** Context passed to `beforeToolCall`. */
export interface BeforeToolCallContext {
	/** The assistant message that requested the tool call. */
	assistantMessage: AssistantMessage;
	/** The raw tool call block from `assistantMessage.content`. */
	toolCall: AgentToolCall;
	/** The resolved tool the call dispatches to. */
	tool: AgentTool;
	/**
	 * Validated tool arguments. The same reference is forwarded to `tool.execute`
	 * (after any `transformToolCallArguments` pass), so in-place mutations stick;
	 * a returned `BeforeToolCallResult.args` replaces them entirely.
	 */
	args: Record<string, unknown>;
	/** Current agent context at the time the tool call is prepared. */
	context: AgentContext;
}

/** Context passed to `afterToolCall`. */
export interface AfterToolCallContext {
	/** The assistant message that requested the tool call. */
	assistantMessage: AssistantMessage;
	/** The raw tool call block from `assistantMessage.content`. */
	toolCall: AgentToolCall;
	/** Validated tool arguments used for execution (post `beforeToolCall` mutations). */
	args: Record<string, unknown>;
	/** The executed tool result before any `afterToolCall` overrides are applied. */
	result: AgentToolResult<any>;
	/** Whether the executed tool result is currently treated as an error. */
	isError: boolean;
	/** Current agent context at the time the tool call is finalized. */
	context: AgentContext;
}

/**
 * Extensible interface for custom app messages.
 * Apps can extend via declaration merging:
 *
 * @example
 * ```typescript
 * declare module "@oh-my-pi/agent" {
 *   interface CustomAgentMessages {
 *     artifact: ArtifactMessage;
 *     notification: NotificationMessage;
 *   }
 * }
 * ```
 */
export interface CustomAgentMessages {
	// Empty by default - apps extend via declaration merging
}

/**
 * AgentMessage: Union of LLM messages + custom messages.
 * This abstraction allows apps to add custom message types while maintaining
 * type safety and compatibility with the base LLM messages.
 */
export type AgentMessage = Message | CustomAgentMessages[keyof CustomAgentMessages];

/**
 * Agent state containing all configuration and conversation data.
 */
export interface AgentState {
	systemPrompt: string[];
	model: Model;
	thinkingLevel?: Effort;
	disableReasoning?: boolean;
	tools: AgentTool<any>[];
	messages: AgentMessage[]; // Can include attachments + custom message types
	isStreaming: boolean;
	streamMessage: AgentMessage | null;
	pendingToolCalls: Set<string>;
	error?: string;
}

export interface AgentToolResult<T = any, _TInput = unknown> {
	// Content blocks supporting text and images
	content: (TextContent | ImageContent)[];
	// Details to be displayed in a UI or logged
	details?: T;
	// Marks a non-throwing failure (e.g. an aggregator catching per-entry errors).
	// agent-loop honors this and surfaces it as a tool error on the wire.
	isError?: boolean;
	/** Provider-native metadata that must survive into history replay unchanged. */
	providerMetadata?: ToolResultProviderMetadata;
	/** Marks the result as contextually useless: safe for compaction to elide once consumed (e.g. zero matches, wait timeout). Ignored when isError is set. */
	useless?: boolean;
}

// Callback for streaming tool execution updates
export type AgentToolUpdateCallback<T = any, TInput = unknown> = (partialResult: AgentToolResult<T, TInput>) => void;

/** Options passed to renderResult */
export interface RenderResultOptions {
	/** Whether the result view is expanded */
	expanded: boolean;
	/** Whether this is a partial/streaming result */
	isPartial: boolean;
	/** Current spinner frame index for animated elements (optional) */
	spinnerFrame?: number;
}

/** Capability tier a tool exercises. Determines which approval modes auto-approve it. */
export type ToolTier = "read" | "write" | "exec";

/**
 * How an enabled tool is presented to the model. `"essential"` tools are exposed
 * as normal top-level tools. `"discoverable"` tools are removed from the top-level
 * schema and either mounted under `xd://` device URLs (when that transport is
 * active) or surfaced through BM25 tool search — keeping their schemas off every
 * request. Selection (settings, `hidden`, `defaultInactive`, explicit `--tools`,
 * provider availability) decides whether a tool is enabled; `loadMode` only
 * decides how an enabled tool is presented.
 */
export type ToolLoadMode = "essential" | "discoverable";

/**
 * Per-tool approval declaration.
 * - bare tier ("read" / "write" / "exec") — static classification.
 * - object form — adds a `reason` (shown in the prompt) and/or `override: true`
 *   (force-prompt even in modes that would otherwise auto-approve this tier).
 *   `policy: "deny"` blocks the call at the approval gate.
 * - function — dynamic, given parsed args. Returns either form above.
 *
 * Omitted approvals are treated as "exec" by callers that enforce approvals.
 */
export type ToolApprovalDecision =
	| ToolTier
	| {
			tier: ToolTier;
			reason?: string;
			override?: boolean;
			policy?: "allow" | "deny" | "prompt";
			/** User-policy key for this decision. When set, `tools.approval.<policyKey>`
			 *  is consulted instead of `tools.approval.<tool.name>`. Lets a dispatcher
			 *  tool (e.g. `write` for an `xd://` device call) scope user allow/deny/
			 *  prompt policies to the tool it dispatches into. */
			policyKey?: string;
	  };
export type ToolApproval = ToolApprovalDecision | ((args: unknown, context?: AgentToolContext) => ToolApprovalDecision);

/**
 * Context passed to tool execution.
 * Apps can extend via declaration merging.
 */
export interface AgentToolContext {
	/**
	 * Attach trusted, agent-authored instructions to the next provider request.
	 * The host emits them after tool results with developer/system priority where
	 * the selected transport supports it. Do not use this channel for raw tool
	 * output, retrieved documents, web content, or other untrusted data; return
	 * those through the ordinary tool result instead. Hosts populate it from
	 * {@link ToolCallContext.addAdditionalContext} (or their own collector for
	 * calls dispatched outside the loop); absent when the host has no sink.
	 */
	addAdditionalContext?(context: string): void;
	/** Present only while the matching outer tool owns its finalized stream session. */
	[SPECULATIVE_STREAM_SESSION]?: ToolSpeculationStreamSession;
}

export type AgentToolExecFn<TParameters extends TSchema = TSchema, TDetails = any, TTheme = unknown> = (
	this: AgentTool<TParameters, TDetails, TTheme>,
	toolCallId: string,
	params: Static<TParameters>,
	signal?: AbortSignal,
	onUpdate?: AgentToolUpdateCallback<TDetails, TParameters>,
	context?: AgentToolContext,
) => Promise<AgentToolResult<TDetails, TParameters>>;

/** Live receiver for a tool call's streamed arguments (see AgentTool.openArgStream). */
export interface AgentToolArgStream {
	/** Raw wire fragment of the arguments (JSON text, or verbatim payload for custom-format tools). */
	push(delta: string): void;
	/** Arguments are complete; `args` is the final parsed object the loop will pass to `execute`. */
	end(args: unknown): void;
	/** The call will never execute (stream error, abort, blocked). Release resources. */
	cancel(): void;
}

export interface AgentToolArgStreamInit {
	toolCallId: string;
	toolName: string;
	/** Wire-level name for custom-format tools; undefined for JSON function tools. */
	customWireName?: string;
	/** Push a serializable projection of the in-flight call (e.g. diff previews); surfaces as `tool_stream_update`. */
	emit(update: unknown): void;
}

// AgentTool extends Tool but adds the execute function
export interface AgentTool<
	TParameters extends TSchema = TSchema,
	TDetails = any,
	TTheme = unknown,
> extends Tool<TParameters> {
	// A human-readable label for the tool to be displayed in UI
	label: string;
	/**
	 * Called at `toolcall_start`, before any argument delta. Return `undefined` to opt out.
	 */
	openArgStream?: (init: AgentToolArgStreamInit) => AgentToolArgStream | undefined;
	hidden?: boolean;
	/** If true, the tool can read `skill://<name>` instruction content; prompt builders gate skill guidance on it. */
	readsSkillUris?: boolean;
	/** If true, tool can stage a pending action that requires explicit resolution via the resolve tool. */
	deferrable?: boolean;
	/** How an enabled tool is presented. See {@link ToolLoadMode}. Omitted is treated as `"essential"` for built-ins; custom-tool adapters normalize omission to `"discoverable"`. */
	loadMode?: ToolLoadMode;
	/** Short one-line summary used for tool discovery indexes. */
	summary?: string;
	/**
	 * Instructions a same-name extension replacement inherits in its description, because results it
	 * obtains by delegating to this native tool through `ctx.invokeTool` follow this tool's contract.
	 */
	readonly delegationGuidance?: string;
	/**
	 * On-demand documentation topics (`topic → markdown`), readable as
	 * `xd://<tool>/<topic>`. Lets a tool keep large sub-surfaces out of its
	 * description and advertise only a one-line pointer per topic.
	 */
	docTopics?(): Readonly<Record<string, string>>;
	/**
	 * Concurrency mode for tool scheduling when multiple calls are in one turn.
	 * - "shared": can run alongside other shared tools (default)
	 * - "exclusive": runs alone; other tools wait until it finishes
	 * - function: resolved per call from the (raw, pre-validation) arguments
	 */
	concurrency?: "shared" | "exclusive" | ((args: Partial<Static<TParameters>>) => "shared" | "exclusive");

	/**
	 * Declares the bounded, validated effect of a finalized call that may execute
	 * before ordinary dispatch commits its result.
	 */
	speculation?: ToolSpeculationPolicy;
	/** If true, schema validation errors are non-fatal: raw args are passed to execute() instead of returning an error to the LLM, and unknown root keys a closed schema would drop stay on the args. Malformed argument JSON still returns the parse error. */
	lenientArgValidation?: boolean;
	/**
	 * Whether the agent loop may abort this tool mid-execution — or skip it
	 * before it starts — to deliver a queued steering message. A function
	 * resolves this per call from the raw, pre-validation arguments.
	 *
	 * Enable only for calls that purely *wait* and observe their abort signal
	 * cleanly (e.g. `job` poll), so the abort surfaces the tool's current
	 * snapshot rather than corrupting a side effect. Every other call runs to
	 * completion even when steering is queued; the message lands at the next
	 * batch boundary. Honored in both `interruptMode`s.
	 */
	interruptible?: boolean | ((args: Partial<Static<TParameters>>) => boolean);
	/**
	 * An interruptible tool can execute with an already-aborted
	 * `TOOL_INTERRUPT_ABORT_REASON` signal to drain caller-owned wake events.
	 * It must not block when that signal is aborted. External/user cancellation
	 * still prevents execution. Omitted tools keep the usual pre-start skip.
	 */
	handlesToolInterrupt?: boolean;
	/**
	 * Controls how the INTENT_FIELD (`i`) is handled for this tool.
	 * - `"require"` (default): `i` is injected and required in the parameter schema.
	 * - `"optional"`: `i` is injected as an optional/nullable field.
	 * - `"omit"`: `i` is NOT injected. Use for tools where intent is obvious (yield, resolve, todo, …).
	 * - function: `i` is NOT injected; intent is derived dynamically from (potentially partial / streaming) args.
	 */
	intent?: "omit" | "optional" | "require" | ((args: Partial<Static<TParameters>>) => string | undefined);

	/**
	 * Normalize (potentially partial) streamed arguments into the plain text that
	 * stream-content matchers (e.g. TTSR rules) should inspect — the real content
	 * the call introduces, without wire grammar such as patch prefixes or JSON
	 * string escaping. Return `undefined` to fall back to raw argument-delta
	 * matching.
	 */
	matcherDigest?: (args: unknown) => string | undefined;

	/**
	 * Surface the target file paths a (potentially partial) streamed call would
	 * touch, so path-scoped stream matchers (e.g. TTSR `tool:edit(*.ts)` globs)
	 * can match without a top-level `path`/`paths` argument. Used for tools whose
	 * wire grammar embeds paths inside the streamed payload (hashline section
	 * headers, apply_patch envelope markers). Return `undefined` (or an empty
	 * array) to fall back to the caller's top-level argument scan.
	 */
	matcherPaths?: (args: unknown) => readonly string[] | undefined;

	/**
	 * Per-file projection of a (potentially partial) streamed call, pairing each
	 * touched file path with the digest of only the lines added to that file.
	 * Path-scoped stream matchers (TTSR) evaluate each entry in isolation, so a
	 * scoped rule like `tool:edit(*.ts)` never fires on text that actually
	 * belongs to a sibling Markdown hunk in a multi-file payload. Takes
	 * precedence over {@link matcherDigest} + {@link matcherPaths} when present;
	 * returns `undefined` (or empty) to fall back to the combined hooks.
	 */
	matcherEntries?: (args: unknown) => readonly { path: string; digest: string }[] | undefined;

	/** Capability tier declaration used by approval gates. Omitted means "exec". */
	approval?: ToolApproval;

	/** Lines appended after the standard approval prompt header. */
	formatApprovalDetails?: (args: unknown) => string | string[] | undefined;

	/**
	 * Remembered-approval keys for `tools.approvalMode: always-ask-cached`: the files (or URL
	 * targets) this call touches. When every key is already granted the call skips its prompt;
	 * approving the call can record them. Omit it (or return `undefined`) and the call prompts by tier.
	 */
	approvalCacheTargets?: (args: unknown) => readonly string[] | undefined;

	/**
	 * Capture per-invocation targets after extension preflight, before final approval and execution.
	 * The coding-agent wrapper calls this once with the final approval args, even without a prompt
	 * or restricted folders. Restriction queries and approval details may then read the binding.
	 */
	bindApprovalTargets?: (args: unknown) => void;

	/**
	 * Query paths a call reads beyond its working directory, matched against restricted folders when
	 * it reports no `approvalCacheTargets`. Never capture bindings here: this also runs before preflight.
	 * Unlike cache targets these paths never key a remembered grant.
	 */
	approvalRestrictionPaths?: (args: unknown) => readonly string[] | undefined;

	/** The main execution callback for this tool. */
	execute: AgentToolExecFn<TParameters, TDetails, TTheme>;

	/** Optional custom rendering for tool call display (returns UI component) */
	renderCall?: (args: Static<TParameters>, options: RenderResultOptions, theme: TTheme) => unknown;

	/** Optional custom rendering for tool result display (returns UI component) */
	renderResult?: (
		result: AgentToolResult<TDetails, TParameters>,
		options: RenderResultOptions,
		theme: TTheme,
	) => unknown;
}

// AgentContext is like Context but uses AgentTool
export interface AgentContext {
	systemPrompt: string[];
	messages: AgentMessage[];
	tools?: AgentTool<any>[];
}

/**
 * Events emitted by the Agent for UI updates.
 * These events provide fine-grained lifecycle information for messages, turns, and tool executions.
 */
export type AgentEvent =
	// Agent lifecycle
	| {
			type: "agent_start";
			/**
			 * Calls of the unpaired assistant tail a continued run executes before its
			 * first model request. They run without a new assistant `message_end`.
			 */
			resumedToolCallIds?: string[];
	  }
	| {
			type: "agent_end";
			messages: AgentMessage[];
			/** Present iff `AgentTelemetryConfig` was supplied on this run. */
			telemetry?: AgentRunSummary;
			coverage?: AgentRunCoverage;
	  }
	// Turn lifecycle - a turn is one assistant response + any tool calls/results
	| { type: "turn_start" }
	| { type: "turn_end"; message: AgentMessage; toolResults: ToolResultMessage[] }
	// Message lifecycle - emitted for user, assistant, and toolResult messages
	| { type: "message_start"; message: AgentMessage }
	// Only emitted for assistant messages during streaming
	| { type: "message_update"; message: AgentMessage; assistantMessageEvent: AssistantMessageEvent }
	| { type: "message_end"; message: AgentMessage }
	// Tool execution lifecycle
	| { type: "tool_execution_start"; toolCallId: string; toolName: string; args: any; intent?: string }
	| { type: "tool_execution_update"; toolCallId: string; toolName: string; args: any; partialResult: any }
	| { type: "tool_stream_update"; toolCallId: string; toolName: string; update: unknown }
	| { type: "tool_execution_end"; toolCallId: string; toolName: string; result: any; isError?: boolean };

