		const config: AgentLoopConfig = {
			model: mock.model,
			convertToLlm: identityConverter,
			// Resolve ONLY from the handed-over snapshot; never from ambient state.
			resolveFallbackTool: (name, advertised) => {
				seen.push(advertised);
