	// =========================================================================
	// IRC Delivery
	// =========================================================================

	/** Whether a queued IRC message ends a `wait` (see {@link IrcBridge.hasInterrupts}). */
	hasIrcInterrupts(): boolean {
		return this.#irc.hasInterrupts();
	}

	/** Delivers an IRC message into this recipient session. */
	deliverIrcMessage(msg: IrcMessage): Promise<"injected" | "woken"> {
		// The sender's context is active here; the delivery is the recipient's work.
		return this.#inLogContext(() => this.#irc.deliver(msg));
	}

	/** Recognizes parent IRC steering at message consumption, without promoting queued requests. */
	isParentIrcSteer(message: AgentMessage): boolean {
		return this.#irc.isParentSteer(message);
	}

	/** Waits for any in-flight IRC wake-turn relays. */
	waitForIrcReplies(): Promise<void> {
		return this.#irc.waitForReplies();
	}

	/** Whether a message from `from` still waits here for a turn of its own (a reply can still come). */
	hasQueuedIrcFrom(from: string): boolean {
		return this.#irc.hasQueuedFrom(from);
	}

	/** Senders with an IRC message still queued here for a turn of its own. */
	queuedIrcSenders(): string[] {
		return this.#irc.queuedSenders();
	}

	/** Registers an in-flight IRC wake-turn relay. */
	trackIrcReply(pending: Promise<void>): void {
		this.#irc.trackReply(pending);
	}

	/**
	 * Installs task-executor monitoring around kept-alive subagent turns that
	 * have no executor caller: IRC wakes, focused prompts and bare continuations.
	 */
	setIrcWakeTurnObserver(
		observer: ((records: AgentMessage[]) => ((error?: unknown) => void | Promise<void>) | undefined) | undefined,
	): void {
		this.#ircWakeTurnObserver = observer;
	}

	/**
	 * Holds IRC wakes from anyone but the parent while the task executor drives
	 * this session's run, whose monitor would take a wake turn's answer as the
	 * run's result. Held messages wait as deferred wakes and get a monitored turn
	 * of their own once every hold is released. Returns the release.
	 */
	holdIrcWakes(): () => void {
		this.#ircWakeHolds++;
		this.#notifyWakeState();
		let released = false;
		return () => {
			if (released) return;
			released = true;
			this.#ircWakeHolds--;
			this.#resumeStrandedIrcAsides();
			this.#notifyWakeState();
		};
	}

	/**
	 * Observe changes of {@link ircWakesPending} and {@link hasPendingWake} that no session
	 * event carries: an IRC wake hold taken or released, an idle compaction's waiting wakes
	 * settling, an owned job settling, a child agent's status or any block changing. A
	 * worker-homed session's publisher republishes on them, so main's lifecycle parks it once
	 * it may and agents waiting on it read a current {@link hasPendingWake}.
	 */
	subscribeWakeState(listener: () => void): () => void {
		this.#wakeStateListeners.add(listener);
		return () => this.#wakeStateListeners.delete(listener);
	}

	#notifyWakeState(): void {
		for (const listener of this.#wakeStateListeners) listener();
		this.#scheduleRunCheck();
	}

	/**
	 * Whether IRC messages still wait here for a turn: under a {@link holdIrcWakes}
	 * hold, behind a running idle compaction, or queued (e.g. behind a pooled yield
	 * contract). The lifecycle must not park this session yet, since parking would
	 * drop them.
	 */
	get ircWakesPending(): boolean {
		return this.#ircWakeHolds > 0 || this.#ircWakesAwaitingCompaction > 0 || this.#irc.hasPending();
	}

	/** Emits an IRC relay observation for UI rendering without persisting it. */
	emitIrcRelayObservation(record: CustomMessage): void {
		this.#irc.emitRelayObservation(record);
	}

	/**
	 * Whether {@link runEphemeralTurn} would honor a `maxTokens` cap on the current model without
	 * otherwise changing the request. On budget-thinking models a cap forces thinking off; when the
	 * session thinks, that changes the thinking parameters, which providers key their prompt caches
	 * on. Callers whose cap is optional send one only when this holds.
	 */
	ephemeralMaxTokensPreservesRequest(): boolean {
		const model = this.model;
		if (!model || ephemeralMaxTokensRejection(model)) return false;
		const budgetThinking = model.thinking?.mode === "budget" || model.thinking?.mode === "anthropic-budget-effort";
		return !budgetThinking || shouldDisableReasoning(this.thinkingLevel);
	}

	/**
	 * Run a single ephemeral side-channel turn against this session's current
	 * model + system prompt + history. The main turn's tool catalog is sent
	 * to preserve the prompt cache unless `tools: false` is requested. The
	 * model is reminded not to call tools and any tool calls are discarded. The side request
	 * does not block on, or interfere with, any in-flight main turn. The
	 * session's history is NOT modified by this call (a snapcompact archive's
	 * no-reasoning view may be stored on its compaction entry).
	 *
	 * Used by `BtwController` (`/btw`) and `OmfgController` (`/omfg`) to share
	 * the snapshot + stream pipeline. The snapshot includes any in-flight
	 * streaming assistant text so the model sees the half-finished response
	 * rather than missing context.
	 */
	async runEphemeralTurn(args: EphemeralTurnOptions): Promise<EphemeralTurnResult> {
		const model = this.model;
		if (!model) {
			throw new Error("No active model on session");
		}
		const modelDescription = `${model.provider}/${model.id} (${model.api})`;
		const sessionGeneration = this.#sessionGeneration;
		const assertEphemeralTurnReady = () => {
			args.signal?.throwIfAborted();
			// The side request must use the exact model snapshot captured above.
			// `modelsAreEqual` intentionally compares only provider/id, while a
			// replacement with that same identity can still change routing and wire
			// behavior (baseUrl, requestModelId, compatibility settings, etc.).
			if (this.model !== model) throw new Error("Active model changed during ephemeral turn; retry.");
			if (this.#sessionGeneration !== sessionGeneration) {
				throw new Error("Active session changed during ephemeral turn; retry.");
			}
		};
		for (const field of ["maxTokens", "maxContextBytes"] as const) {
			const cap = args[field];
			if (cap !== undefined && (!Number.isSafeInteger(cap) || cap <= 0)) {
				throw new Error(`${field} must be a positive safe integer.`);
			}
		}
		const cappedBudgetThinking =
			args.maxTokens !== undefined &&
			(model.thinking?.mode === "budget" || model.thinking?.mode === "anthropic-budget-effort");
		const maxTokensRejection = args.maxTokens !== undefined ? ephemeralMaxTokensRejection(model) : undefined;
		if (maxTokensRejection) {
			throw new Error(
				`Model ${modelDescription} ${maxTokensRejection}. Omit the cap or use a model that supports output limits.`,
			);
		}
		if (args.tools === false && requiresNativeTools(model)) {
			throw new Error(
				`Model ${modelDescription} does not support tools: false for ephemeral turns because its transport requires native tools.`,
			);
		}
		// Images, those of earlier side turns too, get a prompt's handling: normalized
		// for the model, and described by a vision model for a text-only one.
		const promptImages = await this.#normalizeImagesForModel(args.promptImages);
		const imageDescriptionNotice = promptImages?.length
			? await this.#buildImageDescriptionNotice(promptImages, args.signal)
			: undefined;
		const history = args.history && (await this.#prepareSideHistory(args.history, args.signal));
		assertEphemeralTurnReady();
		const cacheSessionId = this.sessionId;
		// Created with the snapshot so the entry sits on the leaf the turn read.
		const usageReporter =
			args.onUsage ?? (args.purpose ? journalCompletion(this.sessionManager, { purpose: args.purpose }) : undefined);
		const snapshot = this.#buildEphemeralSnapshot(
			args.promptText,
			history,
			promptImages,
			imageDescriptionNotice,
			args.conversationKey,
		);
		const llmMessages = await this.convertMessagesToLlm(snapshot, args.signal);
		assertEphemeralTurnReady();
		const sideContext = await this.agent.buildSideRequestContext(llmMessages);
		const toolHistory = sideContext.messages.some(
			message =>
				message.role === "toolResult" ||
				(message.role === "assistant" &&
					Array.isArray(message.content) &&
					message.content.some(block => block.type === "toolCall")),
		);
		if (args.tools === false && requiresToolFreeHistoryForToolOptOut(model) && toolHistory) {
			throw new Error(
				`Model ${modelDescription} cannot support tools: false with historical tool calls. Omit tools: false or start from tool-free history.`,
			);
		}
		// Apply after context transforms, without mutating a potentially shared context.
		const context = obfuscateProviderContext(
			this.#obfuscator,
			args.tools === false ? { ...sideContext, tools: [] } : sideContext,
		);
		if (
			args.maxContextBytes !== undefined &&
			Buffer.byteLength(JSON.stringify(context), "utf8") > args.maxContextBytes
		) {
			throw new Error(`Ephemeral turn context exceeds the configured ${args.maxContextBytes}-byte limit.`);
		}
		// `AssistantMessageEventStream` has no iterator-return cancellation hook, so
		// throwing out of the consumer loop below (a rejected `onTextDelta` delivery,
		// an `error` event) would leave the transport streaming: still burning
		// inference and queueing output nobody reads. Abort the request ourselves when
		// we stop consuming it, without touching the caller's signal.
		const streamAbort = new AbortController();
		const sideSessionId = args.conversationKey
			? `${cacheSessionId}:side:conversation:${args.conversationKey}`
			: `${cacheSessionId}:side:${Snowflake.next()}`;
		const options = this.prepareSimpleStreamOptions(
			{
				apiKey: this.#modelRegistry.resolver(model, cacheSessionId),
				// Side-channel turns must not share OpenAI/Codex append-only
				// conversation state with the main agent turn: IRC and /btw can run
				// while the main turn is mid-tool-call. Keep the prompt-cache key
				// stable, but isolate provider routing from the main conversation.
				// Serialized BTW follow-ups reuse a topic-specific lineage; standalone
				// side requests retain their unique request lineage.
				sessionId: sideSessionId,
				// Request controls (OpenAI effort updates) still replay the main
				// conversation's, so the side request keeps its cached prefix.
				parentSessionId: cacheSessionId,
				promptCacheKey: this.getPromptCacheKeyForModel(model) ?? this.agent.sessionId,
				preferWebsockets: resolveWebsocketPreference(this.settings, model),
				providerSessionState: this.#providerSessionState,
				reasoning: toReasoningEffort(this.thinkingLevel),
				minimizeEffort: args.minimizeEffort,
				// Budget-thinking transports can raise explicit caps to make room for their
				// default thinking budget. A side turn's cap is a hard resource boundary.
				disableReasoning: shouldDisableReasoning(this.thinkingLevel) || cappedBudgetThinking,
				hideThinkingSummary: this.agent.hideThinkingSummary,
				serviceTier: this.#models.effectiveServiceTier(model),
				maxTokens: args.maxTokens,
				signal: args.signal ? AbortSignal.any([args.signal, streamAbort.signal]) : streamAbort.signal,
			},
			model.provider,
		);

		if (args.tools === false) options.toolChoice = "none";

		let providerReplyText = "";
		let emittedReplyText = "";
		let assistantMessage: AssistantMessage | undefined;
		// Reported where the provider settles the request, before any later step can throw it away.
		const reportUsage = (message: AssistantMessage) => {
			try {
				usageReporter?.(message);
			} catch (error) {
				logger.debug("ephemeral-turn: usage reporter failed", {
					error: error instanceof Error ? error.message : String(error),
				});
			}
		};
		assertEphemeralTurnReady();
		try {
			const stream = await this.#sideStreamFn(model, context, options);
			for await (const event of stream) {
				if (event.type === "text_delta") {
					providerReplyText += event.delta;
					if (args.onTextDelta) {
						const readyText = this.#deobfuscatedProviderTextReadyForDelta(providerReplyText);
						if (readyText.length > emittedReplyText.length) {
							const delta = readyText.slice(emittedReplyText.length);
							emittedReplyText = readyText;
							await args.onTextDelta(delta);
						}
					}
					continue;
				}
				if (event.type === "done") {
					// A well-formed provider "done" event carries `content: AssistantContentBlock[]`,
					// but a proxy/wrapper (custom extension providers, gateway-wrapped OAuth streams,
					// see #4323) can hand back a message whose `content` was dropped or replaced with
					// `undefined`. Downstream `.content.filter` at the sanitize step below would then
					// crash the recap turn with `TypeError: undefined is not an object (evaluating
					// 'H.content.filter')`. Normalize to `[]` so the recap surfaces an empty reply
					// instead of turning a malformed side-channel response into a session-mute crash.
					const rawContent = Array.isArray(event.message.content) ? event.message.content : [];
					assistantMessage = this.#obfuscator?.hasSecrets()
						? { ...event.message, content: deobfuscateAssistantContent(this.#obfuscator, rawContent) }
						: { ...event.message, content: rawContent };
					reportUsage(assistantMessage);
					break;
				}
				if (event.type === "error") {
					reportUsage(event.error);
					throw new Error(event.error.errorMessage || "Ephemeral turn failed");
				}
			}
		} catch (error) {
			streamAbort.abort();
			throw error;
		} finally {
			if (!args.conversationKey) {
				for (const [providerKey, state] of this.#providerSessionState) {
					try {
						state.releaseSession?.(sideSessionId);
					} catch (error) {
						logger.warn("Failed to release side request provider state", { providerKey, error: String(error) });
					}
				}
			}
		}

		if (!assistantMessage) {
			throw new Error("Ephemeral turn ended without a final message");
		}
		const replyText = this.#deobfuscateFromProvider(providerReplyText);
		if (args.onTextDelta && replyText.length > emittedReplyText.length) {
			await args.onTextDelta(replyText.slice(emittedReplyText.length));
		}
		const sanitizedMessage: AssistantMessage = {
			...assistantMessage,
			content: assistantMessage.content.filter(block => block.type !== "toolCall"),
		};
		return {
			replyText:
				args.dedupeReply === false ? replyText.trim() : dedupeEphemeralReply(replyText.trim(), args.replyMaxBytes),
			assistantMessage: sanitizedMessage,
		};
	}

	async #prepareSideHistory(history: readonly Message[], signal?: AbortSignal): Promise<AgentMessage[]> {
		const prepared: AgentMessage[] = [];
		for (const message of history) {
			const normalized = await this.#normalizeAgentMessageImages(message);
			const images =
				normalized.role === "user" && Array.isArray(normalized.content)
					? normalized.content.filter((part): part is ImageContent => part.type === "image")
					: [];
			const notice = images.length > 0 ? await this.#buildImageDescriptionNotice(images, signal) : undefined;
			if (notice) prepared.push(notice);
			prepared.push(normalized);
		}
		return prepared;
	}

	/**
	 * Build a message snapshot for an ephemeral side-channel turn. Includes the
	 * in-flight streaming assistant reply, detached side history, and the current
	 * prompt after the no-tools reminder. A keyed conversation can cache its
	 * replayable side history up to the first regenerated vision description.
	 */
	#buildEphemeralSnapshot(
		promptText: string,
		history?: readonly AgentMessage[],
		images?: ImageContent[],
		imageDescriptionNotice?: CustomMessage,
		conversationKey?: string,
	): AgentMessage[] {
		const messages = [...this.messages];
		const streaming = this.agent.state.streamMessage;
		if (streaming && streaming.role === "assistant" && Array.isArray(streaming.content)) {
			const preservedBlocks: AssistantMessage["content"] = [];
			// Preserve thinking blocks: DeepSeek-class encoders replay them as
			// `reasoning_content` and reject the request (HTTP 400) when the field
			// goes missing on a turn that previously emitted thinking. A block still
			// streaming has no signature yet, so a reader whose classifier refuses
			// quoted reasoning (Claude's `reasoning_extraction`) would get it as plain
			// assistant text: leave those out.
			const model = this.model;
			const keepUnsigned = model !== undefined && readerIncludesThinking(model);
			for (const c of streaming.content) {
				if (c.type === "thinking" && (keepUnsigned || c.thinkingSignature?.trim())) preservedBlocks.push(c);
			}
			const streamingText = streaming.content
				.filter((c): c is TextContent => c.type === "text")
				.map(c => c.text)
				.join("");
			if (streamingText) {
				preservedBlocks.push({ type: "text", text: streamingText });
			}
			if (preservedBlocks.length > 0) {
				const normalized: AssistantMessage = {
					...streaming,
					content: preservedBlocks,
				};
				markPerCallContextMessage(normalized);
				const lastMessage = messages.at(-1);
				if (lastMessage?.role === "assistant") {
					messages[messages.length - 1] = normalized;
				} else {
					messages.push(normalized);
				}
			}
		}
		const reminder: AgentMessage = {
			role: "developer",
			content: [{ type: "text", text: sideChannelNoToolsReminder }],
			attribution: "agent",
			timestamp: Date.now(),
		};
		markPerCallContextMessage(reminder);
		messages.push(reminder);
		// A regenerated vision description can change between keyed follow-ups.
		// No breakpoint after it can be read by the next request.
		let volatileSuffix = false;
		if (history?.length) {
			// Detach before the conversion pipeline can await or mutate caller-owned messages.
			const detachedHistory = structuredClone(history);
			for (const message of detachedHistory) {
				if (message.role === "custom" && message.customType === IMAGE_ATTACHMENT_DESCRIPTION_TYPE) {
					volatileSuffix = true;
				}
				if (!conversationKey || volatileSuffix) markPerCallContextMessage(message);
			}
			messages.push(...detachedHistory);
		}
		if (imageDescriptionNotice) {
			markPerCallContextMessage(imageDescriptionNotice);
			messages.push(imageDescriptionNotice);
			volatileSuffix = true;
		}
		const sidePrompt: AgentMessage = {
			role: "user",
			content: [{ type: "text", text: promptText }, ...(images ?? [])],
			attribution: "agent",
			timestamp: Date.now(),
		};
		if (!conversationKey || volatileSuffix) markPerCallContextMessage(sidePrompt);
		messages.push(sidePrompt);
		return messages;
	}

	// =========================================================================
	// Session Management
	// =========================================================================

	/**
	 * Reload the current session from disk.
	 *
	 * Intended for extension commands and headless modes to re-read the current session
	 * file and re-emit session_switch hooks.
	 */
	async reload(): Promise<void> {
		const sessionFile = this.sessionFile;
		if (!sessionFile) return;
		const switched = await this.switchSession(sessionFile);
		if (!switched) throw new Error("Session reload cancelled");
	}
	/**
	 * Switch to a different session file.
	 * Aborts current operation, loads messages, restores model/thinking.
	 * Listeners are preserved and will continue receiving events.
	 *
	 * When none of the target session's saved models can be restored, the switch
	 * throws `Could not restore model <provider/id>` and the current session stays
	 * active; as with a rejected cwd change, `session_before_switch` has already
	 * run and any in-flight turn has already been aborted (the target's models are
	 * only known once its file is loaded). A session created with `allowSessionModelFallback` (and
	 * `retry.modelFallback` on) instead keeps its current model and reports a
	 * warning. Reloading the current session keeps the current model.
	 *
	 * A target whose recorded directory is missing or cannot be entered resumes in the
	 * current cwd (the session manager keeps it there, runtime-only until relocated);
	 * callers can detect this by comparing `getRecordedCwd()` with `getCwd()`.
	 * @returns true if switch completed, false if cancelled by hook or cwd change
	 */
	async switchSession(
		sessionPath: string,
		options?: {
			onCwdChange?: (newCwd: string, previousCwd: string) => Promise<boolean>;
			/** Collab snapshot adoption keeps the guest's process cwd and marks the replica runtime-only. */
			preserveLocalCwd?: boolean;
			/**
			 * Use this model instead of the target's saved one, like an explicit
			 * `--model` at startup, and record it in the session when it differs.
			 */
			model?: Model;
			/** Keep the current model without restoring the target's (collab replicas mirror the host's model). */
			keepModel?: boolean;
			/**
			 * Receives the model fallback warning after the switch commits, instead of a
			 * `notice` event; for hosts that re-render the transcript after switching.
			 */
			onModelFallback?: (warning: string) => void;
		},
	): Promise<boolean> {
		const queued = this.#enterSessionTransition(() => this.switchSession(sessionPath, options));
		if (queued) return queued;
		const explicitModel = options?.model;
		if (explicitModel && !this.#modelRegistry.hasConfiguredAuth(explicitModel)) {
			throw new Error(`No API key for ${explicitModel.provider}/${explicitModel.id}`);
		}
		using _transition = this.#beginSessionTransition();
		const previousSessionFile = this.sessionManager.getSessionFile();
		const switchingToDifferentSession = previousSessionFile
			? path.resolve(previousSessionFile) !== path.resolve(sessionPath)
			: true;
		// Emit session_before_switch event (can be cancelled)
		if (this.#extensionRunner?.hasHandlers("session_before_switch")) {
			const result = (await this.#extensionRunner.emit({
				type: "session_before_switch",
				reason: "resume",
				targetSessionFile: sessionPath,
			})) as SessionBeforeSwitchResult | undefined;

			if (result?.cancel) {
				return false;
			}
		}

		this.#disconnectFromAgent();
		await this.abort({ goalReason: "internal" });
		await this.#sessionBeforeSwitchReconciler?.();

		await this.#bash.flushPending();
		this.#flushExcludedRows();
		// Flush pending writes before switching so restore snapshots reflect committed state.
		await this.sessionManager.flush();
		const previousSessionState = this.sessionManager.captureState();
		const bashTransition = this.#bash.beginSessionTransition();
		// Only same-session reloads compare against the prior context to detect
		// rollback edits (`#didSessionMessagesChange` below). Building it for a
		// different-session switch is a pure waste — and on huge pre-fix sessions
		// it materializes every persisted snapcompact frame plus the
		// `openaiRemoteCompaction.replacementHistory` payload into messages,
		// blowing the heap before the new session even loads (issue #3846). The
		// error-recovery path rebuilds the context on demand from the restored
		// state instead.
		const previousSessionContext = switchingToDifferentSession ? undefined : this.buildDisplaySessionContext();
		// switchSession replaces these arrays wholesale during load/rollback, so retaining
		// the existing message objects is sufficient and avoids structured-clone failures for
		// extension/custom metadata that is valid to persist but not cloneable.
		const previousAgentMessages = [...this.agent.state.messages];
		const previousSteeringMessages = [...this.agent.peekSteeringQueue()];
		const previousFollowUpMessages = [...this.agent.peekFollowUpQueue()];
		const previousPendingNextTurnMessages = [...this.#pendingNextTurnMessages];
		const previousScheduledHiddenNextTurnGeneration = this.#scheduledHiddenNextTurnGeneration;
		const previousQueuedMessageDrainBlocked = this.#queuedMessageDrainBlocked;
		const previousUsagePreflightReadyForNextModelCall = this.#usagePreflightReadyForNextModelCall;
		const previousUsagePreflightReadyModel = this.#usagePreflightReadyModel;
		const previousModel = this.model;
		const previousThinkingLevel = this.thinkingLevel;
		const previousAutoThinking = this.isAutoThinking;
		const previousAutoResolvedLevel = this.autoResolvedThinkingLevel();
		const previousServiceTierByFamily = this.serviceTierByFamily;
		const previousTools = [...this.agent.state.tools];
		const previousBaseSystemPrompt = this.#tools.baseSystemPrompt;
		const previousSystemPromptSources = this.#tools.systemPromptSources;
		const previousSystemPrompt = this.agent.state.systemPrompt;
		const previousBaseSystemPromptBeforeMemoryPromotion = this.#memory.promotionSnapshot;
		const previousFreshProviderSessionId = this.#freshProviderSessionId;
		const previousInheritedProviderPromptCacheKey = this.#inheritedProviderPromptCacheKey;
		const previousTaskSiblingCandidate = this.sessionManager.getTaskSiblingCandidate();

		// Snapshot the full checkpoint runtime state: the success path calls
		// #rehydrateCheckpointRewindState(), which clears and rebuilds all four
		// fields from the target branch. On rollback every one must be restored,
		// or a failed switch leaks the target session's checkpoint state.
		const previousCheckpointState = this.#checkpointState;
		const previousPendingRewindReport = this.#pendingRewindReport;
		const previousLastCompletedRewind = this.#lastCompletedRewind;
		const previousRewoundToolResultIds = new Set(this.#rewoundToolResultIds);

		this.agent.clearAllQueues();
		this.#holdQueuedMessages([...previousSteeringMessages, ...previousFollowUpMessages]);
		// Same rationale as newSession: an aborted turn can skip its final aside poll,
		// stranding IRC/extension asides meant for the outgoing transcript. Snapshot so a
		// rolled-back switch (catch block below) restores them for the still-live session.
		// #sessionGeneration bumps in the same breath (and rolls back with it) so an
		// aside-queueing call still awaiting normalization when the switch started drops its
		// record on success but stays valid if the switch is rolled back to this same session.
		const previousIrcPending = this.#irc.clearPending();
		const previousSessionGeneration = this.#sessionGeneration++;
		const generationSettled = Promise.withResolvers<void>();
		const previousSessionGenerationSettled = this.#sessionGenerationSettled;
		this.#sessionGenerationSettled = generationSettled.promise;
		this.#pendingNextTurnMessages = [];
		this.#pendingExcludedRows = [];
		this.#scheduledHiddenNextTurnGeneration = undefined;
		this.#queuedMessageDrainBlocked = false;
		this.#usagePreflightReadyForNextModelCall = false;
		this.#usagePreflightReadyModel = undefined;

		let cwdChangeTarget: string | undefined;
		try {
			if (switchingToDifferentSession) {
				// Stop and settle in-flight advisors while the old-session feeds can
				// still observe message_end, then mute before swapping files.
				await this.#advisors.drainAndDetachRecorders();
			}
			// The file may be reloaded at the same path with a different latest contract (or the
			// switch rolled back via restoreState); re-read it on the next model call either way.
			this.#sessionInit = undefined;
			await this.sessionManager.setSessionFile(sessionPath);
			this.#bash.markSessionTransition(bashTransition);
			const newCwd = this.sessionManager.getCwd();
			const recordedCwd = this.sessionManager.getRecordedCwd() ?? previousSessionState.cwd;
			if (options?.preserveLocalCwd) {
				this.sessionManager.setCwdWithoutRelocation(previousSessionState.cwd);
			} else {
				if (!options?.onCwdChange && path.resolve(recordedCwd) !== path.resolve(previousSessionState.cwd)) {
					throw SESSION_CWD_CHANGE_REJECTED;
				}
				if (options?.onCwdChange) {
					if (path.resolve(newCwd) !== path.resolve(previousSessionState.cwd)) {
						cwdChangeTarget = newCwd;
						if (!(await options.onCwdChange(newCwd, previousSessionState.cwd))) {
							throw SESSION_CWD_CHANGE_REJECTED;
						}
					}
				}
			}
			if (switchingToDifferentSession) {
				this.#freshProviderSessionId = undefined;
				this.#clearInheritedProviderPromptCacheKey();
				this.#adoptInheritedProviderPromptCacheKey();
				// The outgoing session's parent-derived family candidate is scoped
				// to it; the resumed session's own header decides affinity from here.
				this.sessionManager.clearTaskSiblingCandidate();
			}
			this.#syncAgentSessionId(undefined, false);
			this.#memory.rekeyForCurrentSessionId();

			let sessionContext = this.buildDisplaySessionContext();
			// Resolve the target's model before announcing the switch, so an
			// unrestorable one rolls back before any hook sees the target session.
			const targetModelStrings = getRestorableSessionModels(
				sessionContext.models,
				this.sessionManager.getLastModelChangeRole(),
			);
			let targetModel = explicitModel;
			let modelFallbackWarning: string | undefined;
			if (!targetModel && !options?.keepModel && targetModelStrings.length > 0) {
				targetModel = await this.#resolveSessionModel(targetModelStrings);
				if (!targetModel && switchingToDifferentSession) {
					// Like startup resume: never hand the transcript to a model the
					// session did not choose unless a UI can say so.
					if (!this.#allowSessionModelFallback || !cfgRetryModelFallback.get(this.settings)) {
						throw new Error(`Could not restore model ${targetModelStrings[0]}`);
					}
					const currentModel = this.model;
					modelFallbackWarning = currentModel
						? `Could not restore model ${targetModelStrings[0]}. Using ${currentModel.provider}/${currentModel.id}`
						: `Could not restore model ${targetModelStrings[0]}`;
				}
			}
			// The first build was read by the departing model; rebuild it for the
			// model this session is about to adopt when that one sizes the archive
			// differently or stands on another compaction boundary.
			if (
				targetModel &&
				(frameDataBytesBudget(targetModel) !== frameDataBytesBudget(this.model) ||
					this.#providerBoundary.readsOtherCompaction(targetModel, this.model))
			) {
				sessionContext = this.buildDisplaySessionContext(targetModel);
			}
			const didReloadConversationChange =
				previousSessionContext !== undefined &&
				didSessionMessagesChange(previousSessionContext.messages, sessionContext.messages);
			this.#rehydrateCheckpointRewindState();

			// As on /new: the outgoing session's background jobs share this agent id, so their
			// results would otherwise land in the resumed transcript. Cancelled after the cwd and
			// model checks, so a rejected switch keeps them, and before hooks hear of the switch,
			// so jobs they start belong to the resumed session. Deliveries are held until now.
			if (switchingToDifferentSession) this.#cancelOwnAsyncJobs();

			this.#reseedCostGate();
			// Emit session_switch event to hooks
			if (this.#extensionRunner) {
				await this.#extensionRunner.emit({
					type: "session_switch",
					reason: "resume",
					previousSessionFile,
				});
			}

			// Persisted once the switch can no longer roll back, below.
			this.agent.replaceMessages(sessionContext.messages);
			this.#reseedTokenRate();
			this.#advisors.resetSessionState({ preserveCost: true });
			this.#todo.syncFromBranch();
			this.#modelMentions.syncFromBranch();
			if (switchingToDifferentSession) {
				this.#closeAllProviderSessions("session switch");
			} else if (didReloadConversationChange) {
				this.#closeAllProviderSessions("session reload");
			}

			if (targetModel) {
				const currentModel = this.model;
				const shouldResetProviderState =
					switchingToDifferentSession ||
					(currentModel !== undefined &&
						(currentModel.provider !== targetModel.provider ||
							currentModel.id !== targetModel.id ||
							currentModel.api !== targetModel.api));
				if (shouldResetProviderState) {
					await this.#setModelWithProviderSessionReset(targetModel);
				} else {
					this.agent.setModel(targetModel);
				}
				// Saved selectors may carry a thinking suffix; compare resolved models.
				const savedModel =
					targetModelStrings.length > 0
						? resolveSessionModelSelector(this.#modelRegistry, targetModelStrings[0])?.model
						: undefined;
				if (explicitModel && !(savedModel && modelsAreEqual(savedModel, targetModel))) {
					this.sessionManager.appendModelChange(`${targetModel.provider}/${targetModel.id}`);
				}
			}

			const model = this.model;
			if (model) {
				const interruptedTurnAbort = createInterruptedTurnAbortMessage(this.sessionManager.getBranch(), {
					api: model.api,
					provider: model.provider,
					model: model.id,
				});
				if (interruptedTurnAbort) {
					this.sessionManager.appendMessage(interruptedTurnAbort);
					sessionContext = this.buildDisplaySessionContext();
					this.agent.replaceMessages(sessionContext.messages);
				}
			}

			const hasThinkingEntry = this.sessionManager.getBranch().some(entry => entry.type === "thinking_level_change");
			const hasServiceTierEntry = this.sessionManager
				.getBranch()
				.some(entry => entry.type === "service_tier_change");
			const defaultThinkingLevel = parseConfiguredThinkingLevel(cfgDefaultThinkingLevel.get(this.settings));
			const configuredServiceTierByFamily = buildServiceTierByFamily(
				cfgTierOpenai.get(this.settings),
				cfgTierAnthropic.get(this.settings),
				cfgTierGoogle.get(this.settings),
			);
			// Restore the thinking selector. Each change persists the configured
			// selector (`auto` or a concrete level), so prefer it: an `auto` session
			// resumes in auto mode (reclassifying the next turn) instead of freezing at
			// the last resolved level. Entries written before the `configured` field
			// existed fall back to the concrete level (legacy pin-on-resume behavior).
			// With no thinking entry, fall back to the global default so fresh sessions
			// still classify their first turn.
			const restoredConfigured = sessionContext.configuredThinkingLevel;
			const restoredThinkingLevel: ConfiguredThinkingLevel | undefined =
				hasThinkingEntry || (defaultThinkingLevel === AUTO_THINKING && sessionContext.thinkingLevel !== "off")
					? restoredConfigured === AUTO_THINKING
						? AUTO_THINKING
						: (sessionContext.thinkingLevel as ThinkingLevel | undefined)
					: defaultThinkingLevel;
			this.#models.restoreThinkingLevel(restoredThinkingLevel);
			this.#models.restoreServiceTiers(
				hasServiceTierEntry ? (sessionContext.serviceTier ?? {}) : configuredServiceTierByFamily,
			);

			if (switchingToDifferentSession) {
				await this.#memory.resetContextForNewTranscript();
			}
			// The switch has committed: a rolled-back one must not write the target's journal.
			this.#persistRebuiltEvalStateContext(this.agent.state.messages);
			if (switchingToDifferentSession || didReloadConversationChange) {
				this.#clearSessionScopedToolState();
				this.#prunedTerminalFailure = undefined;
			}
			this.#reconnectToAgent();
			try {
				await this.#sessionSwitchReconciler?.();
			} catch (error) {
				logger.warn("Failed to reconcile session mode after switch", {
					targetSessionFile: sessionPath,
					error: String(error),
				});
			}
			// Refresh the workspace-roots block to match the resumed session's directory set.
			// Wrapped so a rebuild failure (e.g. a gate that intentionally fails in tests)
			// doesn't roll back an otherwise-successful session switch.
			try {
				await this.refreshBaseSystemPrompt();
			} catch (refreshErr) {
				logger.warn("Failed to refresh system prompt after session switch", {
					targetSessionFile: sessionPath,
					error: String(refreshErr),
				});
			}
			// Hand the ledger over to the session that just took over, and only once the
			// switch has committed: an earlier swap would be lost work if any step above
			// rolled it back. The target's own advisor transcripts are the record of what
			// it already spent, so a session with history resumes with its total instead
			// of restarting at zero.
			if (switchingToDifferentSession) {
				const providersBySlug = new Map<string, Set<string>>();
				const costs = await loadAdvisorTranscriptCosts(this.sessionFile, { providersBySlug });
				this.#advisors.restoreCost(costs, providersBySlug);
			}
			this.#bash.finishSessionTransition(bashTransition, true);
			// Keep the old reservations during rollback; the target is committed now,
			// so the snapshotted old queues can no longer be restored.
			this.#releaseTtsrReservations(previousSteeringMessages);
			this.#releaseTtsrReservations(previousFollowUpMessages);
			this.#releaseHeldQueuedMessages([...previousSteeringMessages, ...previousFollowUpMessages]);
			if (previousSessionState.sessionId !== this.sessionManager.getSessionId()) {
				this.#notifySessionChangeCallbacks();
			}
			generationSettled.resolve();
			this.#sessionGenerationSettled = previousSessionGenerationSettled;
			if (modelFallbackWarning) {
				if (options?.onModelFallback) options.onModelFallback(modelFallbackWarning);
				else this.emitNotice("warning", modelFallbackWarning);
			}
			return true;
		} catch (error) {
			this.sessionManager.restoreState(previousSessionState);
			this.#freshProviderSessionId = previousFreshProviderSessionId;
			this.#syncAgentSessionId(previousSessionState.sessionId, false);
			this.#memory.rekeyForCurrentSessionId();
			this.agent.setTools(previousTools);
			this.#tools.restoreBaseSystemPrompt(previousBaseSystemPrompt, previousSystemPromptSources);
			this.#memory.restorePromotionSnapshot(previousBaseSystemPromptBeforeMemoryPromotion);
			this.agent.setSystemPrompt(previousSystemPrompt);
			this.agent.replaceMessages(previousAgentMessages);
			this.agent.replaceQueues(
				this.#releaseHeldQueuedMessages(previousSteeringMessages),
				this.#releaseHeldQueuedMessages(previousFollowUpMessages),
			);
			this.#irc.restorePending(previousIrcPending);
			this.#sessionGeneration = previousSessionGeneration;
			generationSettled.resolve();
			this.#sessionGenerationSettled = previousSessionGenerationSettled;
			this.#pendingNextTurnMessages = previousPendingNextTurnMessages;
			this.#scheduledHiddenNextTurnGeneration = previousScheduledHiddenNextTurnGeneration;
			this.#queuedMessageDrainBlocked = previousQueuedMessageDrainBlocked;
			this.#usagePreflightReadyForNextModelCall = previousUsagePreflightReadyForNextModelCall;
			this.#usagePreflightReadyModel = previousUsagePreflightReadyModel;
			this.#inheritedProviderPromptCacheKey = previousInheritedProviderPromptCacheKey;
			if (previousTaskSiblingCandidate !== undefined) {
				this.sessionManager.setTaskSiblingCandidate(previousTaskSiblingCandidate);
			}
			this.#checkpointState = previousCheckpointState;
			this.#pendingRewindReport = previousPendingRewindReport;
			this.#lastCompletedRewind = previousLastCompletedRewind;
			this.#rewoundToolResultIds = previousRewoundToolResultIds;
			// The try block may have already reached #setModelWithProviderSessionReset
			// for the target session's model, which emits `model_changed` for it.
			// Restoring here bypasses that method (it also resets provider-session
			// state we're already unwinding above), so if the rollback actually
			// changes the model back, emit the corrective event ourselves —
			// otherwise ACP/RPC/TUI keep advertising the never-committed target.
			// Deferred until after restoreThinkingSnapshot below: #emit's listeners
			// (ACP's #handleLifetimeEvent -> #pushConfigOptionUpdate) read
			// session state synchronously before their first await, so emitting
			// here — before the target session's thinking level is unwound —
			// would push a { previousModel, target-session-thinking } config that
			// was never a real session state.
			let modelRolledBack = false;
			if (previousModel) {
				const rolledBackModel = this.model;
				this.agent.setModel(previousModel);
				modelRolledBack = !modelsAreEqual(rolledBackModel, previousModel);
			}
			this.#models.restoreThinkingSnapshot(previousThinkingLevel, previousAutoThinking, previousAutoResolvedLevel);
			this.#models.restoreServiceTiers(previousServiceTierByFamily);
			if (modelRolledBack) {
				this.#emit({ type: "model_changed" });
			}
			this.#todo.syncFromBranch();
			this.#modelMentions.syncFromBranch();
			this.#advisors.resetAllRuntimes();
			this.#advisors.reattachRecorderFeeds();
			this.#reconnectToAgent();
			try {
				await this.#sessionSwitchReconciler?.();
			} catch (reconcileError) {
				logger.warn("Failed to reconcile session mode after switch rollback", {
					targetSessionFile: sessionPath,
					error: String(reconcileError),
				});
			}
			if (cwdChangeTarget && error !== SESSION_CWD_CHANGE_REJECTED && options?.onCwdChange) {
				let rollbackFailure: string | undefined;
				try {
					if (!(await options.onCwdChange(previousSessionState.cwd, cwdChangeTarget))) {
						rollbackFailure = "cwd rollback was rejected";
					}
				} catch (rollbackError) {
					rollbackFailure = `cwd rollback failed: ${rollbackError instanceof Error ? rollbackError.message : String(rollbackError)}`;
				}
				if (rollbackFailure) {
					this.beginDispose();
					this.#bash.finishSessionTransition(bashTransition, false);
					logger.warn("Failed to restore cwd after session switch", { cwd: previousSessionState.cwd });
					const original = error instanceof Error ? error.message : String(error);
					throw new Error(`${original} (${rollbackFailure}; the process may remain in ${cwdChangeTarget})`);
				}
			}
			this.#bash.finishSessionTransition(bashTransition, false);
			if (error === SESSION_CWD_CHANGE_REJECTED) return false;
			throw error;
		}
	}

	/**
	 * First restorable saved session model, resolved like startup resume: when
	 * none is in the catalog, refresh the discovery-backed providers among them
	 * once and retry.
	 */
	async #resolveSessionModel(selectors: readonly string[]): Promise<Model | undefined> {
		const resolve = (): Model | undefined => {
			for (const selector of selectors) {
				const restored = resolveSessionModelSelector(this.#modelRegistry, selector);
				if (restored) return restored.model;
			}
			return undefined;
		};
		const restored = resolve();
		if (restored) return restored;
		const providers = sessionModelDiscoveryProviders(
			this.#modelRegistry,
			selectors,
			disabledProviderIds(this.settings),
		);
		if (providers.size === 0) return undefined;
		await this.#modelRegistry.refreshDiscoverableProviders(providers, "online-if-uncached");
		return resolve();
	}

	/**
	 * Create a branch from a specific entry.
	 * Emits before_branch/branch session events to hooks.
	 *
	 * @param entryId ID of the entry to branch from
	 * @returns Object with:
	 *   - selectedText: The text of the selected user message (for editor pre-fill)
	 *   - selectedImages: Image attachments of the selected user message (for editor draft restore)
	 *   - cancelled: True if a hook cancelled the branch
	 */
	async branch(entryId: string): Promise<{
		selectedText: string;
		selectedImages: ImageContent[];
		cancelled: boolean;
	}> {
		const queued = this.#enterSessionTransition(() => this.branch(entryId));
		if (queued) return queued;
		using _transition = this.#beginSessionTransition();
		const selectedEntry = this.sessionManager.getEntry(entryId);

		if (selectedEntry?.type !== "message" || selectedEntry.message.role !== "user") {
			throw new Error("Invalid entry ID for branching");
		}

		const selectedText = this.#extractUserMessageText(selectedEntry.message.content);
		const selectedImages = this.#extractUserMessageImages(selectedEntry.message.content);
		const completed = await this.#branchIntoNewSession("branch", entryId, selectedEntry.parentId);
		return { selectedText, selectedImages, cancelled: !completed };
	}

	/**
	 * Shared {@link branch}/{@link fork}(entryId) transition: moves the live session onto a
	 * new session file holding the root-to-`leafId` path (an empty one when `leafId` is
	 * null), emitting `session_before_branch`/`session_branch` with `reason` for `entryId`.
	 * `copyArtifacts` goes to {@link SessionManager.createBranchedSession}; `requireIdleFor`
	 * refuses with {@link SessionBusyError} naming that action unless the session is idle.
	 * @returns false when a `session_before_branch` hook cancelled
	 */
	async #branchIntoNewSession(
		reason: "branch" | "fork",
		entryId: string,
		leafId: string | null,
		options?: { copyArtifacts?: boolean; requireIdleFor?: string },
	): Promise<boolean> {
		const previousSessionFile = this.sessionFile;
		const requireIdleFor = options?.requireIdleFor;
		if (requireIdleFor) this.#assertIdleForSnapshot(requireIdleFor);
		let skipConversationRestore = false;

		// Emit session_before_branch event (can be cancelled)
		if (this.#extensionRunner?.hasHandlers("session_before_branch")) {
			const result = (await this.#extensionRunner.emit({
				type: "session_before_branch",
				reason,
				entryId,
			})) as SessionBeforeBranchResult | undefined;

			if (result?.cancel) {
				return false;
			}
			skipConversationRestore = result?.skipConversationRestore ?? false;
			// A turn or user command may have started while the hook awaited.
			if (requireIdleFor) this.#assertIdleForSnapshot(requireIdleFor);
		}

		await this.#bash.flushPending();
		this.#flushExcludedRows();
		// Flush pending writes before branching
		await this.sessionManager.flush();
		// Last refusal point. Nothing below is rolled back when the transition stops, so an
		// idle-only snapshot refuses here, after the flush awaits but before any state of the
		// old session (pending messages, async jobs, auto-learn capture) is discarded.
		if (requireIdleFor) this.#assertIdleForSnapshot(requireIdleFor);

		// Clear pending messages (bound to old session state)
		this.#pendingNextTurnMessages = [];
		this.#pendingExcludedRows = [];
		this.#scheduledHiddenNextTurnGeneration = undefined;
		this.#queuedMessageDrainBlocked = false;
		this.#usagePreflightReadyForNextModelCall = false;

		const bashTransition = this.#bash.beginSessionTransition();
		this.#cancelOwnAsyncJobs();
		this.#abortAutolearnCapture();
		await this.#drainAutolearnCapture();

		let sessionTransitioned = false;
		let advisorRecordersDetached = false;
		try {
			advisorRecordersDetached = true;
			await this.#advisors.drainAndDetachRecorders();
			try {
				// A prompt admitted during the drain awaits above belongs to the history
				// being replaced; the generation bump drops its pending setup.
				this.#promptGeneration++;
				if (!leafId) {
					const title = this.sessionManager.getSessionName();
					const titleSource = this.sessionManager.titleSource;
					await this.sessionManager.newSession({ parentSession: previousSessionFile });
					if (title) await this.sessionManager.setSessionName(title, titleSource);
				} else {
					this.sessionManager.createBranchedSession(leafId, { copyArtifacts: options?.copyArtifacts });
				}
				this.#bash.markSessionTransition(bashTransition);
				this.#advisors.clearCost();
				sessionTransitioned = true;
			} finally {
				this.#bash.finishSessionTransition(bashTransition, sessionTransitioned);
			}
			this.#prunedTerminalFailure = undefined;
			this.#clearSessionScopedToolState();
			this.#rehydrateCheckpointRewindState();
			this.#todo.syncFromBranch();
			this.#modelMentions.syncFromBranch();
			this.#freshProviderSessionId = undefined;
			this.#clearInheritedProviderPromptCacheKey();
			this.#syncAgentSessionId();
			this.#memory.rekeyForCurrentSessionId();
			await this.#memory.resetContextForNewTranscript();

			// Reload messages from entries (works for both file and in-memory mode)
			const sessionContext = this.buildDisplaySessionContext();

			// Emit session_branch event to hooks (after branch completes)
			if (this.#extensionRunner) {
				await this.#extensionRunner.emit({
					type: "session_branch",
					reason,
					previousSessionFile,
				});
			}

			if (!skipConversationRestore) {
				this.replaceMessagesFromSessionContext(sessionContext.messages);
				this.#advisors.resetSessionState();
				this.#closeCodexProviderSessionsForHistoryRewrite();
			}

			this.#advisors.reattachRecorderFeeds();
			advisorRecordersDetached = false;
			await this.#reconcileModeAfterTransition();
			return true;
		} finally {
			if (advisorRecordersDetached) {
				if (sessionTransitioned) this.#advisors.resetSessionState();
				else this.#advisors.reattachRecorderFeeds();
			}
		}
	}

	/** Promotes a completed /btw answer from the explicitly authorized session and leaf. */
	async branchFromBtw(
		question: string,
		assistantMessage: AssistantMessage,
		leafId: string,
		sessionId: string,
		images?: ImageContent[],
	): Promise<{ cancelled: boolean; sessionFile: string | undefined }> {
		const queued = this.#enterSessionTransition(() =>
			this.branchFromBtw(question, assistantMessage, leafId, sessionId, images),
		);
		if (queued) return queued;
		using _transition = this.#beginSessionTransition();
		const previousSessionFile = this.sessionFile;
		if (!this.sessionManager.getSessionFile()) {
			throw new Error("Cannot branch /btw: session is not persisted");
		}

		if (!leafId || this.sessionManager.getSessionId() !== sessionId || this.sessionManager.getLeafId() !== leafId) {
			throw new Error("Cannot branch /btw: session changed since /btw started");
		}

		this.#assertIdleForSnapshot("branch /btw");

		if (this.#extensionRunner?.hasHandlers("session_before_branch")) {
			const result = (await this.#extensionRunner.emit({
				type: "session_before_branch",
				reason: "btw",
				entryId: leafId,
			})) as SessionBeforeBranchResult | undefined;

			if (result?.cancel) {
				return { cancelled: true, sessionFile: previousSessionFile };
			}
		}

		if (this.sessionManager.getSessionId() !== sessionId || this.sessionManager.getLeafId() !== leafId) {
			throw new Error("Cannot branch /btw: session changed since /btw started");
		}

		// The promoted question gets a prompt's image handling, description included.
		const promotedImages = await this.#normalizeImagesForModel(images);
		const imageDescriptionNotice = promotedImages?.length
			? await this.#buildImageDescriptionNotice(promotedImages)
			: undefined;

		await withTimeout(
			this.#cancelPostPromptTasks(),
			POST_PROMPT_DRAIN_TIMEOUT_MS,
			"Timed out draining post-prompt tasks before /btw branch",
		);
		this.#assertIdleForSnapshot("branch /btw");

		this.#pendingNextTurnMessages = [];
		this.#pendingExcludedRows = [];
		this.#scheduledHiddenNextTurnGeneration = undefined;
		this.#releaseQueuedTtsrReservations();
		this.agent.replaceQueues([], []);
		this.#queuedMessageDrainBlocked = false;
		this.#usagePreflightReadyForNextModelCall = false;
		await this.#bash.flushPending();
		await this.sessionManager.flush();
		const bashTransition = this.#bash.beginSessionTransition();
		this.#cancelOwnAsyncJobs();
		this.#abortAutolearnCapture();
		await this.#drainAutolearnCapture();

		let sessionTransitioned = false;
		let advisorRecordersDetached = false;
		try {
			advisorRecordersDetached = true;
			await this.#advisors.drainAndDetachRecorders();
			try {
				if (this.sessionManager.getSessionId() !== sessionId || this.sessionManager.getLeafId() !== leafId) {
					throw new Error("Cannot branch /btw: session changed since /btw started");
				}
				// A prompt may have been admitted during the flush/drain awaits
				// after the idle check. It still belongs to the pre-branch context.
				this.#promptGeneration++;
				this.sessionManager.createBranchedSession(leafId);
				this.#bash.markSessionTransition(bashTransition);
				this.#advisors.clearCost();
				sessionTransitioned = true;
			} finally {
				this.#bash.finishSessionTransition(bashTransition, sessionTransitioned);
			}

			this.#prunedTerminalFailure = undefined;
			this.#clearSessionScopedToolState();

			this.#rehydrateCheckpointRewindState();
			if (imageDescriptionNotice) this.sessionManager.appendMessage(imageDescriptionNotice);
			this.sessionManager.appendMessage({
				role: "user",
				content: [{ type: "text", text: question }, ...(promotedImages ?? [])],
				attribution: "user",
				timestamp: Date.now(),
			});
			this.sessionManager.appendMessage(sanitizeAssistantForReparentedHistory(assistantMessage));
			this.#todo.syncFromBranch();
			this.#modelMentions.syncFromBranch();
			this.#freshProviderSessionId = undefined;
			this.#syncAgentSessionId();
			this.#memory.rekeyForCurrentSessionId();
			await this.#memory.resetContextForNewTranscript();

			const sessionContext = this.buildDisplaySessionContext();

			if (this.#extensionRunner) {
				await this.#extensionRunner.emit({
					type: "session_branch",
					reason: "btw",
					previousSessionFile,
				});
			}

			this.replaceMessagesFromSessionContext(sessionContext.messages);
			this.#advisors.resetSessionState();
			this.#closeCodexProviderSessionsForHistoryRewrite();
			advisorRecordersDetached = false;
			await this.#reconcileModeAfterTransition();

			return { cancelled: false, sessionFile: this.sessionFile };
		} finally {
			if (advisorRecordersDetached) {
				if (sessionTransitioned) this.#advisors.resetSessionState();
				else this.#advisors.reattachRecorderFeeds();
			}
		}
	}

	// =========================================================================
	// Tree Navigation
	// =========================================================================

	/**
	 * Navigate to a different node in the session tree.
	 * Unlike branch() which creates a new session file, this stays in the same file.
	 *
	 * @param targetId The entry ID to navigate to
	 * @param options.summarize Whether user wants to summarize abandoned branch
	 * @param options.customInstructions Custom instructions for summarizer
	 * @returns Result with editorText/editorImages (if user message) and cancelled status
	 */
	async navigateTree(
		targetId: string,
		options: {
			summarize?: boolean;
			customInstructions?: string;
			/**
			 * Opts into the two-phase `ask` toolResult re-answer protocol
			 * (issue #5642): set only by the interactive `/tree` selector, which
			 * knows how to re-open the picker on `reopenAsk` and complete the
			 * navigation with `reanswerAskResult`. Every other public caller
			 * (extensions, hooks, ACP, session-extension actions) leaves this
			 * unset and gets the pre-#5642 plain leaf move onto `ask`
			 * toolResults instead — they have no picker to re-open and would
			 * otherwise report a successful no-op navigation (roboomp review on
			 * #5895).
			 */
			allowAskReopen?: boolean;
			/**
			 * Completes an in-progress `ask` re-answer (issue #5642): the caller
			 * already received `reopenAsk` from a prior call on the same
			 * `targetId`, re-opened the picker, and is handing back the fresh
			 * answer. Branches a new toolResult sibling instead of landing on
			 * the original one.
			 */
			reanswerAskResult?: AgentToolResult<AskToolDetails>;
			/**
			 * Refuse with {@link SessionBusyError} when work started while the hooks
			 * or the branch summary were awaited, before any tree change is made.
			 */
			requireIdle?: boolean;
		} = {},
	): Promise<NavigateTreeResult> {
		const queued = this.#enterSessionTransition(() => this.navigateTree(targetId, options));
		if (queued) return queued;
		using _transition = this.#beginSessionTransition();
		await this.#bash.flushPending();
		this.#flushExcludedRows();
		const oldLeafId = this.sessionManager.getLeafId();

		const targetEntry = this.sessionManager.getEntry(targetId);
		if (!targetEntry) {
			throw new Error(`Entry ${targetId} not found`);
		}
		const targetIsAskResult =
			targetEntry.type === "message" &&
			targetEntry.message.role === "toolResult" &&
			targetEntry.message.toolName === "ask";
		const targetIsUserMessage = targetEntry.type === "message" && targetEntry.message.role === "user";

		// No-op if already at target — except for a user message, which always
		// rewinds PAST itself (leaf → parent, text → editor), so a leaf user
		// prompt (turn aborted before any assistant reply) is still a real move
		// — and except mid-flight through the `ask` re-answer protocol (issue
		// #5642): a probe or completion call can legitimately target the
		// *current* leaf (e.g. the user interrupted right after answering
		// `ask`, before a follow-up assistant message landed, or another caller
		// navigated straight onto the ask result), and must still return
		// `reopenAsk` / branch the new answer instead of silently reporting a
		// no-op (chatgpt-codex review on #5895).
		if (targetId === oldLeafId && !targetIsUserMessage && !(options.allowAskReopen && targetIsAskResult)) {
			return { cancelled: false };
		}

		// Model required for summarization
		if (options.summarize && !this.model) {
			throw new Error("No model available for summarization");
		}

		// `ask` toolResult, first pass: hand control back to the caller to
		// re-open the picker instead of landing on the stale answer in place.
		// Nothing is mutated here — see the `reanswerAskResult` branch below for
		// the actual sibling-branch construction once the caller has an answer.
		// Gated on `allowAskReopen` — callers that don't understand `reopenAsk`
		// fall straight through to the plain leaf move below instead of
		// reporting a successful no-op (roboomp review on #5895).
		if (
			options.allowAskReopen &&
			!options.reanswerAskResult &&
			targetEntry.type === "message" &&
			targetEntry.message.role === "toolResult" &&
			targetEntry.message.toolName === "ask"
		) {
			const toolCallId = targetEntry.message.toolCallId;
			const html = this.#recoverAskReanswerHtml(targetEntry.parentId, toolCallId);
			if (html !== undefined) {
				return { cancelled: false, reopenAsk: { toolCallId, html } };
			}
			// Original arguments couldn't be recovered (corrupted/legacy session
			// data) — fall through to a plain leaf move so navigation still works.
		}

		// Collect entries to summarize (from old leaf to common ancestor). For an
		// `ask` re-answer completion, the branch point is `targetEntry.parentId`
		// (the new sibling toolResult lands there, not on `targetId`) — anchor
		// the collection there too, or the old answer entry is neither on the
		// new branch nor included in the summary (chatgpt-codex review on
		// #5895).
		const summaryAnchorId =
			options.reanswerAskResult !== undefined &&
			targetEntry.type === "message" &&
			targetEntry.message.role === "toolResult" &&
			targetEntry.message.toolName === "ask" &&
			targetEntry.parentId !== null
				? targetEntry.parentId
				: targetId;
		const { entries: entriesToSummarize, commonAncestorId } = collectEntriesForBranchSummary(
			this.sessionManager,
			oldLeafId,
			summaryAnchorId,
		);

		// Prepare event data
		const preparation: TreePreparation = {
			targetId,
			oldLeafId,
			commonAncestorId,
			entriesToSummarize,
			userWantsSummary: options.summarize ?? false,
		};

		// Set up abort controller for summarization
		this.#branchSummaryAbortController = new AbortController();
		let hookSummary: { summary: string; details?: unknown } | undefined;
		let fromExtension = false;

		// Emit session_before_tree event
		if (this.#extensionRunner?.hasHandlers("session_before_tree")) {
			const result = (await this.#extensionRunner.emit({
				type: "session_before_tree",
				preparation,
				signal: this.#branchSummaryAbortController.signal,
			})) as SessionBeforeTreeResult | undefined;

			if (result?.cancel) {
				return { cancelled: true };
			}

			if (result?.summary && options.summarize) {
				hookSummary = result.summary;
				fromExtension = true;
			}
		}

		// Run default summarizer if needed
		let summaryText: string | undefined;
		let summaryDetails: unknown;
		if (options.summarize && entriesToSummarize.length > 0 && !hookSummary) {
			const model = this.model!;
			const apiKey = await this.#modelRegistry.getApiKey(model, this.sessionId);
			if (!apiKey) {
				throw new Error(`No API key for ${model.provider}`);
			}
			// The summary is stored as a branch summary entry; only the spend needs journaling.
			const journal = journalCompletion(this.sessionManager, { purpose: "branch-summary", usageOnly: true });
			const result = await generateBranchSummary(entriesToSummarize, {
				model,
				apiKey: this.#modelRegistry.resolver(model, this.sessionId),
				signal: this.#branchSummaryAbortController.signal,
				customInstructions: this.#obfuscateTextForProvider(options.customInstructions),
				reserveTokens: cfgBranchSummaryReserveTokens.get(this.settings),
				metadata: this.agent.metadataForProvider(model.provider),
				convertToLlm: messages => this.#convertToLlmForSideRequest(messages),
				telemetry: resolveTelemetry(this.agent.telemetry, this.sessionId),
				// Same per-provider concurrency cap rationale as the compaction
				// path above (chatgpt-codex review on #3751).
				completeImpl: async (requestModel, requestContext, requestOptions) => {
					const stream = await this.#sideStreamFn(requestModel, requestContext, requestOptions);
					const message = await stream.result();
					// One call per provider attempt, so a retried or failed one is billed too.
					journal?.(message);
					return message;
				},
			});
			this.#branchSummaryAbortController = undefined;
			if (result.aborted) {
				return { cancelled: true, aborted: true };
			}
			if (result.error) {
				throw new Error(result.error);
			}
			summaryText = result.summary;
			summaryDetails = {
				readFiles: result.readFiles || [],
				modifiedFiles: result.modifiedFiles || [],
			};
		} else if (hookSummary) {
			summaryText = hookSummary.summary;
			summaryDetails = hookSummary.details;
		}

		// A run admitted during the hook or summary awaits would keep writing into the branch the leaf leaves.
		if (options.requireIdle) this.#assertIdleForSnapshot("navigate the session tree");

		// All cancellation/no-op exits are behind us. Invalidate prompt setup
		// admitted on the abandoned branch before committing any tree changes.
		this.#promptGeneration++;

		// Determine the new leaf position based on target type
		let newLeafId: string | null;
		let editorText: string | undefined;
		let editorImages: ImageContent[] | undefined;
		// Set when the second-pass `ask` re-answer branch below actually commits a
		// new sibling answer — the trigger for resuming the agent afterwards so the
		// model consumes it, mirroring a live `ask` completion (issue #6483).
		let isAskReanswerCompletion = false;

		if (isTranscriptEntry(targetEntry) && isUserRequestEntry(targetEntry)) {
			// User request (plain prompt, or a user-invoked skill/collab prompt): leaf = parent
			// (null if root), the draft the user typed goes back to the editor with its images.
			newLeafId = targetEntry.parentId;
			editorText = userTurnDraft(targetEntry);
			const request = transcriptEntryMessage(targetEntry);
			const targetImages =
				request && (request.role === "user" || request.role === "custom")
					? this.#extractUserMessageImages(request.content)
					: [];
			if (targetImages.length > 0) editorImages = targetImages;
		} else if (targetEntry.type === "custom_message" && targetEntry.customType !== SKILL_PROMPT_MESSAGE_TYPE) {
			// Other custom message: leaf = parent (null if root), text goes to editor
			newLeafId = targetEntry.parentId;
			editorText =
				typeof targetEntry.content === "string"
					? targetEntry.content
					: targetEntry.content
							.filter((c): c is { type: "text"; text: string } => c.type === "text")
							.map(c => c.text)
							.join("");
		} else if (
			targetEntry.type === "message" &&
			targetEntry.message.role === "toolResult" &&
			targetEntry.message.toolName === "ask" &&
			options.reanswerAskResult
		) {
			// `ask` toolResult, second pass: the caller re-opened the picker and
			// is handing back a fresh answer. Branch a *new* sibling toolResult
			// off the same `ask` toolCall instead of reusing `targetId` — the
			// original answer's branch stays reachable (issue #5642).
			const reanswer = options.reanswerAskResult;
			const toolResultMessage: ToolResultMessage = {
				role: "toolResult",
				toolCallId: targetEntry.message.toolCallId,
				toolName: "ask",
				content: reanswer.content,
				details: reanswer.details,
				isError: reanswer.isError === true,
				timestamp: Date.now(),
			};
			// The new sibling answer itself becomes the leaf below (`branch(newLeafId)`),
			// so it must not record the pre-navigation leaf as its own.
			newLeafId = this.sessionManager.appendMessageToBranch(toolResultMessage, targetEntry.parentId, {
				preserveActiveLeaf: false,
			});
			isAskReanswerCompletion = true;
		} else {
			// Non-user message (or an agent/autoload skill-prompt injection): land the
			// leaf on the selected node so it stays on the active branch. Injected skill
			// prompts must not be re-editable — their content is a large expanded body,
			// not a user turn (issue #5374).
			newLeafId = targetId;
		}

		// Switch leaf (with or without summary)
		// Summary is attached at the navigation target position (newLeafId), not the old branch
		const bashTransition = this.#bash.beginSessionTransition();
		let summaryEntry: BranchSummaryEntry | undefined;
		let branchTransitioned = false;
		try {
			if (summaryText) {
				// Create summary at target position (can be null for root)
				const summaryId = this.sessionManager.branchWithSummary(
					newLeafId,
					summaryText,
					summaryDetails,
					fromExtension,
				);
				summaryEntry = this.sessionManager.getEntry(summaryId) as BranchSummaryEntry;
			} else if (newLeafId === null) {
				this.sessionManager.resetLeaf();
			} else {
				this.sessionManager.branch(newLeafId);
			}
			this.#bash.markSessionTransition(bashTransition);
			branchTransitioned = true;
			this.#prunedTerminalFailure = undefined;
		} finally {
			this.#bash.finishSessionTransition(bashTransition, branchTransitioned);
		}

		// Update agent state — build display context to populate agent messages.
		const stateContext = this.sessionManager.buildSessionContext({
			maxFrameDataBytes: frameDataBytesBudget(this.model),
			model: this.model,
		});
		const displayContext = this.#withEvalStateContext(deobfuscateSessionContext(stateContext, this.#obfuscator));
		this.replaceMessagesFromSessionContext(displayContext.messages);
		this.#rehydrateCheckpointRewindState();
		this.#advisors.resetSessionState({ preserveCost: true });
		this.#todo.syncFromBranch();
		this.#modelMentions.syncFromBranch();
		this.#closeCodexProviderSessionsForHistoryRewrite();

		this.#branchSummaryAbortController = undefined;

		// Report a committed `ask` re-answer so the interactive caller can resume
		// the agent via `resumeAfterAskReanswer()` *after* rebuilding its
		// transcript. Scheduling the continue here instead would start a fresh
		// streaming turn whose `agent_start`/`turn_start` events could render
		// against the stale pre-rebuild UI and then be clobbered by the caller's
		// `renderInitialMessages(...)` (issue #6483). Plain leaf moves and the
		// read-only `reopenAsk` probe leave the flag unset.

		// Emit session_tree event; only handlers can mutate session entries, so skip
		// the emit and the context rebuild when no handlers are registered (mirrors
		// the session_before_tree guard above).
		if (this.#extensionRunner?.hasHandlers("session_tree")) {
			await this.#extensionRunner.emit({
				type: "session_tree",
				newLeafId: this.sessionManager.getLeafId(),
				oldLeafId,
				summaryEntry,
				fromExtension: summaryText ? fromExtension : undefined,
			});
			const rawContext = this.sessionManager.buildSessionContext({
				maxFrameDataBytes: frameDataBytesBudget(this.model),
				model: this.model,
			});
			return {
				editorText,
				editorImages,
				cancelled: false,
				summaryEntry,
				sessionContext: rawContext,
				askReanswerCommitted: isAskReanswerCompletion,
			};
		}
		return {
			editorText,
			editorImages,
			cancelled: false,
			summaryEntry,
			sessionContext: stateContext,
			askReanswerCommitted: isAskReanswerCompletion,
		};
	}

	/**
	 * Resume the agent after the interactive `/tree` caller has committed an
	 * `ask` re-answer (`navigateTree` returned `askReanswerCommitted`) and
	 * rebuilt its transcript. Mirrors how a live `ask` completion drives a
	 * follow-up turn, but is deferred to the caller so the resumed turn renders
	 * against the rebuilt UI rather than the stale pre-navigation transcript
	 * (issue #6483). The scheduled continue honors the same disposed/compacting
	 * guards as every other post-prompt continuation.
	 */
	resumeAfterAskReanswer(): void {
		this.#scheduleAgentContinue({ source: "ask-reanswer" });
	}

	/**
	 * Look up the `ask` toolCall's persisted `arguments` and validate them
	 * back into its form `html`, for `/tree` `ask` re-answer (issue #5642). Walks
	 * up from the toolResult's parent past any interleaved ancestor entries
	 * — sibling toolResults from other tool calls in the same turn (`ask`
	 * runs `exclusive`, which only serializes *execution*, not persistence
	 * order — roboomp review on #5895), and bookkeeping entries such as the
	 * `tool_execution_start` custom entry `#recordToolExecutionStart()`
	 * appends before every toolResult in real persisted sessions (chatgpt-codex
	 * review on #5895) — until it finds the assistant entry that actually
	 * emitted `toolCallId`. Stops at a `user` message (turn boundary) or a
	 * dead end. Returns `undefined` when no ancestor entry holds a matching
	 * `ask` toolCall, or the arguments can't be resolved — the caller falls
	 * back to a plain leaf move rather than opening a picker with bad data.
	 */
	#recoverAskReanswerHtml(parentId: string | null, toolCallId: string): string | undefined {
		let current = parentId;
		while (current !== null) {
			const entry = this.sessionManager.getEntry(current);
			if (!entry) return undefined;
			if (entry.type === "message") {
				if (entry.message.role === "assistant") {
					const toolCall = entry.message.content.find(
						(block): block is AgentToolCall => block.type === "toolCall" && block.id === toolCallId,
					);
					if (!toolCall) return undefined;
					if (toolCall.name !== "ask") return undefined;
					const args = this.#obfuscator?.hasSecrets()
						? deobfuscateToolArguments(this.#obfuscator, toolCall.arguments)
						: toolCall.arguments;
					return recoverAskHtml(args);
				}
				if (entry.message.role === "user") return undefined;
			}
			current = entry.parentId;
		}
		return undefined;
	}

	/**
	 * Build a standalone `AgentToolContext` for running `AskTool.execute()`
	 * outside a normal agent turn, for `/tree` `ask` re-answer (issue #5642).
	 * `SelectorController` has no reachable `ToolContextStore` (that store is
	 * built inside `sdk.ts` and never threaded through to mode controllers),
	 * so this mirrors `refreshMCPTools()`'s `getCustomToolContext` factory
	 * with real session state instead of a `{ ... } as unknown as
	 * AgentToolContext` cast that could silently compile with an incomplete
	 * context (roboomp review on #5895) — every `CustomToolContext` field is
	 * backed by live session state, so a future required field fails to
	 * compile here instead of surfacing as `undefined` at runtime.
	 */
	buildAskReanswerContext(uiContext: ExtensionUIContext): AgentToolContext {
		return {
			sessionManager: this.sessionManager,
			modelRegistry: this.#modelRegistry,
			model: this.model,
			isIdle: () => !this.isStreaming,
			hasQueuedMessages: () => this.queuedMessageCount > 0,
			abort: () => {
				this.agent.abort();
			},
			settings: this.settings,
			ui: uiContext,
			hasUI: true,
		};
	}

	/**
	 * Get all user messages from session for branch selector.
	 */
	getUserMessagesForBranching(): Array<{ entryId: string; text: string }> {
		const entries = this.sessionManager.getEntries();
		const result: Array<{ entryId: string; text: string }> = [];

		for (const entry of entries) {
			if (entry.type !== "message") continue;
			if (entry.message.role !== "user") continue;

			const text = this.#extractUserMessageText(entry.message.content);
			if (text) {
				result.push({ entryId: entry.id, text });
			}
		}

		return result;
	}

	#extractUserMessageText(content: string | Array<{ type: string; text?: string }>): string {
		if (typeof content === "string") return content;
		if (Array.isArray(content)) {
			return content
				.filter((c): c is { type: "text"; text: string } => c.type === "text")
				.map(c => c.text)
				.join("");
		}
		return "";
	}

	/** Image parts of a stored user request, in submission order — index N-1 backs the
	 *  `[Image #N]` marker in the message text, so restoring them alongside the text keeps
	 *  positional markers resolvable on resubmit. */
	#extractUserMessageImages(content: UserMessage["content"] | CustomMessage["content"]): ImageContent[] {
		if (!Array.isArray(content)) return [];
		return content.filter((c): c is ImageContent => c.type === "image");
	}

	/**
	 * Get session statistics.
	 */
	getSessionStats(): SessionStats {
		return this.#stats.getSessionStats();
	}

	#goalUsage(): GoalTokenUsage {
		const { input, output, cacheRead, cacheWrite } = this.#stats.getTokenTotals();
		return { input, output, cacheRead, cacheWrite };
	}

	/**
	 * Get current context usage statistics.
	 * Uses the last assistant message's usage data when available,
	 * otherwise estimates tokens for all messages.
	 */
	getContextBreakdown(options?: {
		contextWindow?: number;
		pendingMessages?: AgentMessage[];
	}): ContextUsageBreakdown | undefined {
		return this.#stats.getContextBreakdown(options);
	}

	getContextUsage(options?: { contextWindow?: number }): ContextUsage | undefined {
		return this.#stats.getContextUsage(options);
	}

	/**
	 * Monotonic counter that changes whenever the in-flight pending context
	 * snapshot is set or cleared. Status-line context memoization keys on this so
	 * a value computed mid-turn cannot persist after the turn ends/aborts.
	 */
	get contextUsageRevision(): number {
		return this.#stats.revision;
	}

	async fetchUsageReports(signal?: AbortSignal): Promise<UsageReport[] | null> {
		const authStorage = this.#modelRegistry.authStorage;
		if (!authStorage.usage.reports) return null;
		const reports = await authStorage.usage.reports({
			baseUrlResolver: provider => {
				if (provider === "google-antigravity") {
					const mode = cfgProvidersAntigravityEndpoint.get(this.settings);
					if (mode === "sandbox") {
						return "https://daily-cloudcode-pa.sandbox.googleapis.com";
					} else if (mode === "production") {
						return "https://daily-cloudcode-pa.googleapis.com";
					}
				}
				return this.#modelRegistry.getProviderBaseUrl?.(provider);
			},
			signal,
		});
		// Every fresh usage snapshot doubles as the salvage-sweep heartbeat: the
		// status line calls this every 5 minutes while the TUI is open.
		if (reports) {
			this.#usageReports = reports;
			this.#maybeScheduleResetSweep(reports);
		}
		return reports;
	}

	/** The newest usage snapshot, available without a network call. */
	get cachedUsageReports(): UsageReport[] | undefined {
		return this.#usageReports;
	}

	/** Models whose live `/usage` reports map to a quantitative provider scope. */
	getUsageReportingModelSelectors(reports: readonly UsageReport[]): string[] {
		const modelsByProvider = new Map<string, Model[]>();
		for (const model of this.#modelRegistry.getAvailable()) {
			const models = modelsByProvider.get(model.provider) ?? [];
			models.push(model);
			modelsByProvider.set(model.provider, models);
		}
		const selectors = new Set<string>();
		for (const [provider, models] of modelsByProvider) {
			const modelIds = this.#modelRegistry.authStorage.usage.reportingModelIds(
				provider,
				models.map(model => model.id),
				reports,
			);
			for (const modelId of modelIds) selectors.add(`${provider}/${modelId}`);
		}
		return [...selectors].sort((left, right) => left.localeCompare(right));
	}

	/** List stored OAuth accounts for the current model provider and mark this session's active account. */
	async listCurrentProviderOAuthAccounts(): Promise<SessionOAuthAccountList | undefined> {
		const provider = this.model?.provider;
		if (!provider) return undefined;
		const authStorage = this.#modelRegistry.authStorage;
		await authStorage.credentials.reload();
		return {
			provider,
			accounts: authStorage.oauth.accounts(provider, this.sessionId),
		};
	}

	/**
	 * Pin a stored OAuth account to the current model provider for this session.
	 * Returns false while streaming or when the credential is no longer available.
	 */
	pinCurrentProviderOAuthAccount(credentialId: number): boolean {
		const provider = this.model?.provider;
		if (!provider || this.isStreaming) return false;
		return this.#modelRegistry.authStorage.sessions.pin(provider, this.sessionId, credentialId);
	}

	/**
	 * Redeem one provider-selected saved rate-limit reset for an exact stored
	 * credential. Never throws for business outcomes — inspect `code`.
	 */
	async redeemResetCredit(target: ResetCreditTarget, signal?: AbortSignal): Promise<ResetCreditRedeemOutcome> {
		return this.#modelRegistry.authStorage.resets.redeem({
			target,
			baseUrlResolver: provider => this.#modelRegistry.getProviderBaseUrl?.(provider),
			signal,
		});
	}

	/**
	 * List live saved-reset eligibility. An explicit provider lists only that
	 * provider; the public default aggregates Codex and Claude independently.
	 */
	async listResetCredits(signal?: AbortSignal, provider?: string): Promise<ResetCreditAccountStatus[]> {
		const options = {
			sessionId: this.sessionId,
			baseUrlResolver: (candidate: string) => this.#modelRegistry.getProviderBaseUrl?.(candidate),
			signal,
		};
		if (provider) {
			return this.#modelRegistry.authStorage.resets.list({ ...options, provider });
		}
		const [codex, claude] = await Promise.all([
			this.#modelRegistry.authStorage.resets.list({ ...options, provider: "openai-codex" }),
			this.#modelRegistry.authStorage.resets.list({ ...options, provider: "anthropic" }),
		]);
		return [...codex, ...claude];
	}
	/**
	 * Ask before spending resets whose governing window is unset and return the
	 * confirmed actions. The answer is saved to every governing window key still
	 * unset (both chat windows when the window is unknown). A host that cannot
	 * prompt (no extension UI, or one whose prompts cannot reach a human) spends
	 * nothing and gets a one-shot notice instead.
	 */
	async #confirmAutoRedeem(
		provider: "openai-codex" | "anthropic",
		actions: (CodexResetAction | ClaudeResetAction)[],
		coordinator: CodexAutoRedeemCoordinator,
	): Promise<readonly (CodexResetAction | ClaudeResetAction)[]> {
		if (actions.length === 0) return [];
		const providerLabel = provider === "anthropic" ? "Claude" : "Codex";
		const source = provider === "anthropic" ? "claude-auto-reset" : "codex-auto-reset";
		const windowSettings = resetWindowSettings[provider];
		const keys = [
			...new Set(
				actions.flatMap(action =>
					(action.window ? [action.window] : (["5h", "weekly"] as const)).flatMap(
						window => windowSettings[window] ?? [],
					),
				),
			),
		];
		const keyList = keys.map(key => key.id).join(", ");
		const runner = this.#extensionRunner;
		if (!runner?.hasUI() || !this.#interactivePrompts) {
			if (!coordinator.notifiedKeys.has(actions[0].attemptKey)) {
				coordinator.notifiedKeys.add(actions[0].attemptKey);
				this.emitNotice(
					"warning",
					`Saved ${providerLabel} resets are eligible to spend, but auto-redeem is unset and no prompt UI is available. Run \`/usage reset\` or set ${keyList}.`,
					source,
				);
			}
			return [];
		}

		const lines = actions.map(action => {
			if (!("program" in action)) {
				const codex = action;
				return codex.reason === "blocked-account"
					? `${codex.label} is blocked by the Codex ${(codex.blockedWindows ?? []).join(" + ") || "usage"} limit for about ${formatDuration(codex.remainingMs ?? 0)}.`
					: `${codex.label}: a saved reset expires in ${formatDuration(codex.expiresInMs ?? 0)} (${codex.salvageWindow ?? "weekly"} window ${Math.round((codex.salvageUsedFraction ?? codex.weeklyUsedFraction ?? 0) * 100)}% used).`;
			}
			const claude = action;
			const grant = claude.program === "juniper_tide" ? "5h session-only reset" : (claude.title ?? "saved reset");
			const early = claude.requiresLimit
				? ""
				: " This grant permits early use before the covered window is fully blocked.";
			return claude.reason === "blocked-account"
				? `${claude.label}: ${grant} covers ${(claude.blockedWindows ?? []).map(formatUsageResetWindow).join(" + ")} with about ${formatDuration(claude.remainingMs ?? 0)} left.${early}`
				: `${claude.label}: ${grant} expires in ${formatDuration(claude.expiresInMs ?? 0)}; ${formatUsageResetWindow(claude.salvageWindow ?? "")} is ${Math.round((claude.salvageUsedFraction ?? 0) * 100)}% used.${early}`;
		});
		const question =
			actions.length === 1
				? `Spend a saved ${providerLabel} rate-limit reset?\n${lines[0]}`
				: `Spend ${actions.length} saved ${providerLabel} rate-limit resets?\n${lines.join("\n")}`;
		try {
			const choice = await runner.getUIContext().select(question, [
				{ label: "Yes", description: `Redeem now and set ${keyList} to yes.` },
				{ label: "No", description: `Do not redeem, and set ${keyList} to no.` },
			]);
			if (choice === "Yes" || choice === "No") {
				for (const key of keys) {
					if (key.get(this.settings) === "unset") key.set(this.settings, choice === "Yes" ? "yes" : "no");
				}
				if (choice === "Yes") return actions;
			}
		} catch (error) {
			logger.warn(`${source} prompt failed`, { error: String(error) });
		}
		return [];
	}

	/** Spend what each governing window allows outright, then ask about the unset ones. */
	async #redeemConsentedResets(
		provider: "openai-codex" | "anthropic",
		actions: (CodexResetAction | ClaudeResetAction)[],
		coordinator: CodexAutoRedeemCoordinator,
	): Promise<{ restoredCredentialIds: number[]; poolLimited: boolean }> {
		const modes = resetWindowModes(provider, this.settings);
		const approved = actions.filter(action => resetWindowMode(modes, action.window) === "yes");
		const spent = await this.#executeResetActions(provider, approved, coordinator);
		const unset = actions.filter(action => resetWindowMode(modes, action.window) === "unset");
		const confirmed = await this.#confirmAutoRedeem(provider, unset, coordinator);
		if (confirmed.length === 0) return spent;
		const consented = await this.#executeResetActions(provider, confirmed, coordinator);
		return {
			restoredCredentialIds: [...spent.restoredCredentialIds, ...consented.restoredCredentialIds],
			poolLimited: spent.poolLimited || consented.poolLimited,
		};
	}

	#planCodexResets(
		trigger: CodexResetTrigger,
		reports: UsageReport[] | null,
		identity: OAuthAccountIdentity | undefined,
		coordinator: CodexAutoRedeemCoordinator,
		activeBlockUnblockAtMs?: number,
	): CodexResetPlan {
		const cfg = cfgCodexResets.get(this.settings);
		const model = this.model;
		const plan = planCodexResetRedemptions({
			nowMs: Date.now(),
			trigger,
			provider: model?.provider ?? "",
			modelId: model?.id ?? "",
			settings: resetPlanSettings(resetWindowModes("openai-codex", this.settings), cfg),
			identity,
			permitsCredential: credentialId =>
				this.#modelRegistry.authStorage.sessions.permits("openai-codex", this.sessionId, credentialId),
			reports,
			attemptedKeys: coordinator.attemptedKeys,
			deferredUntilByKey: coordinator.deferredUntilByKey,
			lastAttemptAtByAccount: coordinator.lastAttemptAtByAccount,
			activeBlockUnblockAtMs,
		});
		if (plan.skipped.length > 0) {
			logger.debug("codex-auto-reset: plan", { trigger, actions: plan.actions.length, skipped: plan.skipped });
		}
		return plan;
	}

	#planClaudeResets(
		trigger: CodexResetTrigger,
		reports: UsageReport[] | null,
		statuses: readonly ResetCreditAccountStatus[],
		coordinator: CodexAutoRedeemCoordinator,
		activeBlockUnblockAtMs?: number,
	): ClaudeResetPlan {
		const cfg = cfgClaudeResets.get(this.settings);
		const model = this.model;
		const plan = planClaudeResetRedemptions({
			nowMs: Date.now(),
			trigger,
			provider: model?.provider ?? "",
			modelId: model?.provider === "anthropic" ? model.id : "",
			settings: resetPlanSettings(resetWindowModes("anthropic", this.settings), cfg),
			reports,
			statuses,
			permitsCredential: credentialId =>
				this.#modelRegistry.authStorage.sessions.permits("anthropic", this.sessionId, credentialId),
			attemptedKeys: coordinator.attemptedKeys,
			deferredUntilByKey: coordinator.deferredUntilByKey,
			lastAttemptAtByAccount: coordinator.lastAttemptAtByAccount,
			activeBlockUnblockAtMs,
		});
		if (plan.skipped.length > 0) {
			logger.debug("claude-auto-reset: plan", { trigger, actions: plan.actions.length, skipped: plan.skipped });
		}
		return plan;
	}

	#adoptResetMarker(lockKey: string, marker: { state: string; atMs: number }): boolean {
		if (
			marker.state !== "reset" ||
			!Number.isFinite(marker.atMs) ||
			Date.now() - marker.atMs >= ATTEMPT_COOLDOWN_MS ||
			marker.atMs <= (this.#adoptedResetMarkers.get(lockKey) ?? 0)
		) {
			return false;
		}
		this.#adoptedResetMarkers.set(lockKey, marker.atMs);
		return true;
	}

	async #adoptRecentReset(
		statuses: readonly ResetCreditAccountStatus[],
		coordinator: CodexAutoRedeemCoordinator,
	): Promise<number | undefined> {
		for (const status of statuses) {
			if (status.provider !== this.model?.provider) continue;
			// A peer's reset of an account outside the session's pool cannot serve its retry.
			if (!this.#modelRegistry.authStorage.sessions.permits(status.provider, this.sessionId, status.credentialId)) {
				continue;
			}
			const lockKey = resetAccountLockKey(status);
			if (!lockKey) continue;
			const lockPath = resetLockPath(lockKey, coordinator.resetLockPath);
			await fs.promises.mkdir(path.dirname(lockPath), { recursive: true });
			const adopted = await withFileLock(
				lockPath,
				async () => this.#adoptResetMarker(lockKey, await readResetMarker(lockPath)),
				{ retries: 300, retryDelayMs: 100 },
			);
			if (adopted) {
				await this.#modelRegistry.authStorage.credentials.revalidate();
				return status.credentialId;
			}
		}
		return undefined;
	}

	/**
	 * Shared consume executor for Codex and Claude plans. Attempt keys enter the
	 * process-wide set before mutation, while nonterminal outcomes release and
	 * defer the episode so a still-banked grant is not buried permanently.
	 * Returns the credentials whose reset was spent or adopted from a peer, and
	 * whether the session's account pool dropped a planned restore.
	 */
	async #executeResetActions(
		provider: "openai-codex" | "anthropic",
		actions: readonly (CodexResetAction | ClaudeResetAction)[],
		coordinator: CodexAutoRedeemCoordinator,
	): Promise<{ restoredCredentialIds: number[]; poolLimited: boolean }> {
		const authStorage = this.#modelRegistry.authStorage;
		const providerLabel = provider === "anthropic" ? "Claude" : "Codex";
		const source = provider === "anthropic" ? "claude-auto-reset" : "codex-auto-reset";
		// Consent, earlier actions, the fence and the live listing all wait after
		// planning: a restore the session's account pool no longer allows is dropped.
		// Checked with no await before the redeem call.
		const outsidePool = (action: CodexResetAction | ClaudeResetAction): boolean =>
			action.reason === "blocked-account" &&
			!authStorage.sessions.permits(provider, this.sessionId, action.target.credentialId);
		const restored: number[] = [];
		let poolLimited = false;
		for (const action of actions) {
			if (coordinator.attemptedKeys.has(action.attemptKey)) continue;
			const previousAttemptAt = coordinator.lastAttemptAtByAccount.get(action.accountKey);
			coordinator.attemptedKeys.add(action.attemptKey);
			coordinator.lastAttemptAtByAccount.set(action.accountKey, Date.now());
			let outcome: ResetCreditRedeemOutcome | undefined;
			let sharedReset = false;
			let leftPool = false;
			try {
				const redeemOptions = {
					target: action.target,
					baseUrlResolver: (candidate: string) => this.#modelRegistry.getProviderBaseUrl?.(candidate),
					// Caller cancellation must not leave an ambiguous consume in flight.
					signal: AbortSignal.timeout(15_000),
				};
				const lockKey = resetAccountLockKey(action.target);
				if (!lockKey) {
					// An account without an upstream identity cannot share a cross-process fence.
					leftPool = outsidePool(action);
					if (!leftPool) outcome = await authStorage.resets.redeem(redeemOptions);
				} else {
					// The coordinator is process-local. Fence concurrent processes and
					// remember a recent attempt so a late 429 cannot spend again.
					outcome = await withResetFence<ResetCreditRedeemOutcome | undefined>(
						resetLockPath(lockKey, coordinator.resetLockPath),
						async marker => {
							sharedReset = this.#adoptResetMarker(lockKey, marker);
							if (sharedReset) await authStorage.credentials.revalidate();
							return undefined;
						},
						async markedRedeem => {
							// Claude's redeem revalidates its exact offer. Codex needs its
							// balance rechecked after acquiring the cross-process fence.
							if (provider === "openai-codex") {
								const statuses = await this.listResetCredits(AbortSignal.timeout(10_000), provider);
								const balance = checkCodexBalance(statuses, action.target.credentialId, action.availableCount);
								if (balance === "spent") return undefined;
								if (balance) return { ok: false, code: balance, provider } satisfies ResetCreditRedeemOutcome;
							}
							const { outcome: result, attemptedAt } = await markedRedeem(async () => {
								// Checked after the pending marker is written, with no await before
								// the redeem. A restore the pool no longer allows is never sent:
								// report a no-op so the fence clears its marker, and drop it below.
								leftPool = outsidePool(action);
								if (leftPool) return { ok: false, code: "nothing_to_reset", provider };
								return authStorage.resets.redeem(redeemOptions);
							});
							if (leftPool) return undefined;
							if (result.code === "reset") this.#adoptedResetMarkers.set(lockKey, attemptedAt);
							return result;
						},
					);
				}
			} catch (error) {
				coordinator.attemptedKeys.delete(action.attemptKey);
				coordinator.deferredUntilByKey.set(action.attemptKey, Date.now() + REDEEM_RETRY_DEFER_MS);
				logger.warn(`${source}: redeem threw, deferred`, {
					account: action.accountKey,
					error: String(error),
				});
				continue;
			}
			if (!outcome) {
				if (sharedReset) restored.push(action.target.credentialId);
				if (leftPool) {
					// Never attempted: the episode and cooldown stay free if the pool allows it again.
					poolLimited = true;
					coordinator.attemptedKeys.delete(action.attemptKey);
					if (previousAttemptAt === undefined) coordinator.lastAttemptAtByAccount.delete(action.accountKey);
					else coordinator.lastAttemptAtByAccount.set(action.accountKey, previousAttemptAt);
					logger.debug(`${source}: restore dropped, account left the session's pool`, {
						account: action.accountKey,
					});
				}
				continue;
			}
			if (!isTerminalRedeemOutcome(outcome.code)) {
				coordinator.attemptedKeys.delete(action.attemptKey);
				coordinator.deferredUntilByKey.set(action.attemptKey, Date.now() + REDEEM_RETRY_DEFER_MS);
			}
			switch (outcome.code) {
				case "reset": {
					restored.push(action.target.credentialId);
					const left =
						action.availableCount === undefined ? undefined : ` (${Math.max(0, action.availableCount - 1)} left)`;
					const detail =
						action.reason === "expiring-credit"
							? `it was set to expire in ${formatDuration(action.expiresInMs ?? 0)}`
							: outcome.cleared?.length
								? `cleared ${outcome.cleared.map(formatUsageResetWindow).join(" + ")}; retrying now`
								: "retrying now";
					this.emitNotice(
						"info",
						`Auto-redeemed a saved ${providerLabel} rate-limit reset for ${action.label}${left ?? ""}; ${detail}.`,
						source,
					);
					break;
				}
				case "already_redeemed":
					this.emitNotice(
						"warning",
						`A saved ${providerLabel} reset for ${action.label} was already redeemed elsewhere.`,
						source,
					);
					break;
				case "no_credit":
					logger.debug(`${source}: no_credit (snapshot/live mismatch)`, { account: action.accountKey });
					break;
				case "nothing_to_reset":
					if (action.reason === "blocked-account") {
						this.emitNotice(
							"warning",
							`${providerLabel} reset for ${action.label} reported nothing to reset; will retry later.`,
							source,
						);
					} else {
						logger.debug(`${source}: nothing_to_reset deferred`, { account: action.accountKey });
					}
					break;
				default:
					if (action.reason === "blocked-account") {
						this.emitNotice(
							"warning",
							`${providerLabel} auto-redeem for ${action.label} failed (${outcome.code}); will retry later.`,
							source,
						);
					} else {
						logger.warn(`${source}: consume failed, deferred`, {
							account: action.accountKey,
							code: outcome.code,
						});
					}
					break;
			}
		}
		if (restored.length > 0) void this.fetchUsageReports();
		return { restoredCredentialIds: restored, poolLimited };
	}

	async #maybeAutoRedeemReset(activeBlockUnblockAtMs?: number): Promise<ResetRecoveryResult> {
		const provider = this.model?.provider;
		if (provider !== "anthropic" && provider !== "openai-codex") return { restored: false };
		const modes = resetWindowModes(provider, this.settings);
		if (!resetWindowsEnabled(modes)) return { restored: false };
		const coordinator = this.#resetCoordinator;
		const authStorage = this.#modelRegistry.authStorage;
		const identity = authStorage.oauth.identity(provider, this.sessionId);
		const identityValue = (identity?.accountId ?? identity?.email ?? identity?.orgId)?.trim().toLowerCase();
		if (!identityValue) return { restored: false };
		const accountKey = `${provider}|${identity?.orgId?.trim().toLowerCase() ?? "-"}|${identityValue}`;
		// A pass plans within its own session's account pool. A session joining it
		// keeps its outcome only if the pass restored an account this session may
		// use, or restored nothing without its pool excluding a candidate.
		let existing = coordinator.inFlightByAccount.get(accountKey);
		while (existing) {
			const shared = await existing;
			const serves = shared.restored
				? shared.restoredCredentialIds?.some(id => authStorage.sessions.permits(provider, this.sessionId, id))
				: !shared.poolLimited;
			if (serves) return shared;
			existing = coordinator.inFlightByAccount.get(accountKey);
		}

		const run = (async (): Promise<ResetRecoveryResult> => {
			let reports: UsageReport[] | null = null;
			if (provider === "openai-codex") {
				await authStorage.usage.invalidate(provider);
				reports = await this.fetchUsageReports();
			}
			// Claude's live reset listing includes the same response's quota
			// windows; a second broker usage poll adds no evidence and can 429.
			const statuses = await this.listResetCredits(AbortSignal.timeout(10_000), provider);
			const plan =
				provider === "anthropic"
					? this.#planClaudeResets("blocked", reports, statuses, coordinator, activeBlockUnblockAtMs)
					: this.#planCodexResets(
							"blocked",
							overlayLiveResetCredits(reports, statuses, { synthesizeActive: true, nowMs: Date.now() }),
							identity,
							coordinator,
							activeBlockUnblockAtMs,
						);
			const poolLimited = plan.skipped.some(skip => skip.reason === "outside-account-pool");
			if (plan.actions.length === 0) {
				const adoptedId = await this.#adoptRecentReset(statuses, coordinator);
				if (adoptedId !== undefined) return { restored: true, restoredCredentialIds: [adoptedId] };
				let retryAfterMs: number | undefined;
				if (provider === "anthropic" && Object.values(modes).includes("yes")) {
					for (const status of statuses) {
						if (!status.error || status.retryAfterMs === undefined || !Number.isFinite(status.retryAfterMs))
							continue;
						const delay = Math.max(0, status.retryAfterMs);
						retryAfterMs = retryAfterMs === undefined ? delay : Math.min(retryAfterMs, delay);
					}
				}
				return { restored: false, retryAfterMs, poolLimited };
			}
			const executed = await this.#redeemConsentedResets(provider, plan.actions, coordinator);
			return {
				restored: executed.restoredCredentialIds.length > 0,
				restoredCredentialIds: executed.restoredCredentialIds,
				poolLimited: poolLimited || executed.poolLimited,
			};
		})()
			.catch((error): ResetRecoveryResult => {
				logger.warn("auto-reset: blocked pass failed", { provider, account: accountKey, error: String(error) });
				return { restored: false };
			})
			.finally(() => coordinator.inFlightByAccount.delete(accountKey));
		coordinator.inFlightByAccount.set(accountKey, run);
		return run;
	}

	/**
	 * One process-wide salvage sweep handles both providers, but plans and asks
	 * consent independently. Last-chance expiry checks remain active even with
	 * the broader salvage horizon disabled. Every candidate is refreshed through
	 * its live listing before spend; a failed listing cannot fall back to stale usage.
	 * Claude finds its candidates in the usage reports' reset inventory first, so a
	 * sweep with nothing to salvage lists no Claude account.
	 */
	#maybeScheduleResetSweep(reports: UsageReport[]): void {
		const coordinator = this.#resetCoordinator;
		const codexEnabled =
			resetWindowsEnabled(resetWindowModes("openai-codex", this.settings)) &&
			reports.some(report => report.provider === "openai-codex");
		const claudeEnabled =
			resetWindowsEnabled(resetWindowModes("anthropic", this.settings)) &&
			reports.some(report => report.provider === "anthropic");
		if (!codexEnabled && !claudeEnabled) return;
		if (coordinator.sweepInFlight || coordinator.inFlightByAccount.size > 0) return;
		const now = Date.now();
		if (now - coordinator.lastSweepAt < SWEEP_MIN_INTERVAL_MS) return;
		coordinator.sweepInFlight = true;
		coordinator.lastSweepAt = now;
		coordinator.sweepPromise = (async () => {
			if (codexEnabled) {
				try {
					const statuses = await this.listResetCredits(AbortSignal.timeout(10_000), "openai-codex");
					const effectiveReports = overlayLiveResetCredits(reports, statuses);
					const identity = this.#modelRegistry.authStorage.oauth.identity("openai-codex", this.sessionId);
					const plan = this.#planCodexResets("sweep", effectiveReports, identity, coordinator);
					await this.#redeemConsentedResets("openai-codex", plan.actions, coordinator);
				} catch (error) {
					logger.warn("codex-auto-reset: salvage listing failed", { error: String(error) });
				}
			}
			if (claudeEnabled) {
				try {
					const accounts = this.#modelRegistry.authStorage.oauth.accounts("anthropic", this.sessionId);
					const candidates = this.#planClaudeResets(
						"sweep",
						reports,
						claudeResetStatusesFromReports(accounts, reports),
						coordinator,
					);
					const plan =
						candidates.actions.length > 0
							? this.#planClaudeResets(
									"sweep",
									reports,
									await this.listResetCredits(AbortSignal.timeout(10_000), "anthropic"),
									coordinator,
								)
							: candidates;
					if (plan.actions.length > 0) {
						await this.#redeemConsentedResets("anthropic", plan.actions, coordinator);
					}
				} catch (error) {
					logger.warn("claude-auto-reset: salvage listing failed", { error: String(error) });
				}
			}
		})()
			.catch(error => logger.warn("reset salvage sweep failed", { error: String(error) }))
			.finally(() => {
				coordinator.sweepInFlight = false;
			});
	}

	/**
	 * Export session to HTML.
	 * @param outputPath Optional output path
	 * @param useUserThemes Bundle the dark and light TUI themes selected in settings
	 */
	async exportToHtml(outputPath?: string, useUserThemes = false): Promise<string> {
		// Lazy import: the export module embeds the HTML template and pre-built
		// tool renderers as text; only `/export` should pay that load.
		const { exportSessionToHtml } = await import("../export/html");
		return exportSessionToHtml(this.sessionManager, this.state, {
			outputPath,
			palette: useUserThemes ? "theme" : "web",
			themeNames: useUserThemes
				? {
						dark: cfgThemeDark.get(this.settings),
						light: cfgThemeLight.get(this.settings),
					}
				: undefined,
		});
	}

	// =========================================================================
	// Utilities
	// =========================================================================

	/**
	 * Get text content of last assistant message.
	 * Consumed by the `/copy` command and the RPC `get_last_assistant_text` request.
	 * @returns Trimmed text content, or undefined if no assistant message has text
	 */
	getLastAssistantText(): string | undefined {
		const lastAssistant = this.#getLastCopyCandidateAssistantMessage();
		if (!lastAssistant) return undefined;

		let text = "";
		for (const content of lastAssistant.content) {
			if (content.type === "text") {
				text += content.text;
			}
		}

		return text.trim() || undefined;
	}

	hasCopyCandidateAssistantMessage(): boolean {
		return this.#getLastCopyCandidateAssistantMessage() !== undefined;
	}

	#getLastCopyCandidateAssistantMessage(): AssistantMessage | undefined {
		for (let i = this.messages.length - 1; i >= 0; i--) {
			const message = this.messages[i];
			if (message.role !== "assistant") continue;

			const assistantMessage = message as AssistantMessage;
			// Skip aborted messages with no content
			if (assistantMessage.stopReason === "aborted" && assistantMessage.content.length === 0) continue;

			return assistantMessage;
		}

		return undefined;
	}
	/**
	 * Get text content of the most recent visible handoff message.
	 * Sessions created by older versions injected the handoff document as a
	 * custom message at the top of a fresh session; callers that copy the
	 * "last" message use this as a fallback while no assistant response exists.
	 */
	getLastVisibleHandoffText(): string | undefined {
		for (let i = this.messages.length - 1; i >= 0; i--) {
			const message = this.messages[i];
			if (message.role !== "custom") continue;

			const customMessage = message as CustomMessage;
			if (customMessage.customType !== "handoff" || !customMessage.display) continue;

			if (typeof customMessage.content === "string") {
				return customMessage.content.trim() || undefined;
			}

			let text = "";
			for (const content of customMessage.content) {
				if (content.type === "text") {
					text += content.text;
				}
			}
			return text.trim() || undefined;
		}

		return undefined;
	}

	/**
	 * Format the entire session as plain text for clipboard export: system
	 * prompt, model/thinking config, tool inventory, and the full transcript
	 * rendered with markdown role headings (`## User`, `## Assistant`,
	 * `### Tool Call`/`### Tool Result`).
	 */
	formatSessionAsText(): string {
		return formatSessionDumpText({
			messages: this.messages,
			systemPrompt: this.agent.state.systemPrompt,
			model: this.agent.state.model,
			thinkingLevel: this.thinkingLevel,
			tools: this.agent.state.tools,
			inlineToolDescriptors: this.agent.pruneToolDescriptions,
		});
	}

	/**
	 * Write `/dump all` to an auto-named zip in `os.tmpdir()`: `session.md` (the
	 * {@link formatSessionAsText} transcript), `llm-request.json` (the
	 * {@link dumpLlmRequestToTmpDir} payload), and one `subagents/<path>.md` per
	 * persisted subagent transcript stored next to the session file, nested
	 * subagents included. Subagents still live in this process also carry their
	 * registry status, last activity, pending tool calls, and the in-flight
	 * assistant turn that is not persisted yet. Subagents with no messages and
	 * no in-flight turn are skipped. A subagent discovery failure still writes
	 * the main dump and is reported in `subagentError`.
	 *
	 * The archive persists on disk and may contain raw context/secrets.
	 *
	 * @returns the archive path and member names, or `undefined` when the main
	 * session has no messages.
	 */
	async dumpSessionArchiveToTmpDir(): Promise<SessionDumpArchive | undefined> {
		const messages = this.messages;
		if (messages.length === 0) return undefined;
		const entries: Array<readonly [string, string]> = [["session.md", `${this.formatSessionAsText()}\n`]];
		try {
			entries.push(["llm-request.json", await this.#formatLlmRequestJson(messages)]);
		} catch (error) {
			// Best-effort like the `/dump` sidecar: the transcripts are still archived.
			logger.warn("Failed to build LLM request JSON for dump", { error: String(error) });
		}
		const sessionFile = this.sessionManager.getSessionFile();
		let subSessions: Record<string, SubSession> = {};
		let subagentError: string | undefined;
		try {
			if (sessionFile) subSessions = await collectSubSessions(sessionFile);
		} catch (error) {
			subagentError = error instanceof Error ? error.message : String(error);
			logger.warn("Failed to collect subagent transcripts for dump", { sessionFile, error: subagentError });
		}
		const liveByFile = new Map<string, AgentRef>();
		for (const ref of AgentRegistry.global().list()) {
			if (ref.session && ref.sessionFile) liveByFile.set(path.resolve(ref.sessionFile), ref);
		}
		const subagentRoot = sessionFile?.endsWith(".jsonl") ? sessionFile.slice(0, -6) : undefined;
		let subagentCount = 0;
		for (const [key, sub] of Object.entries(subSessions)) {
			const context = deobfuscateSessionContext(buildSessionContext(sub.entries, sub.leafId), this.#obfuscator);
			const liveRef = subagentRoot
				? liveByFile.get(path.resolve(path.join(subagentRoot, ...key.split("/")) + ".jsonl"))
				: undefined;
			const live = liveRef ? captureLiveDumpState(liveRef) : undefined;
			if (context.messages.length === 0 && !live?.streamMessage) continue;
			const text = formatSubagentDumpText({
				key,
				messages: context.messages,
				model: context.models.default,
				thinkingLevel: context.thinkingLevel,
				aborted: sub.aborted,
				live,
			});
			entries.push([`subagents/${key}.md`, `${text}\n`]);
			subagentCount++;
		}
		const filePath = path.join(os.tmpdir(), `omp-dump-${Snowflake.next()}.zip`);
		await writeArchive(filePath, "zip", entries);
		return { path: filePath, files: entries.map(([name]) => name), subagentCount, subagentError };
	}

	/**
	 * Write `/dump anon` to an auto-named zip in `os.tmpdir()`: `session.jsonl`
	 * and one `subagents/<path>.jsonl` per persisted subagent, anonymized with one
	 * shared token table (see {@link anonymizeSessionTranscripts}).
	 *
	 * @returns the archive path and member names, or `undefined` when the main
	 * session has no messages.
	 */
	async dumpAnonymizedArchiveToTmpDir(): Promise<SessionDumpArchive | undefined> {
		if (this.messages.length === 0) return undefined;
		const result = await anonymizeSessionTranscripts({
			header: this.sessionManager.getHeader(),
			entries: this.sessionManager.getEntries(),
			sessionFile: this.sessionManager.getSessionFile(),
			malformedRecords: this.sessionManager.loadedMalformedRecords,
		});
		const filePath = path.join(os.tmpdir(), `omp-dump-anon-${Snowflake.next()}.zip`);
		await writeArchive(filePath, "zip", result.files);
		return {
			path: filePath,
			files: result.files.map(([name]) => name),
			subagentCount: result.subagentCount,
			subagentError: result.subagentError,
			anonymized: true,
			malformed: result.malformed,
			unreadable: result.unreadable,
		};
	}

	/**
	 * Dump the current session's LLM-facing request context as JSON to a
	 * auto-named file in `os.tmpdir()`. This is the synchronous
	 * `convertToLlm`-boundary snapshot — system prompt, tools (wire schemas),
	 * thinking/service tier, and converted messages — with no network round-trip
	 * and no arming flag, so advisor/side requests cannot intercept it.
	 *
	 * The file persists on disk and may contain the same raw context/secrets
	 * as `/dump`; treat the path accordingly.
	 *
	 * @returns the written file path, or `undefined` when there are no messages.
	 */
	async dumpLlmRequestToTmpDir(): Promise<string | undefined> {
		const messages = this.messages;
		if (messages.length === 0) return undefined;
		const filePath = path.join(os.tmpdir(), `omp-llm-request-${Snowflake.next()}.json`);
		await Bun.write(filePath, await this.#formatLlmRequestJson(messages));
		return filePath;
	}

	async #formatLlmRequestJson(messages: AgentMessage[]): Promise<string> {
		const llmMessages = await this.convertMessagesToLlm(messages);
		const payload = {
			model: this.agent.state.model ?? null,
			thinkingLevel: this.thinkingLevel ?? null,
			serviceTier: this.#models.serviceTierEntry(),
			systemPrompt: this.agent.state.systemPrompt,
			tools: this.agent.state.tools.map(tool => ({
				name: tool.name,
				description: tool.description,
				parameters: toolWireSchema(tool),
				...(tool.strict !== undefined ? { strict: tool.strict } : {}),
				...(tool.customWireName ? { customWireName: tool.customWireName } : {}),
			})),
			messages: llmMessages,
		};
		return `${JSON.stringify(payload, null, 2)}\n`;
	}

	/**
	 * Enable or disable the advisor for this session. The setting is overridden for the session,
	 * and the runtime is started or stopped to match.
	 *
	 * @returns true when the advisor is actively running after the call.
	 */
	setAdvisorEnabled(enabled: boolean): boolean {
		return this.#advisors.setAdvisorEnabled(enabled);
	}

	/**
	 * Reactivate an advisor that resolved to `no_model` at construction because a
	 * discovery-backed provider had not populated the model registry yet. Awaits
	 * the initial background refresh, then rebuilds the advisor and emits
	 * `model_changed` so the status line reflects the now-active advisor. See #9010.
	 */
	async #retryInactiveAdvisorAfterModelDiscovery(): Promise<void> {
		if (this.#isDisposed || !this.#advisors.hasInactiveNoModelAdvisor()) return;
		await this.#modelRegistry.awaitInitialBackgroundRefresh(this.#modelDiscoveryAbortController.signal);
		if (this.#isDisposed) return;
		if (this.#advisors.retryAfterModelDiscovery()) this.#emit({ type: "model_changed" });
	}

	/**
	 * Run the retry.fallbackChains validation a `deferRetryFallbackValidation`
	 * session skipped at construction. Validation composes the catalog slice of
	 * every provider a chain names, so interactive startup runs it after the
	 * first frame; the header picks the warnings up via `config_warnings_changed`.
	 */
	validateRetryFallbackChains(): void {
		if (this.#isDisposed || !this.#fallbackChainValidationDeferred) return;
		this.#fallbackChainValidationDeferred = false;
		const warningCount = this.configWarnings.length;
		this.#recovery.validateRetryFallbackChains();
		if (this.configWarnings.length !== warningCount) this.#emit({ type: "config_warnings_changed" });
		void this.#revalidateFallbackChainsAfterModelDiscovery();
	}

	/**
	 * Re-run retry.fallbackChains validation once the initial background discovery
	 * settles. Startup validation suppresses "unknown model" warnings for
	 * config-declared discovery providers whose cold cache left the registry empty
	 * (#10048); this retracts the ones discovery resolved and surfaces any that
	 * stayed unknown. Uses {@link ModelRegistry.awaitInitialBackgroundRefresh}
	 * because the CLI starts that refresh right after the session is built, so an
	 * in-flight snapshot taken in the constructor would always miss it.
	 */
	async #revalidateFallbackChainsAfterModelDiscovery(): Promise<void> {
		if (this.#isDisposed || !this.#recovery.hasPendingDiscoveryDeferredFallbackValidation()) return;
		await this.#modelRegistry.awaitInitialBackgroundRefresh(this.#modelDiscoveryAbortController.signal);
		if (this.#isDisposed) return;
		if (this.#recovery.revalidateRetryFallbackChainsAfterDiscovery()) {
			this.#emit({ type: "config_warnings_changed" });
		}
	}

	/**
	 * Move registry warnings produced by the initial background discovery into
	 * {@link configWarnings} so the interactive header shows them. Startup drains
	 * the registry before discovery runs, so a discovery-time warning (an
	 * env-redirected built-in provider failing) would otherwise only be logged.
	 */
	async #surfaceModelRegistryWarningsAfterDiscovery(): Promise<void> {
		if (this.#isDisposed || typeof this.#modelRegistry.awaitInitialBackgroundRefresh !== "function") return;
		await this.#modelRegistry.awaitInitialBackgroundRefresh(this.#modelDiscoveryAbortController.signal);
		if (this.#isDisposed) return;
		const warnings = this.#modelRegistry.drainConfigWarnings();
		if (warnings.length === 0) return;
		this.configWarnings.push(...warnings);
		this.#emit({ type: "config_warnings_changed" });
	}

	/**
	 * Rebind the active model to its refreshed registry entry once the initial
	 * background discovery settles.
	 *
	 * Startup resolves the active model from the pre-discovery catalog snapshot
	 * (`main.ts` fires `refreshInBackground` only after the session is built), so
	 * a discovery-backed provider that re-clamps or splits a selector after the
	 * fact leaves the live model holding stale metadata. GitHub Copilot caps a
	 * tiered base selector (e.g. `github-copilot/gpt-5.6-sol`) to its default-tier
	 * context window and synthesizes a separate `-1m` sibling only during live
	 * discovery; the bundled base entry still carries the full long-context
	 * window, so a fresh session runs with the 1.05M window that contradicts the
	 * 400K catalog value until the user re-selects the same model. Re-look-up the
	 * active selector post-discovery and, when its context window changed, fold
	 * the refreshed spec into the live model. Same selector, so this is a metadata
	 * refresh with no provider-session reset; reconcile model-dependent tools and
	 * append-only state before `model_changed` notifies the status line and RPC
	 * subscribers. Issue #10488.
	 */
	async #rebindActiveModelAfterModelDiscovery(): Promise<void> {
		const boundAtStartup = this.model;
		if (this.#isDisposed || !boundAtStartup) return;
		if (typeof this.#modelRegistry.awaitInitialBackgroundRefresh !== "function") return;
		await this.#modelRegistry.awaitInitialBackgroundRefresh(this.#modelDiscoveryAbortController.signal);
		if (this.#isDisposed) return;
		// Only silently re-metadata the startup-bound selector: bail if the user
		// switched models while discovery was in flight.
		const current = this.model;
		if (!current || !modelsAreEqual(current, boundAtStartup)) return;
		const found = this.#modelRegistry.find(current.provider, current.id);
		const refreshed = found && this.#modelRegistry.fitContextWindow(found, this.settings);
		if (!refreshed || refreshed.contextWindow === current.contextWindow) return;
		this.agent.setModel(refreshed);
		await this.#reconcileModelDependentState(refreshed);
		if (this.#isDisposed) return;
		this.#emit({ type: "model_changed" });
	}

	/**
	 * Toggle the advisor setting and start/stop the runtime accordingly.
	 *
	 * @returns true when the advisor is actively running after the call.
	 */
	toggleAdvisorEnabled(): boolean {
		return this.#advisors.toggleAdvisorEnabled();
	}

	/**
	 * Replace the live advisor roster from an edited `WATCHDOG.yml` (the `/advisor
	 * configure` save path). Swaps the configs + shared baseline, then rebuilds the
	 * runtimes in place so the change applies without a restart. When the advisor is
	 * disabled the new configs are simply stored for the next enable.
	 *
	 * @returns the number of advisors active after the rebuild.
	 */
	applyAdvisorConfigs(
		advisors: AdvisorConfig[],
		sharedInstructions: string | undefined,
		sharedMaxNotesPerUpdate?: number,
	): number {
		return this.#advisors.applyAdvisorConfigs(advisors, sharedInstructions, sharedMaxNotesPerUpdate);
	}

	/**
	 * Refresh the project context prompt advisor sessions run against after
	 * context files change on `/reload-plugins`. Rebuilds live advisor runtimes so
	 * they stop evaluating turns against stale `AGENTS.md` instructions.
	 */
	setAdvisorContextPrompt(contextPrompt: string | undefined): void {
		this.#advisors.setContextPrompt(contextPrompt);
	}

	/**
	 * Refresh the memory backend instructions advisor sessions run against.
	 * Store-only: live advisors pick the new value up at their next runtime
	 * build (compaction, reset, toggle) — see `SessionAdvisors#setMemoryPrompt`.
	 */
	setAdvisorMemoryPrompt(memoryPrompt: string | undefined): void {
		this.#advisors.setMemoryPrompt(memoryPrompt);
	}

	/**
	 * Whether the advisor setting is enabled for this session.
	 */
	isAdvisorEnabled(): boolean {
		return this.#advisors.isAdvisorEnabled();
	}

	/**
	 * Whether a live advisor agent is attached to this session. True only when
	 * `advisor.enabled` is set for this session (subagents opt in per agent via
	 * frontmatter `advisor` / `task.agentAdvisor`) AND a model resolved for the
	 * `advisor` role — i.e. the actual runtime exists, not merely the setting.
	 * Drives the status-line badge and `/dump advisor`.
	 */
	isAdvisorActive(): boolean {
		return this.#advisors.isAdvisorActive();
	}

	/**
	 * The names of the tools available to advisors this session (the pool a
	 * `/advisor configure` editor lists). The advisor is a full agent, so this is the
	 * full built tool set; a tool whose optional factory returns null (e.g. lsp with
	 * no servers) is absent.
	 */
	getAdvisorAvailableToolNames(): string[] {
		return this.#advisors.getAdvisorAvailableToolNames();
	}

	/**
	 * The live advisor `Agent`, or `undefined` when no advisor runtime is
	 * attached. Surfaced for diagnostics (`/dump advisor` already serializes
	 * its transcript via {@link formatAdvisorHistoryAsText}) and so callers can
	 * verify the advisor inherits the session's provider-shaping options
	 * (`streamFn`, `promptCacheKey`, `providerSessionState`, ...).
	 */
	getAdvisorAgent(): Agent | undefined {
		return this.#advisors.getAdvisorAgent();
	}

	/** WATCHDOG.yml problems from startup discovery; shown by the UI once it is ready. */
	getAdvisorConfigWarnings(): readonly string[] {
		return this.#advisors.configWarnings;
	}

	/**
	 * Lightweight advisor status for the status line: returns just the configured
	 * flag and per-advisor name/status without computing token/cost breakdowns.
	 * Avoids re-tokenizing the advisor transcript on every render frame.
	 */
	getAdvisorStatusOverview(): { configured: boolean; advisors: AdvisorStatusOverviewEntry[] } {
		return this.#advisors.getAdvisorStatusOverview();
	}

	/** Return cumulative cost recorded for the current session's advisor activity. */
	getAdvisorCost(): number {
		return this.#advisors.getAdvisorCost();
	}

	/**
	 * Begin backfilling advisor spend recorded before this resume, off the
	 * critical path. A large transcript would otherwise block startup while
	 * the file is streamed; the status-line total hydrates once the scan
	 * settles.
	 */
	beginInitialAdvisorCostRestore(): void {
		let stale = false;
		const unregisterSessionChange = this.registerSessionChangeCallback(() => {
			stale = true;
		});
		const snapshot = this.#advisors.beginCostRestoreSnapshot();
		const providersBySlug = new Map<string, Set<string>>();
		this.#advisorCostRestore = loadAdvisorTranscriptCosts(this.sessionFile, {
			beforeSnapshot: snapshot.ready,
			onSnapshot: snapshot.release,
			shouldContinue: () => !stale && !this.isDisposed,
			providersBySlug,
		})
			.then(costs => {
				if (stale || this.isDisposed) return;
				this.restoreInitialAdvisorCosts(costs, snapshot.costsAtSnapshot, providersBySlug);
				this.#emit({ type: "advisor_cost_changed" });
			})
			.catch(err => logger.debug("advisor cost restore failed", { err: String(err) }))
			.finally(() => {
				snapshot.release();
				unregisterSessionChange();
			});
	}

	/** Resolves once {@link beginInitialAdvisorCostRestore}'s scan has settled. */
	get advisorCostRestore(): Promise<void> {
		return this.#advisorCostRestore;
	}

	/**
	 * Restore persisted advisor spend plus the process-local delta billed after
	 * `costsAtSnapshot`. The recorder barrier fixes every transcript's byte length
	 * after capturing that baseline, so a turn completed while the scan runs is added
	 * exactly once.
	 */
	restoreInitialAdvisorCosts(
		costs: ReadonlyMap<string, number>,
		costsAtSnapshot: ReadonlyMap<string, number> = new Map(),
		providersBySlug?: ReadonlyMap<string, ReadonlySet<string>>,
	): void {
		this.#advisors.restoreInitialCost(costs, costsAtSnapshot, providersBySlug);
	}
	/** Return whether any active or configured advisor is running on an OAuth/subscription model. */
	isAdvisorUsingSubscription(): boolean {
		return this.#advisors.isUsingSubscription();
	}
	/**
	 * Return structured advisor stats for the status command and TUI panel.
	 */
	getAdvisorStats(): AdvisorStats {
		return this.#advisors.getAdvisorStats();
	}

	/**
	 * Format a concise advisor status line for ACP/text output.
	 */
	formatAdvisorStatus(): string {
		return this.#advisors.formatAdvisorStatus();
	}

	/**
	 * Format the advisor agent's own transcript (its system prompt, config,
	 * tools, and the markdown deltas it received plus its thinking/advise/read
	 * calls) as plain text — the advisor-side equivalent of
	 * {@link formatSessionAsText}. Returns null when no advisor is active.
	 */
	formatAdvisorHistoryAsText(options?: { compact?: boolean }): string | null {
		return this.#advisors.formatAdvisorHistoryAsText(options);
	}

	// =========================================================================
	// Extension System
	// =========================================================================

	/**
	 * Check if extensions have handlers for a specific event type.
	 */
	hasExtensionHandlers(eventType: string): boolean {
		return this.#extensionRunner?.hasHandlers(eventType) ?? false;
	}

	/**
	 * Get the extension runner (for setting UI context and error handlers).
	 */
	get extensionRunner(): ExtensionRunner | undefined {
		return this.#extensionRunner;
	}

	/**
	 * Consume any pending Anthropic fallback credit handle for the next retry turn.
	 */
	consumeActiveFallbackCreditRedemption(targetModel?: Model): AnthropicFallbackCreditHandle | undefined {
		return this.#recovery.consumeActiveFallbackCreditRedemption(targetModel);
	}

	/** Whether requests to `model` leave other models' reasoning out of their input. */
	omitsDemotedReasoning(model: Model): boolean {
		return this.#recovery.omitsDemotedReasoning(model);
	}
}

import {
	type AgentMessage,
	ASIDE_MESSAGE_COMMIT,
	ASIDE_MESSAGE_DISCARD,
	ASIDE_MESSAGE_REFRESH,
} from "@oh-my-pi/pi-agent-core";
import { logger, toError } from "@oh-my-pi/pi-utils";

export interface YieldDispatcher<P> {
	/** Drop entries already delivered through another path. Called per-entry at flush time. */
	isStale?(entry: P): boolean;
	/** Rebuild this batch if any such entry was drained before an asynchronous commit boundary. */
	refreshBeforeCommit?(entry: P): boolean;
	/** Produce one batched AgentMessage from non-stale entries. Return null to skip. */
	build(survivors: P[]): AgentMessage | null;
	/** If true, entries for this kind are drained only by {@link drainLazy} and never trigger the idle flush. */
	skipIdleFlush?: boolean;
}

export interface YieldQueueOptions {
	isStreaming: () => boolean;
	injectStreaming?(msg: AgentMessage): void;
	injectIdle(messages: AgentMessage[]): Promise<void>;
	scheduleIdleFlush(run: () => Promise<void>): void;
}

type YieldFlushMode = "streaming" | "idle";

interface StoredDispatcher {
	isStale?: (entry: unknown) => boolean;
	refreshBeforeCommit?: (entry: unknown) => boolean;
	build: (survivors: unknown[]) => AgentMessage | null;
	skipIdleFlush?: boolean;
}

interface StoredEntry {
	value: unknown;
	resolve?: () => void;
	reject?: (error: Error) => void;
}

interface BuiltMessage {
	message: AgentMessage;
	entries: StoredEntry[];
}

function formatError(error: unknown): string {
	return error instanceof Error ? error.message : String(error);
}

export class YieldQueue {
	readonly #options: YieldQueueOptions;
	readonly #dispatchers = new Map<string, StoredDispatcher>();
	readonly #entries = new Map<string, StoredEntry[]>();
	#idleFlushPending = false;
	#idleFlushHolds = 0;

	constructor(options: YieldQueueOptions) {
		this.#options = options;
	}

	/**
	 * Keep follow-ups queued until a restored turn has scheduled its retry.
	 * Streaming step-boundary delivery remains available and receipts remain
	 * outstanding, so run drivers still see pending work. Releases nest safely.
	 */
	holdIdleFlush(): () => void {
		this.#idleFlushHolds++;
		let released = false;
		return () => {
			if (released) return;
			released = true;
			if (--this.#idleFlushHolds === 0) this.requestIdleFlush();
		};
	}

	register<P>(kind: string, dispatcher: YieldDispatcher<P>): () => void {
		const stored: StoredDispatcher = {
			...(dispatcher.isStale ? { isStale: entry => dispatcher.isStale?.(entry as P) ?? false } : {}),
			...(dispatcher.refreshBeforeCommit
				? { refreshBeforeCommit: entry => dispatcher.refreshBeforeCommit?.(entry as P) ?? false }
				: {}),
			build: survivors => dispatcher.build(survivors as P[]),
			...(dispatcher.skipIdleFlush ? { skipIdleFlush: true } : {}),
		};
		this.#dispatchers.set(kind, stored);
		return () => {
			if (this.#dispatchers.get(kind) !== stored) return;
			this.#dispatchers.delete(kind);
			this.#rejectEntries(this.#entries.get(kind) ?? [], new Error(`Yield queue dispatcher removed: ${kind}`));
			this.#entries.delete(kind);
		};
	}

	enqueue<P>(kind: string, entry: P): void {
		this.#enqueue(kind, { value: entry });
	}

	enqueueWithReceipt<P>(kind: string, entry: P): Promise<void> {
		const { promise, resolve, reject } = Promise.withResolvers<void>();
		if (!this.#enqueue(kind, { value: entry, resolve, reject })) {
			reject(new Error(`Yield queue entry ignored for unregistered kind: ${kind}`));
		}
		return promise;
	}

	#enqueue(kind: string, entry: StoredEntry): boolean {
		if (!this.#dispatchers.has(kind)) {
			logger.warn("Yield queue entry ignored for unregistered kind", { kind });
			return false;
		}
		let entries = this.#entries.get(kind);
		if (!entries) {
			entries = [];
			this.#entries.set(kind, entries);
		}
		entries.push(entry);
		if (!this.#options.isStreaming() && !this.#dispatchers.get(kind)!.skipIdleFlush) {
			this.#scheduleIdleFlush();
		}
		return true;
	}

	has(kind?: string): boolean {
		if (kind !== undefined) return (this.#entries.get(kind)?.length ?? 0) > 0;
		for (const entries of this.#entries.values()) {
			if (entries.length > 0) return true;
		}
		return false;
	}

	/**
	 * Non-consuming check for an entry of `kind` that the drain would deliver.
	 * Unlike {@link has}, it skips entries the dispatcher reports stale, since
	 * the drain drops those without a message.
	 */
	hasDeliverable(kind: string): boolean {
		const entries = this.#entries.get(kind);
		if (!entries || entries.length === 0) return false;
		const isStale = this.#dispatchers.get(kind)?.isStale;
		if (!isStale) return true;
		return entries.some(entry => {
			try {
				return !isStale(entry.value);
			} catch {
				// The drain rejects an entry whose stale check throws.
				return false;
			}
		});
	}

	/** Arrange an idle flush for entries queued near the end of a streaming run. */
	requestIdleFlush(): void {
		for (const [kind, dispatcher] of this.#dispatchers) {
			if (!dispatcher.skipIdleFlush && this.has(kind)) {
				this.#scheduleIdleFlush();
				return;
			}
		}
	}

	async flush(mode: YieldFlushMode): Promise<void> {
		if (mode === "idle") {
			this.#idleFlushPending = false;
			if (this.#idleFlushHolds > 0) return;
		}
		const idleMessages: BuiltMessage[] = [];
		for (const [kind, dispatcher] of this.#dispatchers) {
			if (mode === "idle" && dispatcher.skipIdleFlush) continue;
			const entries = this.#drain(kind);
			if (entries.length === 0) continue;
			const built = this.#build(kind, dispatcher, entries);
			if (!built) continue;
			if (mode === "streaming") {
				try {
					if (!this.#options.injectStreaming) throw new Error("Streaming injection is unavailable");
					this.#options.injectStreaming(built.message);
					this.#resolveEntries(built.entries);
				} catch (error) {
					const dispatchError = toError(error);
					this.#rejectEntries(built.entries, dispatchError);
					logger.warn("Yield queue streaming dispatch failed", { kind, error: formatError(error) });
				}
			} else {
				idleMessages.push(built);
			}
		}
		if (mode === "idle" && idleMessages.length > 0) {
			for (const item of idleMessages) this.#attachEntrySettlement(item);
			try {
				await this.#options.injectIdle(idleMessages.map(item => item.message));
				for (const item of idleMessages) {
					(item.message as AgentMessage & { [ASIDE_MESSAGE_COMMIT]?: () => void })[ASIDE_MESSAGE_COMMIT]?.();
				}
			} catch (error) {
				const dispatchError = toError(error);
				for (const item of idleMessages) {
					(item.message as AgentMessage & { [ASIDE_MESSAGE_DISCARD]?: (error: Error) => void })[
						ASIDE_MESSAGE_DISCARD
					]?.(dispatchError);
				}
				logger.warn("Yield queue idle dispatch failed", { error: formatError(error) });
			}
		}
	}

	/**
	 * Snapshot and remove all queued entries, returning one lazy thunk per kind.
	 * Each thunk applies the dispatcher's staleness filter and builds the batched
	 * message only when called — so the consumer (the agent loop) decides, at the
	 * moment it injects, whether the message is still worth delivering (a thunk may
	 * return null to skip). Background-job completions and late diagnostics reach
	 * the model between requests without the agent having to stop.
	 */
	drainLazy(): Array<() => AgentMessage | null> {
		const thunks: Array<() => AgentMessage | null> = [];
		for (const [kind, dispatcher] of this.#dispatchers) {
			const entries = this.#drain(kind);
			if (entries.length === 0) continue;
			thunks.push(() => {
				const built = this.#build(kind, dispatcher, entries);
				if (!built) return null;
				this.#attachEntrySettlement(built);
				if (
					dispatcher.refreshBeforeCommit &&
					built.entries.some(entry => dispatcher.refreshBeforeCommit!(entry.value))
				) {
					Object.defineProperty(built.message, ASIDE_MESSAGE_REFRESH, {
						value: () => {
							const fresh = this.#build(kind, dispatcher, built.entries);
							if (!fresh) return null;
							this.#attachEntrySettlement(fresh);
							return fresh.message;
						},
					});
				}
				return built.message;
			});
		}
		return thunks;
	}

	/** Discard only matching receipts still queued for this kind. */
	discardWhere<P>(kind: string, predicate: (entry: P) => boolean): void {
		const entries = this.#entries.get(kind);
		if (!entries) return;
		const discarded = entries.filter(entry => predicate(entry.value as P));
		if (discarded.length === 0) return;
		const discardedSet = new Set(discarded);
		const retained = entries.filter(entry => !discardedSet.has(entry));
		if (retained.length > 0) this.#entries.set(kind, retained);
		else this.#entries.delete(kind);
		this.#rejectEntries(discarded, new Error(`Yield queue entries discarded before dispatch: ${kind}`));
	}

	/** Drop queued entries. With `kind`, drop only that kind's entries (leaving
	 *  any pending idle-flush for other kinds intact); otherwise drop everything. */
	clear(kind?: string): void {
		const error = new Error("Yield queue entry cleared before dispatch");
		if (kind !== undefined) {
			this.#rejectEntries(this.#entries.get(kind) ?? [], error);
			this.#entries.delete(kind);
			return;
		}
		for (const entries of this.#entries.values()) this.#rejectEntries(entries, error);
		this.#entries.clear();
		this.#idleFlushPending = false;
	}

	/** Clear a scheduled-flush latch when its host task is cancelled before running. */
	cancelIdleFlushScheduling(): void {
		this.#idleFlushPending = false;
	}

	#scheduleIdleFlush(): void {
		if (this.#idleFlushPending || this.#idleFlushHolds > 0) return;
		this.#idleFlushPending = true;
		try {
			this.#options.scheduleIdleFlush(async () => {
				this.#idleFlushPending = false;
				if (this.#options.isStreaming()) return;
				await this.flush("idle");
			});
		} catch (error) {
			this.#idleFlushPending = false;
			logger.warn("Yield queue idle flush scheduling failed", { error: formatError(error) });
		}
	}

	#drain(kind: string): StoredEntry[] {
		const entries = this.#entries.get(kind);
		if (!entries || entries.length === 0) return [];
		this.#entries.delete(kind);
		return entries;
	}

	#build(kind: string, dispatcher: StoredDispatcher, entries: StoredEntry[]): BuiltMessage | null {
		const survivors: StoredEntry[] = [];
		for (const entry of entries) {
			if (dispatcher.isStale) {
				let stale: boolean;
				try {
					stale = dispatcher.isStale(entry.value);
				} catch (error) {
					const staleError = toError(error);
					entry.reject?.(staleError);
					logger.warn("Yield queue stale check failed", { kind, error: formatError(error) });
					continue;
				}
				if (stale) {
					entry.reject?.(new Error(`Yield queue entry became stale: ${kind}`));
					continue;
				}
			}
			survivors.push(entry);
		}
		if (survivors.length === 0) return null;
		try {
			const message = dispatcher.build(survivors.map(entry => entry.value));
			if (!message) {
				this.#rejectEntries(survivors, new Error(`Yield queue dispatcher skipped entry: ${kind}`));
				return null;
			}
			return { message, entries: survivors };
		} catch (error) {
			const buildError = toError(error);
			this.#rejectEntries(survivors, buildError);
			logger.warn("Yield queue build failed", { kind, error: formatError(error) });
			return null;
		}
	}

	#attachEntrySettlement(built: BuiltMessage): void {
		let settled = false;
		Object.defineProperties(built.message, {
			[ASIDE_MESSAGE_COMMIT]: {
				configurable: true,
				value: () => {
					if (settled) return;
					settled = true;
					this.#resolveEntries(built.entries);
				},
			},
			[ASIDE_MESSAGE_DISCARD]: {
				configurable: true,
				value: (error: Error) => {
					if (settled) return;
					settled = true;
					this.#rejectEntries(built.entries, error);
				},
			},
		});
	}

	#resolveEntries(entries: StoredEntry[]): void {
		for (const entry of entries) entry.resolve?.();
	}

	#rejectEntries(entries: StoredEntry[], error: Error): void {
		for (const entry of entries) entry.reject?.(error);
	}
}

/**
 * Worker-side handle for an agent session homed on another thread (the main
 * thread or a sibling worker).
 *
 * One canonical instance per instance key (see `./session-directory`), built
 * by the `"agent-session"` codec. Every synchronous member is a `callSync` to
 * the main thread's bridge, which answers from its local session or its
 * `RemoteAgentSession` mirror; commands go to main asynchronously and main
 * routes them to the home thread. `subscribe`/`subscribeRunState` keep one
 * main-side forwarding subscription each, shared by every local listener.
 */
import type { AsyncJobManagerApi } from "../async/job-manager";
import type { AgentMessage, ThinkingLevel } from "@oh-my-pi/pi-agent-core";
import type { ImageContent, Model } from "@oh-my-pi/pi-ai";
import { logger } from "@oh-my-pi/pi-utils";
import type { IrcMessage } from "@oh-my-pi/pi-tui/tools/irc";
import type { EffectiveExtensionRoots } from "../capability/types";
import type {
	AgentSessionAdvisorOverview,
	AgentSessionHandle,
	AgentSessionLoopHandle,
	AgentSessionManagerHandle,
} from "../session/agent-session-handle";
import type { AgentSessionEvent, AgentSessionEventListener } from "../session/agent-session-events";
import type {
	AgentSessionDisposeOptions,
	PromptOptions,
	SessionStats,
	SteerOptions,
} from "../session/agent-session-types";
import type { CustomMessage } from "../session/messages";
import type { ServingModel } from "../session/retry-fallback-chains";
import type { AgentDefinition } from "../task/types";
import type { WorkPoolYieldItem } from "../task/workpool-yield";
import type { ThreadId } from "./identity";
import { emptyMirrorState } from "./remote-agent-session";
import { findRemoteSession, rememberRemoteSession } from "./session-directory";
import type {
	PeerStateField,
	SessionAbortOptions,
	SessionBridgeClient,
	SessionMirrorState,
	SessionRunState,
} from "./session-mirror";

let bridge: SessionBridgeClient | undefined;

/** Worker boot only: the main thread's session bridge every peer handle talks through. */
export function installPeerBridge(client: SessionBridgeClient): void {
	bridge = client;
}

function mainBridge(): SessionBridgeClient {
	if (!bridge) throw new Error("Agent session bridge is not installed on this worker");
	return bridge;
}

/** Canonical worker-side handle for the session `key` homed on `home` (another thread). */
export function peerAgentSession(key: string, home: ThreadId): PeerAgentSession {
	const known = findRemoteSession(key);
	if (known instanceof PeerAgentSession) return known;
	const session = new PeerAgentSession(key, home);
	rememberRemoteSession(key, session);
	return session;
}

const DEFAULTS = emptyMirrorState();

/** {@link AgentSessionHandle} for a session homed on another thread; see the module doc. */
export class PeerAgentSession implements AgentSessionHandle {
	readonly instanceKey: string;
	/** Thread the session lives on. */
	readonly home: ThreadId;
	readonly agent: AgentSessionLoopHandle;
	readonly sessionManager: AgentSessionManagerHandle;
	readonly #listeners = new Set<AgentSessionEventListener>();
	readonly #runStateListeners = new Set<(state: SessionRunState) => void>();
	#unsubscribe: (() => void) | undefined;
	#unsubscribeRunState: (() => void) | undefined;

	/** Use {@link peerAgentSession}; direct construction breaks identity. */
	constructor(key: string, home: ThreadId) {
		this.instanceKey = key;
		this.home = home;
		const peer = this;
		const loopState = {
			get messages(): AgentMessage[] {
				return peer.messages;
			},
			get streamMessage(): AgentMessage | null {
				return peer.#field("streamMessage");
			},
			get pendingToolCalls(): Set<string> {
				return new Set(peer.#field("pendingToolCalls"));
			},
		};
		this.agent = {
			get isPaused(): boolean {
				return peer.#field("isPaused");
			},
			state: loopState,
		};
		this.sessionManager = {
			getCwd: () => this.#field("cwd"),
			getSessionId: () => this.#field("sessionId"),
			getSessionFile: () => this.#field("sessionFile"),
			getArtifactsDir: () => this.#field("artifactsDir"),
			getUsageStatistics: () => this.#field("usageStatistics"),
		};
	}

	get isStreaming(): boolean {
		return this.#field("isStreaming");
	}

	get runStartedAt(): number | undefined {
		return this.#field("runStartedAt");
	}

	get ircWakesPending(): boolean {
		return this.#field("ircWakesPending");
	}

	get hasPendingWake(): boolean {
		return this.#field("hasPendingWake");
	}

	get messages(): AgentMessage[] {
		return mainBridge().remote.callSync("readMessages", this);
	}

	get sessionFile(): string | undefined {
		return this.#field("sessionFile");
	}

	get model(): Model | undefined {
		return this.#field("model");
	}

	get thinkingLevel(): ThinkingLevel | undefined {
		return this.#field("thinkingLevel");
	}

	get servingModel(): ServingModel | undefined {
		return this.#field("servingModel");
	}

	get effectiveExtensionRoots(): EffectiveExtensionRoots {
		return this.#field("effectiveExtensionRoots");
	}

	get hindsightActive(): boolean {
		return this.#field("hindsightActive");
	}

	getSessionStats(): SessionStats {
		return this.#field("sessionStats");
	}

	getAdvisorStatusOverview(): AgentSessionAdvisorOverview {
		return this.#field("advisorOverview");
	}

	getSessionAgents(): AgentDefinition[] {
		return this.#field("sessionAgents");
	}

	hasQueuedIrcFrom(from: string): boolean {
		return mainBridge().remote.callSync("hasQueuedIrcFrom", this, from);
	}

	/** Only ever called on the caller's own session; a peer is never that. */
	hasIrcInterrupts(): boolean {
		throw new Error(`hasIrcInterrupts must run on the session's home thread (${this.home}), not on a peer handle`);
	}

	emitIrcRelayObservation(record: CustomMessage): void {
		mainBridge().remote.notify("emitIrcRelayObservation", this, record);
	}

	subscribe(listener: AgentSessionEventListener): () => void {
		this.#listeners.add(listener);
		if (!this.#unsubscribe) {
			this.#unsubscribe = mainBridge().remote.callSync("subscribe", this, event => this.#dispatch(event));
		}
		return () => {
			if (!this.#listeners.delete(listener) || this.#listeners.size > 0) return;
			const unsubscribe = this.#unsubscribe;
			this.#unsubscribe = undefined;
			unsubscribe?.();
		};
	}

	subscribeRunState(listener: (state: SessionRunState) => void): () => void {
		this.#runStateListeners.add(listener);
		if (!this.#unsubscribeRunState) {
			this.#unsubscribeRunState = mainBridge().remote.callSync("subscribeRunState", this, state =>
				this.#dispatchRunState(state),
			);
		}
		return () => {
			if (!this.#runStateListeners.delete(listener) || this.#runStateListeners.size > 0) return;
			const unsubscribe = this.#unsubscribeRunState;
			this.#unsubscribeRunState = undefined;
			unsubscribe?.();
		};
	}

	deliverIrcMessage(msg: IrcMessage): Promise<"injected" | "woken"> {
		return mainBridge().remote.call("deliverIrcMessage", this, msg);
	}

	waitForIrcReplies(): Promise<void> {
		return mainBridge().remote.call("waitForIrcReplies", this);
	}

	prompt(text: string, options?: PromptOptions): Promise<boolean> {
		return mainBridge().remote.call("prompt", this, text, options);
	}

	steer(text: string, images?: ImageContent[], options?: SteerOptions): Promise<void> {
		return mainBridge().remote.call("steer", this, text, images, options);
	}

	abort(options?: SessionAbortOptions): Promise<void> {
		return mainBridge().remote.call("abort", this, options);
	}

	acquireRestoreIdleHold(
		expectedSessionFile: string,
		manager: AsyncJobManagerApi,
		signal: AbortSignal,
	): Promise<string> {
		return mainBridge().remote.call("acquireRestoreIdleHold", this, expectedSessionFile, manager, signal);
	}

	releaseRestoreIdleHold(token: string): Promise<boolean> {
		return mainBridge().remote.call("releaseRestoreIdleHold", this, token);
	}

	hasRestorePendingReceipt(token: string): Promise<boolean> {
		return mainBridge().remote.call("hasRestorePendingReceipt", this, token);
	}

	finishRestoreIdleHold(token: string, discard: boolean): Promise<boolean> {
		return mainBridge().remote.call("finishRestoreIdleHold", this, token, discard);
	}

	waitForRunEnd(): Promise<void> {
		return mainBridge().remote.call("waitForRunEnd", this);
	}

	setWorkPoolYieldItems(items: readonly WorkPoolYieldItem[]): Promise<void> {
		return mainBridge().remote.call("setWorkPoolYieldItems", this, items);
	}

	dispose(options?: AgentSessionDisposeOptions): Promise<void> {
		return mainBridge().remote.call("dispose", this, options);
	}

	#field<K extends PeerStateField>(field: K): SessionMirrorState[K] {
		const value = mainBridge().remote.callSync("read", this, [field])[field];
		return value === undefined ? DEFAULTS[field] : value;
	}

	#dispatch(event: AgentSessionEvent): void {
		// oxlint-disable-next-line unicorn/no-useless-spread -- snapshot: the loop body may add or remove listeners
		for (const listener of [...this.#listeners]) {
			try {
				listener(event);
			} catch (error) {
				logger.warn("PeerAgentSession listener threw", {
					key: this.instanceKey,
					error: error instanceof Error ? error.message : String(error),
				});
			}
		}
	}

	#dispatchRunState(state: SessionRunState): void {
		// oxlint-disable-next-line unicorn/no-useless-spread -- snapshot: the loop body may add or remove listeners
		for (const listener of [...this.#runStateListeners]) {
			try {
				listener(state);
			} catch (error) {
				logger.warn("PeerAgentSession run-state listener threw", {
					key: this.instanceKey,
					error: error instanceof Error ? error.message : String(error),
				});
			}
		}
	}
}

/**
 * Main-thread mirror of an agent session homed on a subagent worker.
 *
 * Created when the worker's `SessionPublisher` posts `opened` and held by the
 * session directory until `closed` (or the worker dies). It serves both the
 * cross-agent {@link AgentSessionHandle} surface and the TUI's
 * {@link AgentViewSession} surface, without ever blocking on the worker:
 *
 * - handle state reads come from the mirrored {@link SessionMirrorState} and
 *   message list the publisher keeps current;
 * - view reads come from the {@link SessionViewState} and entry list the
 *   publisher pushes while main watches the session (any `subscribe`
 *   listener, e.g. the focused TUI view; the entry list is kept between
 *   watches, so a new watch only catches it up), or are computed on main
 *   from them: the transcript context (entries + leaf), role-model cycles,
 *   temporary model thinking levels and service tiers (main-side settings
 *   and model registry), async job views (the root job manager scoped to the
 *   child's agent id), and generation tok/s (a main-local meter fed by
 *   forwarded events);
 * - `settings` is rebuilt on main from the main instance the worker's
 *   settings mirror plus the child's own overlay layers, and `modelRegistry`
 *   is the main registry the worker's registry mirrors;
 * - tool renderers and extension renderers resolve through the nearest
 *   main-thread ancestor session (worker tool copies carry no render hooks);
 * - synchronous commands (thinking level, queued-message restore, todo
 *   phases, custom entries) apply optimistically to the mirror and are sent
 *   to the home worker, whose next patch reconciles; asynchronous commands
 *   are RPC to the publisher.
 *
 * `subscribe` turns the worker's event stream (and view state) on while any
 * listener is attached; run-state listeners are fed by every transition the
 * publisher reports. A closed mirror keeps its last state, rejects commands
 * with an error naming the worker, and treats `dispose` as already done.
 */
import type { AsyncJobManagerApi } from "../async/job-manager";
import { type AgentMessage, type AgentTool, ThinkingLevel, Tokenizer } from "@oh-my-pi/pi-agent-core";
import type { Effort, ImageContent, Model, ServiceTier, ToolResultMessage, UsageReport } from "@oh-my-pi/pi-ai";
import { AUTO_THINKING, type ConfiguredThinkingLevel } from "@oh-my-pi/pi-tui/thinking";
import type { IrcMessage } from "@oh-my-pi/pi-tui/tools/irc";
import type { JobWidgetEntry } from "@oh-my-pi/pi-tui/tools/job-widget";
import type { TodoPhase } from "@oh-my-pi/pi-tui/tools/todo";
import { getBlobsDir, logger } from "@oh-my-pi/pi-utils";
import type { EffectiveExtensionRoots } from "../capability/types";
import type { ModelRegistry } from "../config/model-registry";
import { Settings } from "../config/settings";
import type { ExtensionRunner } from "../extensibility/extensions";
import type { ContextUsage } from "../extensibility/extensions/types";
import type { Skill } from "../extensibility/skills";
import type { GoalModeState } from "../goals/state";
import { AgentRegistry, MAIN_AGENT_ID } from "../registry/agent-registry";
import type { AgentSession } from "../session/agent-session";
import type { AgentSessionEvent, AgentSessionEventListener } from "../session/agent-session-events";
import {
	type AgentSessionAdvisorOverview,
	type AgentViewLoop,
	type AgentViewRuleSource,
	type AgentViewSession,
	type AgentViewSessionManager,
	type AgentViewState,
