	getTodoPhases(): TodoPhase[] {
		return this.#view.todoPhases;
	}

	/** Applied to the mirror at once and sent to the home worker. */
	setTodoPhases(phases: TodoPhase[]): void {
		this.#view = { ...this.#view, todoPhases: phases };
		this.#notify("setTodoPhases", toWireData(phases));
	}

	/** Same two steps as a home session: the optimistic entry and the mirror update reach the worker in order. */
	commitTodoPhases(phases: TodoPhase[]): void {
		this.sessionManager.appendCustomEntry(USER_TODO_EDIT_CUSTOM_TYPE, { phases });
		this.setTodoPhases(phases);
	}

	/**
	 * Main-thread renderer source for the child's tool `name`: the nearest
	 * main-thread ancestor's tool of that name (worker tool copies drop their
	 * render hooks), and only while the child itself registers the name.
	 */
	getToolByName(name: string): AgentTool | undefined {
		return this.#toolNames.has(name) ? this.#mainAncestor()?.getToolByName(name) : undefined;
	}

	hasBuiltInTool(name: string): boolean {
		return this.#builtInTools.has(name);
	}

	getQueuedMessages(): { steering: readonly string[]; followUp: readonly string[]; liveSteered: number } {
		return this.#view.queuedMessages;
	}

	/**
	 * Restore the newest user-authored queued message (steering first) the home
	 * has not claimed for delivery, drop it from the mirror, and have the home
	 * take it out of its queue. Main decides: the home's gate asks main before
	 * delivering any restorable entry, so a message restored here is never
	 * delivered too.
	 */
	popLastQueuedMessage(): DequeuedMessage | undefined {
		const queue = this.#view.restorableQueue;
		const chips = this.#view.queuedMessages;
		const steering = this.#lastRestorable(queue.steering);
		const followUp = steering < 0 ? this.#lastRestorable(queue.followUp) : -1;
		let popped: SessionQueuedEntry;
		let from: DequeuedMessage["queue"];
		if (steering >= 0) {
			popped = queue.steering[steering];
			from = "steering";
			// Chips list live-steered messages ahead of the queue: restorable entries align with their tail.
			const chip = chips.steering.length - (queue.steering.length - steering);
			this.#view = {
				...this.#view,
				restorableQueue: { steering: withoutIndex(queue.steering, steering), followUp: queue.followUp },
				queuedMessages: { ...chips, steering: withoutIndex(chips.steering, chip) },
			};
		} else if (followUp >= 0) {
			popped = queue.followUp[followUp];
			from = "followUp";
			const chip = chips.followUp.length - (queue.followUp.length - followUp);
			this.#view = {
				...this.#view,
				restorableQueue: { steering: queue.steering, followUp: withoutIndex(queue.followUp, followUp) },
				queuedMessages: { ...chips, followUp: withoutIndex(chips.followUp, chip) },
			};
		} else {
			return undefined;
		}
		this.#withdraw(popped.id);
		return { ...popped.message, queue: from };
	}

	/**
	 * Bridge only, synchronous: the home's gate is about to deliver queued
	 * entries `ids`. Returns those already restored here, which the home drops;
	 * either way none of them is restorable any more.
	 */
	claimQueued(ids: readonly string[]): string[] {
		const restored: string[] = [];
		for (const id of ids) {
			if (this.#withdrawnQueued.has(id)) restored.push(id);
			this.#settle(id);
		}
		return restored;
	}

	resume(): Promise<void> {
		return this.#command("resume");
	}

	retry(): Promise<boolean> {
		return this.#command("retry");
	}

	abortRetry(): void {
		this.#notify("abortRetry");
	}

	abortCompaction(reason?: unknown): void {
		this.#notify("abortCompaction", toWireData(reason));
	}

	runEphemeralTurn(args: EphemeralTurnOptions): Promise<EphemeralTurnResult> {
		return this.#command("runEphemeralTurn", args);
	}

	ephemeralMaxTokensPreservesRequest(): boolean {
		return this.#view.ephemeralMaxTokensPreservesRequest;
	}

	exportToHtml(outputPath?: string, useUserThemes?: boolean): Promise<string> {
		return this.#command("exportToHtml", outputPath, useUserThemes);
	}

	/** Idle maintenance runs on the home worker; its blocking predicates are answered synchronously from main. */
	enableIdleMaintenance(options: IdleMaintenanceOptions = {}): void {
		const { isBlocked, scheduledTurn, onRecap } = options;
		this.#notify("enableIdleMaintenance", {
			isBlocked: isBlocked && rpcSync(() => isBlocked()),
			scheduledTurn: scheduledTurn && rpcSync(() => scheduledTurn()),
			onRecap,
		});
	}

	refreshIdleMaintenance(): void {
		this.#notify("refreshIdleMaintenance");
	}

	subscribe(listener: AgentSessionEventListener): () => void {
		const first = this.#listeners.size === 0;
		this.#listeners.add(listener);
		if (first) this.#watch(true);
		return () => {
			if (!this.#listeners.delete(listener)) return;
			if (this.#listeners.size === 0) this.#watch(false);
		};
	}

	subscribeRunState(listener: (state: SessionRunState) => void): () => void {
		this.#runStateListeners.add(listener);
		return () => {
			this.#runStateListeners.delete(listener);
		};
	}

	deliverIrcMessage(msg: IrcMessage): Promise<"injected" | "woken"> {
		return this.#command("deliverIrcMessage", msg);
	}

	waitForIrcReplies(): Promise<void> {
		if (this.#closed !== undefined) return Promise.resolve();
		return this.#command("waitForIrcReplies");
	}

	prompt(text: string, options?: PromptOptions): Promise<boolean> {
		return this.#command("prompt", text, options);
	}

	steer(text: string, images?: ImageContent[], options?: SteerOptions): Promise<void> {
		return this.#command("steer", text, images, options);
	}

	abort(options?: SessionAbortOptions): Promise<void> {
		if (this.#closed !== undefined) return Promise.resolve();
		return this.#command("abort", options);
	}

	acquireRestoreIdleHold(
		expectedSessionFile: string,
		manager: AsyncJobManagerApi,
		signal: AbortSignal,
	): Promise<string> {
		return this.#command("acquireRestoreIdleHold", expectedSessionFile, manager, signal);
	}

	releaseRestoreIdleHold(token: string): Promise<boolean> {
		return this.#command("releaseRestoreIdleHold", token);
	}

	hasRestorePendingReceipt(token: string): Promise<boolean> {
		return this.#command("hasRestorePendingReceipt", token);
	}

	finishRestoreIdleHold(token: string, discard: boolean): Promise<boolean> {
		return this.#command("finishRestoreIdleHold", token, discard);
	}

	waitForRunEnd(): Promise<void> {
		return this.#command("waitForRunEnd");
	}

	setWorkPoolYieldItems(items: readonly WorkPoolYieldItem[]): Promise<void> {
		return this.#command("setWorkPoolYieldItems", items);
	}

	/** Dispose on the home worker; a session that is already gone counts as disposed. */
	async dispose(options?: AgentSessionDisposeOptions): Promise<void> {
		if (this.#closed !== undefined) return;
		try {
			await this.#command("dispose", options);
		} catch (error) {
			if (!(error instanceof RpcClosedError)) throw error;
		}
	}

	/** Bridge only: merge a state patch from the publisher. */
	applyPatch(patch: Partial<SessionMirrorState>): void {
		if (this.#closed !== undefined) return;
		this.#state = { ...this.#state, ...patch };
		if (patch.pendingToolCalls) this.#pendingToolCalls = new Set(patch.pendingToolCalls);
	}

	/** Bridge only: apply a message-list change in place (the array identity is stable). */
	applyMessages(delta: SessionMessagesDelta): void {
		if (this.#closed !== undefined) return;
		if (delta.kind === "replace") this.#messages.length = 0;
		for (const message of delta.messages) this.#messages.push(message);
	}

	/**
	 * Bridge only: a watch started; replace the view state with the publisher's
	 * snapshot and catch the entry list (kept across watches) up with `entries`.
	 */
	applyView(state: SessionViewState, entries: SessionEntriesDelta | undefined): void {
		if (this.#closed !== undefined) return;
		this.#view = state;
		this.#pruneSettled(state.restorableQueue);
		this.#activeUpdates.clear();
		for (const update of state.activeToolExecutionUpdates) this.#activeUpdates.set(update.toolCallId, update);
		if (entries) this.applyEntries(entries);
		this.#entryIndex.setLeaf(state.leafId);
		this.#syncViewDerived(state);
		this.#reseedTokenRate();
	}

	/** Bridge only: merge a view-state patch from the publisher. */
	applyViewPatch(patch: Partial<SessionViewState>): void {
		if (this.#closed !== undefined) return;
		this.#view = { ...this.#view, ...patch };
		if (patch.restorableQueue) this.#pruneSettled(patch.restorableQueue);
		if (patch.leafId !== undefined) this.#entryIndex.setLeaf(patch.leafId);
		this.#syncViewDerived(patch);
	}

	/** Bridge only: apply an entry-list change; locally appended entries give way to the worker's. */
	applyEntries(delta: SessionEntriesDelta): void {
		if (this.#closed !== undefined) return;
		if (delta.kind === "append" && this.#provisional.size === 0) {
			for (const entry of delta.entries) {
				this.#entries.push(entry);
				this.#entryIndex.insert(entry);
			}
			return;
		}
		const kept = delta.kind === "replace" ? [] : this.#entries.filter(entry => !this.#provisional.has(entry));
		this.#provisional.clear();
		this.#entries = [...kept, ...delta.entries];
		this.#entryIndex.rebuild(this.#entries);
		this.#entryIndex.setLeaf(this.#view.leafId);
	}

	/** Bridge only: dispatch one forwarded event to subscribers. */
	applyEvent(event: AgentSessionEvent): void {
		if (this.#closed !== undefined) return;
		this.#trackEvent(event);
		// oxlint-disable-next-line unicorn/no-useless-spread -- snapshot: the loop body may add or remove listeners
		for (const listener of [...this.#listeners]) {
			try {
				listener(event);
			} catch (error) {
				logger.warn("RemoteAgentSession listener threw", {
					key: this.instanceKey,
					error: error instanceof Error ? error.message : String(error),
				});
			}
		}
	}

	/** Bridge only: report a run-state transition to run-state subscribers. */
	applyRunState(state: SessionRunState): void {
		if (this.#closed !== undefined) return;
		// oxlint-disable-next-line unicorn/no-useless-spread -- snapshot: the loop body may add or remove listeners
		for (const listener of [...this.#runStateListeners]) {
			try {
				listener(state);
			} catch (error) {
				logger.warn("RemoteAgentSession run-state listener threw", {
					key: this.instanceKey,
					error: error instanceof Error ? error.message : String(error),
				});
			}
		}
	}

	/**
	 * Bridge only: the home closed the session or died. The mirror keeps its
	 * last data, reports idle to run-state subscribers that saw it running,
	 * and drops every listener.
	 */
	close(reason: string): void {
		if (this.#closed !== undefined) return;
		const wasRunning = this.#state.runStartedAt !== undefined;
		this.#state = {
			...this.#state,
			isStreaming: false,
			runStartedAt: undefined,
			hasPendingWake: false,
			streamMessage: null,
		};
		if (wasRunning) this.applyRunState("idle");
		this.#closed = reason;
		this.#settledQueued.clear();
		this.#withdrawnQueued.clear();
		this.#listeners.clear();
		this.#runStateListeners.clear();
	}

	/** Keep the event-derived mirror (stream message, running tool updates, tok/s meter) current. */
	#trackEvent(event: AgentSessionEvent): void {
		switch (event.type) {
			case "message_start":
				if (event.message.role !== "assistant") return;
				this.#state = { ...this.#state, streamMessage: event.message };
				this.tokenRate.begin(event.message.timestamp);
				return;
			case "message_update": {
				if (event.message.role !== "assistant") return;
				this.#state = { ...this.#state, streamMessage: event.message };
				const delta = event.assistantMessageEvent;
				if (delta.type === "text_delta" || delta.type === "thinking_delta" || delta.type === "toolcall_delta") {
					this.tokenRate.push(delta.delta);
				}
				return;
			}
			case "message_end":
				this.#state = { ...this.#state, streamMessage: null };
				if (event.message.role === "assistant") {
					const message = event.message;
					this.tokenRate.end(
						message.usage.output,
						message.duration !== undefined ? message.timestamp + message.duration : undefined,
					);
				}
				return;
			case "tool_execution_update":
				this.#activeUpdates.set(event.toolCallId, event);
				return;
			case "tool_execution_end":
				this.#activeUpdates.delete(event.toolCallId);
				return;
		}
	}

	/** Refresh lookups derived from view fields present in `changed`. */
	#syncViewDerived(changed: Partial<SessionViewState>): void {
		if (changed.toolNames) this.#toolNames = new Set(changed.toolNames);
		if (changed.builtInTools) this.#builtInTools = new Set(changed.builtInTools);
		if (changed.runToolCallIds) this.#runToolCallIds = new Set(changed.runToolCallIds);
		if (changed.settings) this.#settings = undefined;
	}

	/** Seed the tok/s meter from the newest completed assistant turn (attach, watch restart). */
	#reseedTokenRate(): void {
		for (let i = this.#messages.length - 1; i >= 0; i--) {
			const message = this.#messages[i];
			if (message?.role !== "assistant" || message.duration === undefined) continue;
			this.tokenRate.seed(message.usage.output, message.duration);
			return;
		}
		this.tokenRate.reset();
	}

	#countTokens(text: string): number {
		const model = this.#state.model;
		let cached = this.#tokenizer;
		if (!cached || cached.model !== model) {
			cached = { model, tokenizer: new Tokenizer(model) };
			this.#tokenizer = cached;
		}
		return cached.tokenizer.countTokens(text);
	}

	/** Optimistic local entry, replaced by the worker's own once its entries delta arrives. */
	#appendCustomEntry(customType: string, data: unknown): void {
		const wireData = toWireData(data);
		this.#notify("appendCustomEntry", customType, wireData);
		if (this.#closed !== undefined) return;
		const entry: CustomEntry = {
			type: "custom",
			customType,
			data: wireData,
			id: `pending:${++this.#provisionalSeq}`,
			parentId: this.#entryIndex.leafId(),
			timestamp: new Date().toISOString(),
		};
		this.#provisional.add(entry);
		this.#entries.push(entry);
		this.#entryIndex.insert(entry);
	}

	/** Nearest main-thread session up the registry's parent chain, else the main agent's. */
	#mainAncestor(): AgentSession | undefined {
		const registry = AgentRegistry.global();
		const seen = new Set<string>();
		let id = this.agentId === undefined ? undefined : registry.get(this.agentId)?.parentId;
		while (id !== undefined && !seen.has(id)) {
			seen.add(id);
			const ref = registry.get(id);
			const session = ref?.session;
			if (session && isLocalAgentSession(session)) return session;
			id = ref?.parentId;
		}
		const main = registry.get(MAIN_AGENT_ID)?.session;
		return main && isLocalAgentSession(main) ? main : undefined;
	}

	#goneError(): RpcClosedError {
		return new RpcClosedError(
			`Agent session ${this.agentId ?? this.instanceKey} on worker ${this.home} is gone: ${this.#closed ?? "worker link closed"}`,
		);
	}

	/** Index of the newest entry of `entries` neither claimed for delivery nor already restored; -1 when none. */
	#lastRestorable(entries: readonly SessionQueuedEntry[]): number {
		for (let i = entries.length - 1; i >= 0; i--) {
			const entry = entries[i];
			if (!entry.claimed && !this.#settledQueued.has(entry.id) && !this.#withdrawnQueued.has(entry.id)) return i;
		}
		return -1;
	}

	/**
	 * Have the home retire restored entry `id`: take it out of its queue, or keep
	 * whatever holds it aside (a follow-up parked behind a wake turn) from putting
	 * it back. Until the home confirms, its gate drops the entry.
	 */
	#withdraw(id: string): void {
		if (this.#closed !== undefined || !this.#host) return;
		this.#withdrawnQueued.add(id);
		this.#host.remote.call("popQueuedMessage", id).then(
			() => this.#settle(id),
			(error: unknown) => {
				if (error instanceof RpcClosedError) return;
				logger.warn("RemoteAgentSession failed to withdraw a queued message", {
					key: this.instanceKey,
					error: error instanceof Error ? error.message : String(error),
				});
			},
		);
	}

	/**
	 * The home settled entry `id` (claimed it for delivery, dropped it, or
	 * retired it): stop vetoing it, and keep it unrestorable while the mirror
	 * still lists it. Every queue the home publishes after this point lists it
	 * flagged or not at all, so the first one retires the mark.
	 */
	#settle(id: string): void {
		this.#withdrawnQueued.delete(id);
		const queue = this.#view.restorableQueue;
		const listed = (entry: SessionQueuedEntry) => entry.id === id && !entry.claimed;
		if (queue.steering.some(listed) || queue.followUp.some(listed)) this.#settledQueued.add(id);
	}

	/** A newly published queue lists settled entries flagged or not at all: their marks have served. */
	#pruneSettled(queue: SessionRestorableQueue): void {
		if (this.#settledQueued.size === 0) return;
		const restorable = new Set<string>();
		for (const entry of queue.steering) if (!entry.claimed) restorable.add(entry.id);
		for (const entry of queue.followUp) if (!entry.claimed) restorable.add(entry.id);
		for (const id of this.#settledQueued) if (!restorable.has(id)) this.#settledQueued.delete(id);
	}

	#watch(on: boolean): void {
		this.#notify("watch", on);
	}

	/** Fire-and-forget command to the home worker; dropped once the session is gone. */
	#notify<K extends keyof SessionHostProtocol & string>(method: K, ...args: SessionHostProtocol[K]["args"]): void {
		if (this.#closed !== undefined || !this.#host) return;
		this.#host.remote.notify(method, ...args);
	}

	async #command<K extends keyof SessionHostProtocol & string>(
		method: K,
		...args: SessionHostProtocol[K]["args"]
	): Promise<SessionHostProtocol[K]["result"]> {
		if (this.#closed !== undefined || !this.#host) throw this.#goneError();
		try {
			return await this.#host.remote.call(method, ...args);
		} catch (error) {
			if (error instanceof RpcClosedError) throw this.#goneError();
			throw error;
		}
	}
}

/**
 * Remote-object protocols of the main-owned agent singletons, as spoken by a
 * worker's proxies to the main thread's instances (see `./agents`).
 */
import type { IrcDeliveryReceipt, IrcMessage } from "@oh-my-pi/pi-tui/tools/irc";
import type { IrcWaitFilter, UnansweredSend } from "../../irc/bus";
import type { AwaitHoldOptions, AwaitWaiter } from "../../registry/agent-awaits";
import type { AdoptOptions, AgentReleaseOptions } from "../../registry/agent-lifecycle";
import type {
	AgentHistorySummary,
	AgentRef,
	AgentRefExpectation,
	AgentRegistryApi,
	AgentStatus,
	RegisterInput,
	RegistryListener,
} from "../../registry/agent-registry";
import type { AgentSessionHandle } from "../../session/agent-session-handle";
import type { RpcMethod } from "../rpc";

/** Remote-object kind of the main `AgentRegistry`. */
export const AGENT_REGISTRY_KIND = "agent-registry";
/** Remote-object kind of the main `AgentLifecycleManager`. */
export const AGENT_LIFECYCLE_KIND = "agent-lifecycle";
/** Remote-object kind of the main `IrcBus`. */
export const IRC_BUS_KIND = "irc-bus";
/** Remote-object kind of main's per-worker session bridge. */
export const AGENT_SESSION_BRIDGE_KIND = "agent-session-bridge";
/** Remote-object kind of a worker's session publisher. */
export const AGENT_SESSION_HOST_KIND = "agent-session-host";

/** `AgentRegistryApi` (with its `awaits`) over the link. */
export type AgentRegistryProtocol = {
	register: RpcMethod<[input: RegisterInput], AgentRef>;
	registerIfAvailable: RpcMethod<[input: RegisterInput, expected: AgentRef | null], AgentRef | undefined>;
	reopen: RpcMethod<[id: string, expected: AgentRef], AgentRef | undefined>;
	setHistory: RpcMethod<[id: string, history: AgentHistorySummary, expectedSessionFile?: string], boolean>;
	setStatus: RpcMethod<[id: string, status: AgentStatus, expected?: AgentRefExpectation], boolean>;
	markResultAccepted: RpcMethod<[id: string, expected?: AgentRefExpectation, responseAt?: number], boolean>;
	staleAcceptedRuns: RpcMethod<[], AgentRef[]>;
	setActivity: RpcMethod<[id: string, activity: string], void>;
	attachSession: RpcMethod<
		[id: string, session: AgentSessionHandle, sessionFile?: string | null, expected?: AgentRefExpectation],
		boolean
	>;
	detachSession: RpcMethod<[id: string, expected?: AgentRefExpectation], boolean>;
	unregister: RpcMethod<[id: string, expected?: AgentRefExpectation], boolean>;
	get: RpcMethod<[id: string], AgentRef | undefined>;
	list: RpcMethod<[], AgentRef[]>;
	listVisibleTo: RpcMethod<[id: string], AgentRef[]>;
	isRunning: RpcMethod<[ref: AgentRef], boolean>;
	/** One forwarding subscription per worker; returns a sync unsubscribe. */
	subscribe: RpcMethod<[listener: RegistryListener], () => void>;
	awaitsHold: RpcMethod<[waiter: string, awaited: readonly string[], options: AwaitHoldOptions], () => void>;
	awaitsBlocksOn: RpcMethod<[agent: string, target: string, sentAt: number], boolean>;
	awaitsBlockedVia: RpcMethod<[agent: string, target: string, sentAt: number], readonly string[] | undefined>;
	awaitsWaitersOn: RpcMethod<[target: string], AwaitWaiter[]>;
	/** One forwarding subscription per worker; returns a sync unsubscribe. */
	awaitsSubscribe: RpcMethod<[listener: () => void], () => void>;
};

/** `AgentLifecycleApi` over the link (the persisted reviver factory and teardown stay main-only). */
export type AgentLifecycleProtocol = {
	adopt: RpcMethod<[id: string, opts: AdoptOptions, expected?: AgentRefExpectation], void>;
	has: RpcMethod<[id: string, expected?: AgentRefExpectation], boolean>;
	reclaimDeadCorpse: RpcMethod<[id: string, expected: AgentRef], boolean>;
	manages: RpcMethod<[registry: AgentRegistryApi], boolean>;
	isParking: RpcMethod<[id: string, expected?: AgentRefExpectation], boolean>;
	park: RpcMethod<[id: string], void>;
	hold: RpcMethod<[id: string, expected: AgentRef], () => void>;
	ensureLive: RpcMethod<[id: string, expected?: AgentRef], AgentSessionHandle>;
	release: RpcMethod<[id: string, expected?: AgentRefExpectation, options?: AgentReleaseOptions], boolean>;
};

/** `IrcBusApi` over the link. */
export type IrcBusProtocol = {
	send: RpcMethod<[msg: Omit<IrcMessage, "id" | "ts">], IrcDeliveryReceipt>;
	sentSince: RpcMethod<[from: string, to: string, sinceTs: number], boolean>;
	unansweredSends: RpcMethod<[from: string, sinceTs: number], UnansweredSend[]>;
	lastMessageAt: RpcMethod<[from: string, to: string], number | undefined>;
	wait: RpcMethod<
		[
			agentId: string,
			filter: IrcWaitFilter,
			timeoutMs: number,
			signal?: AbortSignal,
			options?: { drainPending?: boolean },
		],
		IrcMessage | null
	>;
	take: RpcMethod<[agentId: string, from?: string], IrcMessage | undefined>;
	park: RpcMethod<[msg: Omit<IrcMessage, "id" | "ts">], IrcMessage>;
	unreadCount: RpcMethod<[agentId: string], number>;
	recordReply: RpcMethod<[from: string, to: string], void>;
};

/**
 * Worker-side proxies of the main-owned agent singletons, installed with
 * `installGlobal` at worker boot (see `./agents`).
 *
 * The APIs are synchronous wherever the main classes are, so those calls are
 * `callSync` round trips; async APIs use `call`, and results nobody reads
 * (`setActivity`, `recordReply`, `adopt`) are ordered notifications. Change
 * listeners share one main-side forwarding subscription per proxy, which is
 * dropped once the last local listener unsubscribes; events arrive
 * asynchronously after the main-side change.
 */
import type { IrcDeliveryReceipt, IrcMessage } from "@oh-my-pi/pi-tui/tools/irc";
import { logger } from "@oh-my-pi/pi-utils";
import type { AgentAwaitsApi, AwaitHoldOptions, AwaitWaiter } from "../../registry/agent-awaits";
import type {
	AdoptOptions,
	AgentLifecycleApi,
	AgentReleaseOptions,
	PersistedSubagentReviverFactory,
} from "../../registry/agent-lifecycle";
import type {
	AgentHistorySummary,
	AgentRef,
	AgentRefExpectation,
	AgentRegistryApi,
	AgentStatus,
	RegisterInput,
	RegistryEvent,
	RegistryListener,
} from "../../registry/agent-registry";
import type { IrcBusApi, IrcWaitFilter, UnansweredSend } from "../../irc/bus";
import type { AgentSessionHandle } from "../../session/agent-session-handle";
import type { RemoteObject } from "../rpc";
import type { AgentLifecycleProtocol, AgentRegistryProtocol, IrcBusProtocol } from "./agents-protocol";

/** Local listeners fed by one lazily opened remote subscription. */
class ForwardedListeners<A extends unknown[]> {
	readonly #listeners = new Set<(...args: A) => void>();
	readonly #open: (forward: (...args: A) => void) => () => void;
	readonly #label: string;
	#close: (() => void) | undefined;

	constructor(label: string, open: (forward: (...args: A) => void) => () => void) {
		this.#label = label;
		this.#open = open;
	}

	add(listener: (...args: A) => void): () => void {
		this.#listeners.add(listener);
		this.#close ??= this.#open((...args) => this.#emit(args));
		return () => {
			if (!this.#listeners.delete(listener) || this.#listeners.size > 0) return;
			const close = this.#close;
			this.#close = undefined;
			close?.();
		};
	}

	#emit(args: A): void {
		// oxlint-disable-next-line unicorn/no-useless-spread -- snapshot: the loop body may add or remove listeners
		for (const listener of [...this.#listeners]) {
			try {
				listener(...args);
			} catch (error) {
				logger.debug("Forwarded listener threw", { source: this.#label, error: String(error) });
			}
		}
	}
}

/** Worker proxy of main's agent awaits table. */
export class RemoteAgentAwaits implements AgentAwaitsApi {
	readonly #remote: RemoteObject<AgentRegistryProtocol>;
	readonly #listeners: ForwardedListeners<[]>;

	constructor(remote: RemoteObject<AgentRegistryProtocol>) {
		this.#remote = remote;
		this.#listeners = new ForwardedListeners("agent-awaits", forward => remote.callSync("awaitsSubscribe", forward));
	}

	hold(waiter: string, awaited: readonly string[], options: AwaitHoldOptions): () => void {
		return this.#remote.callSync("awaitsHold", waiter, awaited, options);
	}

	blocksOn(agent: string, target: string, sentAt: number): boolean {
		return this.#remote.callSync("awaitsBlocksOn", agent, target, sentAt);
	}

	blockedVia(agent: string, target: string, sentAt: number): readonly string[] | undefined {
		return this.#remote.callSync("awaitsBlockedVia", agent, target, sentAt);
	}

	waitersOn(target: string): AwaitWaiter[] {
		return this.#remote.callSync("awaitsWaitersOn", target);
	}

	onChange(listener: () => void): () => void {
		return this.#listeners.add(listener);
	}
}

/** Worker proxy of main's {@link AgentRegistryApi}. */
export class RemoteAgentRegistry implements AgentRegistryApi {
	readonly awaits: AgentAwaitsApi;
	readonly #remote: RemoteObject<AgentRegistryProtocol>;
	readonly #listeners: ForwardedListeners<[RegistryEvent]>;

	constructor(remote: RemoteObject<AgentRegistryProtocol>) {
		this.#remote = remote;
		this.awaits = new RemoteAgentAwaits(remote);
		this.#listeners = new ForwardedListeners("agent-registry", forward => remote.callSync("subscribe", forward));
	}

	register(input: RegisterInput): AgentRef {
		return this.#remote.callSync("register", input);
	}

	registerIfAvailable(input: RegisterInput, expected: AgentRef | null): AgentRef | undefined {
		return this.#remote.callSync("registerIfAvailable", input, expected);
	}

	reopen(id: string, expected: AgentRef): AgentRef | undefined {
		return this.#remote.callSync("reopen", id, expected);
	}

	setHistory(id: string, history: AgentHistorySummary, expectedSessionFile?: string): boolean {
		return this.#remote.callSync("setHistory", id, history, expectedSessionFile);
	}

	setStatus(id: string, status: AgentStatus, expected?: AgentRefExpectation): boolean {
		return this.#remote.callSync("setStatus", id, status, expected);
	}

	markResultAccepted(id: string, expected?: AgentRefExpectation, responseAt?: number): boolean {
		return this.#remote.callSync("markResultAccepted", id, expected, responseAt);
	}

	staleAcceptedRuns(): AgentRef[] {
		return this.#remote.callSync("staleAcceptedRuns");
	}

	setActivity(id: string, activity: string): void {
		this.#remote.notify("setActivity", id, activity);
	}

	attachSession(
		id: string,
		session: AgentSessionHandle,
		sessionFile?: string | null,
		expected?: AgentRefExpectation,
	): boolean {
		return this.#remote.callSync("attachSession", id, session, sessionFile, expected);
	}

	detachSession(id: string, expected?: AgentRefExpectation): boolean {
		return this.#remote.callSync("detachSession", id, expected);
	}

	unregister(id: string, expected?: AgentRefExpectation): boolean {
		return this.#remote.callSync("unregister", id, expected);
	}

	get(id: string): AgentRef | undefined {
		return this.#remote.callSync("get", id);
	}

	list(): AgentRef[] {
		return this.#remote.callSync("list");
	}

	listVisibleTo(id: string): AgentRef[] {
		return this.#remote.callSync("listVisibleTo", id);
	}

	isRunning(ref: AgentRef): boolean {
		return this.#remote.callSync("isRunning", ref);
	}

	/** Subscribes on the session's own thread view and reports each transition to main in order. */
	syncSessionStatus(id: string, session: AgentSessionHandle): () => void {
		return session.subscribeRunState(status => {
			this.#remote.notify("setStatus", id, status, session);
		});
	}

	onChange(listener: RegistryListener): () => void {
		return this.#listeners.add(listener);
	}
}

/** Worker proxy of main's {@link AgentLifecycleApi}; the reviver factory and teardown are main-only. */
export class RemoteAgentLifecycle implements AgentLifecycleApi {
	readonly #remote: RemoteObject<AgentLifecycleProtocol>;

	constructor(remote: RemoteObject<AgentLifecycleProtocol>) {
		this.#remote = remote;
	}

	setPersistedSubagentReviverFactory(_factory: PersistedSubagentReviverFactory, _idleTtlMs: () => number): void {
		throw new Error("The persisted subagent reviver factory is owned by the main thread");
	}

	adopt(id: string, opts: AdoptOptions, expected?: AgentRefExpectation): void {
		this.#remote.notify("adopt", id, opts, expected);
	}

	has(id: string, expected?: AgentRefExpectation): boolean {
		return this.#remote.callSync("has", id, expected);
	}

	reclaimDeadCorpse(id: string, expected: AgentRef): Promise<boolean> {
		return this.#remote.call("reclaimDeadCorpse", id, expected);
	}

	/** Identity across the link: only main's registry (this worker's proxy of it) is managed. */
	manages(registry: AgentRegistryApi): boolean {
		return registry instanceof RemoteAgentRegistry && this.#remote.callSync("manages", registry);
	}

	isParking(id: string, expected?: AgentRefExpectation): boolean {
		return this.#remote.callSync("isParking", id, expected);
	}

	park(id: string): Promise<void> {
		return this.#remote.call("park", id);
	}

	hold(id: string, expected: AgentRef): () => void {
		return this.#remote.callSync("hold", id, expected);
	}

	ensureLive(id: string, expected?: AgentRef): Promise<AgentSessionHandle> {
		return this.#remote.call("ensureLive", id, expected);
	}

	release(id: string, expected?: AgentRefExpectation, options?: AgentReleaseOptions): Promise<boolean> {
		return this.#remote.call("release", id, expected, options);
	}

	dispose(_deadlineAt?: number): Promise<void> {
		return Promise.reject(new Error("The agent lifecycle is torn down by the main thread"));
	}
}

