/**
 * Agent registry, awaits, lifecycle, IRC bus, and agent sessions across
 * subagent worker links.
 *
 * Main side, per worker:
 * - exports the main `AgentRegistry`, `AgentLifecycleManager`, and `IrcBus`
 *   by reference; the worker installs proxies as its globals (see
 *   `./agents-remote`). Forwarding subscriptions, awaits holds, and IRC waits
 *   a worker opens are tracked and dropped when it dies.
 * - exports a session bridge: the worker's publishers report sessions homed
 *   there (main keeps one `RemoteAgentSession` per open session, strongly,
 *   and retains the worker while any is open), and the worker's peer handles
 *   read and command sessions homed elsewhere through it.
 * - on worker death: adoptions carrying that worker's revivers are dropped
 *   (the next `ensureLive` cold-revives through the persisted factory), every
 *   registry ref holding a session homed there is detached and turns `parked`
 *   (session file on disk) or `aborted`, and the mirrors close, so in-flight
 *   commands reject with an error naming the worker.
 *
 * Worker side: proxies installed with `installGlobal`, the bridge handed to
 * peer handles, and a `SessionPublisher` for every session constructed here.
 */
import { logger } from "@oh-my-pi/pi-utils";
import { IrcBus } from "../../irc/bus";
import { type AdoptOptions, type AgentReviver, AgentLifecycleManager } from "../../registry/agent-lifecycle";
import { AgentRegistry, type RegistryListener } from "../../registry/agent-registry";
import { PromptDroppedError, SessionBusyError } from "../../session/agent-session";
import type { WorkerThreadLink } from "../protocol";
import { installPeerBridge } from "../peer-agent-session";
import { RemoteAgentSession, SessionHostClient } from "../remote-agent-session";
import { registerRpcError, type RpcServe } from "../rpc";
import type { ThreadService, WorkerPeer } from "../services";
import { holdRemoteSession, onLocalSessionRegistered, releaseRemoteSession } from "../session-directory";
import {
	readSessionFields,
	SessionBridgeClient,
	type SessionBridgeProtocol,
	type SessionHostProtocol,
	type SessionOpened,
	toWireData,
} from "../session-mirror";
import { SESSION_HOST_SERVE, SessionPublisher } from "../session-publisher";
import {
	AGENT_LIFECYCLE_KIND,
	AGENT_REGISTRY_KIND,
	AGENT_SESSION_BRIDGE_KIND,
	AGENT_SESSION_HOST_KIND,
	type AgentLifecycleProtocol,
	type AgentRegistryProtocol,
	IRC_BUS_KIND,
	type IrcBusProtocol,
} from "./agents-protocol";
import { RemoteAgentLifecycle, RemoteAgentRegistry, RemoteIrcBus } from "./agents-remote";
import { trackWorkerSubscription } from "./support";

/** Boot globals of {@link agentsThreadService}: main's singletons and this worker's session bridge. */
export interface AgentsThreadGlobals {
	readonly registry: AgentRegistry;
	readonly lifecycle: AgentLifecycleManager;
	readonly bus: IrcBus;
	readonly bridge: MainSessionBridge;
}

function registerSessionErrors(): void {
	registerRpcError("PromptDroppedError", message => Object.assign(new PromptDroppedError(), { message }));
	registerRpcError("SessionBusyError", message => Object.assign(new SessionBusyError("continue"), { message }));
}

// ─────────────────────────────────────────────────────────────────────────────
// Main side
// ─────────────────────────────────────────────────────────────────────────────

interface OpenSession {
	readonly session: RemoteAgentSession;
	readonly release: () => void;
}

/**
 * Main-side endpoint of one worker's sessions: mirrors of the sessions homed
 * there, and the peer surface for sessions homed elsewhere. Also the
 * per-worker ledger of everything that must end when the worker dies.
 */
export class MainSessionBridge {
	readonly #peer: WorkerPeer;
	readonly #open = new Map<string, OpenSession>();
	readonly #subscriptions = new Set<() => void>();
	readonly #revivers = new Set<{ lifecycle: AgentLifecycleManager; id: string; revive: AgentReviver }>();
	/** Aborts IRC waits the worker parked on main. */
	readonly exited = new AbortController();

	constructor(peer: WorkerPeer) {
		this.#peer = peer;
	}

	/** Worker the bridge serves. */
	get threadId(): WorkerPeer["threadId"] {
		return this.#peer.threadId;
	}

	/** Mirror of the open session `key` homed on this worker. */
	session(key: string): RemoteAgentSession | undefined {
		return this.#open.get(key)?.session;
	}

	/** A publisher opened a session: create and hold its canonical mirror. */
	opened(opened: SessionOpened): void {
		if (!(opened.host instanceof SessionHostClient)) throw new Error("Session opened without a host");
		const session = new RemoteAgentSession({
			key: opened.key,
			home: this.#peer.threadId,
			agentId: opened.agentId,
			host: opened.host,
			state: opened.state,
			messages: opened.messages,
			modelRegistry: opened.modelRegistry,
			asyncJobManager: opened.asyncJobManager,
		});
		holdRemoteSession(opened.key, session);
		this.#open.set(opened.key, { session, release: this.#peer.retain?.() ?? (() => {}) });
	}

	/** A publisher closed its session (dispose began). */
	closed(key: string, reason = "disposed"): void {
		const open = this.#open.get(key);
		if (!open) return;
		this.#open.delete(key);
		releaseRemoteSession(key);
		open.session.close(reason);
		open.release();
	}

	/**
	 * Keep `stop` until it runs or the worker dies; returns it marked sync so
	 * the worker can unsubscribe without a round trip of its own.
	 */
	track(stop: () => void): () => void {
		return trackWorkerSubscription(this.#subscriptions, stop);
	}

	/**
	 * Wrap a worker function as a main-side listener: delivery is async, and a
	 * failed delivery (closed link, collected receiver) ends the subscription.
	 */
	forward<A extends unknown[]>(
		deliver: (...args: A) => unknown,
		subscribe: (listener: (...args: A) => void) => () => void,
	): () => void {
		let stop: () => void = () => {};
		const listener = (...args: A): void => {
			Promise.resolve(deliver(...args)).catch(() => stop());
		};
		stop = this.track(subscribe(listener));
		return stop;
	}

	/** Live worker revivers adopted on main; test seam for ledger bounds. */
	get reviverCount(): number {
		return this.#revivers.size;
	}

	/**
	 * Record a reviver this worker handed to `lifecycle` for `id`; returns the adopt options
	 * to pass on, whose reviver holds the worker (and its idle shutdown off) while a revive
	 * runs there. The record is dropped when the adoption lets go of the reviver.
	 */
	adopted(lifecycle: AgentLifecycleManager, id: string, opts: AdoptOptions): AdoptOptions {
		const revive = opts.revive;
		if (!revive) return opts;
		const peer = this.#peer;
		const held: AgentReviver = async expected => {
			const release = peer.retain?.();
			try {
				return await revive(expected);
			} finally {
				release?.();
			}
		};
		const entry = { lifecycle, id, revive: held };
		this.#revivers.add(entry);
		const revivers = this.#revivers;
		const onReviverDropped = opts.onReviverDropped;
		return {
			...opts,
			revive: held,
			onReviverDropped: () => {
				revivers.delete(entry);
				onReviverDropped?.();
			},
		};
	}

	/** The worker died: see the module doc for the ordering. */
	exit(reason: string): void {
		this.exited.abort(new Error(`Subagent worker ${this.#peer.threadId} exited: ${reason}`));
		// oxlint-disable-next-line unicorn/no-useless-spread -- snapshot: the loop body may add or remove subscriptions
		for (const stop of [...this.#subscriptions]) {
			try {
				stop();
			} catch (error) {
				logger.debug("Dropping a dead worker's subscription failed", { error: String(error) });
			}
		}
		const revivers = [...this.#revivers];
		this.#revivers.clear();
		for (const { lifecycle, id, revive } of revivers) lifecycle.forgetReviver(id, revive);
		const registry = AgentRegistry.global();
		for (const ref of registry.list()) {
			const session = ref.session;
			if (!(session instanceof RemoteAgentSession) || session.home !== this.#peer.threadId) continue;
			registry.detachSession(ref.id, ref);
			if (ref.status !== "aborted") registry.setStatus(ref.id, ref.sessionFile ? "parked" : "aborted", ref);
		}
		const why = `worker ${this.#peer.threadId} exited: ${reason}`;
		// oxlint-disable-next-line unicorn/no-useless-spread -- snapshot: the loop body may add or remove open channels
		for (const key of [...this.#open.keys()]) this.closed(key, why);
	}
}

/** Publisher notifications for this worker's sessions, and peer reads/commands main routes to a session's home. */
function serveBridge(): RpcServe<MainSessionBridge, SessionBridgeProtocol> {
	return {
		opened: (bridge, opened) => bridge.opened(opened),
		patch: (bridge, key, patch) => bridge.session(key)?.applyPatch(patch),
		messages: (bridge, key, delta) => bridge.session(key)?.applyMessages(delta),
		event: (bridge, key, event) => bridge.session(key)?.applyEvent(event),
		runState: (bridge, key, state) => bridge.session(key)?.applyRunState(state),
		view: (bridge, key, state, entries) => bridge.session(key)?.applyView(state, entries),
		viewPatch: (bridge, key, patch) => bridge.session(key)?.applyViewPatch(patch),
		claimQueued: (bridge, key, ids) => bridge.session(key)?.claimQueued(ids) ?? [],
		entries: (bridge, key, delta) => bridge.session(key)?.applyEntries(delta),
		closed: (bridge, key) => bridge.closed(key),
		read: (_bridge, session, fields) => readSessionFields(session, fields),
		readMessages: (_bridge, session) => toWireData(session.messages),
		hasQueuedIrcFrom: (_bridge, session, from) => session.hasQueuedIrcFrom(from),
		subscribe: (bridge, session, listener) =>
			bridge.forward(listener, forward => session.subscribe(event => forward(toWireData(event)))),
		subscribeRunState: (bridge, session, listener) =>
			bridge.forward(listener, forward => session.subscribeRunState(forward)),
		prompt: (_bridge, session, text, options) => session.prompt(text, options),
		steer: (_bridge, session, text, images, options) => session.steer(text, images, options),
		abort: (_bridge, session, options) => session.abort(options),
		dispose: (_bridge, session, options) => session.dispose(options),
		deliverIrcMessage: (_bridge, session, msg) => session.deliverIrcMessage(msg),
		waitForIrcReplies: (_bridge, session) => session.waitForIrcReplies(),
		setWorkPoolYieldItems: (_bridge, session, items) => session.setWorkPoolYieldItems(items),
		acquireRestoreIdleHold: (_bridge, session, expectedSessionFile, manager, signal) =>
			session.acquireRestoreIdleHold(expectedSessionFile, manager, signal),
		releaseRestoreIdleHold: (_bridge, session, token) => session.releaseRestoreIdleHold(token),
		hasRestorePendingReceipt: (_bridge, session, token) => session.hasRestorePendingReceipt(token),
		finishRestoreIdleHold: (_bridge, session, token, discard) => session.finishRestoreIdleHold(token, discard),
		waitForRunEnd: (_bridge, session) => session.waitForRunEnd(),
		emitIrcRelayObservation: (_bridge, session, record) => session.emitIrcRelayObservation(record),
	};
}

function serveRegistry(bridge: MainSessionBridge): RpcServe<AgentRegistry, AgentRegistryProtocol> {
	return {
		register: (registry, input) => registry.register(input),
		registerIfAvailable: (registry, input, expected) => registry.registerIfAvailable(input, expected),
		reopen: (registry, id, expected) => registry.reopen(id, expected),
		setHistory: (registry, id, history, expectedSessionFile) => registry.setHistory(id, history, expectedSessionFile),
		setStatus: (registry, id, status, expected) => registry.setStatus(id, status, expected),
		markResultAccepted: (registry, id, expected, responseAt) => registry.markResultAccepted(id, expected, responseAt),
		staleAcceptedRuns: registry => registry.staleAcceptedRuns(),
		setActivity: (registry, id, activity) => registry.setActivity(id, activity),
		attachSession: (registry, id, session, sessionFile, expected) =>
			registry.attachSession(id, session, sessionFile, expected),
		detachSession: (registry, id, expected) => registry.detachSession(id, expected),
		unregister: (registry, id, expected) => registry.unregister(id, expected),
		get: (registry, id) => registry.get(id),
		list: registry => registry.list(),
		listVisibleTo: (registry, id) => registry.listVisibleTo(id),
		isRunning: (registry, ref) => registry.isRunning(ref),
		subscribe: (registry, listener: RegistryListener) =>
			bridge.forward(listener, forward => registry.onChange(forward)),
		awaitsHold: (registry, waiter, awaited, options) => bridge.track(registry.awaits.hold(waiter, awaited, options)),
		awaitsBlocksOn: (registry, agent, target, sentAt) => registry.awaits.blocksOn(agent, target, sentAt),
		awaitsBlockedVia: (registry, agent, target, sentAt) => registry.awaits.blockedVia(agent, target, sentAt),
		awaitsWaitersOn: (registry, target) => registry.awaits.waitersOn(target),
		awaitsSubscribe: (registry, listener) => bridge.forward(listener, forward => registry.awaits.onChange(forward)),
	};
}

function serveLifecycle(bridge: MainSessionBridge): RpcServe<AgentLifecycleManager, AgentLifecycleProtocol> {
	return {
		adopt: (lifecycle, id, opts, expected) => lifecycle.adopt(id, bridge.adopted(lifecycle, id, opts), expected),
		has: (lifecycle, id, expected) => lifecycle.has(id, expected),
		reclaimDeadCorpse: (lifecycle, id, expected) => lifecycle.reclaimDeadCorpse(id, expected),
		manages: (lifecycle, registry) => lifecycle.manages(registry),
		isParking: (lifecycle, id, expected) => lifecycle.isParking(id, expected),
		park: (lifecycle, id) => lifecycle.park(id),
		hold: (lifecycle, id, expected) => bridge.track(lifecycle.hold(id, expected)),
		ensureLive: (lifecycle, id, expected) => lifecycle.ensureLive(id, expected),
		release: (lifecycle, id, expected, options) => lifecycle.release(id, expected, options),
	};
}

function serveBus(bridge: MainSessionBridge): RpcServe<IrcBus, IrcBusProtocol> {
	return {
		send: (bus, msg) => bus.send(msg),
		sentSince: (bus, from, to, sinceTs) => bus.sentSince(from, to, sinceTs),
		unansweredSends: (bus, from, sinceTs) => bus.unansweredSends(from, sinceTs),
		lastMessageAt: (bus, from, to) => bus.lastMessageAt(from, to),
		// A wait parked by a dead worker must not swallow the next message for its agent.
		wait: (bus, agentId, filter, timeoutMs, signal, options) =>
			bus.wait(
				agentId,
				filter,
				timeoutMs,
				signal ? AbortSignal.any([signal, bridge.exited.signal]) : bridge.exited.signal,
				options,
			),
		take: (bus, agentId, from) => bus.take(agentId, from),
		park: (bus, msg) => bus.park(msg),
		unreadCount: (bus, agentId) => bus.unreadCount(agentId),
		recordReply: (bus, from, to) => bus.recordReply(from, to),
	};
}

const bridges = new Map<WorkerPeer["threadId"], MainSessionBridge>();

function installMain(peer: WorkerPeer): void {
	registerSessionErrors();
	const bridge = new MainSessionBridge(peer);
	bridges.set(peer.threadId, bridge);
	const { link } = peer;
	link.exportClass(
		AGENT_SESSION_BRIDGE_KIND,
		(value): value is MainSessionBridge => value instanceof MainSessionBridge,
		serveBridge(),
	);
	link.exportClass(
		AGENT_REGISTRY_KIND,
		(value): value is AgentRegistry => value instanceof AgentRegistry,
		serveRegistry(bridge),
	);
	link.exportClass(
		AGENT_LIFECYCLE_KIND,
		(value): value is AgentLifecycleManager => value instanceof AgentLifecycleManager,
		serveLifecycle(bridge),
	);
	link.exportClass(IRC_BUS_KIND, (value): value is IrcBus => value instanceof IrcBus, serveBus(bridge));
	link.importClass<SessionHostClient, SessionHostProtocol>(
		AGENT_SESSION_HOST_KIND,
		remote => new SessionHostClient(remote),
	);
}

function mainGlobals(peer: WorkerPeer): AgentsThreadGlobals {
	const bridge = bridges.get(peer.threadId);
	const registry = AgentRegistry.global();
	const lifecycle = AgentLifecycleManager.global();
	const bus = IrcBus.global();
	if (!bridge) throw new Error(`No agent session bridge for ${peer.threadId}`);
	if (
		!(registry instanceof AgentRegistry) ||
		!(lifecycle instanceof AgentLifecycleManager) ||
		!(bus instanceof IrcBus)
	) {
		throw new Error("Agent singletons must be main-thread instances to bridge them into a worker");
	}
	return { registry, lifecycle, bus, bridge };
}

function onWorkerExit(peer: WorkerPeer, reason: string): void {
	const bridge = bridges.get(peer.threadId);
	bridges.delete(peer.threadId);
	bridge?.exit(reason);
}

// ─────────────────────────────────────────────────────────────────────────────
// Worker side
// ─────────────────────────────────────────────────────────────────────────────

function installWorker(link: WorkerThreadLink): void {
	registerSessionErrors();
	link.importClass<RemoteAgentRegistry, AgentRegistryProtocol>(
		AGENT_REGISTRY_KIND,
		remote => new RemoteAgentRegistry(remote),
	);
	link.importClass<RemoteAgentLifecycle, AgentLifecycleProtocol>(
		AGENT_LIFECYCLE_KIND,
		remote => new RemoteAgentLifecycle(remote),
	);
	link.importClass<RemoteIrcBus, IrcBusProtocol>(IRC_BUS_KIND, remote => new RemoteIrcBus(remote));
	link.importClass<SessionBridgeClient, SessionBridgeProtocol>(
		AGENT_SESSION_BRIDGE_KIND,
		remote => new SessionBridgeClient(remote),
	);
	link.exportClass<SessionPublisher, SessionHostProtocol>(
		AGENT_SESSION_HOST_KIND,
		(value): value is SessionPublisher => value instanceof SessionPublisher,
		SESSION_HOST_SERVE,
	);
}

interface WorkerAgentsGlobals {
	readonly registry: RemoteAgentRegistry;
	readonly lifecycle: RemoteAgentLifecycle;
	readonly bus: RemoteIrcBus;
	readonly bridge: SessionBridgeClient;
}

function isWorkerGlobals(value: unknown): value is WorkerAgentsGlobals {
	return (
		typeof value === "object" &&
		value !== null &&
		Reflect.get(value, "registry") instanceof RemoteAgentRegistry &&
		Reflect.get(value, "lifecycle") instanceof RemoteAgentLifecycle &&
		Reflect.get(value, "bus") instanceof RemoteIrcBus &&
		Reflect.get(value, "bridge") instanceof SessionBridgeClient
	);
}

let stopPublishing: (() => void) | undefined;

function bootWorker(globals: unknown): void {
	if (!isWorkerGlobals(globals)) throw new Error("Malformed agents thread globals");
	AgentRegistry.installGlobal(globals.registry);
	AgentLifecycleManager.installGlobal(globals.lifecycle);
	IrcBus.installGlobal(globals.bus);
	installPeerBridge(globals.bridge);
	stopPublishing?.();
	const bridge = globals.bridge;
	stopPublishing = onLocalSessionRegistered(session => {
		new SessionPublisher(session, bridge);
	});
}

/** Registry, awaits, lifecycle, IRC bus, and agent-session bridging; see the module doc. */
export const agentsThreadService: ThreadService = {
	name: "agents",
	installMain,
	globals: mainGlobals,
	onWorkerExit,
	installWorker,
	boot: bootWorker,
};

/**
 * Wire protocol of the root `AsyncJobManager` a subagent worker reaches by
 * reference (kind `"async-job-manager"`).
 *
 * Job rows cross as {@link AsyncJobWire} projections: data only, no
 * `AbortController`, run promise, process handle or widget inputs. The worker
 * rebuilds rows with local equivalents (`./async-jobs-remote`).
 *
 * Inputs the main thread reads synchronously from a job (`process.pids()`,
 * `widgetInputs.sources()`/`brief()`) cannot call back into a worker; a job
 * registered from a worker sends a {@link WireJobFeed} instead, and main keeps
 * the latest {@link JobFeedDelta} it pulled or was pushed.
 *
 * Abort reasons that are symbols cannot cross: {@link toWireReason} maps
 * `ASYNC_JOB_MANAGER_SHUTDOWN_REASON` to a plain sentinel and
 * {@link fromWireReason} maps it back on the receiving thread.
 */
import { isRecord } from "@oh-my-pi/pi-utils";
import type { JobWidgetView } from "@oh-my-pi/pi-tui/tools/job-widget";
import {
	ASYNC_JOB_MANAGER_SHUTDOWN_REASON,
	type AsyncJob,
	type AsyncJobDeliveryState,
	type AsyncJobDetails,
	type AsyncJobFilter,
	type AsyncJobReapResult,
	type AsyncJobRunResult,
	type AsyncJobType,
	type EvictedJob,
} from "../../async/job-manager";
import type { JobWidgetBrief } from "../../job-widgets/types";
import type { RpcMethod } from "../rpc";
import type { WireCallback, WireUnsubscribe } from "./support";

/** Remote-object kind of the root `AsyncJobManager`. */
export const ASYNC_JOB_MANAGER_KIND = "async-job-manager";

/** Cloneable projection of one job row. */
export interface AsyncJobWire {
	readonly id: string;
	readonly type: AsyncJobType;
	readonly status: AsyncJob["status"];
	readonly startTime: number;
	readonly endTime?: number;
	readonly label: string;
	readonly intent?: string;
	readonly resultText?: string;
	readonly errorText?: string;
	readonly structured?: AsyncJob["structured"];
	readonly progressText?: string;
	readonly latestDetails?: AsyncJobDetails;
	readonly ownerId?: string;
	readonly restoreReceiptId?: string;
	readonly agentId?: string;
	readonly agentOutputPublished?: boolean;
	readonly queued?: boolean;
	readonly foreground?: boolean;
	/** The job's process: command line, start directory, and its live pids at projection time. */
	readonly process?: { readonly command: string; readonly cwd: string; readonly pids: readonly number[] };
	/** Whether the job offers widget inputs on the root's thread. */
	readonly hasWidgetInputs: boolean;
}

/** New text of one widget source since the previous delta. */
export interface JobFeedSource {
	readonly id: string;
	readonly label: string;
	readonly text: string;
	readonly open: boolean;
	/** The worker's source object for this id changed: drop the text kept so far. */
	readonly reset?: boolean;
}

/** What changed in a worker-registered job's process and widget inputs. */
export interface JobFeedDelta {
	readonly pids?: readonly number[];
	readonly brief?: JobWidgetBrief;
	readonly sources?: readonly JobFeedSource[];
}

/** Data stand-in for `process` / `widgetInputs` of a job registered from a worker. */
export interface WireJobFeed {
	readonly process?: { readonly command: string; readonly cwd: string };
	/** Present when the job offers widget inputs; their brief at registration. */
	readonly brief?: JobWidgetBrief;
	/** Reads the delta since the previous pull or push (a worker function). */
	readonly pull: () => JobFeedDelta | Promise<JobFeedDelta>;
}

/** Registration options as they cross: live inputs replaced by {@link WireJobFeed}. */
export interface WireRegisterOptions {
	readonly id?: string;
	readonly ownerId?: string;
	readonly restoreReceiptId?: string;
	readonly agentId?: string;
	readonly onProgress?: (text: string, details?: AsyncJobDetails) => void | Promise<void>;
	readonly queued?: boolean;
	readonly waitForCapacity?: boolean;
	/** The existing job endpoint handles a prepare phase; no separate callback is exported. */
	readonly prepareBeforeAdmission?: boolean;
	readonly foreground?: boolean;
	readonly intent?: string;
	readonly feed?: WireJobFeed;
}

/** The run context main hands a worker job body. */
export interface WireRunContext {
	readonly phase: "run";
	readonly jobId: string;
	/** Aborts with the wire form of the job's abort reason (see {@link fromWireReason}). */
	readonly signal: AbortSignal;
	readonly reportProgress: (text: string, details?: AsyncJobDetails) => Promise<void>;
	readonly markRunning: WireCallback<[]>;
	/** Present for jobs registered with a feed: applies the body's final delta before its result lands. */
	readonly pushFeed?: WireCallback<[delta: JobFeedDelta]>;
}

/** Dependency check of this registration only, before claiming a slot. */
export interface WirePrepareContext {
	readonly phase: "prepare";
	readonly signal: AbortSignal;
}

/** The job endpoint returns an acknowledgement for preparation, or the runner's result. */
export type WireJobRun = (ctx: WireRunContext | WirePrepareContext) => Promise<true | string | AsyncJobRunResult>;

/** A worker delivery sink as main calls it. */
export type WireDeliverySink = (jobId: string, text: string, job?: AsyncJobWire) => void | Promise<void>;

/** Remote-object protocol of kind {@link ASYNC_JOB_MANAGER_KIND}; sync methods are served synchronously on main. */
export type AsyncJobManagerProtocol = {
	hasWidgets: RpcMethod<[], boolean>;
	atCapacity: RpcMethod<[], boolean>;
	onJobSettled: RpcMethod<[listener: WireCallback<[]>], WireUnsubscribe>;
	onJobsChanged: RpcMethod<[listener: WireCallback<[]>], WireUnsubscribe>;
	register: RpcMethod<
		[type: AsyncJobType, label: string, run: WireJobRun, options: WireRegisterOptions | undefined],
		string
	>;
	publishCompleted: RpcMethod<
		[
			type: AsyncJobType,
			label: string,
			result: AsyncJobRunResult,
			options: { id?: string; ownerId?: string; agentId?: string },
		],
		string
	>;
	cancel: RpcMethod<[id: string, filter: AsyncJobFilter | undefined], boolean>;
	getJob: RpcMethod<[id: string], AsyncJobWire | undefined>;
	getRunningJobs: RpcMethod<[filter: AsyncJobFilter | undefined], AsyncJobWire[]>;
	getRecentJobs: RpcMethod<[limit: number | undefined, filter: AsyncJobFilter | undefined], AsyncJobWire[]>;
	getAllJobs: RpcMethod<[filter: AsyncJobFilter | undefined], AsyncJobWire[]>;
	backgroundJob: RpcMethod<[jobId: string], boolean>;
	releaseForegroundJob: RpcMethod<[jobId: string], void>;
	getDeliveryState: RpcMethod<[filter: AsyncJobFilter | undefined], AsyncJobDeliveryState>;
	hasPendingDeliveries: RpcMethod<[filter: AsyncJobFilter | undefined], boolean>;
	watchJobs: RpcMethod<[jobIds: string[]], number>;
	unwatchJobs: RpcMethod<[jobIds: string[]], number>;
	acknowledgeDeliveries: RpcMethod<[jobIds: string[]], number>;
	consumeJobResults: RpcMethod<[jobIds: string[]], number>;
	isJobResultConsumed: RpcMethod<[jobId: string], boolean>;
	cancelAll: RpcMethod<[filter: AsyncJobFilter | undefined, reason: unknown], void>;
	evictCompletedJobs: RpcMethod<[filter: AsyncJobFilter | undefined], number>;
	getEvictedJob: RpcMethod<[id: string, filter: AsyncJobFilter | undefined], EvictedJob | undefined>;
	getEvictedJobs: RpcMethod<[filter: AsyncJobFilter | undefined], EvictedJob[]>;
	waitForAll: RpcMethod<[], void>;
	registerDeliverySink: RpcMethod<[ownerId: string, sink: WireDeliverySink], WireUnsubscribe>;
	waitForOwnerJobs: RpcMethod<
		[ownerId: string, options: { timeoutMs?: number; excludeSuppressed?: boolean } | undefined],
		boolean
	>;
	cancelAndReapOwnerJobs: RpcMethod<[ownerId: string, deadlineAt: number], AsyncJobReapResult>;
	drainDeliveries: RpcMethod<[options: { timeoutMs?: number; filter?: AsyncJobFilter } | undefined], boolean>;
	isDeliverySuppressed: RpcMethod<[jobId: string], boolean>;
	isDeliveryPending: RpcMethod<[jobId: string], boolean>;
	isDeliverySuperseded: RpcMethod<[jobId: string], boolean>;
	/** Resolves once the job's run promise settled (immediately for unknown ids). */
	whenSettled: RpcMethod<[jobId: string], void>;
	/** The job's abort signal in wire form, or undefined for unknown ids. */
	signal: RpcMethod<[jobId: string], AbortSignal | undefined>;
	setRetainedArtifactsCleanup: RpcMethod<[jobId: string, cleanup: (() => Promise<void>) | undefined], void>;
	widgetView: RpcMethod<[jobId: string], JobWidgetView | undefined>;
	widgetCaption: RpcMethod<[jobId: string], string | undefined>;
	widgetRequestCaption: RpcMethod<[jobId: string], void>;
	widgetSubscribe: RpcMethod<[listener: WireCallback<[]>], WireUnsubscribe>;
	widgetForget: RpcMethod<[jobId: string], void>;
};

const SHUTDOWN_SENTINEL_KEY = "__ompAsyncJobManagerShutdown";

/** Abort reason as it can cross: the shutdown symbol becomes a sentinel, other symbols their description. */
export function toWireReason(reason: unknown): unknown {
	if (reason === ASYNC_JOB_MANAGER_SHUTDOWN_REASON) return { [SHUTDOWN_SENTINEL_KEY]: true };
	if (typeof reason === "symbol") return String(reason);
	return reason;
}

/** Inverse of {@link toWireReason}. */
export function fromWireReason(reason: unknown): unknown {
	return isRecord(reason) && reason[SHUTDOWN_SENTINEL_KEY] === true ? ASYNC_JOB_MANAGER_SHUTDOWN_REASON : reason;
}

const kWireSignal = Symbol("async-jobs.wireSignal");
const kLocalSignal = Symbol("async-jobs.localSignal");

/**
 * Signal derived from `signal` that aborts with {@link toWireReason} of its reason; one per
 * source signal, cached on it.
 */
export function toWireSignal(signal: AbortSignal): AbortSignal {
	return derivedSignal(signal, kWireSignal, toWireReason);
}

/** Signal derived from a received wire signal that aborts with {@link fromWireReason} of its reason. */
export function fromWireSignal(signal: AbortSignal): AbortSignal {
	return derivedSignal(signal, kLocalSignal, fromWireReason);
}

function derivedSignal(signal: AbortSignal, key: symbol, map: (reason: unknown) => unknown): AbortSignal {
	const cached: unknown = Reflect.get(signal, key);
	if (cached instanceof AbortSignal) return cached;
	const controller = new AbortController();
	if (signal.aborted) controller.abort(map(signal.reason));
	else signal.addEventListener("abort", () => controller.abort(map(signal.reason)), { once: true });
	Reflect.set(signal, key, controller.signal);
	return controller.signal;
}

/**
 * Worker-side {@link AsyncJobManagerApi} over the root's main-thread manager.
 *
 * Every query and command runs on main: synchronous methods through
 * `callSync` (`releaseForegroundJob`, which returns nothing, as an ordered
 * notification), async ones through `call`. Job rows come back as
 * {@link RemoteAsyncJob}s built from {@link AsyncJobWire} projections, with
 * local equivalents of the live fields:
 *
 * - `promise` resolves when main's run promise settles (one `whenSettled`
 *   call per job id while anyone awaits it);
 * - `abortController` is a local controller aborted with main's reason;
 * - `process` and `widgetInputs` are the original live objects for jobs this
 *   worker registered, and a pids snapshot otherwise;
 * - assigning `retainedArtifactsCleanup` forwards the closure to main's row.
 *
 * A job registered here keeps its body in this thread: main calls the `run`
 * function across the link and aborts it through the run context's signal.
 * Its `process` / `widgetInputs` stay here too; main reads them through a
 * {@link WireJobFeed} whose pulls and final push this module answers.
 */
import type { JobWidgetView } from "@oh-my-pi/pi-tui/tools/job-widget";
import type {
	AsyncJob,
	AsyncJobDeliverySink,
	AsyncJobDeliveryState,
	AsyncJobDetails,
	AsyncJobFilter,
	AsyncJobManagerApi,
	AsyncJobProcess,
	AsyncJobReapResult,
	AsyncJobRegisterOptions,
	AsyncJobRun,
	AsyncJobRunResult,
	AsyncJobType,
	EvictedJob,
} from "../../async/job-manager";
import type { JobTextSource, JobWidgetInputs, JobWidgetRegistry } from "../../job-widgets/types";
import type { RemoteObject } from "../rpc";
import {
	type AsyncJobManagerProtocol,
	type AsyncJobWire,
	fromWireSignal,
	type JobFeedDelta,
	type JobFeedSource,
	toWireReason,
	type WireJobFeed,
	type WireJobRun,
	type WireRegisterOptions,
} from "./async-jobs-protocol";
import { ignoreSettle, localUnsubscribe } from "./support";

/**
 * How long a settled job's live `process` / `widgetInputs` stay readable here
 * (e.g. `proc://<id>/streams` after the job ended). Longer than main's default
 * row retention, so the row is gone first.
 */
const LOCAL_INPUTS_RETENTION_MS = 10 * 60 * 1000;

type Remote = RemoteObject<AsyncJobManagerProtocol>;

/** Live inputs of a job registered from this worker. */
interface LocalInputs {
	readonly process?: AsyncJobProcess;
	readonly widgetInputs?: JobWidgetInputs;
}

/** Reads a worker job's live inputs as {@link JobFeedDelta}s: each source's text since the last read. */
class WorkerJobFeed {
	readonly #inputs: LocalInputs;
	readonly #offsets = new Map<string, { source: JobTextSource; end: number; open: boolean }>();

	constructor(inputs: LocalInputs) {
		this.#inputs = inputs;
	}

	wire(): WireJobFeed {
		const { process, widgetInputs } = this.#inputs;
		return {
			process: process ? { command: process.command, cwd: process.cwd } : undefined,
			brief: widgetInputs?.brief(),
			pull: () => this.delta(),
		};
	}

	delta(): JobFeedDelta {
		const { process, widgetInputs } = this.#inputs;
		if (!widgetInputs) return { pids: process ? [...process.pids()] : undefined };
		const sources: JobFeedSource[] = [];
		for (const source of widgetInputs.sources()) {
			const known = this.#offsets.get(source.id);
			const reset = known !== undefined && known.source !== source;
			const from = known && !reset ? known.end : 0;
			const chunk = source.read(from);
			this.#offsets.set(source.id, { source, end: chunk.end, open: chunk.open });
			if (chunk.text.length === 0 && known && !reset && known.open === chunk.open) continue;
			sources.push({
				id: source.id,
				label: source.label,
				text: chunk.text,
				open: chunk.open,
				...(reset ? { reset: true } : {}),
			});
		}
		return { pids: process ? [...process.pids()] : undefined, brief: widgetInputs.brief(), sources };
	}
}

/** Worker-side job row: a projection of main's row plus local stand-ins for its live fields. */
export class RemoteAsyncJob implements AsyncJob {
	readonly id: string;
	readonly type: AsyncJobType;
	readonly status: AsyncJob["status"];
	readonly startTime: number;
	readonly endTime?: number;
	readonly label: string;
	readonly intent?: string;
	readonly resultText?: string;
	readonly errorText?: string;
	readonly structured?: AsyncJob["structured"];
	readonly progressText?: string;
	readonly latestDetails?: AsyncJobDetails;
	readonly ownerId?: string;
	readonly restoreReceiptId?: string;
	readonly agentId?: string;
	readonly agentOutputPublished?: boolean;
	readonly queued?: boolean;
	readonly foreground?: boolean;
	readonly process?: AsyncJobProcess;
	readonly widgetInputs?: JobWidgetInputs;
	readonly #manager: RemoteAsyncJobManager;
	#cleanup: (() => Promise<void>) | undefined;

	constructor(manager: RemoteAsyncJobManager, wire: AsyncJobWire, local: LocalInputs | undefined) {
		this.#manager = manager;
		this.id = wire.id;
		this.type = wire.type;
		this.status = wire.status;
		this.startTime = wire.startTime;
		this.endTime = wire.endTime;
		this.label = wire.label;
		this.intent = wire.intent;
		this.resultText = wire.resultText;
		this.errorText = wire.errorText;
		this.structured = wire.structured;
		this.progressText = wire.progressText;
		this.latestDetails = wire.latestDetails;
		this.ownerId = wire.ownerId;
		this.restoreReceiptId = wire.restoreReceiptId;
		this.agentId = wire.agentId;
		this.agentOutputPublished = wire.agentOutputPublished;
		this.queued = wire.queued;
		this.foreground = wire.foreground;
		const pids = wire.process?.pids ?? [];
		this.process =
			local?.process ??
			(wire.process ? { command: wire.process.command, cwd: wire.process.cwd, pids: () => pids } : undefined);
		this.widgetInputs = local?.widgetInputs;
	}

	/** Settles when main's run promise settles; never rejects. */
	get promise(): Promise<void> {
		return this.#manager.whenSettled(this.id);
	}

	/** Local controller aborted when main aborts the job. */
	get abortController(): AbortController {
		return this.#manager.controllerFor(this.id);
	}

	get retainedArtifactsCleanup(): (() => Promise<void>) | undefined {
		return this.#cleanup;
	}

	/** Hands the cleanup to main's row, which runs it on eviction. */
	set retainedArtifactsCleanup(cleanup: (() => Promise<void>) | undefined) {
		this.#cleanup = cleanup;
		this.#manager.setRetainedArtifactsCleanup(this.id, cleanup);
	}
}

/** Worker-side {@link JobWidgetRegistry} over the root's main-thread widgets. */
class RemoteJobWidgets implements JobWidgetRegistry {
	readonly #remote: Remote;

	constructor(remote: Remote) {
		this.#remote = remote;
	}

	view(job: AsyncJob): JobWidgetView | undefined {
		return this.#remote.callSync("widgetView", job.id);
	}

	caption(job: AsyncJob): string | undefined {
		return this.#remote.callSync("widgetCaption", job.id);
	}

	requestCaption(job: AsyncJob): void {
		this.#remote.notify("widgetRequestCaption", job.id);
	}

	subscribe(listener: () => void): () => void {
		return localUnsubscribe(this.#remote.callSync("widgetSubscribe", listener));
	}

	forget(jobId: string): void {
		this.#remote.notify("widgetForget", jobId);
	}

	/** The root session owns the widgets; a worker never disposes them. */
	dispose(): void {}
}

/** Worker-side root job manager; see the module doc. */
export class RemoteAsyncJobManager implements AsyncJobManagerApi {
	readonly #remote: Remote;
	readonly #local = new Map<string, LocalInputs>();
	readonly #settled = new Map<string, Promise<void>>();
	readonly #controllers = new Map<string, AbortController>();
	#widgets: RemoteJobWidgets | null | undefined;

	constructor(remote: Remote) {
		this.#remote = remote;
	}

	get widgets(): JobWidgetRegistry | undefined {
		if (this.#widgets === undefined) {
			this.#widgets = this.#remote.callSync("hasWidgets") ? new RemoteJobWidgets(this.#remote) : null;
		}
		return this.#widgets ?? undefined;
	}

	get atCapacity(): boolean {
		return this.#remote.callSync("atCapacity");
	}

	onJobSettled(listener: () => void): () => void {
		return localUnsubscribe(this.#remote.callSync("onJobSettled", listener));
	}

	onJobsChanged(listener: () => void): () => void {
		return localUnsubscribe(this.#remote.callSync("onJobsChanged", listener));
	}

	register(type: AsyncJobType, label: string, run: AsyncJobRun, options?: AsyncJobRegisterOptions): string {
		const local: LocalInputs | undefined =
			options?.process || options?.widgetInputs
				? { process: options.process, widgetInputs: options.widgetInputs }
				: undefined;
		const feed = local ? new WorkerJobFeed(local) : undefined;
		const beforeStart = options?.waitForCapacity ? options.beforeStart : undefined;
		const wired: WireJobRun = async ctx => {
			const signal = fromWireSignal(ctx.signal);
			if (ctx.phase === "prepare") {
				signal.throwIfAborted();
				if (!beforeStart) throw new Error("Job has no admission preparation");
				await beforeStart(signal);
				signal.throwIfAborted();
				return true;
			}
			try {
				if (options?.waitForCapacity) signal.throwIfAborted();
				return await run({
					jobId: ctx.jobId,
					signal,
					reportProgress: ctx.reportProgress,
					markRunning: () => ignoreSettle(ctx.markRunning()),
				});
			} finally {
				// Sent ahead of the result, so main's final widget read sees the job's last output.
				if (feed && ctx.pushFeed) ignoreSettle(ctx.pushFeed(feed.delta()));
				if (local && !options?.waitForCapacity) this.#expireLocal(ctx.jobId, local);
			}
		};
		const wireOptions: WireRegisterOptions = {
			id: options?.id,
			ownerId: options?.ownerId,
			restoreReceiptId: options?.restoreReceiptId,
			agentId: options?.agentId,
			onProgress: options?.onProgress,
			queued: options?.queued,
			waitForCapacity: options?.waitForCapacity,
			prepareBeforeAdmission: beforeStart !== undefined,
			foreground: options?.foreground,
			intent: options?.intent,
			feed: feed?.wire(),
		};
		const id = this.#remote.callSync("register", type, label, wired, wireOptions);
		if (local) {
			this.#local.set(id, local);
			if (options?.waitForCapacity) void this.whenSettled(id).then(() => this.#expireLocal(id, local));
		}
		return id;
	}

	publishCompleted(
		type: AsyncJobType,
		label: string,
		result: AsyncJobRunResult,
		options: { id?: string; ownerId?: string; agentId?: string },
	): string {
		return this.#remote.callSync("publishCompleted", type, label, result, options);
	}

	cancel(id: string, filter?: AsyncJobFilter): boolean {
		return this.#remote.callSync("cancel", id, filter);
	}

	getJob(id: string): AsyncJob | undefined {
		const wire = this.#remote.callSync("getJob", id);
		if (!wire) {
			this.#local.delete(id);
			return undefined;
		}
		return this.#row(wire);
	}

	getRunningJobs(filter?: AsyncJobFilter): AsyncJob[] {
		return this.#rows(this.#remote.callSync("getRunningJobs", filter));
	}

	getRecentJobs(limit?: number, filter?: AsyncJobFilter): AsyncJob[] {
		return this.#rows(this.#remote.callSync("getRecentJobs", limit, filter));
	}

	getAllJobs(filter?: AsyncJobFilter): AsyncJob[] {
		return this.#rows(this.#remote.callSync("getAllJobs", filter));
	}

	backgroundJob(jobId: string): boolean {
		return this.#remote.callSync("backgroundJob", jobId);
	}

	/** A notification: nothing to wait for, and every later call reaches main after it. */
	releaseForegroundJob(jobId: string): void {
		this.#remote.notify("releaseForegroundJob", jobId);
	}

	getDeliveryState(filter?: AsyncJobFilter): AsyncJobDeliveryState {
		return this.#remote.callSync("getDeliveryState", filter);
	}

	hasPendingDeliveries(filter?: AsyncJobFilter): boolean {
		return this.#remote.callSync("hasPendingDeliveries", filter);
	}

	watchJobs(jobIds: string[]): number {
		return this.#remote.callSync("watchJobs", jobIds);
	}

	unwatchJobs(jobIds: string[]): number {
		return this.#remote.callSync("unwatchJobs", jobIds);
	}

	acknowledgeDeliveries(jobIds: string[]): number {
		return this.#remote.callSync("acknowledgeDeliveries", jobIds);
	}

	consumeJobResults(jobIds: string[]): number {
		return this.#remote.callSync("consumeJobResults", jobIds);
	}

	isJobResultConsumed(jobId: string): boolean {
		return this.#remote.callSync("isJobResultConsumed", jobId);
	}

	cancelAll(filter?: AsyncJobFilter, reason?: unknown): void {
		this.#remote.callSync("cancelAll", filter, toWireReason(reason));
	}

	evictCompletedJobs(filter?: AsyncJobFilter): number {
		return this.#remote.callSync("evictCompletedJobs", filter);
	}

	getEvictedJob(id: string, filter?: AsyncJobFilter): EvictedJob | undefined {
		return this.#remote.callSync("getEvictedJob", id, filter);
	}

	getEvictedJobs(filter?: AsyncJobFilter): EvictedJob[] {
		return this.#remote.callSync("getEvictedJobs", filter);
	}

	waitForAll(): Promise<void> {
		return this.#remote.call("waitForAll");
	}

	registerDeliverySink(ownerId: string, sink: AsyncJobDeliverySink): () => void {
		return localUnsubscribe(
			this.#remote.callSync("registerDeliverySink", ownerId, (jobId, text, job) =>
				sink(jobId, text, job ? this.#row(job) : undefined),
			),
		);
	}

	waitForOwnerJobs(ownerId: string, options?: { timeoutMs?: number; excludeSuppressed?: boolean }): Promise<boolean> {
		return this.#remote.call("waitForOwnerJobs", ownerId, options);
	}

	cancelAndReapOwnerJobs(ownerId: string, deadlineAt: number): Promise<AsyncJobReapResult> {
		return this.#remote.call("cancelAndReapOwnerJobs", ownerId, deadlineAt);
	}

	drainDeliveries(options?: { timeoutMs?: number; filter?: AsyncJobFilter }): Promise<boolean> {
		return this.#remote.call("drainDeliveries", options);
	}

	isDeliverySuppressed(jobId: string): boolean {
		return this.#remote.callSync("isDeliverySuppressed", jobId);
	}

	isDeliveryPending(jobId: string): boolean {
		return this.#remote.callSync("isDeliveryPending", jobId);
	}

	isDeliverySuperseded(jobId: string): boolean {
		return this.#remote.callSync("isDeliverySuperseded", jobId);
	}

	/** One main `whenSettled` call per job id while it is pending; resolves (never rejects) on settle or link loss. */
	whenSettled(jobId: string): Promise<void> {
		let settled = this.#settled.get(jobId);
		if (!settled) {
			settled = this.#remote.call("whenSettled", jobId).then(
				() => {
					this.#settled.delete(jobId);
				},
				() => {
					this.#settled.delete(jobId);
				},
			);
			this.#settled.set(jobId, settled);
		}
		return settled;
	}

	/** Local controller for `jobId`, aborted with main's (unmapped) reason; one per job while it runs. */
	controllerFor(jobId: string): AbortController {
		const existing = this.#controllers.get(jobId);
		if (existing) return existing;
		const controller = new AbortController();
		const signal = this.#remote.callSync("signal", jobId);
		if (!signal) return controller;
		const local = fromWireSignal(signal);
		if (local.aborted) {
			controller.abort(local.reason);
			return controller;
		}
		this.#controllers.set(jobId, controller);
		local.addEventListener("abort", () => controller.abort(local.reason), { once: true });
		void this.whenSettled(jobId).then(() => {
			if (this.#controllers.get(jobId) === controller) this.#controllers.delete(jobId);
		});
		return controller;
	}

	/** Forward a row's `retainedArtifactsCleanup` assignment to main. */
	setRetainedArtifactsCleanup(jobId: string, cleanup: (() => Promise<void>) | undefined): void {
		this.#remote.notify("setRetainedArtifactsCleanup", jobId, cleanup);
	}

	#row(wire: AsyncJobWire): RemoteAsyncJob {
		return new RemoteAsyncJob(this, wire, this.#local.get(wire.id));
	}

	#rows(wires: AsyncJobWire[]): AsyncJob[] {
		return wires.map(wire => this.#row(wire));
	}

	/** Drop a settled job's live inputs once main's row is certainly gone. */
	#expireLocal(jobId: string, local: LocalInputs): void {
		const timer = setTimeout(() => {
			if (this.#local.get(jobId) === local) this.#local.delete(jobId);
		}, LOCAL_INPUTS_RETENTION_MS);
		timer.unref();
	}
}

/**
 * The root `AsyncJobManager` across subagent worker links (kind
 * `"async-job-manager"`, protocol in `./async-jobs-protocol`).
 *
 * Main side: every manager crossing to a worker is served by reference. Job ids,
 * rows, the running-job cap, delivery queues and sinks stay on the root's
 * manager; a worker-registered job's body runs in the worker (its `run`
 * function crosses), and main's cancellation aborts it through the run
 * context's signal. Delivery sinks, settle listeners and widget subscriptions a
 * worker registered are dropped when it exits, so owned deliveries dead-letter
 * exactly as for a disposed in-process session.
 *
 * A worker job's `process` and `widgetInputs` arrive as a {@link WireJobFeed};
 * {@link JobFeedMirror} keeps the latest pids, brief and source text main
 * pulled (each synchronous read starts one background pull) or the body pushed
 * as it settled, so the widget registry's final read sees the job's last output.
 *
 * Worker side: see `./async-jobs-remote`.
 */
import {
	type AsyncJob,
	AsyncJobError,
	AsyncJobManager,
	type AsyncJobProcess,
	type AsyncJobRegisterOptions,
} from "../../async/job-manager";
import { TextTap } from "../../job-widgets/text-tap";
import type { JobTextSource, JobWidgetBrief, JobWidgetInputs } from "../../job-widgets/types";
import type { ThreadId } from "../identity";
import { registerRpcError, type RpcServe } from "../rpc";
import type { ThreadService, WorkerPeer } from "../services";
import {
	ASYNC_JOB_MANAGER_KIND,
	type AsyncJobManagerProtocol,
	type AsyncJobWire,
	fromWireReason,
	type JobFeedDelta,
	toWireSignal,
	type WireJobFeed,
	type WireRegisterOptions,
	type WireRunContext,
} from "./async-jobs-protocol";
import { RemoteAsyncJobManager } from "./async-jobs-remote";
import { ignoreSettle, PeerCleanups } from "./support";

registerRpcError("AsyncJobError", message => new AsyncJobError(message));

// ─────────────────────────────────────────────────────────────────────────────
// Main side
// ─────────────────────────────────────────────────────────────────────────────

/** Main-side mirror of a worker job's process. */
class MirroredProcess implements AsyncJobProcess {
	constructor(
		readonly command: string,
		readonly cwd: string,
		readonly mirror: JobFeedMirror,
	) {}

	pids(): readonly number[] {
		this.mirror.refresh();
		return this.mirror.pids;
	}
}

/** Main-side mirror of one worker widget source: the text received so far. */
class MirroredSource extends TextTap {}

/** Latest data of a worker job's {@link WireJobFeed}; implements its widget inputs over it. */
class JobFeedMirror implements JobWidgetInputs {
	readonly process: MirroredProcess | undefined;
	readonly widgetInputs: JobWidgetInputs | undefined;
	pids: readonly number[] = [];
	#brief: JobWidgetBrief | undefined;
	readonly #sources = new Map<string, MirroredSource>();
	readonly #pull: WireJobFeed["pull"];
	#pulling = false;
	#done = false;

	constructor(feed: WireJobFeed) {
		this.#pull = feed.pull;
		this.#brief = feed.brief;
		this.process = feed.process ? new MirroredProcess(feed.process.command, feed.process.cwd, this) : undefined;
		this.widgetInputs = feed.brief ? this : undefined;
	}

	/** Start one background pull unless one is in flight or the job settled. */
	refresh(): void {
		if (this.#pulling || this.#done) return;
		this.#pulling = true;
		Promise.resolve(this.#pull()).then(
			delta => {
				this.#pulling = false;
				if (!this.#done) this.apply(delta);
			},
			() => {
				// Closed link or dead worker: keep the last data, stop pulling.
				this.#done = true;
			},
		);
	}

	/** Adopt a delta; `final` is the settled body's last one, after which no pulls run. */
	apply(delta: JobFeedDelta, final = false): void {
		if (delta.pids) this.pids = delta.pids;
		if (delta.brief) this.#brief = delta.brief;
		for (const source of delta.sources ?? []) {
			let mirror = this.#sources.get(source.id);
			if (!mirror || source.reset) {
				mirror = new MirroredSource(source.id, source.label);
				this.#sources.set(source.id, mirror);
			}
			mirror.append(source.text);
			if (!source.open) mirror.close();
		}
		if (final) {
			this.#done = true;
			this.pids = [];
			for (const mirror of this.#sources.values()) mirror.close();
		}
	}

	sources(): readonly JobTextSource[] {
		this.refresh();
		return Array.from(this.#sources.values());
	}

	brief(): JobWidgetBrief {
		this.refresh();
		if (!this.#brief) throw new Error("Job has no widget brief");
		return this.#brief;
	}
}

/** Cloneable projection of a main job row. */
export function toJobWire(job: AsyncJob): AsyncJobWire {
	const process = job.process;
	return {
		id: job.id,
		type: job.type,
		status: job.status,
		startTime: job.startTime,
		endTime: job.endTime,
		label: job.label,
		intent: job.intent,
		resultText: job.resultText,
		errorText: job.errorText,
		structured: job.structured,
		progressText: job.progressText,
		latestDetails: job.latestDetails,
		ownerId: job.ownerId,
		restoreReceiptId: job.restoreReceiptId,
		agentId: job.agentId,
		agentOutputPublished: job.agentOutputPublished,
		queued: job.queued,
		foreground: job.foreground,
		process: process
			? {
					command: process.command,
					cwd: process.cwd,
					// A mirror's cached pids: projecting must not pull from the worker that runs the job.
					pids:
						job.status !== "running"
							? []
							: process instanceof MirroredProcess
								? process.mirror.pids
								: [...process.pids()],
				}
			: undefined,
		hasWidgetInputs: job.widgetInputs !== undefined,
	};
}

function toJobWires(jobs: readonly AsyncJob[]): AsyncJobWire[] {
	return jobs.map(toJobWire);
}

/** Main-side registration options for a worker job. */
function mainRegisterOptions(options: WireRegisterOptions | undefined, feed: JobFeedMirror | undefined) {
	const result: AsyncJobRegisterOptions = {
		id: options?.id,
		ownerId: options?.ownerId,
		restoreReceiptId: options?.restoreReceiptId,
		agentId: options?.agentId,
		onProgress: options?.onProgress,
		queued: options?.queued,
		waitForCapacity: options?.waitForCapacity,
		foreground: options?.foreground,
		intent: options?.intent,
		process: feed?.process,
		widgetInputs: feed?.widgetInputs,
	};
	return result;
}

/** Everything workers registered on main managers (sinks, listeners, subscriptions). */
const cleanups = new PeerCleanups(ASYNC_JOB_MANAGER_KIND);

function serveManager(threadId: ThreadId): RpcServe<AsyncJobManager, AsyncJobManagerProtocol> {
	return {
		hasWidgets: manager => manager.widgets !== undefined,
		atCapacity: manager => manager.atCapacity,
		onJobSettled: (manager, listener) =>
			cleanups.track(
				threadId,
				manager.onJobSettled(() => ignoreSettle(listener())),
			),
		onJobsChanged: (manager, listener) =>
			cleanups.track(
				threadId,
				manager.onJobsChanged(() => ignoreSettle(listener())),
			),
		register: (manager, type, label, run, options) => {
			const feed = options?.feed ? new JobFeedMirror(options.feed) : undefined;
			const admissionOptions = mainRegisterOptions(options, feed);
			if (options?.waitForCapacity && options.prepareBeforeAdmission) {
				admissionOptions.beforeStart = async signal => {
					if ((await run({ phase: "prepare", signal: toWireSignal(signal) })) !== true) {
						throw new Error("Worker did not acknowledge job admission readiness");
					}
				};
			}
			const id = manager.register(
				type,
				label,
				async ctx => {
					const wire: WireRunContext = {
						phase: "run",
						jobId: ctx.jobId,
						signal: toWireSignal(ctx.signal),
						reportProgress: ctx.reportProgress,
						markRunning: ctx.markRunning,
						pushFeed: feed ? delta => feed.apply(delta, true) : undefined,
					};
					const result = await run(wire);
					if (result === true)
						throw new Error("Worker returned an admission acknowledgement instead of a job result");
					return result;
				},
				admissionOptions,
			);
			if (options?.waitForCapacity) {
				const job = manager.getJob(id);
				if (job) {
					const untrack = cleanups.track(threadId, () => {
						// An id can be reused after eviction; never cancel its replacement.
						if (manager.getJob(id) === job) manager.cancel(id);
					});
					void job.promise.then(untrack, untrack);
				}
			}
			return id;
		},
		publishCompleted: (manager, type, label, result, options) =>
			manager.publishCompleted(type, label, result, options),
		cancel: (manager, id, filter) => manager.cancel(id, filter),
		getJob: (manager, id) => {
			const job = manager.getJob(id);
			return job ? toJobWire(job) : undefined;
		},
		getRunningJobs: (manager, filter) => toJobWires(manager.getRunningJobs(filter)),
		getRecentJobs: (manager, limit, filter) => toJobWires(manager.getRecentJobs(limit, filter)),
		getAllJobs: (manager, filter) => toJobWires(manager.getAllJobs(filter)),
		backgroundJob: (manager, jobId) => manager.backgroundJob(jobId),
		releaseForegroundJob: (manager, jobId) => manager.releaseForegroundJob(jobId),
		getDeliveryState: (manager, filter) => manager.getDeliveryState(filter),
		hasPendingDeliveries: (manager, filter) => manager.hasPendingDeliveries(filter),
		watchJobs: (manager, jobIds) => manager.watchJobs(jobIds),
		unwatchJobs: (manager, jobIds) => manager.unwatchJobs(jobIds),
		acknowledgeDeliveries: (manager, jobIds) => manager.acknowledgeDeliveries(jobIds),
		consumeJobResults: (manager, jobIds) => manager.consumeJobResults(jobIds),
		isJobResultConsumed: (manager, jobId) => manager.isJobResultConsumed(jobId),
		cancelAll: (manager, filter, reason) => manager.cancelAll(filter, fromWireReason(reason)),
		evictCompletedJobs: (manager, filter) => manager.evictCompletedJobs(filter),
		getEvictedJob: (manager, id, filter) => manager.getEvictedJob(id, filter),
		getEvictedJobs: (manager, filter) => manager.getEvictedJobs(filter),
		waitForAll: manager => manager.waitForAll(),
		registerDeliverySink: (manager, ownerId, sink) =>
			cleanups.track(
				threadId,
				manager.registerDeliverySink(ownerId, (jobId, text, job) =>
					sink(jobId, text, job ? toJobWire(job) : undefined),
				),
			),
		waitForOwnerJobs: (manager, ownerId, options) => manager.waitForOwnerJobs(ownerId, options),
		cancelAndReapOwnerJobs: (manager, ownerId, deadlineAt) => manager.cancelAndReapOwnerJobs(ownerId, deadlineAt),
		drainDeliveries: (manager, options) => manager.drainDeliveries(options),
		isDeliverySuppressed: (manager, jobId) => manager.isDeliverySuppressed(jobId),
		isDeliveryPending: (manager, jobId) => manager.isDeliveryPending(jobId),
		isDeliverySuperseded: (manager, jobId) => manager.isDeliverySuperseded(jobId),
		whenSettled: async (manager, jobId) => {
			await manager.getJob(jobId)?.promise;
		},
		signal: (manager, jobId) => {
			const job = manager.getJob(jobId);
			return job ? toWireSignal(job.abortController.signal) : undefined;
		},
		setRetainedArtifactsCleanup: (manager, jobId, cleanup) => {
			const job = manager.getJob(jobId);
			if (job) job.retainedArtifactsCleanup = cleanup;
		},
		widgetView: (manager, jobId) => {
			const job = manager.getJob(jobId);
			return job ? manager.widgets?.view(job) : undefined;
		},
		widgetCaption: (manager, jobId) => {
			const job = manager.getJob(jobId);
			return job ? manager.widgets?.caption(job) : undefined;
		},
		widgetRequestCaption: (manager, jobId) => {
			const job = manager.getJob(jobId);
			if (job) manager.widgets?.requestCaption(job);
		},
		widgetSubscribe: (manager, listener) => {
			const widgets = manager.widgets;
			if (!widgets) return () => {};
			return cleanups.track(
				threadId,
				widgets.subscribe(() => ignoreSettle(listener())),
			);
		},
		widgetForget: (manager, jobId) => manager.widgets?.forget(jobId),
	};
}

function installMain(peer: WorkerPeer): void {
	peer.link.exportClass<AsyncJobManager, AsyncJobManagerProtocol>(
		ASYNC_JOB_MANAGER_KIND,
		(value): value is AsyncJobManager => value instanceof AsyncJobManager,
		serveManager(peer.threadId),
	);
}

/**
 * Root `AsyncJobManager`s for subagent workers: main serves them by reference, workers use
 * {@link RemoteAsyncJobManager}. See the module doc.
 */
export const asyncJobsThreadService: ThreadService = {
	name: ASYNC_JOB_MANAGER_KIND,
	installMain,
	onWorkerExit: peer => cleanups.release(peer.threadId),
	installWorker(link) {
		link.importClass<RemoteAsyncJobManager, AsyncJobManagerProtocol>(
			ASYNC_JOB_MANAGER_KIND,
			remote => new RemoteAsyncJobManager(remote),
		);
	},
};

/**
 * Wire model of agent sessions homed on another thread.
 *
 * A worker's `SessionPublisher` pushes a {@link SessionMirrorState} (plus the
 * message list and, while watched, the event stream) to the main thread, where
 * a `RemoteAgentSession` serves the {@link AgentSessionHandle} surface from it.
 * Workers reach sessions homed elsewhere through `PeerAgentSession`, which
 * reads the same fields from main through {@link SessionBridgeProtocol.read}.
 *
 * While main watches a session (the main-thread TUI focused on it, or any
 * other main subscriber), the publisher also pushes a {@link SessionViewState}
 * and the session's entry list, which back the `AgentViewSession` surface of
 * the mirror; unwatched sessions never pay for them.
 *
 * Everything here is data: models, messages, and events pass through
 * {@link toWireData}, which strips functions and flattens foreign class
 * instances so a session's state never drags live objects across a link. The
 * exceptions are main-owned objects a worker session was built over (its
 * model registry, async job manager, settings), which travel back to main as
 * references to the originals.
 */
import type { AsyncJobManagerApi } from "../async/job-manager";
import type { AgentMessage, ThinkingLevel } from "@oh-my-pi/pi-agent-core";
import type { Effort, ImageContent, Model, ServiceTierByFamily, ToolResultMessage, UsageReport } from "@oh-my-pi/pi-ai";
import type { ConfiguredThinkingLevel } from "@oh-my-pi/pi-tui/thinking";
import type { IrcMessage } from "@oh-my-pi/pi-tui/tools/irc";
import type { TodoPhase } from "@oh-my-pi/pi-tui/tools/todo";
import type { Rule } from "../capability/rule";
import type { EffectiveExtensionRoots } from "../capability/types";
import type { ModelRegistry } from "../config/model-registry";
import type { OverlayLayers, Settings } from "../config/settings";
import type { ContextUsage } from "../extensibility/extensions/types";
import type { Skill } from "../extensibility/skills";
import type { GoalModeState } from "../goals/state";
import type {
	AgentSessionAdvisorOverview,
	AgentSessionHandle,
	AgentViewToolSchema,
	ToolExecutionUpdateEvent,
} from "../session/agent-session-handle";
import type { AgentSessionEvent, AgentSessionEventListener } from "../session/agent-session-events";
import type {
	AgentSessionDisposeOptions,
	EphemeralTurnOptions,
	EphemeralTurnResult,
	Prewalk,
	PromptOptions,
	ResolvedRoleModel,
	RestoredQueuedMessage,
	RoleModelCycleResult,
	SessionStats,
	SteerOptions,
} from "../session/agent-session-types";
import type { IdleMaintenanceOptions } from "../session/idle-maintenance";
import type { CustomMessage } from "../session/messages";
import type { ServingModel } from "../session/retry-fallback-chains";
import type { ModelUsageRecord, SessionEntry, UsageStatistics } from "../session/session-entries";
import type { AgentDefinition } from "../task/types";
import type { WorkPoolYieldItem } from "../task/workpool-yield";
import type { RemoteObject, RpcMethod } from "./rpc";

/** Data a session homed on another thread exposes synchronously. */
export interface SessionMirrorState {
	isStreaming: boolean;
	runStartedAt: number | undefined;
	ircWakesPending: boolean;
	hasPendingWake: boolean;
	/** Senders with a message still queued for a turn of its own (backs `hasQueuedIrcFrom`). */
	ircQueuedFrom: string[];
	isPaused: boolean;
	streamMessage: AgentMessage | null;
	pendingToolCalls: string[];
	model: Model | undefined;
	servingModel: ServingModel | undefined;
	thinkingLevel: ThinkingLevel | undefined;
	sessionFile: string | undefined;
	sessionId: string;
	cwd: string;
	artifactsDir: string | null;
	usageStatistics: UsageStatistics;
	sessionStats: SessionStats;
	advisorOverview: AgentSessionAdvisorOverview;
	sessionAgents: AgentDefinition[];
	hindsightActive: boolean;
	effectiveExtensionRoots: EffectiveExtensionRoots;
}

/** One field of {@link SessionMirrorState}. */
export type SessionStateField = keyof SessionMirrorState;

/** Fields a worker can read on a session homed elsewhere (queued senders are only mirrored, never polled). */
export type PeerStateField = Exclude<SessionStateField, "ircQueuedFrom">;

/** Change to a mirrored message list. */
export type SessionMessagesDelta =
	| { readonly kind: "append"; readonly messages: AgentMessage[] }
	| { readonly kind: "replace"; readonly messages: AgentMessage[] };

/** Run-state transition reported by `subscribeRunState`. */
export type SessionRunState = "running" | "idle";

/** Change to a mirrored session entry list. */
export type SessionEntriesDelta =
	| { readonly kind: "append"; readonly entries: SessionEntry[] }
	| { readonly kind: "replace"; readonly entries: SessionEntry[] };

/**
 * Where a worker session's settings come from: the main instance its worker
 * chain mirrors (null when the chain's root is a worker-local instance) and the
 * own layers of every worker-local overlay below it, outermost first. Main
 * rebuilds an equivalent with `restoreOverlay`.
 */
export interface SessionSettingsSource {
	readonly base: Settings | null;
	readonly layers: OverlayLayers[];
}

/** Queue chips of a session (see `AgentSession.getQueuedMessages`). */
export interface SessionQueuedMessages {
	readonly steering: readonly string[];
	readonly followUp: readonly string[];
	readonly liveSteered: number;
}

/** User-authored queued messages in queue order, as `popLastQueuedMessage` restores them. */
export interface SessionRestorableQueue {
	readonly steering: SessionQueuedEntry[];
	readonly followUp: SessionQueuedEntry[];
}

/**
 * One user-authored queued message under the id its home tagged it with. The
 * id stays put while the message sits in a queue; a message that goes back to
 * a queue after it was claimed for delivery comes back under a fresh id.
 */
export interface SessionQueuedEntry {
	readonly id: string;
	readonly message: RestoredQueuedMessage;
	/** Already claimed for delivery (its batch is being prepared); not restorable. */
	readonly claimed: boolean;
}

/** View-only data of a worker-homed session, published while main watches it (see the module doc). */
export interface SessionViewState {
	/** Provider-facing session id (`AgentSession.sessionId`). */
	providerSessionId: string;
	sessionName: string | undefined;
	leafId: string | null;
	/** Effort applied to the agent loop (`agent.state.thinkingLevel`). */
	agentEffort: Effort | undefined;
	tools: AgentViewToolSchema[];
	/** Every registered tool name (active or not), which `getToolByName` can answer for. */
	toolNames: string[];
	/** The registered names that came from a built-in factory. */
	builtInTools: string[];
	pendingToolResults: ToolResultMessage[];
	/** Tool calls emitted by the current run (kept live by a mid-turn transcript rebuild). */
	runToolCallIds: string[];
	systemPrompt: string[];
	skills: Skill[];
	/** TTSR rules; null when the session has no TTSR manager. */
	rules: Rule[] | null;
	/** Published only while idle (false mid-run), the one time the retry hint reads it. */
	hasAbortedToolCallTail: boolean;
	isAutoThinking: boolean;
	isCompacting: boolean;
	compactionSpeculation: "idle" | "running" | "armed";
	contextUsageRevision: number;
	contextUsage: ContextUsage | undefined;
	isRetrying: boolean;
	retryAttempt: number;
	isTtsrAbortPending: boolean;
	hasInterruptibleInput: boolean;
	autoResolvedThinkingLevel: Effort | undefined;
	configuredThinkingLevel: ConfiguredThinkingLevel | undefined;
	availableEffortSelectors: ConfiguredThinkingLevel[];
	serviceTierByFamily: ServiceTierByFamily;
	fastModeActive: boolean;
	anthropicSlowModeLabel: string | undefined;
	prewalk: Prewalk | undefined;
	goalMode: GoalModeState | undefined;
	advisorCost: number;
	advisorUsingSubscription: boolean;
	todoPhases: TodoPhase[];
	queuedMessages: SessionQueuedMessages;
	restorableQueue: SessionRestorableQueue;
	ephemeralMaxTokensPreservesRequest: boolean;
	settings: SessionSettingsSource;
	/**
	 * Latest updates of tools still running. Sent only in the full snapshot that
	 * starts a watch; main keeps it current from the forwarded event stream.
	 */
	activeToolExecutionUpdates: ToolExecutionUpdateEvent[];
}

/** One field of {@link SessionViewState}. */
export type SessionViewField = keyof SessionViewState;

/** Payload of {@link SessionBridgeProtocol.opened}. */
export interface SessionOpened {
	readonly key: string;
	/** Registry id the session runs as, when it has one. */
	readonly agentId: string | undefined;
	/** The worker's publisher, imported on main as a `SessionHostClient`. */
	readonly host: object;
	readonly state: SessionMirrorState;
	readonly messages: AgentMessage[];
	/** Main registry the session's registry mirrors; null when the worker built its own. */
	readonly modelRegistry: ModelRegistry | null;
	/** Main async job manager the session registers jobs with; null when it has none or a worker-local one. */
	readonly asyncJobManager: AsyncJobManagerApi | null;
}

/** Abort options of `AgentSessionHandle.abort`. */
export interface SessionAbortOptions {
	goalReason?: "interrupted" | "internal";
	reason?: string;
	preserveCompaction?: boolean;
	deliverQueuedMessages?: boolean;
}

/**
 * Remote-object protocol (kind `"agent-session-host"`) the main thread speaks
 * to a worker's publisher: commands on the worker-homed session plus the
 * event-stream watch toggle.
 */
export type SessionHostProtocol = {
	prompt: RpcMethod<[text: string, options?: PromptOptions], boolean>;
	steer: RpcMethod<[text: string, images?: ImageContent[], options?: SteerOptions], void>;
	abort: RpcMethod<[options?: SessionAbortOptions], void>;
	dispose: RpcMethod<[options?: AgentSessionDisposeOptions], void>;
	deliverIrcMessage: RpcMethod<[msg: IrcMessage], "injected" | "woken">;
	waitForIrcReplies: RpcMethod<[], void>;
	setWorkPoolYieldItems: RpcMethod<[items: readonly WorkPoolYieldItem[]], void>;
	acquireRestoreIdleHold: RpcMethod<
		[expectedSessionFile: string, manager: AsyncJobManagerApi, signal: AbortSignal],
		string
	>;
	releaseRestoreIdleHold: RpcMethod<[token: string], boolean>;
	hasRestorePendingReceipt: RpcMethod<[token: string], boolean>;
	finishRestoreIdleHold: RpcMethod<[token: string, discard: boolean], boolean>;
	waitForRunEnd: RpcMethod<[], void>;
	emitIrcRelayObservation: RpcMethod<[record: CustomMessage], void>;
	/** Start (true) or stop (false) forwarding the full event stream and the view state. */
	watch: RpcMethod<[on: boolean], void>;
	settleInFlightMessagePersistence: RpcMethod<[], void>;
	setThinkingLevel: RpcMethod<[level: ConfiguredThinkingLevel | undefined, persist?: boolean], void>;
	/**
	 * Retire queued message `id` (main restored it): take it out of its queue,
	 * or keep whatever holds it aside from putting it back. Resolves once it can
	 * never be delivered.
	 */
	popQueuedMessage: RpcMethod<[id: string], void>;
	setTodoPhases: RpcMethod<[phases: TodoPhase[]], void>;
	appendCustomEntry: RpcMethod<[customType: string, data: unknown], void>;
	appendModelUsage: RpcMethod<[usage: ModelUsageRecord, owner: { sessionId: string; parentId: string | null }], void>;
	flushSession: RpcMethod<[], void>;
	ensureOnDisk: RpcMethod<[], void>;
	getArtifactPath: RpcMethod<[id: string], string | null>;
	resume: RpcMethod<[], void>;
	retry: RpcMethod<[], boolean>;
	abortRetry: RpcMethod<[], void>;
	abortCompaction: RpcMethod<[reason?: unknown], void>;
	setModelTemporary: RpcMethod<
		[model: Model, thinkingLevel?: ConfiguredThinkingLevel, options?: { ephemeral?: boolean }],
		void
	>;
	cycleRoleModels: RpcMethod<
		[roleOrder: readonly string[], direction?: "forward" | "backward"],
		RoleModelCycleResult | undefined
	>;
	applyRoleModel: RpcMethod<[entry: ResolvedRoleModel], void>;
	fetchUsageReports: RpcMethod<[signal?: AbortSignal], UsageReport[] | null>;
	runEphemeralTurn: RpcMethod<[args: EphemeralTurnOptions], EphemeralTurnResult>;
	exportToHtml: RpcMethod<[outputPath?: string, useUserThemes?: boolean], string>;
	enableIdleMaintenance: RpcMethod<[options: IdleMaintenanceOptions], void>;
	refreshIdleMaintenance: RpcMethod<[], void>;
};

/**
 * Remote-object protocol (kind `"agent-session-bridge"`) a worker speaks to
 * its main-thread bridge: publisher notifications for sessions homed on the
 * worker, and peer access to sessions homed elsewhere (main answers from its
 * local session or its mirror, and routes commands to the home thread).
 */
export type SessionBridgeProtocol = {
	opened: RpcMethod<[opened: SessionOpened], void>;
	patch: RpcMethod<[key: string, patch: Partial<SessionMirrorState>], void>;
	messages: RpcMethod<[key: string, delta: SessionMessagesDelta], void>;
	event: RpcMethod<[key: string, event: AgentSessionEvent], void>;
	runState: RpcMethod<[key: string, state: SessionRunState], void>;
	/**
	 * Watch started: the full view state, and what main's entry list (kept across
	 * watches) lacks; undefined when it is current.
	 */
	view: RpcMethod<[key: string, state: SessionViewState, entries: SessionEntriesDelta | undefined], void>;
	viewPatch: RpcMethod<[key: string, patch: Partial<SessionViewState>], void>;
	/**
	 * Synchronous, from the agent's queued-message gate: queued entries `ids` are
	 * about to be delivered. Returns those main already restored (they must be
	 * dropped); the rest count as claimed and are no longer restorable on main.
	 */
	claimQueued: RpcMethod<[key: string, ids: string[]], string[]>;
	entries: RpcMethod<[key: string, delta: SessionEntriesDelta], void>;
	closed: RpcMethod<[key: string], void>;
	read: RpcMethod<[session: AgentSessionHandle, fields: readonly PeerStateField[]], Partial<SessionMirrorState>>;
	readMessages: RpcMethod<[session: AgentSessionHandle], AgentMessage[]>;
	hasQueuedIrcFrom: RpcMethod<[session: AgentSessionHandle, from: string], boolean>;
	subscribe: RpcMethod<[session: AgentSessionHandle, listener: AgentSessionEventListener], () => void>;
	subscribeRunState: RpcMethod<[session: AgentSessionHandle, listener: (state: SessionRunState) => void], () => void>;
	prompt: RpcMethod<[session: AgentSessionHandle, text: string, options?: PromptOptions], boolean>;
	steer: RpcMethod<[session: AgentSessionHandle, text: string, images?: ImageContent[], options?: SteerOptions], void>;
	abort: RpcMethod<[session: AgentSessionHandle, options?: SessionAbortOptions], void>;
	dispose: RpcMethod<[session: AgentSessionHandle, options?: AgentSessionDisposeOptions], void>;
	deliverIrcMessage: RpcMethod<[session: AgentSessionHandle, msg: IrcMessage], "injected" | "woken">;
	waitForIrcReplies: RpcMethod<[session: AgentSessionHandle], void>;
	setWorkPoolYieldItems: RpcMethod<[session: AgentSessionHandle, items: readonly WorkPoolYieldItem[]], void>;
	acquireRestoreIdleHold: RpcMethod<
		[session: AgentSessionHandle, expectedSessionFile: string, manager: AsyncJobManagerApi, signal: AbortSignal],
		string
	>;
	releaseRestoreIdleHold: RpcMethod<[session: AgentSessionHandle, token: string], boolean>;
	hasRestorePendingReceipt: RpcMethod<[session: AgentSessionHandle, token: string], boolean>;
	finishRestoreIdleHold: RpcMethod<[session: AgentSessionHandle, token: string, discard: boolean], boolean>;
	waitForRunEnd: RpcMethod<[session: AgentSessionHandle], void>;
	emitIrcRelayObservation: RpcMethod<[session: AgentSessionHandle, record: CustomMessage], void>;
};

/** Worker-side proxy of the main thread's bridge (remote-object kind `"agent-session-bridge"`). */
export class SessionBridgeClient {
	constructor(readonly remote: RemoteObject<SessionBridgeProtocol>) {}
}

/** Readers of every {@link PeerStateField} on any handle, returning wire-safe data. */
export const SESSION_STATE_READERS: {
	readonly [K in PeerStateField]: (session: AgentSessionHandle) => SessionMirrorState[K];
} = {
	isStreaming: session => session.isStreaming,
	runStartedAt: session => session.runStartedAt,
	ircWakesPending: session => session.ircWakesPending,
	hasPendingWake: session => session.hasPendingWake,
	isPaused: session => session.agent.isPaused,
	streamMessage: session => toWireData(session.agent.state.streamMessage),
	pendingToolCalls: session => [...session.agent.state.pendingToolCalls],
	model: session => toWireData(session.model),
	servingModel: session => toWireData(session.servingModel),
	thinkingLevel: session => session.thinkingLevel,
	sessionFile: session => session.sessionFile,
	sessionId: session => session.sessionManager.getSessionId(),
	cwd: session => session.sessionManager.getCwd(),
	artifactsDir: session => session.sessionManager.getArtifactsDir(),
	usageStatistics: session => toWireData(session.sessionManager.getUsageStatistics()),
	sessionStats: session => toWireData(session.getSessionStats()),
	advisorOverview: session => toWireData(session.getAdvisorStatusOverview()),
	sessionAgents: session => toWireData(session.getSessionAgents()),
	hindsightActive: session => session.hindsightActive,
	effectiveExtensionRoots: session => toWireData(session.effectiveExtensionRoots),
};

/** Read `fields` of `session` into a partial state. */
export function readSessionFields(
	session: AgentSessionHandle,
	fields: readonly PeerStateField[],
): Partial<SessionMirrorState> {
	const state: Partial<SessionMirrorState> = {};
	for (const field of fields) assignField(state, field, session);
	return state;
}

function assignField<K extends PeerStateField>(
	state: Partial<SessionMirrorState>,
	field: K,
	session: AgentSessionHandle,
): void {
	state[field] = SESSION_STATE_READERS[field](session);
}

/** Built-in structured-clone types passed through unchanged. */
function isCloneableBuiltin(value: object): boolean {
	return (
		value instanceof Date ||
		value instanceof RegExp ||
		value instanceof Map ||
		value instanceof Set ||
		value instanceof Error ||
		value instanceof ArrayBuffer ||
		ArrayBuffer.isView(value) ||
		value instanceof Blob
	);
}

function wire(value: unknown): unknown {
	if (typeof value === "function" || typeof value === "symbol") return undefined;
	if (value === null || typeof value !== "object") return value;
	if (Array.isArray(value)) {
		let copy: unknown[] | undefined;
		for (let i = 0; i < value.length; i++) {
			const item: unknown = value[i];
			const next = wire(item);
			if (next !== item && !copy) copy = value.slice(0, i);
			copy?.push(next);
		}
		return copy ?? value;
	}
	if (isCloneableBuiltin(value)) return value;
	const proto: unknown = Object.getPrototypeOf(value);
	const plain = proto === Object.prototype || proto === null;
	let copy: Record<string, unknown> | undefined = plain ? undefined : {};
	for (const key in value) {
		if (!Object.hasOwn(value, key)) continue;
		const item: unknown = Reflect.get(value, key);
		const next = wire(item);
		if (next !== item && !copy) {
			copy = {};
			for (const prior in value) {
				if (prior === key) break;
				if (Object.hasOwn(value, prior)) copy[prior] = Reflect.get(value, prior);
			}
		}
		if (copy && next !== undefined) copy[key] = next;
	}
	return copy ?? value;
}

/**
 * Wire-safe copy of session data: functions and symbols are dropped, foreign
 * class instances become plain records of their own enumerable fields, and
 * already-clean values are returned as-is (copy on write).
 */
export function toWireData<T>(value: T): T {
	let result!: T;
	// Trust boundary: the copy has the declared shape minus behavior; method
	// bivariance lets the typed sink accept it.
	const sink: { put(item: unknown): void } = {
		put: (item: T) => {
			result = item;
		},
	};
	sink.put(wire(value));
	return result;
}

/**
 * Worker-side publisher that keeps the main thread's `RemoteAgentSession`
 * mirror of one worker-homed `AgentSession` current.
 *
 * Created for every session constructed on a worker (through the session
 * directory's registration hook, which runs at the end of the constructor), so
 * `opened` — key, agent id, full initial state, the message list, and the
 * main-owned registry and job manager the session was built over — is posted
 * before anything can reference the session across the link: every
 * worker→main frame, `callSync` included, shares one FIFO port.
 *
 * After that it posts:
 * - state patches, coalesced per microtask and diffed field by field against
 *   the last published state, whenever an event, run-state transition, or
 *   command may have changed something (a forwarded event first flushes any
 *   pending patch so main never sees an event ahead of the state it implies);
 * - message-list deltas (`append` for messages added after the last
 *   published one, `replace` when the list was rebuilt: compaction, branch
 *   switch, `replaceMessages`);
 * - every run-state transition, unconditionally (registry status sync);
 * - while main watches it (`watch(true)`): the full event stream, plus the
 *   view state and the entry list (a full `view` snapshot when the watch
 *   starts, then `entries` deltas and `viewPatch` diffs in the same flush as
 *   the state patch, ahead of the event that caused them). Main keeps its
 *   entry list between watches, so the snapshot carries only the entries
 *   added since main last received any (the whole list after a rewrite) and
 *   refocusing a long session does not re-send its history. Entries are sent
 *   in display form: model-authored text has its secret placeholders restored,
 *   as `buildTranscriptSessionContext` would. While unwatched,
 *   `message_update`/`tool_execution_update` do not even refresh state, since
 *   main derives `streamMessage` and running tool updates from forwarded
 *   events;
 * - `closed` when the session begins disposing.
 *
 * The publisher is exported to main as the session's command host (kind
 * `"agent-session-host"`), so main's mirror keeps it, and through it the
 * session, alive until `closed`.
 *
 * Main restores queued messages to its composer synchronously from the
 * mirror, so it owns the arbitration between that and delivery: published
 * user-authored queued messages carry an id (a Symbol-keyed tag on the
 * message), and the publisher installs itself as the agent's queued-message
 * gate, asking main synchronously which tagged candidates it already took
 * back before a batch leaves the queue. Candidates the gate lets through are
 * marked claimed, which the queue publishes for a batch still being prepared.
 * A claimed message that goes back to a queue loses its id and mark, so main
 * sees it as a fresh, restorable entry.
 */
import type { AgentMessage, AgentTool, QueuedMessageGate } from "@oh-my-pi/pi-agent-core";
import type { Model } from "@oh-my-pi/pi-ai";
import { logger } from "@oh-my-pi/pi-utils";
import type { Rule } from "../capability/rule";
import type { OverlayLayers, Settings } from "../config/settings";
import type { Skill } from "../extensibility/skills";
import { deobfuscateAssistantContent } from "../secrets/message-transform";
import type { SecretObfuscator } from "../secrets/obfuscator";
import type { AgentSession } from "../session/agent-session";
import type { AgentSessionEvent } from "../session/agent-session-events";
import type { AgentViewToolSchema } from "../session/agent-session-handle";
import {
	isHiddenUserCompanion,
	isUserAuthoredQueuedMessage,
	toRestoredQueuedMessage,
} from "../session/queued-messages";
import type { SessionEntry } from "../session/session-entries";
import { isRpcProxy, type RpcServe } from "./rpc";
import {
	SESSION_STATE_READERS as read,
	type SessionBridgeClient,
	type SessionEntriesDelta,
	type SessionHostProtocol,
	type SessionMirrorState,
	type SessionQueuedEntry,
	type SessionRunState,
	type SessionSettingsSource,
	type SessionViewState,
	toWireData,
} from "./session-mirror";

/** Full state of a local session, as published to main. */
export function captureSessionState(session: AgentSession): SessionMirrorState {
	return {
		isStreaming: read.isStreaming(session),
		runStartedAt: read.runStartedAt(session),
		ircWakesPending: read.ircWakesPending(session),
		hasPendingWake: read.hasPendingWake(session),
		ircQueuedFrom: session.queuedIrcSenders(),
		isPaused: read.isPaused(session),
		streamMessage: read.streamMessage(session),
		pendingToolCalls: read.pendingToolCalls(session),
		model: read.model(session),
		servingModel: read.servingModel(session),
		thinkingLevel: read.thinkingLevel(session),
		sessionFile: read.sessionFile(session),
		sessionId: read.sessionId(session),
		cwd: read.cwd(session),
		artifactsDir: read.artifactsDir(session),
		usageStatistics: read.usageStatistics(session),
		sessionStats: read.sessionStats(session),
		advisorOverview: read.advisorOverview(session),
		sessionAgents: read.sessionAgents(session),
		hindsightActive: read.hindsightActive(session),
		effectiveExtensionRoots: read.effectiveExtensionRoots(session),
	};
}

/** Id main knows a queued message by (see the module doc). */
const kQueuedMessageId = Symbol("omp.queuedMessageId");
/** Set on a queued message the gate let through for delivery. */
const kQueuedMessageClaimed = Symbol("omp.queuedMessageClaimed");
let queuedMessageSeq = 0;

/** The id `message` was published under, if it was. */
function publishedQueuedMessageId(message: AgentMessage): string | undefined {
	const id: unknown = Reflect.get(message, kQueuedMessageId);
	return typeof id === "string" ? id : undefined;
}

/** `message` as a restorable queue entry, tagging it with an id on first publication. */
function queuedEntry(message: AgentMessage): SessionQueuedEntry {
	let id = publishedQueuedMessageId(message);
	if (id === undefined) {
		id = `q${++queuedMessageSeq}`;
		Reflect.set(message, kQueuedMessageId, id);
	}
	return {
		id,
		message: toRestoredQueuedMessage(message),
		claimed: Reflect.get(message, kQueuedMessageClaimed) === true,
	};
}

/** Queued message published under `id`, if `messages` hold it. */
function findQueuedMessage(messages: Iterable<AgentMessage>, id: string): AgentMessage | undefined {
	for (const message of messages) if (publishedQueuedMessageId(message) === id) return message;
	return undefined;
}

/** View state without the event-maintained running tool updates, as diffed between flushes. */
/** View state without the event-maintained running tool updates, as diffed between flushes. */
type DiffedViewState = Omit<SessionViewState, "activeToolExecutionUpdates">;

/** Live objects behind the wire copies of the heavy view fields; an unchanged source reuses its copy. */
interface ViewSources {
	readonly tools: readonly AgentTool[];
	readonly systemPrompt: readonly string[];
	readonly skills: readonly Skill[];
	readonly rules: Rule[] | null;
	readonly toolNames: readonly string[];
}

/** Whether two lists hold the same items in the same order (identity). */
function sameItems(a: readonly unknown[] | null, b: readonly unknown[] | null): boolean {
	if (a === b) return true;
	if (!a || !b || a.length !== b.length) return false;
	for (let i = 0; i < a.length; i++) if (a[i] !== b[i]) return false;
	return true;
}

/** Main-side rebuild recipe of `settings` (see {@link SessionSettingsSource}). */
function settingsSource(settings: Settings): SessionSettingsSource {
	const layers: OverlayLayers[] = [];
	let current: Settings | undefined = settings;
	while (current && !isRpcProxy(current)) {
		layers.push(current.overlayLayers());
		current = current.overlayParent();
	}
	layers.reverse();
	return { base: current ?? null, layers };
}

/** `entry` as the transcript shows it: model-authored text with secret placeholders restored. */
function displayEntry(entry: SessionEntry, obfuscator: SecretObfuscator): SessionEntry {
	if (entry.type === "message" && entry.message.role === "assistant") {
		const content = deobfuscateAssistantContent(obfuscator, entry.message.content);
		return content === entry.message.content ? entry : { ...entry, message: { ...entry.message, content } };
	}
	if (entry.type === "compaction") {
		const summary = obfuscator.deobfuscate(entry.summary);
		const shortSummary = entry.shortSummary === undefined ? undefined : obfuscator.deobfuscate(entry.shortSummary);
		return summary === entry.summary && shortSummary === entry.shortSummary
			? entry
			: { ...entry, summary, shortSummary };
	}
	if (entry.type === "branch_summary") {
		const summary = obfuscator.deobfuscate(entry.summary);
		return summary === entry.summary ? entry : { ...entry, summary };
	}
	return entry;
}

/** Wire copies of `entries` in display form. */
function displayEntries(entries: SessionEntry[], obfuscator: SecretObfuscator | undefined): SessionEntry[] {
	if (!obfuscator?.hasSecrets()) return toWireData(entries);
	return toWireData(entries.map(entry => displayEntry(entry, obfuscator)));
}

/** Publishes one worker-homed session to main; see the module doc. */
export class SessionPublisher {
	readonly session: AgentSession;
	readonly #bridge: SessionBridgeClient;
	readonly #key: string;
	#state: SessionMirrorState;
	/** Messages main holds, by identity, in order. */
	#published: AgentMessage[];
	/**
	 * The live message array last published. The loop appends in place, while
	 * history rewrites (compaction, pruning, branch switch) install a new array
	 * whose interior can differ even when its endpoints match.
	 */
	#publishedSource: AgentMessage[];
	#watched = false;
	/** Last published view state; undefined until the current watch sent its snapshot. */
	#view: DiffedViewState | undefined;
	#viewSources: ViewSources | undefined;
	/** Entries main holds (kept across watches), by identity, in order, and the body revision they were read at. */
	#entries: SessionEntry[] = [];
	#entriesRevision = 0;
	#scheduled = false;
	#closed = false;
	readonly #gate: QueuedMessageGate;
	readonly #unsubscribe: () => void;
	readonly #unsubscribeRunState: () => void;
	readonly #unsubscribeWakeState: () => void;

	constructor(session: AgentSession, bridge: SessionBridgeClient) {
		this.session = session;
		this.#bridge = bridge;
		this.#key = session.instanceKey;
		this.#state = captureSessionState(session);
		this.#publishedSource = session.messages;
		this.#published = [...this.#publishedSource];
		const jobs = session.asyncJobManager;
		bridge.remote.notify("opened", {
			key: this.#key,
			agentId: session.getAgentId(),
			host: this,
			state: this.#state,
			messages: toWireData(this.#published),
			modelRegistry: isRpcProxy(session.modelRegistry) ? session.modelRegistry : null,
			asyncJobManager: jobs && isRpcProxy(jobs) ? jobs : null,
		});
		this.#gate = {
			claim: (_queue, candidates) => this.#claimQueued(candidates),
			release: messages => {
				for (const message of messages) {
					Reflect.deleteProperty(message, kQueuedMessageId);
					Reflect.deleteProperty(message, kQueuedMessageClaimed);
				}
			},
		};
		session.agent.queuedMessageGate = this.#gate;
		this.#unsubscribe = session.subscribe(event => this.#onEvent(event));
		this.#unsubscribeRunState = session.subscribeRunState(state => this.#onRunState(state));
		// `ircWakesPending` gates main's idle parking and, like `hasPendingWake`, changes without an event.
		this.#unsubscribeWakeState = session.subscribeWakeState(() => this.schedule());
		session.addDisposer(() => this.close());
	}

	/** Post any state change now instead of at the end of the microtask. */
	flush(): void {
		this.#scheduled = false;
		if (this.#closed) return;
		try {
			this.#publishMessages();
			if (this.#watched && this.#view) this.#publishEntries();
			const next = captureSessionState(this.session);
			const patch: Partial<SessionMirrorState> = {};
			let changed = false;
			for (const field in next) {
				if (!isStateField(field, next)) continue;
				if (Bun.deepEquals(next[field], this.#state[field])) continue;
				copyField(patch, next, field);
				changed = true;
			}
			this.#state = next;
			if (changed) this.#bridge.remote.notify("patch", this.#key, patch);
			if (this.#watched) this.#publishView();
		} catch (error) {
			logger.warn("SessionPublisher failed to publish state", { key: this.#key, error: String(error) });
		}
	}

	/** Start or stop forwarding the full event stream and the view state. */
	watch(on: boolean): void {
		this.#watched = on;
		if (on) {
			this.flush();
			return;
		}
		this.#view = undefined;
		this.#viewSources = undefined;
	}

	/** Post `closed` and stop observing the session. Idempotent. */
	close(): void {
		if (this.#closed) return;
		this.flush();
		this.#closed = true;
		if (this.session.agent.queuedMessageGate === this.#gate) this.session.agent.queuedMessageGate = undefined;
		this.#unsubscribe();
		this.#unsubscribeRunState();
		this.#unsubscribeWakeState();
		this.#bridge.remote.notify("closed", this.#key);
	}

	/** Coalesce a publish into the end of the current microtask. */
	schedule(): void {
		if (this.#scheduled || this.#closed) return;
		this.#scheduled = true;
		queueMicrotask(() => {
			if (this.#scheduled) this.flush();
		});
	}

	#onEvent(event: AgentSessionEvent): void {
		if (this.#closed) return;
		// Streaming ticks only move the cursor; main derives `streamMessage` from forwarded updates.
		const tick = event.type === "message_update" || event.type === "tool_execution_update";
		if (!this.#watched) {
			if (!tick) this.schedule();
			return;
		}
		if (!tick || this.#scheduled) this.flush();
		try {
			this.#bridge.remote.notify("event", this.#key, toWireData(event));
		} catch (error) {
			logger.warn("SessionPublisher failed to forward an event", {
				key: this.#key,
				type: event.type,
				error: String(error),
			});
		}
	}

	/**
	 * Gate claim: main decides, synchronously and in order with its own restores,
	 * which published candidates it already took back. Those go, together with
	 * the hidden companions queued right before them; never-published
	 * candidates cannot have been restored and skip the round trip. The rest
	 * are marked claimed.
	 */
	#claimQueued(candidates: readonly AgentMessage[]): AgentMessage[] {
		if (this.#closed) return [];
		const ids: string[] = [];
		for (const message of candidates) {
			const id = publishedQueuedMessageId(message);
			if (id !== undefined) ids.push(id);
		}
		const restored = new Set(ids.length > 0 ? this.#bridge.remote.callSync("claimQueued", this.#key, ids) : []);
		const dropped = new Set<AgentMessage>();
		for (let i = 0; i < candidates.length && restored.size > 0; i++) {
			const id = publishedQueuedMessageId(candidates[i]);
			if (id === undefined || !restored.has(id)) continue;
			let start = i;
			while (start > 0 && isHiddenUserCompanion(candidates[start - 1])) start--;
			for (let j = start; j <= i; j++) dropped.add(candidates[j]);
		}
		for (const message of candidates) if (!dropped.has(message)) Reflect.set(message, kQueuedMessageClaimed, true);
		return [...dropped];
	}

	#onRunState(state: SessionRunState): void {
		if (this.#closed) return;
		this.flush();
		this.#bridge.remote.notify("runState", this.#key, state);
	}

	#publishMessages(): void {
		const current = this.session.messages;
		const published = this.#published;
		const last = published.length - 1;
		const extends_ =
			current === this.#publishedSource &&
			current.length >= published.length &&
			(published.length === 0 || (current[0] === published[0] && current[last] === published[last]));
		if (extends_ && current.length === published.length) return;
		this.#publishedSource = current;
		if (extends_) {
			const added = current.slice(published.length);
			for (const message of added) published.push(message);
			this.#bridge.remote.notify("messages", this.#key, { kind: "append", messages: toWireData(added) });
			return;
		}
		this.#published = [...current];
		this.#bridge.remote.notify("messages", this.#key, { kind: "replace", messages: toWireData(this.#published) });
	}

	#publishEntries(): void {
		const delta = this.#entriesDelta();
		if (delta) this.#bridge.remote.notify("entries", this.#key, delta);
	}

	/**
	 * What main's entry list lacks, recorded as sent: the entries appended since
	 * it last received any, or the whole list once the journal was rewritten
	 * (body revision bump, or a published endpoint no longer in place).
	 * Undefined when main is current.
	 */
	#entriesDelta(): SessionEntriesDelta | undefined {
		const manager = this.session.sessionManager;
		const current = manager.getEntriesView();
		const revision = manager.bodyRevision;
		const published = this.#entries;
		const last = published.length - 1;
		const extends_ =
			revision === this.#entriesRevision &&
			current.length >= published.length &&
			(published.length === 0 || (current[0] === published[0] && current[last] === published[last]));
		if (extends_ && current.length === published.length) return undefined;
		this.#entriesRevision = revision;
		const obfuscator = this.session.obfuscator;
		if (extends_) {
			const added = current.slice(published.length);
			for (const entry of added) published.push(entry);
			return { kind: "append", entries: displayEntries(added, obfuscator) };
		}
		this.#entries = [...current];
		return { kind: "replace", entries: displayEntries(this.#entries, obfuscator) };
	}

	#publishView(): void {
		const next = this.#captureView();
		const previous = this.#view;
		this.#view = next;
		if (!previous) {
			const state: SessionViewState = {
				...next,
				activeToolExecutionUpdates: toWireData([...this.session.activeToolExecutionUpdates()]),
			};
			this.#bridge.remote.notify("view", this.#key, state, this.#entriesDelta());
			return;
		}
		const patch: Partial<SessionViewState> = {};
		let changed = false;
		for (const field in next) {
			if (!isViewField(field, next)) continue;
			const same =
				field === "settings"
					? next.settings.base === previous.settings.base &&
						Bun.deepEquals(next.settings.layers, previous.settings.layers)
					: Bun.deepEquals(next[field], previous[field]);
			if (same) continue;
			copyViewField(patch, next, field);
			changed = true;
		}
		if (changed) this.#bridge.remote.notify("viewPatch", this.#key, patch);
	}

	#captureView(): DiffedViewState {
		const session = this.session;
		const manager = session.sessionManager;
		const previous = this.#view;
		const prior = this.#viewSources;
		const sources: ViewSources = {
			tools: session.agent.state.tools,
			systemPrompt: session.systemPrompt,
			skills: session.skills,
			rules: session.ttsrManager?.getRules() ?? null,
			toolNames: session.getAllToolNames(),
		};
		this.#viewSources = sources;
		const reuse = <K extends keyof ViewSources>(key: K): boolean =>
			previous !== undefined && prior !== undefined && sameItems(prior[key], sources[key]);
		const tools: AgentViewToolSchema[] =
			previous && reuse("tools")
				? previous.tools
				: toWireData(
						sources.tools.map(tool => ({
							name: tool.name,
							description: tool.description,
							parameters: tool.parameters,
						})),
					);
		const steering = session.agent.peekSteeringQueue().filter(isUserAuthoredQueuedMessage);
		const followUp = session.agent.peekFollowUpQueue().filter(isUserAuthoredQueuedMessage);
		return {
			providerSessionId: session.sessionId,
			sessionName: manager.getSessionName(),
			leafId: manager.getLeafId(),
			agentEffort: session.agent.state.thinkingLevel,
			tools,
			toolNames: previous && reuse("toolNames") ? previous.toolNames : [...sources.toolNames],
			builtInTools:
				previous && reuse("toolNames")
					? previous.builtInTools
					: sources.toolNames.filter(name => session.hasBuiltInTool(name)),
			pendingToolResults: toWireData([...session.agent.getPendingToolResults()]),
			runToolCallIds: [...session.runToolCallIds],
			systemPrompt: previous && reuse("systemPrompt") ? previous.systemPrompt : [...sources.systemPrompt],
			skills: previous && reuse("skills") ? previous.skills : toWireData([...session.skills]),
			rules: previous && reuse("rules") ? previous.rules : sources.rules && toWireData(sources.rules),
			// Mid-run its transcript fallback rebuilds the display context on every flush; main reads it only idle.
			hasAbortedToolCallTail: !session.isStreaming && session.hasAbortedToolCallTail,
			isAutoThinking: session.isAutoThinking,
			isCompacting: session.isCompacting,
			compactionSpeculation: session.compactionSpeculation,
			contextUsageRevision: session.contextUsageRevision,
			contextUsage: toWireData(session.getContextUsage()),
			isRetrying: session.isRetrying,
			retryAttempt: session.retryAttempt,
			isTtsrAbortPending: session.isTtsrAbortPending,
			hasInterruptibleInput: session.hasInterruptibleInput,
			autoResolvedThinkingLevel: session.autoResolvedThinkingLevel(),
			configuredThinkingLevel: session.configuredThinkingLevel(),
			availableEffortSelectors: session.getAvailableEffortSelectors(),
			serviceTierByFamily: toWireData(session.serviceTierByFamily),
			fastModeActive: session.isFastModeActive(),
			anthropicSlowModeLabel: session.getAnthropicSlowModeLabel(),
			prewalk: toWireData(session.getPrewalkState()),
			goalMode: toWireData(session.getGoalModeState()),
			advisorCost: session.getAdvisorCost(),
			advisorUsingSubscription: session.isAdvisorUsingSubscription(),
			todoPhases: toWireData(session.getTodoPhases()),
			queuedMessages: toWireData(session.getQueuedMessages()),
			restorableQueue: toWireData({ steering: steering.map(queuedEntry), followUp: followUp.map(queuedEntry) }),
			ephemeralMaxTokensPreservesRequest: session.ephemeralMaxTokensPreservesRequest(),
			settings: settingsSource(session.settings),
		};
	}
}

function isStateField(field: string, state: SessionMirrorState): field is keyof SessionMirrorState {
	return Object.hasOwn(state, field);
}

function copyField<K extends keyof SessionMirrorState>(
	patch: Partial<SessionMirrorState>,
	state: SessionMirrorState,
	field: K,
): void {
	patch[field] = state[field];
}

function isViewField(field: string, state: DiffedViewState): field is keyof DiffedViewState {
	return Object.hasOwn(state, field);
}

function copyViewField<K extends keyof DiffedViewState>(
	patch: Partial<SessionViewState>,
	state: DiffedViewState,
	field: K,
): void {
	patch[field] = state[field];
}

/** `model` as resolved by the worker session's own registry (main sends plain model data). */
function localModel(session: AgentSession, model: Model): Model {
	return session.modelRegistry.find(model.provider, model.id) ?? model;
}

/** Worker-side implementation of {@link SessionHostProtocol}; commands flush state before their result posts. */
export const SESSION_HOST_SERVE: RpcServe<SessionPublisher, SessionHostProtocol> = {
	prompt: async (publisher, text, options) => settle(publisher, publisher.session.prompt(text, options)),
	steer: async (publisher, text, images, options) => settle(publisher, publisher.session.steer(text, images, options)),
	abort: async (publisher, options) => settle(publisher, publisher.session.abort(options)),
	dispose: async (publisher, options) => settle(publisher, publisher.session.dispose(options)),
	deliverIrcMessage: async (publisher, msg) => settle(publisher, publisher.session.deliverIrcMessage(msg)),
	waitForIrcReplies: async publisher => settle(publisher, publisher.session.waitForIrcReplies()),
	setWorkPoolYieldItems: async (publisher, items) => settle(publisher, publisher.session.setWorkPoolYieldItems(items)),
	acquireRestoreIdleHold: (publisher, expectedSessionFile, manager, signal) =>
		publisher.session.acquireRestoreIdleHold(expectedSessionFile, manager, signal),
	releaseRestoreIdleHold: (publisher, token) => settle(publisher, publisher.session.releaseRestoreIdleHold(token)),
	hasRestorePendingReceipt: (publisher, token) => publisher.session.hasRestorePendingReceipt(token),
	finishRestoreIdleHold: (publisher, token, discard) =>
		settle(publisher, publisher.session.finishRestoreIdleHold(token, discard)),
	waitForRunEnd: publisher => settle(publisher, publisher.session.waitForRunEnd()),
	emitIrcRelayObservation: (publisher, record) => publisher.session.emitIrcRelayObservation(record),
	watch: (publisher, on) => publisher.watch(on),
	settleInFlightMessagePersistence: async publisher =>
		settle(publisher, publisher.session.settleInFlightMessagePersistence()),
	setThinkingLevel: (publisher, level, persist) => {
		publisher.session.setThinkingLevel(level, persist);
		publisher.schedule();
	},
	popQueuedMessage: (publisher, id) => {
		const session = publisher.session;
		// Neither queued nor held aside: it already left for good and can never be delivered.
		const message =
			findQueuedMessage(session.agent.peekSteeringQueue(), id) ??
			findQueuedMessage(session.agent.peekFollowUpQueue(), id) ??
			findQueuedMessage(session.heldQueuedMessages, id);
		if (message) session.withdrawQueuedMessage(message);
		publisher.schedule();
	},
	setTodoPhases: (publisher, phases) => {
		publisher.session.setTodoPhases(phases);
		publisher.schedule();
	},
	appendCustomEntry: (publisher, customType, data) => {
		publisher.session.sessionManager.appendCustomEntry(customType, data);
		publisher.schedule();
	},
	appendModelUsage: (publisher, usage, owner) => {
		publisher.session.sessionManager.appendModelUsage(usage, owner);
		publisher.schedule();
	},
	flushSession: async publisher => settle(publisher, publisher.session.sessionManager.flush()),
	ensureOnDisk: async publisher => settle(publisher, publisher.session.sessionManager.ensureOnDisk()),
	getArtifactPath: (publisher, id) => publisher.session.sessionManager.getArtifactPath(id),
	resume: async publisher => settle(publisher, publisher.session.resume()),
	retry: async publisher => settle(publisher, publisher.session.retry()),
	abortRetry: publisher => {
		publisher.session.abortRetry();
		publisher.schedule();
	},
	abortCompaction: (publisher, reason) => {
		publisher.session.abortCompaction(reason);
		publisher.schedule();
	},
	setModelTemporary: async (publisher, model, thinkingLevel, options) =>
		settle(
			publisher,
			publisher.session.setModelTemporary(localModel(publisher.session, model), thinkingLevel, options),
		),
	cycleRoleModels: async (publisher, roleOrder, direction) =>
		toWireData(await settle(publisher, publisher.session.cycleRoleModels(roleOrder, direction))),
	applyRoleModel: async (publisher, entry) =>
		settle(
			publisher,
			publisher.session.applyRoleModel({ ...entry, model: localModel(publisher.session, entry.model) }),
		),
	fetchUsageReports: async (publisher, signal) => toWireData(await publisher.session.fetchUsageReports(signal)),
	runEphemeralTurn: async (publisher, args) => toWireData(await publisher.session.runEphemeralTurn(args)),
	exportToHtml: async (publisher, outputPath, useUserThemes) =>
		publisher.session.exportToHtml(outputPath, useUserThemes),
	enableIdleMaintenance: (publisher, options) => publisher.session.enableIdleMaintenance(options),
	refreshIdleMaintenance: publisher => publisher.session.refreshIdleMaintenance(),
};

async function settle<T>(publisher: SessionPublisher, pending: Promise<T>): Promise<T> {
	try {
		return await pending;
	} finally {
		publisher.flush();
	}
}

