/**
 * Target cleanup for omp-created relay tabs.
 *
 * The relay exposes no browser target, so puppeteer's `browser.target()`
 * throws and the generic CDP-session close path cannot reach it. Root-level
 * commands go over a short-lived websocket to the relay's CDP endpoint instead.
 *
 * Tabs omp creates through the relay are recorded in the durable
 * orphan registry (keyed by relay endpoint, under the machine-global relay
 * runtime dir) so a later omp process can close them once their creator has
 * died without running its own cleanup (crash, TerminateProcess, SIGKILL).
 */
import { createHash } from "node:crypto";
import { daemonDir } from "../../../daemon/paths";
import type { SharedTargetScope } from "../orphan-registry";

const ROOT_COMMAND_TIMEOUT_MS = 5_000;

/** Durable-ownership scope for omp-created tabs behind one relay endpoint. */
export function relayTargetScope(cdpUrl: string): SharedTargetScope {
	const runtimeDir = daemonDir();
	const url = new URL(cdpUrl);
	// Include origin and discovery path; never put endpoint credentials in the filename.
	const endpoint = createHash("sha256").update(url.origin + url.pathname + url.search).digest("hex").slice(0, 32);
	return { projectDir: runtimeDir, runtimeDir, daemonName: `omp.browser.relay-${endpoint}` };
}

/** Send one root-session CDP command to the relay and return its result; rejects on CDP error or timeout. */
async function sendRootCommand(
	wsEndpoint: string,
	method: string,
	params: Record<string, unknown>,
): Promise<Record<string, unknown>> {
	const { promise, resolve, reject } = Promise.withResolvers<Record<string, unknown>>();
	const socket = new WebSocket(wsEndpoint);
	const timer = setTimeout(() => reject(new Error(`relay ${method} timed out`)), ROOT_COMMAND_TIMEOUT_MS);
	socket.onopen = () => socket.send(JSON.stringify({ id: 1, method, params }));
	socket.onmessage = event => {
		let reply: unknown;
		try {
			reply = JSON.parse(String(event.data));
		} catch {
			return;
		}
		if (typeof reply !== "object" || reply === null || !("id" in reply) || reply.id !== 1) return;
		if ("error" in reply) {
			const error = reply.error;
			const message =
				typeof error === "object" && error !== null && "message" in error ? String(error.message) : "CDP error";
			reject(new Error(message));
			return;
		}
		const result = "result" in reply ? reply.result : undefined;
		resolve(typeof result === "object" && result !== null ? { ...result } : {});
	};
	socket.onerror = () => reject(new Error(`relay websocket failed during ${method}`));
	socket.onclose = () => reject(new Error(`relay websocket closed during ${method}`));
	try {
		return await promise;
	} finally {
		clearTimeout(timer);
		socket.close();
	}
}

/**
 * Close a relay tab this process created. True only when the relay confirms
 * the close. Discovery is filtered (including while an extension is offline),
 * so an absent target cannot prove closure or justify forgetting ownership.
 */
export async function closeRelayTarget(wsEndpoint: string, targetId: string): Promise<boolean> {
	try {
		const result = await sendRootCommand(wsEndpoint, "Target.closeTarget", { targetId });
		return result.success === true;
	} catch {
		return false;
	}
}

/**
 * Reaper close for a dead process's relay tab. The relay closes it only when
 * the extension created it in the current browser session and no live
 * connection drives it. True when the record is resolved (closed or stale);
 * false keeps it for a later retry (relay or its browser unreachable).
 */
export async function closeRelayOwnedTarget(wsEndpoint: string, targetId: string): Promise<boolean> {
	try {
		const result = await sendRootCommand(wsEndpoint, "OMP.closeOwnedTarget", { targetId });
		return result.resolved === true;
	} catch {
		return false;
	}
}

import { expect, test } from "bun:test";
import { scheduler } from "node:timers/promises";
import { AsyncJobManager } from "@oh-my-pi/pi-coding-agent/async/job-manager";

test("stages parents without slots, then admits at most one ready job and publishes the admission", async () => {
	const manager = new AsyncJobManager({ maxRunningJobs: 1 });
	const childDone = Promise.withResolvers<void>();
	const parentDone = Promise.withResolvers<void>();
	const order: string[] = [];
	const changes: string[] = [];
	let maxObservedRunning = 0;
	const unlisten = manager.onJobsChanged(() => {
		let running = 0;
		for (const id of ["parent", "child", "peer"]) {
			const job = manager.getJob(id);
			if (job?.status === "running" && !job.queued) {
				running++;
				changes.push(id);
			}
		}
		maxObservedRunning = Math.max(maxObservedRunning, running);
	});
	try {
		manager.register(
			"task",
			"parent",
			async () => {
				order.push("parent");
				await parentDone.promise;
				return "parent result";
			},
			{
				id: "parent",
				foreground: true,
				waitForCapacity: true,
				beforeStart: async () => {
					const child = manager.getJob("child");
					expect(child).toBeDefined();
					await child!.promise;
				},
			},
		);
		manager.register(
			"task",
			"child",
			async () => {
				order.push("child");
				await childDone.promise;
				return "child result";
			},
			{ id: "child", foreground: true, waitForCapacity: true },
		);
		await scheduler.yield();
		expect(order).toEqual(["child"]);
		expect(manager.getJob("parent")?.queued).toBe(true);
		expect(changes).toContain("child");
		manager.register(
			"task",
			"peer",
			async () => {
				order.push("peer");
				return "peer result";
			},
			{ id: "peer", foreground: true, waitForCapacity: true },
		);
		await scheduler.yield();
		expect(order).toEqual(["child"]);
		expect(manager.getJob("peer")?.queued).toBe(true);
		childDone.resolve();
		await scheduler.yield();
		expect(order.length).toBeGreaterThanOrEqual(2);
		parentDone.resolve();
		await scheduler.yield();
		expect(order).toHaveLength(3);
		expect(maxObservedRunning).toBe(1);
		expect(order.slice(1).sort()).toEqual(["parent", "peer"]);
		expect(changes).toContain("parent");
		expect(changes).toContain("peer");
	} finally {
		unlisten();
		childDone.resolve();
		parentDone.resolve();
		await manager.dispose();
	}
});

test("cancels a queued dependency wait even before its callback returns", async () => {
	const manager = new AsyncJobManager({ maxRunningJobs: 1 });
	const dependency = Promise.withResolvers<void>();
	const preparing = Promise.withResolvers<void>();
	let started = false;
	try {
		const id = manager.register(
			"task",
			"pending dependency",
			async () => {
				started = true;
				return "not reached";
			},
			{
				waitForCapacity: true,
				beforeStart: () => {
					preparing.resolve();
					return dependency.promise;
				},
			},
		);
		await preparing.promise;
		expect(manager.cancel(id)).toBe(true);
		await scheduler.yield();
		expect(manager.getJob(id)?.status).toBe("cancelled");
		expect(manager.getJob(id)?.endTime).toBeDefined();
		expect(started).toBe(false);
	} finally {
		dependency.resolve();
		await manager.dispose();
	}
});

test("a synchronous admission observer can cancel before the runner starts", async () => {
	const manager = new AsyncJobManager({ maxRunningJobs: 1 });
	let started = false;
	const unlisten = manager.onJobsChanged(() => {
		const job = manager.getJob("observed");
		if (job?.status === "running" && !job.queued) manager.cancel(job.id);
	});
	try {
		const id = manager.register(
			"task",
			"observed",
			async () => {
				started = true;
				return "not reached";
			},
			{ id: "observed", waitForCapacity: true },
		);
		await manager.getJob(id)?.promise;
		expect(manager.getJob(id)?.status).toBe("cancelled");
		expect(started).toBe(false);
	} finally {
		unlisten();
		await manager.dispose();
	}
});

/**
 * Subagent worker entry for the agents-bridge tests: the real link wiring of
 * `subagent-worker-entry` with the identity, agents and async-jobs services, plus a
 * probe service that hands the test functions driving real `AgentSession`s
 * homed on this worker.
 */
import { MessagePort, parentPort } from "node:worker_threads";
import { Agent } from "@oh-my-pi/pi-agent-core";
import { createMockModel } from "@oh-my-pi/pi-ai/providers/mock";
import { getBundledModel } from "@oh-my-pi/pi-catalog/models";
import type { AsyncJobManagerApi } from "../../src/async/job-manager";
import { ModelRegistry } from "../../src/config/model-registry";
import { Settings } from "../../src/config/settings";
import { AgentLifecycleManager } from "../../src/registry/agent-lifecycle";
import { type AgentRef, AgentRegistry } from "../../src/registry/agent-registry";
import { AgentSession } from "../../src/session/agent-session";
import { AuthStorage } from "../../src/session/auth-storage";
import { convertToLlm } from "../../src/session/messages";
import { SessionManager } from "../../src/session/session-manager";
import { isThreadId, setCurrentThreadId } from "../../src/thread/identity";
import { PeerAgentSession } from "../../src/thread/peer-agent-session";
import type { SubagentWorkerInit, SubagentWorkerReady, WorkerThreadLink } from "../../src/thread/protocol";
import { type RpcFrame, RpcLink } from "../../src/thread/rpc";
import type { ThreadService } from "../../src/thread/services";
import { agentsThreadService } from "../../src/thread/services/agents";
import { asyncJobsThreadService } from "../../src/thread/services/async-jobs";
import { identityThreadService } from "../../src/thread/services/identity";

/** What a worker-side peer handle reports about a session homed elsewhere. */
export interface PeerReport {
	isPeer: boolean;
	key: string;
	isStreaming: boolean;
	messageCount: number;
	sessionFile: string | undefined;
	canonical: boolean;
	casBySession: boolean;
}

/** Operations the test drives on the worker. */
interface ProbeOpenOptions {
	sessionFile?: string;
	gated?: boolean;
	/** Optional actual main-owned manager, imported as its worker proxy. */
	manager?: AsyncJobManagerApi;
}

export interface AgentsProbe {
	threadId(): Promise<string>;
	/** Build a real session (mock model) and register it as `id` in the (remote) registry. */
	open(id: string, options: ProbeOpenOptions): Promise<string>;
	/** Acquire from a different worker through the actual peer, main bridge and owner host. */
	peerAcquireRestore(id: string, file: string, manager: AsyncJobManagerApi): Promise<string>;
	peerRestorePending(id: string, token: string): Promise<boolean>;
	peerReleaseRestore(id: string, token: string): Promise<boolean>;
	peerFinishRestore(id: string, token: string, discard: boolean): Promise<boolean>;
	/** Run a prompt on the local session to completion. */
	prompt(id: string, text: string): Promise<void>;
	/** Let gated model calls answer. */
	openGate(): Promise<void>;
	/** Rewrite the second message's text through `replaceMessages`, keeping the first and last objects (as pruning does). */
	rewriteInterior(id: string, text: string): Promise<void>;
	/** Custom message types of the local session's transcript. */
	localCustomTypes(id: string): Promise<string[]>;
	/** Keep the current ref object for `id`. */
	grab(id: string): Promise<number>;
	/** CAS `setStatus` with the grabbed ref, then with a fresh one. */
	cas(id: string, status: "idle" | "running"): Promise<{ grabbed: boolean; fresh: boolean; canonical: boolean }>;
	/** Read a session homed elsewhere through its peer handle. */
	peer(id: string): Promise<PeerReport>;
	/** Subscribe to events and run state of the session of `id` through its peer handle. */
	peerSubscribe(id: string): Promise<void>;
	/** Prompt the session of `id` through its peer handle (main routes it to the home thread). */
	peerPrompt(id: string, text: string): Promise<{ accepted: boolean }>;
	/** Event types and run states the peer subscriptions received. */
	peerSeen(): Promise<{ events: string[]; runStates: string[] }>;
	/** Adopt `id` into the main lifecycle with a reviver that builds a fresh session here. */
	adopt(id: string): Promise<void>;
	/** Whether the local session of `key` was disposed. */
	disposed(key: string): Promise<boolean>;
	/** Whether the worker's lifecycle proxy manages the worker's registry proxy. */
	manages(): Promise<boolean>;
}

/** Test-only boot globals of the probe service. */
export interface AgentsProbeGlobals {
	ready(probe: AgentsProbe): void;
}

const port = parentPort;
if (!port) throw new Error("fixture must run in a worker");

const sessions = new Map<string, AgentSession>();
const byKey = new Map<string, AgentSession>();
const grabbed = new Map<string, AgentRef>();
const restoreControllers = new Map<string, AbortController>();
const peerSeen: { events: string[]; runStates: string[] } = { events: [], runStates: [] };
let threadName = "";
let gate = Promise.withResolvers<void>();
let gateOpen = false;

async function makeSession(id: string, options: ProbeOpenOptions): Promise<AgentSession> {
	const model = getBundledModel("anthropic", "claude-sonnet-4-5");
	if (!model) throw new Error("bundled model missing");
	const mock = createMockModel({
		handler: async () => {
			if (options.gated && !gateOpen) await gate.promise;
			return { content: ["Done"] };
		},
	});
	const agent = new Agent({
		getApiKey: () => "test-key",
		initialState: { model, systemPrompt: ["Test"], tools: [] },
		convertToLlm,
		streamFn: mock.stream,
	});
	const authStorage = await AuthStorage.create(":memory:");
	authStorage.keys.setRuntime("anthropic", "test-key");
	const sessionManager = SessionManager.inMemory();
	// Supply identity before the session publisher takes its initial snapshot.
	// The manager's internal persistence path stays unset; no file is opened.
	const file = options.sessionFile;
	if (options.manager && file) sessionManager.getSessionFile = () => file;
	const session = new AgentSession({
		agent,
		sessionManager,
		settings: Settings.isolated(),
		modelRegistry: new ModelRegistry(authStorage),
		agentId: id,
		asyncJobManager: options.manager,
	});
	sessions.set(id, session);
	byKey.set(session.instanceKey, session);
	return session;
}

function local(id: string): AgentSession {
	const session = sessions.get(id);
	if (!session) throw new Error(`no local session ${id}`);
	return session;
}

function peerSession(id: string): PeerAgentSession {
	const session = AgentRegistry.global().get(id)?.session;
	if (!(session instanceof PeerAgentSession)) throw new Error("expected a remote peer session for " + id);
	return session;
}

const probe: AgentsProbe = {
	threadId: async () => threadName,
	open: async (id, options) => {
		const session = await makeSession(id, options);
		const registry = AgentRegistry.global();
		registry.register({
			id,
			displayName: id,
			kind: "sub",
			session,
			sessionFile: options.sessionFile ?? null,
			status: "idle",
		});
		registry.syncSessionStatus(id, session);
		return session.instanceKey;
	},
	peerAcquireRestore: async (id, file, manager) => {
		const controller = new AbortController();
		const token = await peerSession(id).acquireRestoreIdleHold(file, manager, controller.signal);
		restoreControllers.set(token, controller);
		return token;
	},
	peerRestorePending: async (id, token) => peerSession(id).hasRestorePendingReceipt(token),
	peerReleaseRestore: async (id, token) => peerSession(id).releaseRestoreIdleHold(token),
	peerFinishRestore: async (id, token, discard) => {
		const finished = await peerSession(id).finishRestoreIdleHold(token, discard);
		if (finished) restoreControllers.delete(token);
		return finished;
	},
	prompt: async (id, text) => {
		await local(id).prompt(text);
	},
	rewriteInterior: async (id, text) => {
		const session = local(id);
		const messages = [...session.messages];
		const interior = messages[1];
		if (messages.length < 3 || interior?.role !== "assistant") throw new Error("need [user, assistant, …] history");
		messages[1] = { ...interior, content: [{ type: "text", text }] };
		session.agent.replaceMessages(messages);
	},
	openGate: async () => {
		gateOpen = true;
		gate.resolve();
		gate = Promise.withResolvers<void>();
	},
	localCustomTypes: async id =>
		local(id).messages.flatMap(message => (message.role === "custom" ? [message.customType] : [])),
	grab: async id => {
		const ref = AgentRegistry.global().get(id);
		if (!ref) throw new Error(`no ref ${id}`);
		grabbed.set(id, ref);
		return ref.generation;
	},
	cas: async (id, status) => {
		const registry = AgentRegistry.global();
		const old = grabbed.get(id);
		if (!old) throw new Error(`nothing grabbed for ${id}`);
		const grabbedOk = registry.setStatus(id, status, old);
		const fresh = registry.get(id);
		const freshOk = fresh ? registry.setStatus(id, status, fresh) : false;
		return { grabbed: grabbedOk, fresh: freshOk, canonical: fresh === registry.get(id) };
	},
	peer: async id => {
		const registry = AgentRegistry.global();
		const session = registry.get(id)?.session;
		if (!session) throw new Error(`no session for ${id}`);
		return {
			isPeer: session instanceof PeerAgentSession,
			key: session.instanceKey,
			isStreaming: session.isStreaming,
			messageCount: session.messages.length,
			sessionFile: session.sessionFile,
			canonical: session === registry.get(id)?.session,
			casBySession: registry.setStatus(id, "idle", session),
		};
	},
	peerSubscribe: async id => {
		const session = AgentRegistry.global().get(id)?.session;
		if (!session) throw new Error(`no session for ${id}`);
		session.subscribe(event => peerSeen.events.push(event.type));
		session.subscribeRunState(state => peerSeen.runStates.push(state));
	},
	peerPrompt: async (id, text) => {
		const session = AgentRegistry.global().get(id)?.session;
		if (!session) throw new Error(`no session for ${id}`);
		return { accepted: await session.prompt(text) };
	},
	peerSeen: async () => ({ events: [...peerSeen.events], runStates: [...peerSeen.runStates] }),
	adopt: async id => {
		const registry = AgentRegistry.global();
		const ref = registry.get(id);
		if (!ref) throw new Error(`no ref ${id}`);
		AgentLifecycleManager.global().adopt(
			id,
			{
				idleTtlMs: 0,
				revive: async () => makeSession(id, {}),
			},
			ref,
		);
	},
	disposed: async key => {
		const session = byKey.get(key);
		if (!session) throw new Error(`no session ${key}`);
		return session.isDisposed;
	},
	manages: async () => AgentLifecycleManager.global().manages(AgentRegistry.global()),
};

function isProbeGlobals(value: unknown): value is AgentsProbeGlobals {
	return typeof value === "object" && value !== null && typeof Reflect.get(value, "ready") === "function";
}

const probeService: ThreadService = {
	name: "agents-probe",
	boot(globals) {
		if (!isProbeGlobals(globals)) throw new Error("probe globals missing");
		globals.ready(probe);
	},
};

const services: readonly ThreadService[] = [
	identityThreadService,
	agentsThreadService,
	asyncJobsThreadService,
	probeService,
];

function isInit(value: unknown): value is SubagentWorkerInit {
	return (
		typeof value === "object" &&
		value !== null &&
		Reflect.get(value, "type") === "subagent-worker-init" &&
		isThreadId(Reflect.get(value, "threadId")) &&
		Reflect.get(value, "replyPort") instanceof MessagePort &&
		Reflect.get(value, "counter") instanceof SharedArrayBuffer
	);
}

function isFrame(value: unknown): value is RpcFrame {
	return typeof value === "object" && value !== null && typeof Reflect.get(value, "t") === "string";
}

let frameHandler: ((frame: RpcFrame) => void) | undefined;

port.on("message", (message: unknown) => {
	if (!frameHandler) {
		if (!isInit(message)) return;
		threadName = message.threadId;
		setCurrentThreadId(message.threadId);
		const link: WorkerThreadLink = new RpcLink(
			{
				send: frame => port.postMessage(frame),
				listen: handler => {
					frameHandler = handler;
					return () => {
						frameHandler = undefined;
					};
				},
			},
			{
				name: `${message.threadId}↔main`,
				sync: { port: message.replyPort, counter: new Int32Array(message.counter) },
			},
		);
		for (const service of services) service.installWorker?.(link);
		link.handle("boot", async globals => {
			for (const service of services) await service.boot?.(globals[service.name], link);
		});
		link.handle("ping", nonce => nonce);
		const ready: SubagentWorkerReady = { type: "subagent-worker-ready" };
		port.postMessage(ready);
		return;
	}
	if (isFrame(message)) frameHandler(message);
});

import { type MessagePort, parentPort } from "node:worker_threads";
import {
	ASYNC_JOB_MANAGER_SHUTDOWN_REASON,
	type AsyncJobManagerApi,
	type AsyncJobRunResult,
} from "../../src/async/job-manager";
import { Settings } from "../../src/config/settings";
import { runEvalWait } from "../../src/eval/handle-bridge";
import type { JsStatusEvent } from "../../src/eval/js/shared/types";
import { TextTap } from "../../src/job-widgets/text-tap";
import type { ArtifactManagerApi } from "../../src/session/artifacts";
import { CostCapError, type CostGateApi } from "../../src/session/cost-gate";
import type { SubagentMainApi, SubagentWorkerApi, WorkerThreadLink } from "../../src/thread/protocol";
import { type RpcFrame, RpcLink } from "../../src/thread/rpc";
import { asyncJobsThreadService } from "../../src/thread/services/async-jobs";
import { RemoteAsyncJob, RemoteAsyncJobManager } from "../../src/thread/services/async-jobs-remote";
import { runtimeThreadService } from "../../src/thread/services/runtime";
import { RemoteArtifactManager, RemoteCostGate, RemoteEventBus } from "../../src/thread/services/runtime-remote";
import { settingsThreadService } from "../../src/thread/services/settings";
import type { ToolSession } from "../../src/tools";
import { EventBus, emitSubagentFrame } from "../../src/utils/event-bus";

/** Worker-side probe the test calls through the function it registers at boot. */
export type RuntimeProbe = (op: string, ...args: unknown[]) => unknown;

const port = parentPort;
if (!port) throw new Error("fixture must run in a worker");

interface Body {
	finish: PromiseWithResolvers<string | AsyncJobRunResult>;
	signal?: AbortSignal;
	report?: (text: string, assignment?: string) => Promise<void>;
	tap?: TextTap;
}

const bodies = new Map<string, Body>();
const admissionGates = new Map<string, PromiseWithResolvers<void>>();
const deliveries: unknown[] = [];
const events: unknown[] = [];
const waitStarts = new Map<string, PromiseWithResolvers<void>>();

function waitStart(id: string): PromiseWithResolvers<void> {
	let started = waitStarts.get(id);
	if (!started) {
		started = Promise.withResolvers<void>();
		waitStarts.set(id, started);
	}
	return started;
}

function manager(value: unknown): AsyncJobManagerApi {
	if (!(value instanceof RemoteAsyncJobManager)) throw new Error("expected a remote job manager");
	return value;
}

function body(id: unknown): Body {
	const found = typeof id === "string" ? bodies.get(id) : undefined;
	if (!found) throw new Error(`no job body ${String(id)}`);
	return found;
}

function bus(value: unknown): EventBus | undefined {
	if (value === undefined || value === null) return undefined;
	if (!(value instanceof EventBus)) throw new Error("expected an event bus");
	return value;
}

function registerBody(jobs: AsyncJobManagerApi, ownerId: string, withInputs: boolean): string {
	const entry: Body = { finish: Promise.withResolvers() };
	const tap = withInputs ? new TextTap("out", "fixture output") : undefined;
	entry.tap = tap;
	const id = jobs.register(
		"bash",
		"fixture job",
		async ({ signal, reportProgress, markRunning }) => {
			entry.signal = signal;
			entry.report = (text, assignment) =>
				reportProgress(text, assignment ? { progress: [{ assignment }] } : undefined);
			markRunning();
			const aborted = Promise.withResolvers<never>();
			signal.addEventListener("abort", () => aborted.reject(new Error("aborted")), { once: true });
			try {
				return await Promise.race([entry.finish.promise, aborted.promise]);
			} finally {
				tap?.close();
			}
		},
		{
			ownerId,
			...(tap
				? {
						process: { command: "fixture --run", cwd: "/fixture", pids: () => [4242] },
						widgetInputs: {
							sources: () => [tap],
							brief: () => ({ kind: "bash" as const, command: "fixture --run" }),
						},
					}
				: {}),
		},
	);
	bodies.set(id, entry);
	return id;
}

const probe: RuntimeProbe = async (op, ...args) => {
	switch (op) {
		case "noop":
			return true;
		case "register":
			return registerBody(manager(args[0]), String(args[1]), args[2] === true);
		case "registerCapacity": {
			const jobs = manager(args[0]);
			const id = String(args[1]);
			const state = new Int32Array(args[2] as SharedArrayBuffer);
			const gate = Promise.withResolvers<void>();
			admissionGates.set(id, gate);
			return jobs.register(
				"bash",
				"capacity fixture job",
				async () => {
					Atomics.add(state, 1, 1);
					return "capacity result";
				},
				{
					id,
					waitForCapacity: true,
					beforeStart: async signal => {
						try {
							Atomics.add(state, 0, 1);
							await Promise.race([
								gate.promise,
								new Promise<void>(resolve => {
									if (signal.aborted) resolve();
									else signal.addEventListener("abort", () => resolve(), { once: true });
								}),
							]);
						} finally {
							admissionGates.delete(id);
						}
					},
				},
			);
		}
		case "readyCapacity":
			admissionGates.get(String(args[0]))?.resolve();
			return true;
		case "progress":
			await body(args[0]).report?.(String(args[1]), typeof args[2] === "string" ? args[2] : undefined);
			return true;
		case "finish":
			body(args[0]).finish.resolve(String(args[1]));
			return true;
		case "append":
			body(args[0]).tap?.append(String(args[1]));
			return true;
		case "abortState": {
			const signal = body(args[0]).signal;
			return {
				aborted: signal?.aborted === true,
				shutdown: signal?.reason === ASYNC_JOB_MANAGER_SHUTDOWN_REASON,
			};
		}
		case "awaitJob": {
			const jobs = manager(args[0]);
			const job = jobs.getJob(String(args[1]));
			if (!job) return null;
			const aborted = job.abortController.signal.aborted;
			await job.promise;
			const settled = jobs.getJob(String(args[1]));
			return {
				isRow: job instanceof RemoteAsyncJob,
				abortedBefore: aborted,
				abortedAfter: job.abortController.signal.aborted,
				status: settled?.status,
				resultText: settled?.resultText,
			};
		}
		case "awaitWaitStart": {
			await waitStart(String(args[0])).promise;
			return true;
		}
		case "evalWait":
		case "evalWaitProgress": {
			const jobs = manager(args[0]);
			const session: ToolSession = {
				cwd: process.cwd(),
				hasUI: false,
				settings: Settings.isolated(),
				getSessionFile: () => null,
				getSessionSpawns: () => null,
				getAgentId: () => String(args[1]),
				asyncJobManager: jobs,
			};
			const items = args.slice(2).map(id => ({ kind: "agent", id: String(id) }));
			const statusEvents: JsStatusEvent[] = [];
			const pending = runEvalWait(
				{ items, timeoutMs: 5_000 },
				{ session, emitStatus: op === "evalWaitProgress" ? event => statusEvents.push(event) : undefined },
			);
			for (const item of items) waitStart(item.id).resolve();
			const result = await pending;
			return op === "evalWaitProgress"
				? { result, progress: statusEvents.filter(event => event.op === "agent") }
				: result;
		}
		case "localInputs": {
			const job = manager(args[0]).getJob(String(args[1]));
			return { hasWidgetInputs: job?.widgetInputs !== undefined, pids: job?.process?.pids() ?? null };
		}
		case "cancelAllShutdown":
			manager(args[0]).cancelAll(undefined, ASYNC_JOB_MANAGER_SHUTDOWN_REASON);
			return true;
		case "sink":
			manager(args[0]).registerDeliverySink(String(args[1]), (jobId, text, job) => {
				deliveries.push({ jobId, text, status: job?.status, isRow: job instanceof RemoteAsyncJob });
			});
			return true;
		case "deliveries":
			return deliveries.splice(0);
		case "cost": {
			const gate = costGate(args[0]);
			gate.record(Number(args[1]));
			let capError = false;
			try {
				gate.admit();
			} catch (error) {
				capError = error instanceof CostCapError;
			}
			return { spent: gate.spent, capped: gate.capped, capError };
		}
		case "emit":
			emitSubagentFrame(bus(args[0]), bus(args[1]), String(args[2]), args[3]);
			return { same: args[0] === args[1], remote: args[0] instanceof RemoteEventBus };
		case "hasListeners":
			return bus(args[0])?.hasListeners(String(args[1])) ?? false;
		case "listen":
			bus(args[0])?.on(String(args[1]), data => {
				events.push(data);
			});
			return true;
		case "events":
			return events.splice(0);
		case "allocate": {
			const artifacts = artifactManager(args[0]);
			const ids: string[] = [];
			const count = Number(args[1]);
			for (let i = 0; i < count; i++) {
				ids.push((await artifacts.allocatePath()).id);
				// Interleave with the other worker's allocations.
				if (i % 5 === 0) await Bun.sleep(0);
			}
			return ids;
		}
		case "save": {
			const artifacts = artifactManager(args[0]);
			const id = await artifacts.save(String(args[1]));
			return { id, dir: artifacts.dir, sessionDir: artifacts.sessionDir };
		}
		case "storage": {
			const target = args[0];
			if (!(target instanceof Settings)) throw new Error("expected settings");
			const storage = target.getStorage();
			if (!storage) return { isNull: true };
			storage.setCache("fixture:key", "fixture-value", Math.floor(Date.now() / 1000) + 3_600);
			storage.recordModelUsage("fixture/model");
			return { isNull: false, cache: storage.getCache("fixture:key"), usage: storage.getModelUsageOrder()[0] };
		}
		default:
			throw new Error(`unknown probe ${op}`);
	}
};

function costGate(value: unknown): CostGateApi {
	if (!(value instanceof RemoteCostGate)) throw new Error("expected a remote cost gate");
	return value;
}

function artifactManager(value: unknown): ArtifactManagerApi {
	if (!(value instanceof RemoteArtifactManager)) throw new Error("expected a remote artifact manager");
	return value;
}

function isRegister(value: unknown): value is (probe: RuntimeProbe) => Promise<void> {
	return typeof value === "function";
}

port.once("message", (init: { sync: MessagePort; counter: SharedArrayBuffer }) => {
	const link: WorkerThreadLink = new RpcLink<SubagentWorkerApi, SubagentMainApi>(
		{
			send: frame => port.postMessage(frame),
			listen: handler => {
				const listener = (frame: RpcFrame): void => handler(frame);
				port.on("message", listener);
				return () => port.off("message", listener);
			},
		},
		{ name: "runtime-fixture", sync: { port: init.sync, counter: new Int32Array(init.counter) } },
	);
	settingsThreadService.installWorker?.(link);
	runtimeThreadService.installWorker?.(link);
	asyncJobsThreadService.installWorker?.(link);
	link.handle("boot", async globals => {
		await settingsThreadService.boot?.(globals.settings, link);
		const register = globals.probe;
		if (!isRegister(register)) throw new Error("boot expects a probe registrar");
		await register(probe);
	});
	link.handle("ping", nonce => nonce);
	port.postMessage({ ready: true });
});

import { afterEach, beforeEach, describe, expect, it, vi } from "bun:test";
import * as fsp from "node:fs/promises";
import * as path from "node:path";
import { type AgentLifecycleApi, AgentLifecycleManager } from "@oh-my-pi/pi-coding-agent/registry/agent-lifecycle";
import { AgentRegistry, type AgentRegistryApi, MAIN_AGENT_ID } from "@oh-my-pi/pi-coding-agent/registry/agent-registry";
import { registerPersistedSubagents } from "@oh-my-pi/pi-coding-agent/registry/persisted-agents";
import type { AgentSession } from "@oh-my-pi/pi-coding-agent/session/agent-session";
import type { AgentSessionHandle } from "@oh-my-pi/pi-coding-agent/session/agent-session-handle";
import { TempDir } from "@oh-my-pi/pi-utils";

interface SessionStub {
	session: AgentSession;
	disposeCalls: () => number;
}

/** Minimal session: the lifecycle manager only ever calls dispose() on it. */
function makeSessionStub(dispose?: () => Promise<void>): SessionStub {
	let calls = 0;
	const stub = {
		dispose: async () => {
			calls++;
			await dispose?.();
		},
	};
	return { session: stub as unknown as AgentSession, disposeCalls: () => calls };
}

function deferred(): { promise: Promise<void>; resolve: () => void } {
	let resolve!: () => void;
	const promise = new Promise<void>(r => {
		resolve = r;
	});
	return { promise, resolve };
}

/** Settle the async park chain (timer callback → park() → dispose → setStatus). */
async function flushAsync(): Promise<void> {
	for (let i = 0; i < 5; i++) await Promise.resolve();
}

const TTL = 20;

describe("AgentLifecycleManager", () => {
	let registry: AgentRegistryApi;
	let lifecycle: AgentLifecycleApi;

	beforeEach(() => {
		AgentRegistry.resetGlobalForTests();
		AgentLifecycleManager.resetGlobalForTests();
		registry = AgentRegistry.global();
		lifecycle = AgentLifecycleManager.global();
	});
	afterEach(() => {
		vi.useRealTimers();
		vi.restoreAllMocks();
		AgentLifecycleManager.resetGlobalForTests();
		AgentRegistry.resetGlobalForTests();
	});

	function registerIdleSub(id: string, session: AgentSession | null, sessionFile: string | null = `/tmp/${id}.jsonl`) {
		return registry.register({ id, displayName: "task", kind: "sub", session, sessionFile, status: "idle" });
	}

	it("registerIfAvailable never replaces a collision and reuses only the exact expected ref", () => {
		const parked = registerIdleSub("generation-Sub", null);
		registry.setStatus("generation-Sub", "parked", parked);
		const next = {
			id: "generation-Sub",
			displayName: "replacement",
			kind: "sub" as const,
			session: null,
			status: "running" as const,
		};

		expect(registry.registerIfAvailable(next, null)).toBeUndefined();
		expect(registry.get("generation-Sub")).toBe(parked);
		expect(registry.registerIfAvailable(next, parked)).toBe(parked);
		expect(registry.get("generation-Sub")).toBe(parked);

		registry.setStatus("generation-Sub", "aborted", parked);
		expect(registry.registerIfAvailable(next, parked)).toBeUndefined();
		const staleSession = makeSessionStub().session;
		expect(registry.attachSession("generation-Sub", staleSession, undefined, parked)).toBe(false);
		expect(registry.setStatus("generation-Sub", "idle", parked)).toBe(false);
		expect(registry.get("generation-Sub")).toMatchObject({ status: "aborted", session: null });

		registry.unregister("generation-Sub", parked);
		expect(registry.registerIfAvailable(next, parked)).toBeUndefined();
		expect(registry.get("generation-Sub")).toBeUndefined();
	});

	it("global() rebinds to the current registry after a lone AgentRegistry reset so release still emits aborted", async () => {
		// A prior test file constructed the lifecycle global against registry A,
		// then reset only the registry — the global is now registry B. The stranded
		// manager (issue #11432) would run the terminal transition on the dead A
		// while consumers subscribe to B, so status_changed never arrives.
		const staleManager = lifecycle;
		AgentRegistry.resetGlobalForTests();
		const rebound = AgentLifecycleManager.global();
		expect(rebound).not.toBe(staleManager);

		const current = AgentRegistry.global();
		const ref = current.register({
			id: "Remote-Killed-Sub",
			displayName: "remote kill",
			kind: "sub",
			session: makeSessionStub().session,
			sessionFile: null,
			status: "running",
		});
		const killed = deferred();
		const unsubscribe = current.onChange(event => {
			if (event.ref === ref && event.type === "status_changed" && event.ref.status === "aborted") killed.resolve();
		});
		try {
			await rebound.release("Remote-Killed-Sub", ref, { tombstone: true });
			await killed.promise;
			expect(current.get("Remote-Killed-Sub")).toMatchObject({ status: "aborted", session: null });
		} finally {
			unsubscribe();
		}
	});

	it("adopt arms the TTL: an idle agent is parked — session disposed, ref + sessionFile retained", async () => {
		vi.useFakeTimers();
		const stub = makeSessionStub();
		registerIdleSub("1-Sub", stub.session, "/tmp/1-Sub.jsonl");
		lifecycle.adopt("1-Sub", { idleTtlMs: TTL });

		vi.advanceTimersByTime(TTL);
		await flushAsync();

		const ref = registry.get("1-Sub");
		expect(stub.disposeCalls()).toBe(1);
		expect(ref?.status).toBe("parked");
		expect(ref?.session).toBeNull();
		expect(ref?.sessionFile).toBe("/tmp/1-Sub.jsonl");
		expect(lifecycle.has("1-Sub")).toBe(true);
	});

	it("running disarms the timer; returning to idle re-arms a fresh TTL", async () => {
		vi.useFakeTimers();
		const stub = makeSessionStub();
		registerIdleSub("2-Sub", stub.session);
		lifecycle.adopt("2-Sub", { idleTtlMs: TTL });
		registry.setStatus("2-Sub", "running");

		vi.advanceTimersByTime(TTL * 10);
		await flushAsync();
		expect(registry.get("2-Sub")?.status).toBe("running");
		expect(registry.get("2-Sub")?.session).toBe(stub.session);
		expect(stub.disposeCalls()).toBe(0);

		registry.setStatus("2-Sub", "idle");
		vi.advanceTimersByTime(TTL);
		await flushAsync();
		expect(registry.get("2-Sub")?.status).toBe("parked");
		expect(stub.disposeCalls()).toBe(1);
	});

	it("ensureLive revives a parked agent through its reviver and flips it back to idle", async () => {
		const revived = makeSessionStub();
		registry.register({
			id: "3-Sub",
			displayName: "task",
			kind: "sub",
			session: null,
			sessionFile: "/tmp/3-Sub.jsonl",
			status: "parked",
		});
		lifecycle.adopt("3-Sub", { idleTtlMs: 0, revive: async () => revived.session });

		const session = await lifecycle.ensureLive("3-Sub");

		expect(session).toBe(revived.session);
		const ref = registry.get("3-Sub");
		expect(ref?.status).toBe("idle");
		expect(ref?.session).toBe(revived.session);
		expect(ref?.sessionFile).toBe("/tmp/3-Sub.jsonl");
	});

	it("reclaimDeadCorpse frees a parked, session-less, unadopted id and refuses live/adopted refs (#8490)", async () => {
		// A corpse: registered running, then parked with no session and no adoption
		// (the isolated-run finalize / interrupted-construction outcome). It cannot
		// be revived and would otherwise poison its id for the process lifetime.
		const corpse = registry.register({
			id: "Corpse-Sub",
			displayName: "task",
			kind: "sub",
			session: null,
			sessionFile: "/tmp/Corpse-Sub.jsonl",
			status: "running",
		});
		registry.setStatus("Corpse-Sub", "parked", corpse);
		await expect(lifecycle.ensureLive("Corpse-Sub")).rejects.toThrow(/parked and cannot be revived/);

		// A live ref is never reclaimed.
		const live = makeSessionStub();
		registry.register({
			id: "Live-Sub",
			displayName: "task",
			kind: "sub",
			session: live.session,
			status: "running",
		});
		expect(await lifecycle.reclaimDeadCorpse("Live-Sub", registry.get("Live-Sub")!)).toBe(false);
		expect(registry.get("Live-Sub")?.session).toBe(live.session);

		// An adopted (revivable) parked agent is never reclaimed.
		const adopted = registry.register({
			id: "Adopted-Sub",
			displayName: "task",
			kind: "sub",
			session: null,
			sessionFile: "/tmp/Adopted-Sub.jsonl",
			status: "parked",
		});
		lifecycle.adopt("Adopted-Sub", { idleTtlMs: 0, revive: async () => makeSessionStub().session }, adopted);
		expect(await lifecycle.reclaimDeadCorpse("Adopted-Sub", adopted)).toBe(false);
		expect(registry.get("Adopted-Sub")).toBe(adopted);

		// A stale expected ref (points at a different agent) is never reclaimed.
		expect(await lifecycle.reclaimDeadCorpse("Corpse-Sub", adopted)).toBe(false);

		// The corpse is reclaimed, and its id becomes registerable again.
		expect(await lifecycle.reclaimDeadCorpse("Corpse-Sub", corpse)).toBe(true);
		expect(registry.get("Corpse-Sub")).toBeUndefined();
		const respawn = registry.registerIfAvailable(
			{ id: "Corpse-Sub", displayName: "task", kind: "sub", session: null, status: "running" },
			null,
		);
		expect(respawn?.status).toBe("running");
		expect(registry.get("Corpse-Sub")).toBe(respawn);
	});

	it("reclaimDeadCorpse preserves an unadopted parked ref when its persisted session can cold-revive", async () => {
		const revived = makeSessionStub();
		const cold = registry.register({
			id: "Cold-Sub",
			displayName: "task",
			kind: "sub",
			session: null,
			sessionFile: "/tmp/Cold-Sub.jsonl",
			status: "parked",
		});
		let factoryCalls = 0;
		lifecycle.setPersistedSubagentReviverFactory(
			async ref => {
				factoryCalls++;
				expect(ref).toBe(cold);
				return async () => revived.session;
			},
			() => 0,
		);

		expect(await lifecycle.reclaimDeadCorpse("Cold-Sub", cold)).toBe(false);
		expect(registry.get("Cold-Sub")).toBe(cold);
