				const rootAgent = rootSession(rootStorage, jobs);
				const registry = AgentRegistry.global();
				registry.register({
					id: MAIN_AGENT_ID,
					displayName: "Main",
					kind: "main",
					status: "idle",
					session: rootAgent,
					sessionFile: rootFile,
				});
				await Bun.write(path.join(cwd, "restore-notes.txt"), "read was replayed\n");
				const parentFile = path.join(rootFile.slice(0, -6), parentId + ".jsonl");
				const childFile = path.join(rootFile.slice(0, -6), parentId, childId + ".jsonl");
				const assignment = SCRIPT_ID + "/restore-parent-first-step";
				await fs.mkdir(path.dirname(childFile), { recursive: true });
				await nestedTranscript(parentFile, rootFile, script.parentMarker, assignment, interrupted, [
					assignment,
					script.unsentStep,
				]);
				await nestedTranscript(childFile, parentFile, script.childMarker, "child assignment", true);
				AgentLifecycleManager.global().setPersistedSubagentReviverFactory(
					createPersistedSubagentReviverFactory({
						session: rootAgent,
						authStorage,
						modelRegistry,
						settings,
						enableLsp: false,
						eventBus,
					}),
					() => 0,
				);

				const cap = Promise.withResolvers<void>();
				jobs.register(
					"task",
					"capacity gate",
					async () => {
						await cap.promise;
						return "capacity gate released";
					},
					{ id: "restore-test-cap", foreground: true },
				);
				const sink = Promise.withResolvers<void>();
				const softRelease = Promise.withResolvers<void>();
				const releaseEntered = Promise.withResolvers<void>();
				const originalSink = jobs.registerDeliverySink.bind(jobs);
				const sinkMiddleware = spyOn(jobs, "registerDeliverySink").mockImplementation((id, deliver) =>
					originalSink(id, async (jobId, result, row) => {
						// Wait outside the real home sink: the delivery remains in
						// flight, but the first loop cannot take it while streaming.
						if (id === parentId && jobId === childId) await sink.promise;
						await deliver(jobId, result, row);
					}),
				);
				const originalRelease = RemoteAgentSession.prototype.releaseRestoreIdleHold;
				let heldRelease = false;
				const releaseMiddleware = spyOn(RemoteAgentSession.prototype, "releaseRestoreIdleHold").mockImplementation(
					async function (this: RemoteAgentSession, token) {
						const released = await originalRelease.call(this, token);
						if (this.agentId === parentId && !heldRelease) {
							heldRelease = true;
							releaseEntered.resolve();
							sink.resolve();
							// The home has released and can run. Keep the ACK
							// from the executor until final end has arrived.
							await softRelease.promise;
						}
						return released;
					},
				);
				const parentEvents: string[] = [];
				let releasePlacement: (() => void) | undefined;
				try {
					const restored = await restoreSession(rootAgent);
					expect(restored).toEqual({ turn: false, subagents: [parentId, childId] });
					expect(jobs.getRunningJobs().map(row => [row.id, row.queued])).toEqual([
						[parentId, true],
						[childId, true],
					]);
					const owner = mirrorOf(registry.get(parentId)?.session);
					const unsub = owner.subscribe(event => {
						if (event.type === "agent_pause" || event.type === "agent_end") parentEvents.push(event.type);
					});
					cleanups.push(unsub);
					const ownerWorker = pool.forThread(owner.home);
					if (!ownerWorker) throw new Error("restore owner did not retain its worker");
					releasePlacement = ownerWorker.beginRun(); // Force second *real* persisted home.
					cap.resolve();
					await script.childStarted.promise;
					const child = mirrorOf(registry.get(childId)?.session);
					expect(child.home).not.toBe(owner.home);
					expect(pool.forThread(child.home)?.alive).toBe(true);
					expect(jobs.getJob(childId)?.ownerId).toBe(parentId);
					expect(jobs.getJob(childId)?.restoreReceiptId?.startsWith(owner.instanceKey + ":")).toBe(true);
					expect(jobs.getJob(parentId)?.queued).toBe(true);
					expect(jobs.getJob(childId)?.queued).toBe(false);
					releasePlacement();
					releasePlacement = undefined;
					script.childContinue.resolve();

					await releaseEntered.promise;
					await waitFor(() => parentEvents.includes("agent_end"));
					expect(parentEvents).toEqual(interrupted ? ["agent_pause", "agent_end"] : ["agent_end"]);
					expect(script.parentRequests).toEqual(interrupted ? ["initial", "receipt"] : ["receipt"]);
					softRelease.resolve();
					await jobs.waitForAll();
					await jobs.drainDeliveries();
					expect(jobs.getJob(parentId)?.status).toBe("completed");
					expect(jobs.getJob(parentId)?.ownerId).toBe(MAIN_AGENT_ID);
					expect(jobs.getJob(parentId)?.resultText).toContain(script.finalResult);
					expect(script.parentRequests).toEqual(
						interrupted ? ["initial", "receipt", "step"] : ["receipt", "step"],
					);
					expect(parentEvents.filter(event => event === "agent_end")).toHaveLength(2);
				} finally {
					releasePlacement?.();
					cap.resolve();
					sink.resolve();
					softRelease.resolve();
					script.childContinue.resolve();
					releaseMiddleware.mockRestore();
					sinkMiddleware.mockRestore();
				}
			},
			TEST_TIMEOUT_MS,
		);
	}
});

