			while (!relay.bridge.listTargets().some(target => target.url === updated.href)) {
				if (performance.now() >= deadline) throw new Error("Relay did not observe the fixture URL update");
				await Bun.sleep(20);
			}
			const later = await invoke(readMark);
			expect(later.value).toBe("kept");
			expect(later.text).toContain("Chrome had kept omp out of this tab");
		},
