	it.skipIf(!CHROMIUM_AVAILABLE).each([
		{ owned: true, label: "owned tab closed" },
		{ owned: false, label: "adopted tab left open" },
	])(
		"replaces a held-out tab without re-adopting ($label)",
		async ({ owned }) => {
