			const evaluating = ext.hanging();
			const stalled = invoke({ action: "run", ...HANG }).catch((error: unknown) => error);
			await evaluating;
			await ext.chromeDetach("target_closed");
			const failure = String(await stalled);
			expect(failure).toContain("Chrome detached omp from this tab (target_closed) during this call");
			expect(failure).toContain("could not reattach");
			const later = String(await invoke(readMark).catch((error: unknown) => error));
			expect(later).toContain("could not reattach");
			expect(later).toContain("navigate it in Chrome first");
			// The guidance holds: once the tab's URL changed, it opens again, page state intact.
			ext.refuseAttach = undefined;
			await page?.evaluate("location.hash = 'moved'");
			ext.urlChanged(`${pageUrl}#moved`);
			await invoke({ action: "open", app: "relay", target: "case=", timeout: 20 });
			expect((await invoke(readMark)).value).toBe("kept");
		},
		60_000,
	);

	it.skipIf(!CHROMIUM_AVAILABLE)(
		"releases the tab without re-adopting it when the user cancels Chrome's debugging bar",
		async () => {
			const ext = await openRelayTab();
			const respawn = spyOn(globalThis, "Worker");
			try {
				const evaluating = ext.hanging();
				const stalled = invoke({ action: "run", ...HANG }).catch((error: unknown) => error);
				await evaluating;
				await ext.chromeDetach("canceled_by_user");
				const failure = String(await stalled);
				expect(failure).toContain("Chrome detached omp from this tab (canceled_by_user) during this call");
				expect(failure).toContain("The user cancelled Chrome's debugging bar");
				expect(failure).toContain("navigate it in Chrome, then open it again");
				expect(failure).not.toContain("password manager");
				// No new worker was started for a re-adoption the relay cannot grant.
				expect(respawn).not.toHaveBeenCalled();
			} finally {
				respawn.mockRestore();
			}
			const later = String(await invoke(readMark).catch((error: unknown) => error));
			expect(later).toContain("The user cancelled Chrome's debugging bar");
		},
		60_000,
	);

	it.skipIf(!CHROMIUM_AVAILABLE)(
		"reports a cancel that lands during the re-adoption as a cancel",
		async () => {
			const ext = await openRelayTab();
			const tab = getTab(name);
			if (tab?.backend !== "worker") throw new Error("expected a worker tab");
			// Hold the re-adoption once the detached worker is gone, so the cancel lands while it is under way.
			const terminate = tab.worker.terminate.bind(tab.worker);
			const readopting = Promise.withResolvers<void>();
			const resume = Promise.withResolvers<void>();
			const held = spyOn(tab.worker, "terminate").mockImplementation(async () => {
				await terminate();
				readopting.resolve();
				await resume.promise;
			});
			try {
				const ac = new AbortController();
				const evaluating = ext.hanging();
				const stalled = runInTab(name, {
					code: HANG.code,
					timeoutMs: 30_000,
					session: tool,
					signal: ac.signal,
				}).catch((error: unknown) => error);
				await evaluating;
				await ext.chromeDetach("target_closed");
				await readopting.promise;
				ac.abort();
				resume.resolve();
				// Whether the tab survives depends on the re-adoption beating the cancel grace; the report must not.
				expect(await stalled).toBeInstanceOf(ToolAbortError);
			} finally {
				resume.resolve();
				held.mockRestore();
			}
		},
		60_000,
	);
});

import { afterEach, describe, expect, it, spyOn, vi } from "bun:test";
import { RelayBridge, type RelaySocket } from "@oh-my-pi/pi-coding-agent/tools/browser/relay/bridge";
import { closeRelayOwnedTarget, closeRelayTarget } from "@oh-my-pi/pi-coding-agent/tools/browser/relay/owned-targets";
import type { RelayToExtMessage } from "@oh-my-pi/pi-coding-agent/tools/browser/relay/protocol";

const WS_ENDPOINT = "ws://relay.test/cdp";

/** Exercise the real bridge without a browser or listening socket. */
function connectOwnedTab(bridge: RelayBridge): { extension: RelaySocket; removed: number[]; targetId: string } {
	const removed: number[] = [];
	const extension: RelaySocket = {
		send(raw) {
			const request = JSON.parse(raw) as RelayToExtMessage;
			if (request.t !== "rpc" || request.op !== "removeTab") return;
			removed.push(request.tabId);
			queueMicrotask(() => {
				bridge.extMessage(extension, JSON.stringify({ t: "tabRemoved", tabId: request.tabId }));
				bridge.extMessage(
					extension,
					JSON.stringify({ t: "rpcResult", id: request.id, ok: true, result: { closed: true } }),
				);
			});
		},
		close() {},
	};
	bridge.extConnected(extension);
	bridge.extMessage(
		extension,
		JSON.stringify({
			t: "hello",
			userAgent: "test",
			browserVersion: "Chrome/151.0.0.0",
			discardedTabsProtocol: 1,
			tabs: [
				{
					tabId: 9,
					url: "https://example.com/",
					title: "Owned",
					active: false,
					discarded: false,
					windowId: 1,
					pinned: false,
					groupId: -1,
				},
			],
			attachedTabIds: [],
			ownedTabIds: [9],
		}),
	);
	const targetId = bridge.listTargets()[0]?.id;
	if (!targetId) throw new Error("Owned tab was not discoverable after the extension hello");
	return { extension, removed, targetId };
}

function installRelayTransport(
	bridge: RelayBridge,
	mapReply: (raw: string) => string = raw => raw,
	claim?: string,
): void {
	class RelayWebSocket {
		onopen: (() => void) | null = null;
		onmessage: ((event: { data: string }) => void) | null = null;
		onerror: (() => void) | null = null;
		onclose: (() => void) | null = null;
		readonly #connId: number;
		#closed = false;

		constructor() {
			this.#connId = bridge.cdpConnected(
				{
					send: raw => queueMicrotask(() => this.onmessage?.({ data: mapReply(raw) })),
					close: () => this.close(),
				},
				claim,
			);
			queueMicrotask(() => this.onopen?.());
		}

		send(raw: string): void {
			bridge.cdpMessage(this.#connId, raw);
		}

		close(): void {
			if (this.#closed) return;
			this.#closed = true;
			bridge.cdpClosed(this.#connId);
			queueMicrotask(() => this.onclose?.());
		}
	}

	// Bun's spy types describe callable functions, including mocked constructors.
	const globals = globalThis as unknown as { WebSocket: () => WebSocket };
	spyOn(globals, "WebSocket").mockImplementation(() => new RelayWebSocket() as unknown as WebSocket);
}

afterEach(() => vi.restoreAllMocks());

describe("relay owned-target close confirmation", () => {
	it("confirms closure when the extension removes the requested tab", async () => {
		const bridge = new RelayBridge({});
		const { removed, targetId } = connectOwnedTab(bridge);
		installRelayTransport(bridge, undefined, targetId);

		expect(await closeRelayTarget(WS_ENDPOINT, targetId)).toBe(true);
		expect(removed).toEqual([9]);
		expect(bridge.listTargets()).toEqual([]);
	});

	it("keeps an offline target unresolved even though discovery hides it, allowing a later retry", async () => {
		const bridge = new RelayBridge({});
		const { extension, removed, targetId } = connectOwnedTab(bridge);
		installRelayTransport(bridge);
		bridge.extClosed(extension);
		expect(bridge.listTargets()).toEqual([]);

		expect(await closeRelayOwnedTarget(WS_ENDPOINT, targetId)).toBe(false);
		expect(removed).toEqual([]);

		const reconnected = connectOwnedTab(bridge);
		expect(await closeRelayOwnedTarget(WS_ENDPOINT, targetId)).toBe(true);
		expect(reconnected.removed).toEqual([9]);
	});

	it.each([{ success: false }, {}])("does not confirm an absent target after a close reply of %j", async result => {
		const bridge = new RelayBridge({});
		const { targetId } = connectOwnedTab(bridge);
		installRelayTransport(
			bridge,
			raw => {
				const reply = JSON.parse(raw) as { id?: number; result?: { success?: boolean } };
				return reply.result?.success === true ? JSON.stringify({ id: reply.id, result }) : raw;
			},
			targetId,
		);

		expect(await closeRelayTarget(WS_ENDPOINT, targetId)).toBe(false);
		expect(bridge.listTargets()).toEqual([]);
	});
});

